-- ═══════════════════════════════════════════════════════════════════════════
-- 00488 — Canonical studio authority: focused ordinary rollback
--
-- Run the platform-admin storage rollback first when the nine reserved-owner
-- policies reached their 00488 final state.  This transaction accepts only
-- the exact reviewed ordinary final state with exact source storage policies,
-- then restores the exact reviewed source catalog.  It never guesses a
-- workspace, merges rows, drops a dependency with CASCADE, or discards a
-- non-NULL 00488-only snapshot.
-- ═══════════════════════════════════════════════════════════════════════════

BEGIN;
SET LOCAL search_path = pg_catalog, public;
SET LOCAL standard_conforming_strings = on;
SET LOCAL quote_all_identifiers = off;

-- Exact final-state proof.  This is the same hash-pinned catalog/caller gate
-- used by the forward renderer, forced to the final branch.

DO $c00488_policy_fingerprint_environment$
BEGIN
  IF current_setting('server_version_num')::integer NOT BETWEEN 170000 AND 179999
     OR current_setting('server_encoding') IS DISTINCT FROM 'UTF8'
     OR current_setting('standard_conforming_strings') IS DISTINCT FROM 'on'
     OR current_setting('quote_all_identifiers') IS DISTINCT FROM 'off'
  THEN
    RAISE EXCEPTION
      '00488 policy fingerprint environment must be PostgreSQL 17/UTF8 with pinned deparse settings';
  END IF;
END;
$c00488_policy_fingerprint_environment$;

CREATE OR REPLACE FUNCTION pg_temp._00488_mask_sql(
  p_source text,
  p_preserve_quoted_identifiers boolean DEFAULT true
)
RETURNS text
LANGUAGE plpgsql
IMMUTABLE
SET search_path = pg_catalog, pg_temp
AS $c00488_mask_sql$
DECLARE
  cursor_position integer := 1;
  source_length integer := pg_catalog.char_length(COALESCE(p_source, ''));
  block_depth integer;
  dollar_tag text;
  dollar_candidate text;
  dollar_character text;
  dollar_position integer;
  dollar_valid boolean;
  close_offset integer;
  result text := '';
  character text;
  escape_string boolean;
  string_closed boolean;
BEGIN
  WHILE cursor_position <= source_length LOOP
    IF pg_catalog.substr(p_source, cursor_position, 2) = '--' THEN
      cursor_position := cursor_position + 2;
      WHILE cursor_position <= source_length
        AND pg_catalog.substr(p_source, cursor_position, 1) <> pg_catalog.chr(10)
      LOOP
        cursor_position := cursor_position + 1;
      END LOOP;
      result := result || ' ';
      CONTINUE;
    END IF;

    IF pg_catalog.substr(p_source, cursor_position, 2) = '/*' THEN
      block_depth := 1;
      cursor_position := cursor_position + 2;
      WHILE cursor_position <= source_length AND block_depth > 0 LOOP
        IF pg_catalog.substr(p_source, cursor_position, 2) = '/*' THEN
          block_depth := block_depth + 1;
          cursor_position := cursor_position + 2;
        ELSIF pg_catalog.substr(p_source, cursor_position, 2) = '*/' THEN
          block_depth := block_depth - 1;
          cursor_position := cursor_position + 2;
        ELSE
          cursor_position := cursor_position + 1;
        END IF;
      END LOOP;
      IF block_depth <> 0 THEN
        RAISE EXCEPTION '00488 catalog lexer found an unterminated block comment';
      END IF;
      result := result || ' ';
      CONTINUE;
    END IF;

    character := pg_catalog.substr(p_source, cursor_position, 1);
    IF character = '''' THEN
      escape_string := cursor_position > 1
        AND pg_catalog.lower(
          pg_catalog.substr(p_source, cursor_position - 1, 1)
        ) = 'e'
        AND (
          cursor_position = 2
          OR (
            pg_catalog.substr(p_source, cursor_position - 2, 1)
              !~ '[[:alnum:]_$]'
            AND COALESCE(pg_catalog.ascii(NULLIF(
                  pg_catalog.substr(p_source, cursor_position - 2, 1), ''
                )), 0) < 128
          )
        );
      string_closed := false;
      cursor_position := cursor_position + 1;
      WHILE cursor_position <= source_length LOOP
        character := pg_catalog.substr(p_source, cursor_position, 1);
        IF character = '''' THEN
          IF pg_catalog.substr(p_source, cursor_position + 1, 1) = '''' THEN
            cursor_position := cursor_position + 2;
          ELSE
            cursor_position := cursor_position + 1;
            string_closed := true;
            EXIT;
          END IF;
        ELSIF escape_string AND character = E'\\' THEN
          cursor_position := cursor_position + 2;
        ELSE
          cursor_position := cursor_position + 1;
        END IF;
      END LOOP;
      IF NOT string_closed THEN
        RAISE EXCEPTION '00488 catalog lexer found an unterminated string literal';
      END IF;
      result := result || ' ';
      CONTINUE;
    END IF;

    IF character = '$'
       AND (
         cursor_position = 1
         OR (
           pg_catalog.substr(p_source, cursor_position - 1, 1)
             !~ '[[:alnum:]_$]'
           AND COALESCE(pg_catalog.ascii(NULLIF(
                 pg_catalog.substr(p_source, cursor_position - 1, 1), ''
               )), 0) < 128
         )
       )
    THEN
      dollar_tag := NULL;
      close_offset := pg_catalog.strpos(
        pg_catalog.substr(p_source, cursor_position + 1), '$'
      );
      IF close_offset > 0 THEN
        dollar_candidate := pg_catalog.substr(
          p_source, cursor_position + 1, close_offset - 1
        );
        dollar_valid := dollar_candidate = '';
        IF dollar_candidate <> '' THEN
          dollar_character := pg_catalog.substr(dollar_candidate, 1, 1);
          dollar_valid := dollar_character ~ '[A-Za-z_]'
            OR pg_catalog.ascii(dollar_character) >= 128;
          dollar_position := 2;
          WHILE dollar_valid
            AND dollar_position <= pg_catalog.char_length(dollar_candidate)
          LOOP
            dollar_character := pg_catalog.substr(
              dollar_candidate, dollar_position, 1
            );
            dollar_valid := dollar_character ~ '[A-Za-z0-9_]'
              OR pg_catalog.ascii(dollar_character) >= 128;
            dollar_position := dollar_position + 1;
          END LOOP;
        END IF;
        IF dollar_valid THEN
          dollar_tag := '$' || dollar_candidate || '$';
        END IF;
      END IF;
      IF dollar_tag IS NOT NULL THEN
        close_offset := pg_catalog.strpos(
          pg_catalog.substr(
            p_source, cursor_position + pg_catalog.char_length(dollar_tag)
          ),
          dollar_tag
        );
        IF close_offset = 0 THEN
          RAISE EXCEPTION '00488 catalog lexer found an unterminated dollar literal';
        END IF;
        cursor_position := cursor_position
          + pg_catalog.char_length(dollar_tag)
          + close_offset - 1
          + pg_catalog.char_length(dollar_tag);
        result := result || ' ';
        CONTINUE;
      END IF;
    END IF;

    -- Unicode-escaped identifiers can encode a protected name without its
    -- literal spelling. No reviewed catalog object needs them, so fail closed.
    IF character = '"'
       AND cursor_position >= 3
       AND pg_catalog.lower(
             pg_catalog.substr(p_source, cursor_position - 2, 2)
           ) = 'u&'
       AND (
         cursor_position = 3
         OR pg_catalog.substr(p_source, cursor_position - 3, 1)
              !~ '[[:alnum:]_$]'
       )
    THEN
      RAISE EXCEPTION
        '00488 catalog lexer rejects Unicode-escaped quoted identifiers';
    END IF;

    -- Quoted identifiers are executable code for call/table attribution but
    -- are blanked for keyword recognition. This distinguishes a quoted
    -- "EXECUTE" identifier from the EXECUTE keyword in EXECUTE"sql".
    IF character = '"' THEN
      IF p_preserve_quoted_identifiers THEN
        result := result || '"';
      END IF;
      cursor_position := cursor_position + 1;
      string_closed := false;
      WHILE cursor_position <= source_length LOOP
        character := pg_catalog.substr(p_source, cursor_position, 1);
        IF character = '"' THEN
          IF pg_catalog.substr(p_source, cursor_position + 1, 1) = '"' THEN
            IF p_preserve_quoted_identifiers THEN
              result := result || '""';
            END IF;
            cursor_position := cursor_position + 2;
          ELSE
            IF p_preserve_quoted_identifiers THEN
              result := result || '"';
            END IF;
            cursor_position := cursor_position + 1;
            string_closed := true;
            EXIT;
          END IF;
        ELSE
          IF p_preserve_quoted_identifiers THEN
            result := result || character;
          END IF;
          cursor_position := cursor_position + 1;
        END IF;
      END LOOP;
      IF NOT string_closed THEN
        RAISE EXCEPTION '00488 catalog lexer found an unterminated quoted identifier';
      END IF;
      IF NOT p_preserve_quoted_identifiers THEN
        result := result || ' ';
      END IF;
      CONTINUE;
    END IF;

    result := result || character;
    cursor_position := cursor_position + 1;
  END LOOP;
  RETURN result;
END;
$c00488_mask_sql$;

CREATE OR REPLACE FUNCTION pg_temp._00488_policy_clause_frame(
  p_value text
)
RETURNS bytea
LANGUAGE sql
IMMUTABLE
STRICT
SET search_path = pg_catalog, pg_temp
AS $c00488_policy_clause_frame$
  SELECT pg_catalog.decode('01', 'hex')
    || pg_catalog.int8send(pg_catalog.octet_length(p_value)::bigint)
    || pg_catalog.convert_to(p_value, 'UTF8')
$c00488_policy_clause_frame$;

CREATE OR REPLACE FUNCTION pg_temp._00488_policy_fingerprint(
  p_relation text,
  p_qual_sql text,
  p_check_sql text
)
RETURNS text
LANGUAGE plpgsql
VOLATILE
SET search_path = pg_catalog, public, pg_temp
AS $c00488_policy_fingerprint$
DECLARE
  relation_oid pg_catalog.regclass := pg_catalog.to_regclass(p_relation);
  relation_name text;
  probe_relation pg_catalog.regclass;
  probe_sql text;
  result text;
BEGIN
  IF relation_oid IS NULL THEN
    RAISE EXCEPTION '00488 policy probe relation is missing: %', p_relation;
  END IF;
  SELECT relation.relname INTO STRICT relation_name
  FROM pg_catalog.pg_class AS relation
  WHERE relation.oid = relation_oid;
  IF pg_catalog.to_regclass(
       'pg_temp.' || pg_catalog.quote_ident(relation_name)
     ) IS NOT NULL
  THEN
    RAISE EXCEPTION
      '00488 policy probe temp relation already exists: %', relation_name;
  END IF;

  EXECUTE pg_catalog.format(
    'CREATE TEMP TABLE pg_temp.%I (LIKE %s)', relation_name, relation_oid
  );
  probe_sql := pg_catalog.format(
    'CREATE POLICY c00488_catalog_probe ON pg_temp.%I', relation_name
  );
  IF p_qual_sql IS NOT NULL THEN
    probe_sql := probe_sql || ' USING ' || p_qual_sql;
  END IF;
  IF p_check_sql IS NOT NULL THEN
    probe_sql := probe_sql || ' WITH CHECK ' || p_check_sql;
  END IF;
  EXECUTE probe_sql;
  probe_relation := pg_catalog.to_regclass(
    'pg_temp.' || pg_catalog.quote_ident(relation_name)
  );

  SELECT pg_catalog.encode(extensions.digest(
    pg_catalog.convert_to('patina-csa-policy-v1', 'UTF8')
    || pg_catalog.decode('00', 'hex')
    || COALESCE(
      pg_temp._00488_policy_clause_frame(
        pg_catalog.pg_get_expr(policy.polqual, policy.polrelid)
      ),
      pg_catalog.decode('00', 'hex')
    )
    || COALESCE(
      pg_temp._00488_policy_clause_frame(
        pg_catalog.pg_get_expr(policy.polwithcheck, policy.polrelid)
      ),
      pg_catalog.decode('00', 'hex')
    ),
    'sha256'
  ), 'hex') INTO STRICT result
  FROM pg_catalog.pg_policy AS policy
  WHERE policy.polrelid = probe_relation
    AND policy.polname = 'c00488_catalog_probe';

  EXECUTE pg_catalog.format('DROP TABLE pg_temp.%I', relation_name);
  RETURN result;
EXCEPTION WHEN OTHERS THEN
  IF relation_name IS NOT NULL THEN
    EXECUTE pg_catalog.format(
      'DROP TABLE IF EXISTS pg_temp.%I', relation_name
    );
  END IF;
  RAISE;
END;
$c00488_policy_fingerprint$;

CREATE OR REPLACE FUNCTION pg_temp._00488_catalog_policy_fingerprint(
  p_policy oid
)
RETURNS text
LANGUAGE sql
STABLE
SET search_path = pg_catalog, public, pg_temp
AS $c00488_catalog_policy_fingerprint$
  SELECT pg_catalog.encode(extensions.digest(
    pg_catalog.convert_to('patina-csa-policy-v1', 'UTF8')
    || pg_catalog.decode('00', 'hex')
    || COALESCE(
      pg_temp._00488_policy_clause_frame(
        pg_catalog.pg_get_expr(policy.polqual, policy.polrelid)
      ),
      pg_catalog.decode('00', 'hex')
    )
    || COALESCE(
      pg_temp._00488_policy_clause_frame(
        pg_catalog.pg_get_expr(policy.polwithcheck, policy.polrelid)
      ),
      pg_catalog.decode('00', 'hex')
    ),
    'sha256'
  ), 'hex')
  FROM pg_catalog.pg_policy AS policy
  WHERE policy.oid = p_policy
$c00488_catalog_policy_fingerprint$;

CREATE OR REPLACE FUNCTION pg_temp._00488_call_count(
  p_source text,
  p_helper text
)
RETURNS integer
LANGUAGE sql
IMMUTABLE
SET search_path = pg_catalog, pg_temp
AS $c00488_call_count$
  SELECT count(*)::integer
  FROM pg_catalog.regexp_matches(
    pg_temp._00488_mask_sql(p_source),
    '(^|[^a-z0-9_$])(?:"?public"?[[:space:]]*\.[[:space:]]*)?"?'
      || p_helper || '"?[[:space:]]*\(',
    'gi'
  )
$c00488_call_count$;

CREATE OR REPLACE FUNCTION pg_temp._00488_insert_count(
  p_source text,
  p_table text
)
RETURNS integer
LANGUAGE sql
IMMUTABLE
SET search_path = pg_catalog, pg_temp
AS $c00488_insert_count$
  SELECT count(*)::integer
  FROM pg_catalog.regexp_matches(
    pg_temp._00488_mask_sql(p_source),
    '(^|[^a-z0-9_$])insert[[:space:]]+into[[:space:]]+'
      || '(?:"?public"?[[:space:]]*\.[[:space:]]*)?"?'
      || p_table || '"?([^a-z0-9_$]|$)',
    'gi'
  )
$c00488_insert_count$;

CREATE OR REPLACE FUNCTION pg_temp._00488_dynamic_mentions(
  p_source text,
  p_token text
)
RETURNS boolean
LANGUAGE sql
IMMUTABLE
SET search_path = pg_catalog, pg_temp
AS $c00488_dynamic_mentions$
  -- A dynamic statement can construct the target without spelling it in a
  -- literal. Unknown dynamic bodies therefore fail closed for every target.
  -- Five exact source hashes were independently reviewed; the global
  -- source/final dynamic-routine anti-join proves those hashes are attached
  -- only to their exact signatures before this exemption is useful.
  SELECT p_token IS NOT NULL
     AND pg_temp._00488_mask_sql(COALESCE(p_source, ''), false)
           ~* '(^|[^a-z0-9_$])execute([^a-z0-9_$]|$)'
     AND pg_catalog.encode(extensions.digest(
           pg_catalog.convert_to(COALESCE(p_source, ''), 'UTF8'), 'sha256'
         ), 'hex') NOT IN ('05e2f08a10ca3ce9b356fc8f45a93da6f8003165085d8793c46a3d53e6033732','0f733420758c50632ab9bcdb73fdfe61de21286d598451957ed01055da1ffce6','20c4720148d16b9711a045b06ede7449d9d53e1e55f1a12a419a9db7ab3a0a66','9d7c2703645fb8f774ff37698453de7c15d1fa0e67e2d902f3fd49ae17511142','c3cf2fc6b7a6e4f856b6c76d4fea40bb11d40885328e4e8a4e7bc3ebbb34c455')
$c00488_dynamic_mentions$;

-- pg_proc.prosrc is not a complete representation for SQL-standard
-- BEGIN ATOMIC bodies. The reviewed source/final universe contains none, so
-- reject any such routine before relying on the prosrc lexical contracts.
DO $c00488_sql_body_universe$
BEGIN
  IF EXISTS (
    SELECT 1
    FROM pg_catalog.pg_proc AS routine
    JOIN pg_catalog.pg_namespace AS namespace
      ON namespace.oid = routine.pronamespace
    WHERE namespace.nspname IN ('public', 'app_private')
      AND pg_catalog.pg_get_function_sqlbody(routine.oid) IS NOT NULL
  ) THEN
    RAISE EXCEPTION
      '00488 found an unreviewed SQL-standard routine body outside prosrc';
  END IF;
END;
$c00488_sql_body_universe$;

CREATE OR REPLACE TEMP VIEW _00488_expected_people_directory_source AS
-- ── CLIENTS ───────────────────────────────────────────────────────────────
-- v4: meta gains has_sent_proposal + issued_on_paper (this migration).
-- Everything else in this branch is unchanged from 00420.
SELECT
  dc.id                                                          AS person_id,
  'client'::text                                                 AS role,
  COALESCE(dc.client_name, pr.full_name, pr.display_name, dc.client_email, 'Unnamed client') AS display_name,
  COALESCE(dc.client_email, pr.email)                            AS email,
  pr.phone                                                       AS phone,
  dc.client_id                                                   AS profile_id,
  NULL::uuid                                                     AS project_id,
  dc.designer_id                                                 AS designer_id,
  dc.status                                                      AS status_raw,
  COALESCE(dc.last_contacted_at, dc.last_project_at, dc.updated_at) AS last_touch_at,
  jsonb_build_object(
    'total_projects',     dc.total_projects,
    'total_revenue',      dc.total_revenue,
    'last_project_at',    dc.last_project_at,
    'last_contacted_at',  dc.last_contacted_at,
    'first_project_at',   dc.first_project_at,
    'style_tags',         dc.style_tags,
    'source',             dc.source,
    'satisfaction_score', dc.satisfaction_score,
    'nickname',           dc.nickname,
    'location',           dc.location,
    'lead_id',            dc.lead_id
  ) || public.designer_client_send_evidence(dc.id, dc.designer_id, dc.client_id)
                                                                 AS meta,
  (CASE WHEN dc.designer_id = (select auth.uid()) THEN 'mine' ELSE 'studio' END)::text AS scope
FROM public.designer_clients dc
LEFT JOIN public.profiles pr ON pr.id = dc.client_id
WHERE public.is_studio_comember(dc.designer_id)

UNION ALL

-- ── LEADS (open only) ─────────────────────────────────────────────────────
-- Unchanged from 00420.
SELECT
  l.id,
  'lead',
  COALESCE(l.contact_name, hp.full_name, hp.display_name, l.contact_email, 'New lead'),
  COALESCE(l.contact_email, hp.email),
  hp.phone,
  l.homeowner_id,
  NULL::uuid,
  l.designer_id,
  l.status,
  COALESCE(l.contacted_at, l.created_at),
  jsonb_build_object(
    'project_type',      l.project_type,
    'project_description', l.project_description,
    'budget_range',      l.budget_range,
    'timeline',          l.timeline,
    'match_score',       l.match_score,
    'location_city',     l.location_city,
    'location_state',    l.location_state,
    'response_deadline', l.response_deadline,
    'created_at',        l.created_at
  ),
  (CASE WHEN l.designer_id = (select auth.uid()) THEN 'mine' ELSE 'studio' END)::text
FROM public.leads l
LEFT JOIN public.profiles hp ON hp.id = l.homeowner_id
WHERE public.is_studio_comember(l.designer_id)
  AND l.status NOT IN ('accepted', 'declined', 'expired')

UNION ALL

-- ── MAKERS / VENDORS (saved or engaged, studio-wide) ──────────────────────
-- Unchanged from 00420.
SELECT
  v.id,
  'maker',
  v.name,
  COALESCE(v.orders_email, v.trade_account_email),
  NULL::text,
  v.contact_profile_id,
  NULL::uuid,
  auth.uid(),
  v.nomination_status,
  v.updated_at,
  jsonb_build_object(
    'primary_category',      v.primary_category,
    'lead_times',            v.lead_times,
    'default_payment_terms', v.default_payment_terms,
    'founding_circle',       v.founding_circle,
    'made_in',               v.made_in,
    'trade_terms',           v.trade_terms,
    'is_patina_catalog',     v.is_patina_catalog,
    'review_count',          v.review_count,
    'designer_rating_avg',   v.designer_rating_avg
  ),
  (CASE
     WHEN EXISTS (
       SELECT 1 FROM public.saved_vendors mine
       WHERE mine.vendor_id = v.id
         AND mine.designer_id = (select auth.uid())
     ) THEN 'mine'
     ELSE 'studio'
   END)::text
FROM public.vendors v
WHERE v.id IN (
  SELECT sv.vendor_id
  FROM public.saved_vendors sv
  WHERE public.is_studio_comember(sv.designer_id)
  UNION
  SELECT pp.vendor_id
  FROM public.project_parties pp
  JOIN public.projects pj ON pj.id = pp.project_id
  WHERE pp.vendor_id IS NOT NULL
    AND ( public.is_studio_comember(pj.designer_id)
       OR public.is_studio_comember(pj.lead_designer_id)
       OR public.is_studio_comember(pj.created_by) )
)

UNION ALL

-- ── FIELD / ROSTER PARTIES on studio projects ─────────────────────────────
-- Unchanged from 00420.
SELECT
  pp.id,
  pp.party_kind,
  pp.display_name,
  pp.email,
  pp.phone,
  pp.profile_id,
  pp.project_id,
  auth.uid(),
  pp.sms_consent_status,
  pp.updated_at,
  jsonb_build_object(
    'company_name',       pp.company_name,
    'vendor_id',          pp.vendor_id,
    'project_name',       pj.name,
    'party_kind',         pp.party_kind,
    'trade',              pp.trade,
    'phone_e164',         pp.phone_e164,
    'sms_consent_status', pp.sms_consent_status,
    'sms_consented_at',   pp.sms_consented_at,
    'sms_opt_out_at',     pp.sms_opt_out_at,
    'show_to_client',     pp.show_to_client,
    'studio_contact_id',  pp.studio_contact_id
  ),
  (CASE
     WHEN pj.designer_id      = (select auth.uid())
       OR pj.lead_designer_id = (select auth.uid())
       OR pj.created_by       = (select auth.uid())
     THEN 'mine' ELSE 'studio'
   END)::text
FROM public.project_parties pp
JOIN public.projects pj ON pj.id = pp.project_id
WHERE pp.party_kind IN ('gc', 'sub', 'installer', 'receiver',
                        'architect', 'photographer', 'stager')
  AND ( public.is_studio_comember(pj.designer_id)
     OR public.is_studio_comember(pj.lead_designer_id)
     OR public.is_studio_comember(pj.created_by) )

UNION ALL

-- ── TEAM (studio collaborators on studio projects, one row per teammate) ───
-- Unchanged from 00420.
SELECT
  t.id,
  'team',
  COALESCE(tp.full_name, tp.display_name, tp.email, 'Teammate'),
  tp.email,
  tp.phone,
  t.user_id,
  t.project_id,
  auth.uid(),
  t.role,
  t.assigned_at,
  jsonb_build_object(
    'role',         t.role,
    'project_name', t.project_name,
    'job_title',    t.job_title,
    'staff_role',   t.staff_role
  ),
  (CASE WHEN t.is_mine THEN 'mine' ELSE 'studio' END)::text
FROM (
  SELECT DISTINCT ON (tm.user_id)
    tm.id, tm.user_id, tm.role, tm.project_id, tm.assigned_at, pj.name AS project_name,
    om.job_title  AS job_title,
    om.staff_role AS staff_role,
    ( pj.designer_id      = (select auth.uid())
   OR pj.lead_designer_id = (select auth.uid())
   OR pj.created_by       = (select auth.uid()) ) AS is_mine
  FROM public.project_team_members tm
  JOIN public.projects pj ON pj.id = tm.project_id
  LEFT JOIN public.organization_members om
    ON om.user_id = tm.user_id
   AND om.organization_id = pj.studio_id
   AND om.status = 'active'
  WHERE tm.removed_at IS NULL
    AND tm.user_id <> auth.uid()
    AND tm.role IN ('lead_designer', 'support_designer', 'bookkeeper', 'previous_lead')
    AND ( public.is_studio_comember(pj.designer_id)
       OR public.is_studio_comember(pj.lead_designer_id)
       OR public.is_studio_comember(pj.created_by) )
  ORDER BY tm.user_id, tm.assigned_at DESC
) t
LEFT JOIN public.profiles tp ON tp.id = t.user_id

UNION ALL

-- ── CONTACTS (the shared rolodex, 00417) ──────────────────────────────────
-- Unchanged from 00420.
SELECT
  sc.id,
  'contact',
  COALESCE(sc.full_name, sc.company_name),
  sc.email,
  sc.phone,
  sc.profile_id,
  NULL::uuid,
  sc.created_by,
  (CASE WHEN sc.archived_at IS NULL THEN 'active' ELSE 'archived' END)::text,
  sc.updated_at,
  jsonb_build_object(
    'contact_kind',    sc.contact_kind,
    'entity_kind',     sc.entity_kind,
    'company_name',    sc.company_name,
    'company_id',      sc.company_id,
    'specialties',     sc.specialties,
    'vendor_id',       sc.vendor_id,
    'organization_id', sc.organization_id,
    'archived_at',     sc.archived_at
  ),
  (CASE WHEN sc.created_by = (select auth.uid()) THEN 'mine' ELSE 'studio' END)::text
FROM public.studio_contacts sc
WHERE public.is_active_studio_member(sc.organization_id);

