        AND index_meta.indisunique
        AND index_meta.indisvalid
        AND index_meta.indexprs IS NULL
        AND index_meta.indpred IS NOT NULL
        AND (
          SELECT array_agg(attribute.attname ORDER BY key.ordinality)
