    (SELECT oid FROM expected_oid EXCEPT SELECT oid FROM actual)
    UNION ALL
    (SELECT oid FROM actual EXCEPT SELECT oid FROM expected_oid)
  ) THEN
    RAISE EXCEPTION '00488 frozen 00485 invoice-core caller universe drifted';
  END IF;

  IF EXISTS (
    SELECT 1
    FROM pg_catalog.pg_proc AS routine
    JOIN pg_catalog.pg_namespace AS namespace ON namespace.oid = routine.pronamespace
    WHERE namespace.nspname <> 'information_schema'
      AND namespace.nspname NOT LIKE 'pg_%'
      AND (
        pg_temp._00488_call_count(routine.prosrc, 'create_draft_invoice') > 0
        OR pg_temp._00488_dynamic_mentions(routine.prosrc, 'create_draft_invoice')
      )
  ) THEN
    RAISE EXCEPTION '00488 frozen 00485 draft-invoice database caller universe is not empty';
  END IF;

  IF (SELECT count(*) FROM pg_catalog.pg_proc AS routine
      JOIN pg_catalog.pg_namespace AS namespace ON namespace.oid = routine.pronamespace
      WHERE namespace.nspname = 'public' AND routine.proname = 'create_draft_invoice') <> 1
     OR (SELECT count(*) FROM pg_catalog.pg_proc AS routine
         JOIN pg_catalog.pg_namespace AS namespace ON namespace.oid = routine.pronamespace
         WHERE namespace.nspname = 'app_private'
           AND routine.proname = 'issue_invoice_for_actor') <> 1
  THEN
    RAISE EXCEPTION '00488 frozen 00485 invoice overload universe drifted';
  END IF;

  IF EXISTS (
    WITH expected(signature, root_is_inherent) AS (VALUES
      ('public.set_project_studio_id()'::text, true),
      ('public.set_invoice_studio_id()'::text, false),
      ('public.create_draft_invoice(uuid,uuid,uuid,uuid,numeric,integer,text,text,jsonb)'::text, false),
      ('app_private.issue_invoice_for_actor(uuid,date,uuid)'::text, false),
      ('public._countersign_design_services_agreement_impl(uuid,text,jsonb)'::text, false),
      ('public._execute_furnishings_authorization_authorized(uuid,text,uuid,text)'::text, false),
      ('public._execute_furnishings_authorization_on_paper_authorized(uuid,text,date,uuid,uuid,jsonb)'::text, false),
      ('public._execute_trade_scope_authorized(uuid,text,uuid,text)'::text, false),
      ('public._execute_trade_scope_on_paper_authorized(uuid,text,date,uuid,uuid)'::text, false),
      ('public.issue_trade_draw_invoice(uuid)'::text, false)
    ), positions AS (
      SELECT expected.*,
        LEAST(
          NULLIF(position('FOR SHARE;' IN routine.prosrc), 0),
          NULLIF(position('FOR UPDATE;' IN routine.prosrc), 0)
        ) AS root_lock_position,
        position('PERFORM role.id' IN routine.prosrc) AS role_position,
        position('PERFORM user_role.id' IN routine.prosrc) AS user_role_position,
        LEAST(
          NULLIF(position('PERFORM membership.id' IN routine.prosrc), 0),
          NULLIF(position('PERFORM lead_membership.id' IN routine.prosrc), 0)
        ) AS membership_position,
        position('PERFORM studio.id' IN routine.prosrc) AS studio_position
      FROM expected
      JOIN pg_catalog.pg_proc AS routine
        ON routine.oid = pg_catalog.to_regprocedure(expected.signature)
    )
    SELECT 1 FROM positions
    WHERE role_position = 0 OR user_role_position = 0
       OR membership_position IS NULL OR studio_position = 0
       OR NOT (
         role_position < user_role_position
         AND user_role_position < membership_position
         AND membership_position < studio_position
       )
       OR (NOT root_is_inherent AND (
         root_lock_position IS NULL OR root_lock_position >= role_position
       ))
  ) THEN
    RAISE EXCEPTION '00488 frozen 00485 root/authority lock order drifted';
  END IF;

END;
$canonical_studio_source_preflight$;

DO $canonical_studio_rollback_executor$
BEGIN
  IF current_user IS DISTINCT FROM 'postgres' THEN
    RAISE EXCEPTION '00488 ordinary rollback must run as postgres';
  END IF;
END;
$canonical_studio_rollback_executor$;

-- The ordinary phase may proceed only after reserved-owner storage policies
-- are exactly source-shaped.  The platform rollback deliberately restores
-- the narrow 00488 compatibility helpers so the final-state proof above is
-- coherent before this transaction begins.

DO $canonical_studio_storage_source_sentinel$
BEGIN
  IF EXISTS (
    WITH expected(
      relation_name, policy_name, command, permissive, roles,
      source_fingerprint, final_fingerprint, platform_handoff
    ) AS (VALUES
      ('storage.objects','Designers manage proposal folio objects','*',true,ARRAY['authenticated']::text[],'5ede429cc5709eab29a2c257ac4953327802a1327b81327098e5a1535acbaf71','bee7ae78bc8f07a2310c744285e2a119f0d70cfc414bd1a219d90ecc13859f9d',true),
      ('storage.objects','Site request designers read immutable media','r',true,ARRAY['authenticated']::text[],'b1f30dc540826435b6f6e877f4793df4de60711ed72b3b5ed317170e9e57e942','fe35034e3a0496db75a9475801830fb54fb79d7e975c372af82db588a84ce467',true),
      ('storage.objects','project_ffe_working_studio_delete','d',true,ARRAY['authenticated']::text[],'2fc3e22c995c8503ca6c28b8238a8d360ac01a5f2bcee8e9ef9ca566094ae5c1','4e5e0e407ce7593d83e07ac26c8fbcdf4a3e5a873861673a4d32286b84a8bb69',true),
      ('storage.objects','project_ffe_working_studio_insert','a',true,ARRAY['authenticated']::text[],'a06aecbab06a9a9d275189e37cdce755061ed7c2f7b62d437d604383bc94fe7d','1b4ac00fcefd7c36b2c7408cc4e743c34cb8a72fba347f138e46169b64431019',true),
      ('storage.objects','project_ffe_working_studio_select','r',true,ARRAY['authenticated']::text[],'2fc3e22c995c8503ca6c28b8238a8d360ac01a5f2bcee8e9ef9ca566094ae5c1','61a4b177f97ed6e89a3554768f74af2e2b562a127782fb53851dbba8d3f68c5d',true),
      ('storage.objects','project_ffe_working_studio_update','w',true,ARRAY['authenticated']::text[],'7730555c5c5a0a7e5b465c9a37675ef8c6f56602c571fbf4f3b3e08fe6b7085e','a3d01dc8e5938bdc0ced2f923d5945b93fb0fc2f48ea3b908496b499db52b1df',true),
      ('storage.objects','proposal_mood_boards_proposal_delete','d',true,ARRAY['authenticated']::text[],'3c773dfb461ba298aad09caa33d76b13814777e6cf9698770c1d64a133c27b83','c1296eb2d205742e87c93fc2aa7c7ed62153a94ec1f6e86f149c29dbb6c4156b',true),
      ('storage.objects','proposal_mood_boards_proposal_insert','a',true,ARRAY['authenticated']::text[],'aa0b1f92c406cc783233f736f3070f18a7a490f7757849ff93eb417c8eededbe','9d241e9c66e363ec9ee79da0269fe155a6964b69c8287f5db5a7faa1b1ca0cdc',true),
      ('storage.objects','proposal_mood_boards_proposal_update','w',true,ARRAY['authenticated']::text[],'4ed278068ed7594fb5849516f391b81d9a20b2e33913bb1f2ddd9611143d83e3','9e095779ecf7eaa98bad4208d6986a354031115443e41aef04fcc911c98929e2',true)
    ), actual AS (
      SELECT expected.*, policy.oid, policy.polcmd, policy.polpermissive,
        ARRAY(
          SELECT CASE WHEN role_oid.oid = 0 THEN 'public'::text
                      ELSE role_row.rolname::text END
          FROM pg_catalog.unnest(policy.polroles) AS role_oid(oid)
          LEFT JOIN pg_catalog.pg_roles AS role_row ON role_row.oid = role_oid.oid
          ORDER BY CASE WHEN role_oid.oid = 0 THEN 'public'::text
                        ELSE role_row.rolname::text END
        ) AS actual_roles,
        pg_temp._00488_catalog_policy_fingerprint(policy.oid) AS fingerprint
      FROM expected
      LEFT JOIN pg_catalog.pg_policy AS policy
        ON policy.polrelid = pg_catalog.to_regclass(expected.relation_name)
       AND policy.polname = expected.policy_name
    )
    SELECT 1 FROM actual
    WHERE oid IS NULL OR polcmd <> command::"char"
       OR polpermissive IS DISTINCT FROM permissive
       OR actual_roles IS DISTINCT FROM roles
       OR fingerprint <> source_fingerprint
  ) OR EXISTS (
    SELECT 1
    FROM pg_catalog.pg_policy AS policy
    WHERE policy.polrelid = 'storage.objects'::pg_catalog.regclass
      AND (
        pg_temp._00488_call_count(
          COALESCE(pg_catalog.pg_get_expr(policy.polqual, policy.polrelid), '')
            || ' ' || COALESCE(
              pg_catalog.pg_get_expr(policy.polwithcheck, policy.polrelid), ''
            ), '_can_read_studio_snapshot'
        ) > 0
        OR pg_temp._00488_call_count(
          COALESCE(pg_catalog.pg_get_expr(policy.polqual, policy.polrelid), '')
            || ' ' || COALESCE(
              pg_catalog.pg_get_expr(policy.polwithcheck, policy.polrelid), ''
            ), '_can_author_studio_snapshot'
        ) > 0
      )
  ) THEN
    RAISE EXCEPTION
      '00488 ordinary rollback requires exact source storage policies first';
  END IF;
END;
$canonical_studio_storage_source_sentinel$;


-- Source has no representation for these six columns.  Even one non-NULL
-- value makes a lossless exact-source rollback impossible.
DO $canonical_studio_rollback_data_gate$
BEGIN
  IF EXISTS (SELECT 1 FROM public.proposals WHERE studio_id IS NOT NULL)
     OR EXISTS (SELECT 1 FROM public.designer_clients WHERE studio_id IS NOT NULL)
     OR EXISTS (SELECT 1 FROM public.leads WHERE studio_id IS NOT NULL)
     OR EXISTS (SELECT 1 FROM public.client_decisions WHERE studio_id IS NOT NULL)
     OR EXISTS (SELECT 1 FROM public.saved_vendors WHERE studio_id IS NOT NULL)
     OR EXISTS (SELECT 1 FROM public.phase_templates WHERE studio_id IS NOT NULL)
  THEN
    RAISE EXCEPTION
      '00488 rollback refused: a non-NULL canonical studio snapshot has no source-state representation';
  END IF;

  -- The source uniqueness surface collapses the studio dimension.  Never
  -- choose, merge, or delete a row to make these constraints fit.
  IF EXISTS (
    SELECT 1
    FROM public.designer_clients
    WHERE client_id IS NOT NULL AND status <> 'lead'
    GROUP BY designer_id, client_id
    HAVING count(*) > 1
  ) THEN
    RAISE EXCEPTION
      '00488 rollback refused: designer/client rows collide in source uniqueness';
  END IF;

  IF EXISTS (
    SELECT 1
    FROM public.designer_clients
    WHERE client_email IS NOT NULL AND client_id IS NULL
    GROUP BY designer_id, client_email
    HAVING count(*) > 1
  ) THEN
    RAISE EXCEPTION
      '00488 rollback refused: designer/email rows collide in source uniqueness';
  END IF;

  IF EXISTS (
    SELECT 1
    FROM public.saved_vendors
    GROUP BY designer_id, vendor_id
    HAVING count(*) > 1
  ) THEN
    RAISE EXCEPTION
      '00488 rollback refused: saved-vendor rows collide in source uniqueness';
  END IF;
END;
$canonical_studio_rollback_data_gate$;

-- Re-emit only bodies whose reviewed source and final hashes differ, plus the
-- four source-only RPC signatures and four legacy authority identities.
CREATE OR REPLACE FUNCTION public._can_manage_invoice_owner(p_owner uuid)
RETURNS boolean
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path = public, pg_temp
AS $$
  SELECT public._can_author_proposal(p_owner);
$$;
ALTER FUNCTION public._can_manage_invoice_owner(uuid) RESET ALL;
ALTER FUNCTION public._can_manage_invoice_owner(uuid) SET search_path = pg_catalog, public, pg_temp;
ALTER FUNCTION public._can_manage_invoice_owner(uuid) OWNER TO postgres;

CREATE OR REPLACE FUNCTION public.is_studio_comember(p_owner uuid)
RETURNS boolean
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path = public
AS $$
  SELECT p_owner IS NOT NULL AND (
    p_owner = (select auth.uid())
    OR EXISTS (
      SELECT 1
      FROM organization_members me
      JOIN organization_members owner
        ON owner.organization_id = me.organization_id
      WHERE me.user_id    = (select auth.uid())
        AND me.status     = 'active'
        AND me.role       <> 'guest'
        AND owner.user_id = p_owner
        AND owner.status  = 'active'
        AND owner.role    <> 'guest'
    )
  );
$$;
ALTER FUNCTION public.is_studio_comember(uuid) RESET ALL;
ALTER FUNCTION public.is_studio_comember(uuid) SET search_path = pg_catalog, public, pg_temp;
ALTER FUNCTION public.is_studio_comember(uuid) OWNER TO postgres;

CREATE OR REPLACE FUNCTION public.is_design_studio_comember(
  p_owner uuid
)
RETURNS boolean
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path = public, pg_temp
AS $$
  SELECT p_owner IS NOT NULL
    AND auth.uid() IS NOT NULL
    AND (
      p_owner = (SELECT auth.uid())
      OR EXISTS (
        SELECT 1
        FROM public.organization_members AS actor_membership
        JOIN public.organization_members AS owner_membership
          ON owner_membership.organization_id = actor_membership.organization_id
        JOIN public.organizations AS organization
          ON organization.id = actor_membership.organization_id
        WHERE actor_membership.user_id = (SELECT auth.uid())
          AND actor_membership.status = 'active'
          AND actor_membership.role <> 'guest'
          AND owner_membership.user_id = p_owner
          AND owner_membership.status = 'active'
          AND owner_membership.role <> 'guest'
          AND organization.type = 'design_studio'
          AND organization.status = 'active'
      )
    );
$$;
ALTER FUNCTION public.is_design_studio_comember(uuid) RESET ALL;
ALTER FUNCTION public.is_design_studio_comember(uuid) SET search_path = pg_catalog, public, pg_temp;
ALTER FUNCTION public.is_design_studio_comember(uuid) OWNER TO postgres;

CREATE OR REPLACE FUNCTION public._can_author_proposal(p_owner uuid)
RETURNS boolean
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path = public, pg_temp
AS $$
  SELECT p_owner IS NOT NULL AND (
    p_owner = (SELECT auth.uid())
    OR EXISTS (
      SELECT 1
      FROM public.organization_members AS actor_membership
      JOIN public.organization_members AS owner_membership
        ON owner_membership.organization_id = actor_membership.organization_id
      JOIN public.organizations AS organization
        ON organization.id = actor_membership.organization_id
      WHERE actor_membership.user_id = (SELECT auth.uid())
        AND actor_membership.status = 'active'
        AND actor_membership.role <> 'guest'
        AND owner_membership.user_id = p_owner
        AND owner_membership.status = 'active'
        AND owner_membership.role <> 'guest'
        AND organization.type = 'design_studio'
        AND organization.status = 'active'
    )
  );
$$;
ALTER FUNCTION public._can_author_proposal(uuid) RESET ALL;
ALTER FUNCTION public._can_author_proposal(uuid) SET search_path = pg_catalog, public, pg_temp;
ALTER FUNCTION public._can_author_proposal(uuid) OWNER TO postgres;

CREATE OR REPLACE FUNCTION public.is_active_studio_member(p_org uuid)
RETURNS boolean
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path = public
AS $$
  SELECT p_org IS NOT NULL AND EXISTS (
    SELECT 1
    FROM organization_members
    WHERE organization_id = p_org
      AND user_id = (select auth.uid())
      AND status  = 'active'
      AND role   <> 'guest'
  );
$$;
ALTER FUNCTION public.is_active_studio_member(uuid) RESET ALL;
ALTER FUNCTION public.is_active_studio_member(uuid) SET search_path = pg_catalog, public, pg_temp;
ALTER FUNCTION public.is_active_studio_member(uuid) OWNER TO postgres;

CREATE OR REPLACE FUNCTION public._can_access_product_configuration(
  p_configuration_id uuid
)
RETURNS boolean
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path = public
AS $$
  SELECT (select auth.uid()) IS NOT NULL
    AND (
      EXISTS (SELECT 1 FROM public.profiles actor WHERE actor.id = (select auth.uid()) AND actor.is_designer)
      OR EXISTS (
        SELECT 1 FROM public.organization_members actor_membership
        JOIN public.organizations actor_organization
          ON actor_organization.id = actor_membership.organization_id
        WHERE actor_membership.user_id = (select auth.uid())
          AND actor_membership.status = 'active'
          AND actor_membership.role <> 'guest'
          AND actor_organization.type = 'design_studio'
          AND actor_organization.status = 'active'
      )
    ) AND EXISTS (
    SELECT 1
    FROM public.product_configurations c
    WHERE c.id = p_configuration_id
      AND (
        c.owner_user_id = (select auth.uid())
        OR (
          c.studio_id IS NOT NULL
          AND EXISTS (
            SELECT 1 FROM public.organization_members om
            JOIN public.organizations o ON o.id = om.organization_id
            WHERE om.organization_id = c.studio_id
              AND om.user_id = (select auth.uid())
              AND om.status = 'active'
              AND om.role <> 'guest'
              AND o.type = 'design_studio'
              AND o.status = 'active'
          )
        )
        OR (
          c.project_id IS NOT NULL
          AND EXISTS (
            SELECT 1 FROM public.projects p
            WHERE p.id = c.project_id
              AND public.is_design_studio_comember(p.designer_id)
          )
        )
      )
  );
$$;
ALTER FUNCTION public._can_access_product_configuration(uuid) RESET ALL;
ALTER FUNCTION public._can_access_product_configuration(uuid) SET search_path = pg_catalog, public, pg_temp;
ALTER FUNCTION public._can_access_product_configuration(uuid) OWNER TO postgres;

CREATE OR REPLACE FUNCTION public._create_project_approval_decision_checked(
  p_project_id uuid,
  p_payload jsonb,
  p_idempotency_key text,
  p_predecessor_decision_id uuid
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, pg_temp
AS $$
DECLARE
  v_actor uuid := auth.uid();
  v_project public.projects%ROWTYPE;
  v_authority public.project_decision_authorities%ROWTYPE;
  v_relationship public.designer_clients%ROWTYPE;
  v_receipt public.project_approval_action_receipts%ROWTYPE;
  v_source record;
  v_unknown jsonb;
  v_title text;
  v_question text;
  v_context text;
  v_due_at timestamptz;
  v_phase_id uuid;
  v_section_key text;
  v_source_kind text;
  v_source_id uuid;
  v_cost_delta integer;
  v_schedule_delta integer;
  v_lead_delta integer;
  v_key text := btrim(COALESCE(p_idempotency_key, ''));
  v_request jsonb;
  v_request_hash text;
  v_decision_id uuid := extensions.gen_random_uuid();
  v_snapshot_id uuid := extensions.gen_random_uuid();
  v_artifact_id uuid := extensions.gen_random_uuid();
  v_receipt_id uuid := extensions.gen_random_uuid();
  v_decision_updated_at timestamptz;
  v_result jsonb;
  v_previous_decision_insert text := current_setting(
    'app.project_approval_decision_insert_id', true
  );
  v_previous_option_insert text := current_setting(
    'app.project_approval_option_decision_id', true
  );
  v_previous_evidence_insert text := current_setting(
    'app.project_approval_evidence_decision_id', true
  );
BEGIN
  IF v_actor IS NULL THEN
    RAISE EXCEPTION 'project approval creation requires an authenticated studio actor'
      USING ERRCODE = 'insufficient_privilege';
  END IF;
  IF p_payload IS NULL OR jsonb_typeof(p_payload) <> 'object' THEN
    RAISE EXCEPTION 'p_payload must be a JSON object'
      USING ERRCODE = 'invalid_parameter_value';
  END IF;
  IF v_key = '' OR char_length(v_key) > 200 THEN
    RAISE EXCEPTION 'idempotency key must contain 1 to 200 characters'
      USING ERRCODE = 'invalid_parameter_value';
  END IF;

  v_unknown := p_payload - ARRAY[
    'title', 'question', 'context', 'dueAt', 'phaseId', 'sectionKey',
    'artifactKind', 'artifactId', 'costCentsDelta',
    'scheduleDaysDelta', 'leadTimeDaysDelta'
  ];
  IF v_unknown <> '{}'::jsonb THEN
    RAISE EXCEPTION 'unsupported project approval payload keys: %', v_unknown
      USING ERRCODE = 'invalid_parameter_value';
  END IF;

  v_title := btrim(COALESCE(p_payload->>'title', ''));
  v_question := btrim(COALESCE(p_payload->>'question', ''));
  v_context := NULLIF(btrim(COALESCE(p_payload->>'context', '')), '');
  IF char_length(v_title) NOT BETWEEN 1 AND 240 THEN
    RAISE EXCEPTION 'approval title must contain 1 to 240 characters'
      USING ERRCODE = 'check_violation';
  END IF;
  IF char_length(v_question) NOT BETWEEN 1 AND 500 THEN
    RAISE EXCEPTION 'approval question must contain 1 to 500 characters'
      USING ERRCODE = 'check_violation';
  END IF;
  IF NOT (p_payload ? 'dueAt')
     OR NULLIF(p_payload->>'dueAt', '') IS NULL
  THEN
    RAISE EXCEPTION 'approval dueAt is required'
      USING ERRCODE = 'check_violation';
  END IF;
  v_due_at := (p_payload->>'dueAt')::timestamptz;

  IF NOT (p_payload ? 'phaseId')
     OR NULLIF(p_payload->>'phaseId', '') IS NULL
  THEN
    RAISE EXCEPTION 'approval phaseId is required'
      USING ERRCODE = 'check_violation';
  END IF;
  v_phase_id := (p_payload->>'phaseId')::uuid;
  v_section_key := NULLIF(p_payload->>'sectionKey', '');
  v_source_kind := NULLIF(p_payload->>'artifactKind', '');
  v_source_id := NULLIF(p_payload->>'artifactId', '')::uuid;
  IF v_source_kind IS NULL OR v_source_id IS NULL THEN
    RAISE EXCEPTION 'one artifactKind and artifactId are required'
      USING ERRCODE = 'check_violation';
  END IF;

  IF NOT (p_payload ?& ARRAY[
       'costCentsDelta', 'scheduleDaysDelta', 'leadTimeDaysDelta'
     ])
     OR jsonb_typeof(p_payload->'costCentsDelta') <> 'number'
     OR jsonb_typeof(p_payload->'scheduleDaysDelta') <> 'number'
     OR jsonb_typeof(p_payload->'leadTimeDaysDelta') <> 'number'
     OR p_payload->>'costCentsDelta' !~ '^-?[0-9]+$'
     OR p_payload->>'scheduleDaysDelta' !~ '^-?[0-9]+$'
     OR p_payload->>'leadTimeDaysDelta' !~ '^-?[0-9]+$'
  THEN
    RAISE EXCEPTION 'all three signed integer impact deltas are required'
      USING ERRCODE = 'check_violation';
  END IF;
  BEGIN
    v_cost_delta := (p_payload->>'costCentsDelta')::integer;
    v_schedule_delta := (p_payload->>'scheduleDaysDelta')::integer;
    v_lead_delta := (p_payload->>'leadTimeDaysDelta')::integer;
  EXCEPTION WHEN numeric_value_out_of_range THEN
    RAISE EXCEPTION 'impact deltas must fit signed int32'
      USING ERRCODE = 'numeric_value_out_of_range';
  END;

  v_request := jsonb_build_object(
    'projectId', p_project_id,
    'predecessorDecisionId', p_predecessor_decision_id,
    'title', v_title,
    'question', v_question,
    'context', v_context,
    'dueAt', v_due_at,
    'phaseId', v_phase_id,
    'sectionKey', v_section_key,
    'artifactKind', v_source_kind,
    'artifactId', v_source_id,
    'costCentsDelta', v_cost_delta,
    'scheduleDaysDelta', v_schedule_delta,
    'leadTimeDaysDelta', v_lead_delta
  );
  v_request_hash := public._project_approval_hash(v_request);

  SELECT * INTO v_project
  FROM public.projects AS project
  WHERE project.id = p_project_id
  FOR UPDATE;
  IF NOT FOUND OR NOT public.is_design_studio_comember(v_project.designer_id) THEN
    RAISE EXCEPTION 'project not found or approval creation denied'
      USING ERRCODE = 'insufficient_privilege';
  END IF;

  SELECT * INTO v_receipt
  FROM public.project_approval_action_receipts AS receipt
  WHERE receipt.project_id = p_project_id
    AND receipt.action_kind = 'created'
    AND receipt.idempotency_key = v_key
  FOR UPDATE;
  IF FOUND THEN
    IF v_receipt.request_hash IS DISTINCT FROM v_request_hash
       OR v_receipt.actor_id IS DISTINCT FROM v_actor
    THEN
      RAISE EXCEPTION 'idempotency key was reused with a different create request'
        USING ERRCODE = 'unique_violation';
    END IF;
    RETURN v_receipt.result || jsonb_build_object('idempotent', true);
  END IF;
  IF v_due_at <= now() THEN
    RAISE EXCEPTION 'approval dueAt must be in the future'
      USING ERRCODE = 'check_violation';
  END IF;

  SELECT * INTO v_authority
  FROM public.project_decision_authorities AS authority
  WHERE authority.project_id = p_project_id
  FOR SHARE;
  IF NOT FOUND
     OR v_project.client_id IS NULL
     OR v_authority.decision_lead_id IS DISTINCT FROM v_project.client_id
     OR v_authority.required_coapprover_id IS NOT NULL
  THEN
    RAISE EXCEPTION 'project has no valid explicit household approval authority'
      USING ERRCODE = 'check_violation';
  END IF;

  SELECT * INTO v_relationship
  FROM public.designer_clients AS relationship
  WHERE relationship.designer_id = v_project.designer_id
    AND relationship.client_id = v_project.client_id
    AND relationship.status = 'active'
  ORDER BY relationship.created_at, relationship.id
  LIMIT 1;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'project has no exact active designer-client relationship'
      USING ERRCODE = 'check_violation';
  END IF;
  IF NOT EXISTS (
    SELECT 1 FROM public.project_phases AS phase
    WHERE phase.id = v_phase_id AND phase.project_id = p_project_id
  ) THEN
    RAISE EXCEPTION 'approval phase must belong to the project'
      USING ERRCODE = 'check_violation';
  END IF;
  IF p_predecessor_decision_id IS NOT NULL
     AND NOT EXISTS (
       SELECT 1
       FROM public.client_decisions AS predecessor
       WHERE predecessor.id = p_predecessor_decision_id
         AND predecessor.project_id = p_project_id
         AND predecessor.approval_contract = 'project_artifact_v1'
     )
  THEN
    RAISE EXCEPTION 'Stage-2 predecessor must belong to the same project'
      USING ERRCODE = 'check_violation';
  END IF;

  SELECT * INTO v_source
  FROM public._resolve_project_approval_artifact(
    p_project_id, v_source_kind, v_source_id
  );

  PERFORM set_config(
    'app.project_approval_decision_insert_id', v_decision_id::text, true
  );
  INSERT INTO public.client_decisions (
    id, designer_client_id, project_id, title, context, due_date,
    status, decision_type, decision_kind, coordination_kind,
    blocking_status, blocks_kind, court, designer_id, phase_id,
    section_key, approval_contract, predecessor_decision_id
  ) VALUES (
    v_decision_id, v_relationship.id, p_project_id, v_title, v_context, v_due_at,
    'draft', 'approval', 'approval', 'signoff',
    'blocks_phase', 'phase',
    'client', v_project.designer_id, v_phase_id, v_section_key,
    'project_artifact_v1', p_predecessor_decision_id
  ) RETURNING updated_at INTO v_decision_updated_at;
  PERFORM set_config(
    'app.project_approval_decision_insert_id',
    COALESCE(v_previous_decision_insert, ''), true
  );

  PERFORM set_config(
    'app.project_approval_evidence_decision_id', v_decision_id::text, true
  );
  INSERT INTO public.project_decision_authority_snapshots (
    id, decision_id, project_id, decision_lead_id,
    required_coapprover_id, authority_revision, assigned_by
  ) VALUES (
    v_snapshot_id, v_decision_id, p_project_id,
    v_authority.decision_lead_id, v_authority.required_coapprover_id,
    v_authority.revision, v_authority.assigned_by
  );

  PERFORM set_config(
    'app.project_approval_option_decision_id', v_decision_id::text, true
  );
  INSERT INTO public.client_decision_options (
    decision_id, name, designer_note, quantity, cost_delta_cents,
    lead_time_days_delta, approves, selected, sort_order,
    approval_outcome, cost_cents_delta, schedule_days_delta
  ) VALUES
    (v_decision_id, 'Approved', NULL, 1, v_cost_delta,
     v_lead_delta, true, false, 0, 'approved', v_cost_delta, v_schedule_delta),
    (v_decision_id, 'Changes requested', NULL, 1, v_cost_delta,
     v_lead_delta, false, false, 1, 'changes_requested', v_cost_delta, v_schedule_delta),
    (v_decision_id, 'Needs discussion', NULL, 1, v_cost_delta,
     v_lead_delta, false, false, 2, 'needs_discussion', v_cost_delta, v_schedule_delta);
  PERFORM set_config(
    'app.project_approval_option_decision_id',
    COALESCE(v_previous_option_insert, ''), true
  );

  INSERT INTO public.project_approval_artifacts (
    id, decision_id, project_id, source_kind, source_id, source_version,
    artifact_hash, artifact_title, question, context, due_at, phase_id,
    cost_cents_delta, schedule_days_delta, lead_time_days_delta,
    source_snapshot
  ) VALUES (
    v_artifact_id, v_decision_id, p_project_id, v_source_kind, v_source_id,
    v_source.source_version, v_source.artifact_hash, v_source.artifact_title,
    v_question, v_context, v_due_at, v_phase_id,
    v_cost_delta, v_schedule_delta, v_lead_delta, v_source.safe_snapshot
  );

  v_result := jsonb_build_object(
    'receiptId', v_receipt_id,
    'projectId', p_project_id,
    'decisionId', v_decision_id,
    'authoritySnapshotId', v_snapshot_id,
    'artifactId', v_artifact_id,
    'artifactHash', v_source.artifact_hash,
    'authorityRevision', v_authority.revision,
    'predecessorDecisionId', p_predecessor_decision_id,
    'updatedAt', v_decision_updated_at,
    'status', 'draft'
  );
  INSERT INTO public.project_approval_action_receipts (
    id, project_id, decision_id, action_kind, idempotency_key,
    request_hash, actor_id, result
  ) VALUES (
    v_receipt_id, p_project_id, v_decision_id, 'created', v_key,
    v_request_hash, v_actor, v_result
  );
  PERFORM set_config(
    'app.project_approval_evidence_decision_id',
    COALESCE(v_previous_evidence_insert, ''), true
  );

  RETURN v_result || jsonb_build_object('idempotent', false);
EXCEPTION WHEN OTHERS THEN
  PERFORM set_config(
    'app.project_approval_decision_insert_id',
    COALESCE(v_previous_decision_insert, ''), true
  );
  PERFORM set_config(
    'app.project_approval_option_decision_id',
    COALESCE(v_previous_option_insert, ''), true
  );
  PERFORM set_config(
    'app.project_approval_evidence_decision_id',
    COALESCE(v_previous_evidence_insert, ''), true
  );
  RAISE;
END;
$$;
ALTER FUNCTION public._create_project_approval_decision_checked(uuid,jsonb,text,uuid) RESET ALL;
ALTER FUNCTION public._create_project_approval_decision_checked(uuid,jsonb,text,uuid) SET search_path = pg_catalog, public, pg_temp;
ALTER FUNCTION public._create_project_approval_decision_checked(uuid,jsonb,text,uuid) OWNER TO postgres;

CREATE OR REPLACE FUNCTION public._ffe_require_studio_project(p_project_id uuid)
RETURNS public.projects
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public', 'pg_temp'
AS $$
DECLARE v_project public.projects%ROWTYPE;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'authentication required'
      USING ERRCODE = 'insufficient_privilege';
  END IF;
  SELECT * INTO v_project FROM public.projects WHERE id = p_project_id;
  IF NOT FOUND OR NOT public.is_studio_comember(v_project.designer_id) THEN
    RAISE EXCEPTION 'project not found or access denied'
      USING ERRCODE = 'insufficient_privilege';
  END IF;
  RETURN v_project;
END;
$$;
ALTER FUNCTION public._ffe_require_studio_project(uuid) RESET ALL;
ALTER FUNCTION public._ffe_require_studio_project(uuid) SET search_path = pg_catalog, public, pg_temp;
ALTER FUNCTION public._ffe_require_studio_project(uuid) OWNER TO postgres;

CREATE OR REPLACE FUNCTION public._issue_design_services_agreement_on_paper(
  p_proposal_id uuid
)
RETURNS void
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, pg_temp
AS $$
DECLARE
  v_issuer uuid := auth.uid();
  v_proposal public.proposals%ROWTYPE;
  v_previous_commercial text := current_setting('app.commercial_document_id', true);
  v_previous_send text := current_setting('app.proposal_send_id', true);
BEGIN
  IF v_issuer IS NULL THEN
    RAISE EXCEPTION 'issuing a design services agreement on paper requires an authenticated studio author'
      USING ERRCODE = 'insufficient_privilege';
  END IF;

  SELECT * INTO v_proposal FROM public.proposals
  WHERE id = p_proposal_id FOR UPDATE;
  IF NOT FOUND OR NOT public._can_author_proposal(v_proposal.designer_id)
     OR v_proposal.client_id IS NULL
     OR v_proposal.document_kind NOT IN ('design_services', 'service_addendum')
  THEN
    RAISE EXCEPTION 'design services agreement % not found or access denied', p_proposal_id
      USING ERRCODE = 'insufficient_privilege';
  END IF;

  -- Says what it found. The caller asked to issue a document still in the
  -- studio's hands; if it is not one, that is the answer, not a silent
  -- fall-through into a different act.
  IF COALESCE(v_proposal.commercial_state, 'draft') IS DISTINCT FROM 'draft' THEN
    RAISE EXCEPTION 'design services agreement % is not issuable on paper (%)',
      p_proposal_id, COALESCE(v_proposal.commercial_state, 'NULL')
      USING ERRCODE = 'check_violation';
  END IF;

  -- send's exact-client-relationship bar (00423:1598-1608), in send's words.
  -- The emailed rail refuses a document whose designer_client_id names a
  -- different household than client_id; the paper door is the same issuance by
  -- another route, so it refuses it too.
  IF v_proposal.designer_client_id IS NULL
     OR NOT EXISTS (
       SELECT 1 FROM public.designer_clients dc
       WHERE dc.id = v_proposal.designer_client_id
         AND dc.designer_id = v_proposal.designer_id
         AND dc.client_id = v_proposal.client_id
     )
  THEN
    RAISE EXCEPTION 'commercial document requires an exact client relationship before sending'
      USING ERRCODE = 'check_violation';
  END IF;

  IF NOT EXISTS (SELECT 1 FROM public.proposal_service_terms t WHERE t.proposal_id = p_proposal_id)
     OR NOT EXISTS (SELECT 1 FROM public.proposal_service_rates r WHERE r.proposal_id = p_proposal_id)
  THEN
    RAISE EXCEPTION 'design services agreement requires terms and at least one role rate'
      USING ERRCODE = 'check_violation';
  END IF;

  -- Both GUCs, one UPDATE: app.proposal_send_id is what 00387's
  -- guard_proposal_authority requires before status may enter 'sent', and
  -- app.commercial_document_id is what 00412's guard requires before
  -- commercial_state or either stamp may move. sent_at is deliberately absent —
  -- nothing was sent.
  PERFORM set_config('app.commercial_document_id', p_proposal_id::text, true);
  PERFORM set_config('app.proposal_send_id', p_proposal_id::text, true);
  UPDATE public.proposals SET
    status = 'sent',
    commercial_state = 'sent',
    issued_on_paper = true,
    paper_issued_by = v_issuer,
    updated_at = now()
  WHERE id = p_proposal_id;
  PERFORM set_config('app.proposal_send_id', COALESCE(v_previous_send, ''), true);
  PERFORM set_config('app.commercial_document_id', COALESCE(v_previous_commercial, ''), true);
EXCEPTION WHEN OTHERS THEN
  PERFORM set_config('app.proposal_send_id', COALESCE(v_previous_send, ''), true);
  PERFORM set_config('app.commercial_document_id', COALESCE(v_previous_commercial, ''), true);
  RAISE;
END;
$$;
ALTER FUNCTION public._issue_design_services_agreement_on_paper(uuid) RESET ALL;
ALTER FUNCTION public._issue_design_services_agreement_on_paper(uuid) SET search_path = pg_catalog, public, pg_temp;
ALTER FUNCTION public._issue_design_services_agreement_on_paper(uuid) OWNER TO postgres;

CREATE OR REPLACE FUNCTION public._prepare_legacy_proposal_phase_insert(
  p_proposal_id uuid,
  p_requested_follows_phase_id uuid
)
RETURNS TABLE(follows_phase_id uuid, sort_order integer)
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, pg_temp
AS $$
DECLARE
  v_proposal public.proposals%ROWTYPE;
  v_tail uuid;
  v_sort integer;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'proposal phase insert requires an authenticated user'
      USING ERRCODE = 'insufficient_privilege';
  END IF;

  SELECT * INTO v_proposal
  FROM public.proposals
  WHERE id = p_proposal_id
  FOR UPDATE;
  IF NOT FOUND OR NOT public._can_author_proposal(v_proposal.designer_id) THEN
    RAISE EXCEPTION 'proposal % not found or access denied', p_proposal_id
      USING ERRCODE = 'insufficient_privilege';
  END IF;
  IF v_proposal.status <> 'draft' THEN
    RAISE EXCEPTION 'proposal % is %, so its authored copy is immutable',
      p_proposal_id, v_proposal.status
      USING ERRCODE = 'check_violation';
  END IF;

  PERFORM phase.id
  FROM public.proposal_phases AS phase
  WHERE phase.proposal_id = p_proposal_id
  ORDER BY phase.id
  FOR UPDATE;

  v_tail := public._proposal_phase_main_tail(
    p_proposal_id, 'legacy proposal phase insert precondition'
  );
  IF p_requested_follows_phase_id IS NOT NULL
     AND p_requested_follows_phase_id IS DISTINCT FROM v_tail
  THEN
    RAISE EXCEPTION
      'legacy proposal phase predecessor must be the canonical main tail'
      USING ERRCODE = 'check_violation';
  END IF;

  SELECT COALESCE(max(phase.sort_order), -1) + 1
  INTO v_sort
  FROM public.proposal_phases AS phase
  WHERE phase.proposal_id = p_proposal_id;

  follows_phase_id := v_tail;
  sort_order := v_sort;
  RETURN NEXT;
END;
$$;
ALTER FUNCTION public._prepare_legacy_proposal_phase_insert(uuid,uuid) RESET ALL;
ALTER FUNCTION public._prepare_legacy_proposal_phase_insert(uuid,uuid) SET search_path = pg_catalog, public, pg_temp;
ALTER FUNCTION public._prepare_legacy_proposal_phase_insert(uuid,uuid) OWNER TO postgres;

