CREATE OR REPLACE FUNCTION public.activate_proposal_as_project(p_proposal_id uuid,p_start_date date DEFAULT CURRENT_DATE)
RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'public','pg_temp'
AS $$
DECLARE v_designer_id uuid; v_document_kind text; v_commercial_state text; v_project_id uuid;
BEGIN
  IF auth.uid() IS NULL THEN RAISE EXCEPTION 'activate_proposal_as_project requires an authenticated studio author' USING ERRCODE='insufficient_privilege'; END IF;
  SELECT proposal.designer_id,proposal.document_kind,proposal.commercial_state INTO v_designer_id,v_document_kind,v_commercial_state FROM public.proposals proposal WHERE proposal.id=p_proposal_id FOR UPDATE;
  IF NOT FOUND OR NOT public._can_author_proposal(v_designer_id) THEN RAISE EXCEPTION 'activate_proposal_as_project: proposal % not found or access denied',p_proposal_id USING ERRCODE='insufficient_privilege'; END IF;
  IF v_document_kind<>'legacy' THEN RAISE EXCEPTION 'commercial documents activate only through their dedicated execution RPC' USING ERRCODE='check_violation'; END IF;
  IF v_commercial_state='superseded' THEN RAISE EXCEPTION 'superseded proposal % cannot be activated',p_proposal_id USING ERRCODE='check_violation'; END IF;
  PERFORM set_config('app.ffe_mutation_rpc','on',true); PERFORM set_config('app.board_state_rpc','on',true);
  v_project_id:=public._activate_proposal_as_project_authorized(p_proposal_id,p_start_date);
  PERFORM public._reconcile_activated_ffe_placements(v_project_id);
  RETURN v_project_id;
END;
$$;
ALTER FUNCTION public.activate_proposal_as_project(uuid,date) RESET ALL;
ALTER FUNCTION public.activate_proposal_as_project(uuid,date) SET search_path = pg_catalog, public, pg_temp;
ALTER FUNCTION public.activate_proposal_as_project(uuid,date) OWNER TO postgres;

CREATE OR REPLACE FUNCTION public.apply_decision(
  p_decision_id uuid,
  p_selected_option_id uuid,
  p_selected_by uuid DEFAULT NULL
)
RETURNS void
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, pg_temp
AS $$
DECLARE
  v_actor uuid := auth.uid();
  v_client_id uuid;
  v_designer_id uuid;
  v_coordination_kind text;
  v_court text;
  v_client_consent_method text;
  v_client_signature text;
BEGIN
  IF v_actor IS NULL THEN
    RAISE EXCEPTION 'apply_decision requires an authenticated user'
      USING ERRCODE = 'insufficient_privilege';
  END IF;

  SELECT relationship.client_id, decision.designer_id,
         decision.coordination_kind, decision.court,
         decision.client_consent_method, decision.client_signature
  INTO v_client_id, v_designer_id, v_coordination_kind, v_court,
       v_client_consent_method, v_client_signature
  FROM public.client_decisions AS decision
  JOIN public.designer_clients AS relationship
    ON relationship.id = decision.designer_client_id
  WHERE decision.id = p_decision_id
  FOR UPDATE OF decision
  FOR SHARE OF relationship;

  IF v_client_id IS NOT DISTINCT FROM v_actor THEN
    IF v_coordination_kind IS DISTINCT FROM 'selection'
       OR v_court IS DISTINCT FROM 'client'
    THEN
      RAISE EXCEPTION
        'only client-court selection decisions may be applied by the addressed client'
        USING ERRCODE = 'insufficient_privilege';
    END IF;
    IF p_selected_by IS NOT NULL AND p_selected_by IS DISTINCT FROM v_actor THEN
      RAISE EXCEPTION 'p_selected_by must match the authenticated client'
        USING ERRCODE = 'insufficient_privilege';
    END IF;

    PERFORM public._apply_client_decision_authorized(
      p_decision_id, p_selected_option_id, v_actor,
      v_client_consent_method, v_client_signature, NULL, NULL
    );
    RETURN;
  END IF;

  IF public._can_author_proposal(v_designer_id)
     AND (
       v_coordination_kind IS DISTINCT FROM 'selection'
       OR v_court IS DISTINCT FROM 'client'
     )
  THEN
    RAISE EXCEPTION
      'only client-court selection decisions may be overridden through an option'
      USING ERRCODE = 'insufficient_privilege';
  END IF;

  IF public._can_author_proposal(v_designer_id)
     AND p_selected_by IS NOT DISTINCT FROM COALESCE(v_client_id, v_actor)
     AND EXISTS (
       SELECT 1
       FROM public.decision_overrides AS override
       WHERE override.decision_id = p_decision_id
         AND override.option_id = p_selected_option_id
         AND override.acted_by = v_actor
         AND override.consent_method IN (
           'verbal', 'written', 'text_excerpt', 'email_excerpt'
         )
         AND btrim(override.consent_evidence) <> ''
     )
  THEN
    PERFORM public._apply_client_decision_authorized(
      p_decision_id, p_selected_option_id, v_actor,
      NULL, NULL, NULL, NULL
    );
    RETURN;
  END IF;

  RAISE EXCEPTION
    'apply_decision requires the addressed client or an audited studio override'
    USING ERRCODE = 'insufficient_privilege';

END;
$$;
ALTER FUNCTION public.apply_decision(uuid,uuid,uuid) RESET ALL;
ALTER FUNCTION public.apply_decision(uuid,uuid,uuid) SET search_path = pg_catalog, public, pg_temp;
ALTER FUNCTION public.apply_decision(uuid,uuid,uuid) OWNER TO postgres;

CREATE OR REPLACE FUNCTION public.apply_decision_override(
  p_decision_id uuid,
  p_selected_option_id uuid,
  p_consent_method text,
  p_consent_evidence text
)
RETURNS public.client_decisions
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, pg_temp
AS $$
DECLARE
  v_actor uuid := auth.uid();
  v_decision public.client_decisions%ROWTYPE;
BEGIN
  IF v_actor IS NULL THEN
    RAISE EXCEPTION 'apply_decision_override requires an authenticated user'
      USING ERRCODE = 'insufficient_privilege';
  END IF;
  IF p_consent_method NOT IN ('verbal', 'written', 'text_excerpt', 'email_excerpt')
     OR btrim(COALESCE(p_consent_evidence, '')) = ''
  THEN
    RAISE EXCEPTION 'valid override consent evidence is required'
      USING ERRCODE = 'check_violation';
  END IF;

  SELECT * INTO v_decision
  FROM public.client_decisions
  WHERE id = p_decision_id
  FOR UPDATE;

  IF NOT FOUND OR NOT public._can_author_proposal(v_decision.designer_id) THEN
    RAISE EXCEPTION 'decision % not found or access denied', p_decision_id
      USING ERRCODE = 'insufficient_privilege';
  END IF;

  IF v_decision.coordination_kind IS DISTINCT FROM 'selection'
     OR v_decision.court IS DISTINCT FROM 'client'
  THEN
    RAISE EXCEPTION
      'only client-court selection decisions may be overridden through an option'
      USING ERRCODE = 'insufficient_privilege';
  END IF;

  -- A retry of the already-winning override is a read-only receipt. Do not add
  -- duplicate evidence rows; a different winner is rejected by the locked core.
  IF v_decision.status = 'responded' THEN
    RETURN public._apply_client_decision_authorized(
      p_decision_id, p_selected_option_id, v_actor, NULL, NULL, NULL, NULL
    );
  END IF;
  IF v_decision.status <> 'pending' THEN
    RAISE EXCEPTION 'decision % cannot be overridden from status %',
      p_decision_id, v_decision.status
      USING ERRCODE = 'check_violation';
  END IF;

  INSERT INTO public.decision_overrides (
    decision_id, option_id, acted_by, consent_method, consent_evidence
  ) VALUES (
    p_decision_id, p_selected_option_id, v_actor,
    p_consent_method, btrim(p_consent_evidence)
  );

  RETURN public._apply_client_decision_authorized(
    p_decision_id, p_selected_option_id, v_actor, NULL, NULL, NULL, NULL
  );
END;
$$;
ALTER FUNCTION public.apply_decision_override(uuid,uuid,text,text) RESET ALL;
ALTER FUNCTION public.apply_decision_override(uuid,uuid,text,text) SET search_path = pg_catalog, public, pg_temp;
ALTER FUNCTION public.apply_decision_override(uuid,uuid,text,text) OWNER TO postgres;

CREATE OR REPLACE FUNCTION public.apply_phase_template(
  p_proposal_id uuid,
  p_template_slug text,
  p_request_id uuid
)
RETURNS SETOF uuid
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, pg_temp
AS $$
DECLARE
  v_actor uuid := auth.uid();
  v_proposal public.proposals%ROWTYPE;
  v_template public.phase_templates%ROWTYPE;
  v_receipt public.proposal_phase_template_applications%ROWTYPE;
  v_phase_data jsonb;
  v_phase_id uuid;
  v_prev_phase_id uuid;
  v_deliverable jsonb;
  v_gate jsonb;
  v_max_sort integer;
  v_existing_count integer;
  v_prefix_mismatch_count integer;
  v_recovered_prefix_count integer := 0;
  v_existing record;
  v_inserted_phase_ids uuid[] := '{}'::uuid[];
  v_effect_phase_ids uuid[] := '{}'::uuid[];
  v_effective_phases jsonb;
  v_legacy_default_phases jsonb := '[
    {
      "name":"Schematic Design",
      "phase_key":"concept_development",
      "duration_weeks":3,
      "fee_cents":250000,
      "revision_limit":2
    },
    {
      "name":"Design Development",
      "phase_key":"design_refinement",
      "duration_weeks":4,
      "fee_cents":350000,
      "revision_limit":2
    },
    {
      "name":"Procurement Management",
      "phase_key":"procurement",
      "duration_weeks":8,
      "fee_cents":200000,
      "revision_limit":1
    },
    {
      "name":"Installation & Styling",
      "phase_key":"installation",
      "duration_weeks":3,
      "fee_cents":150000,
      "revision_limit":1
    },
    {
      "name":"Completion & Handover",
      "phase_key":"final_walkthrough",
      "duration_weeks":1,
      "fee_cents":50000,
      "revision_limit":0
    }
  ]'::jsonb;
  v_return_id uuid;
BEGIN
  IF v_actor IS NULL THEN
    RAISE EXCEPTION 'apply_phase_template requires an authenticated user'
      USING ERRCODE = 'insufficient_privilege';
  END IF;
  IF p_request_id IS NULL THEN
    RAISE EXCEPTION 'p_request_id is required'
      USING ERRCODE = 'invalid_parameter_value';
  END IF;

  SELECT * INTO v_proposal
  FROM public.proposals
  WHERE id = p_proposal_id
  FOR UPDATE;

  IF NOT FOUND OR NOT public._can_author_proposal(v_proposal.designer_id) THEN
    RAISE EXCEPTION 'proposal % not found or access denied', p_proposal_id
      USING ERRCODE = 'insufficient_privilege';
  END IF;

  SELECT * INTO v_receipt
  FROM public.proposal_phase_template_applications
  WHERE proposal_id = p_proposal_id
    AND request_id = p_request_id
  FOR UPDATE;
  IF FOUND THEN
    IF v_receipt.template_slug IS DISTINCT FROM p_template_slug
       OR EXISTS (
         SELECT 1
         FROM unnest(v_receipt.phase_ids) AS receipt_phase(id)
         WHERE NOT EXISTS (
           SELECT 1
           FROM public.proposal_phases AS phase
           WHERE phase.id = receipt_phase.id
             AND phase.proposal_id = p_proposal_id
         )
       )
       OR v_receipt.effect_snapshot IS DISTINCT FROM
            public._proposal_phase_effect_snapshot(
              p_proposal_id, v_receipt.phase_ids
            )
    THEN
      RAISE EXCEPTION 'template request % conflicts with its recorded effect',
        p_request_id
        USING ERRCODE = 'serialization_failure';
    END IF;
    FOREACH v_return_id IN ARRAY v_receipt.phase_ids LOOP
      RETURN NEXT v_return_id;
    END LOOP;
    RETURN;
  END IF;

  -- A named template is one compositional act per proposal, even when two
  -- browser tabs initiate that act with different request UUIDs. The proposal
  -- row lock above serializes both callers. Preserve the later request as an
  -- alias to the first durable effect so its retries remain exact as well.
  SELECT * INTO v_receipt
  FROM public.proposal_phase_template_applications
  WHERE proposal_id = p_proposal_id
    AND template_slug = p_template_slug
  ORDER BY created_at, request_id
  LIMIT 1
  FOR UPDATE;
  IF FOUND THEN
    IF EXISTS (
      SELECT 1
      FROM unnest(v_receipt.phase_ids) AS receipt_phase(id)
      WHERE NOT EXISTS (
        SELECT 1
        FROM public.proposal_phases AS phase
        WHERE phase.id = receipt_phase.id
          AND phase.proposal_id = p_proposal_id
      )
    ) OR v_receipt.effect_snapshot IS DISTINCT FROM
           public._proposal_phase_effect_snapshot(
             p_proposal_id, v_receipt.phase_ids
           )
    THEN
      RAISE EXCEPTION
        'template % was already applied but its recorded effect changed',
        p_template_slug
        USING ERRCODE = 'serialization_failure';
    END IF;

    INSERT INTO public.proposal_phase_template_applications (
      request_id, proposal_id, template_slug, phase_ids,
      effect_snapshot, created_by
    ) VALUES (
      p_request_id, p_proposal_id, p_template_slug,
      v_receipt.phase_ids, v_receipt.effect_snapshot, v_actor
    );

    FOREACH v_return_id IN ARRAY v_receipt.phase_ids LOOP
      RETURN NEXT v_return_id;
    END LOOP;
    RETURN;
  END IF;

  IF v_proposal.status <> 'draft' THEN
    RAISE EXCEPTION 'proposal % is %, so its authored copy is immutable',
      p_proposal_id, v_proposal.status
      USING ERRCODE = 'check_violation';
  END IF;

  SELECT * INTO v_template
  FROM public.phase_templates
  WHERE slug = p_template_slug
    AND (is_system OR public._can_author_proposal(designer_id))
  FOR SHARE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'template not found or access denied: %', p_template_slug
      USING ERRCODE = 'insufficient_privilege';
  END IF;
  IF jsonb_typeof(v_template.phases) <> 'array'
     OR jsonb_array_length(v_template.phases) = 0
  THEN
    RAISE EXCEPTION 'template % has no valid phases', p_template_slug
      USING ERRCODE = 'check_violation';
  END IF;
  v_effective_phases := v_template.phases;

  PERFORM phase.id
  FROM public.proposal_phases AS phase
  WHERE phase.proposal_id = p_proposal_id
  ORDER BY phase.id
  FOR UPDATE;

  SELECT count(*) INTO v_existing_count
  FROM public.proposal_phases
  WHERE proposal_id = p_proposal_id;

  IF p_template_slug = 'patina_six'
     AND v_existing_count BETWEEN 1 AND 5
  THEN
    WITH ordered_existing AS (
      SELECT phase.*,
             row_number() OVER (ORDER BY phase.sort_order, phase.id) AS ordinal,
             lag(phase.id) OVER (
               ORDER BY phase.sort_order, phase.id
             ) AS expected_predecessor_id,
             bool_and(phase.follows_phase_id IS NULL) OVER () AS all_null_legacy
      FROM public.proposal_phases AS phase
      WHERE phase.proposal_id = p_proposal_id
    )
    SELECT count(*) INTO v_prefix_mismatch_count
    FROM ordered_existing AS existing
    JOIN LATERAL (
      SELECT blueprint.value
      FROM jsonb_array_elements(v_legacy_default_phases)
           WITH ORDINALITY AS blueprint(value, ordinal)
      WHERE blueprint.ordinal = existing.ordinal
    ) AS expected ON true
    WHERE existing.lane <> 'main'
       OR (
         NOT existing.all_null_legacy
         AND existing.follows_phase_id
               IS DISTINCT FROM existing.expected_predecessor_id
       )
       OR existing.sort_order <> existing.ordinal - 1
       OR existing.name IS DISTINCT FROM expected.value->>'name'
       OR existing.phase_key IS DISTINCT FROM expected.value->>'phase_key'
       OR existing.duration_weeks IS DISTINCT FROM
            (expected.value->>'duration_weeks')::integer
       OR existing.duration_days IS NOT NULL
       OR existing.fee_cents IS DISTINCT FROM
            (expected.value->>'fee_cents')::integer
       OR existing.revision_limit IS DISTINCT FROM
            (expected.value->>'revision_limit')::integer;

    IF v_prefix_mismatch_count = 0 THEN
      v_prev_phase_id := NULL;
      FOR v_existing IN
        SELECT phase.id
        FROM public.proposal_phases AS phase
        WHERE phase.proposal_id = p_proposal_id
        ORDER BY phase.sort_order, phase.id
      LOOP
        UPDATE public.proposal_phases
        SET follows_phase_id = v_prev_phase_id
        WHERE id = v_existing.id;
        v_prev_phase_id := v_existing.id;
      END LOOP;
      v_recovered_prefix_count := v_existing_count;
      v_effective_phases := v_legacy_default_phases;
    END IF;
  END IF;

  IF v_recovered_prefix_count = 0 THEN
    v_prev_phase_id := public._proposal_phase_main_tail(
      p_proposal_id, 'apply_phase_template precondition'
    );
  ELSE
    PERFORM public._assert_proposal_phase_topology(
      p_proposal_id, 'apply_phase_template recovered prefix'
    );
  END IF;

  SELECT COALESCE(max(sort_order), -1) INTO v_max_sort
  FROM public.proposal_phases
  WHERE proposal_id = p_proposal_id;

  FOR v_phase_data IN
    SELECT blueprint.value
    FROM jsonb_array_elements(v_effective_phases)
         WITH ORDINALITY AS blueprint(value, ordinal)
    WHERE blueprint.ordinal > v_recovered_prefix_count
    ORDER BY blueprint.ordinal
  LOOP
    IF btrim(COALESCE(v_phase_data->>'name', '')) = '' THEN
      RAISE EXCEPTION 'every template phase requires a name'
        USING ERRCODE = 'check_violation';
    END IF;
    v_max_sort := v_max_sort + 1;

    INSERT INTO public.proposal_phases (
      proposal_id, name, phase_key, duration_weeks, duration_days, lane,
      follows_phase_id, fee_cents, revision_limit, sort_order
    ) VALUES (
      p_proposal_id,
      btrim(v_phase_data->>'name'),
      NULLIF(v_phase_data->>'phase_key', ''),
      NULLIF(v_phase_data->>'duration_weeks', '')::integer,
      NULLIF(v_phase_data->>'duration_days', '')::integer,
      COALESCE(NULLIF(v_phase_data->>'lane', ''), 'main'),
      v_prev_phase_id,
      COALESCE(NULLIF(v_phase_data->>'fee_cents', '')::integer, 0),
      COALESCE(NULLIF(v_phase_data->>'revision_limit', '')::integer, 0),
      v_max_sort
    )
    RETURNING id INTO v_phase_id;

    v_inserted_phase_ids := array_append(v_inserted_phase_ids, v_phase_id);
    v_prev_phase_id := v_phase_id;

    IF v_phase_data ? 'deliverables' THEN
      FOR v_deliverable IN
        SELECT value FROM jsonb_array_elements(v_phase_data->'deliverables')
      LOOP
        INSERT INTO public.proposal_phase_deliverables (
          phase_id, label, description, is_required, sort_order
        ) VALUES (
          v_phase_id,
          v_deliverable->>'label',
          v_deliverable->>'description',
          COALESCE((v_deliverable->>'is_required')::boolean, true),
          COALESCE((v_deliverable->>'sort_order')::integer, 0)
        );
      END LOOP;
    END IF;

    IF v_phase_data ? 'default_gates' THEN
      FOR v_gate IN
        SELECT value FROM jsonb_array_elements(v_phase_data->'default_gates')
      LOOP
        INSERT INTO public.proposal_phase_gates (
          phase_id, gate_kind, payload, sort_order
        ) VALUES (
          v_phase_id,
          v_gate->>'gate_kind',
          COALESCE(v_gate->'payload', '{}'::jsonb),
          COALESCE((v_gate->>'sort_order')::integer, 0)
        );
      END LOOP;
    END IF;
  END LOOP;

  PERFORM public._assert_proposal_phase_topology(
    p_proposal_id, 'apply_phase_template result'
  );

  IF v_recovered_prefix_count > 0 THEN
    SELECT COALESCE(
             array_agg(phase.id ORDER BY phase.sort_order, phase.id),
             '{}'::uuid[]
           )
    INTO v_effect_phase_ids
    FROM public.proposal_phases AS phase
    WHERE phase.proposal_id = p_proposal_id;
  ELSE
    v_effect_phase_ids := v_inserted_phase_ids;
  END IF;

  PERFORM public._recompute_proposal_total_locked(p_proposal_id);

  INSERT INTO public.proposal_phase_template_applications (
    request_id, proposal_id, template_slug, phase_ids,
    effect_snapshot, created_by
  ) VALUES (
    p_request_id, p_proposal_id, p_template_slug,
    v_effect_phase_ids,
    public._proposal_phase_effect_snapshot(
      p_proposal_id, v_effect_phase_ids
    ),
    v_actor
  );

  FOREACH v_return_id IN ARRAY v_effect_phase_ids LOOP
    RETURN NEXT v_return_id;
  END LOOP;
END;
$$;
ALTER FUNCTION public.apply_phase_template(uuid,text,uuid) RESET ALL;
ALTER FUNCTION public.apply_phase_template(uuid,text,uuid) SET search_path = pg_catalog, public, pg_temp;
ALTER FUNCTION public.apply_phase_template(uuid,text,uuid) OWNER TO postgres;

CREATE OR REPLACE FUNCTION public.archive_project(
  p_project_id uuid,
  p_expected_status public.project_status
)
RETURNS public.projects
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, pg_temp
AS $$
DECLARE
  v_project public.projects%ROWTYPE;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'archive_project requires an authenticated user'
      USING ERRCODE = 'insufficient_privilege';
  END IF;

  SELECT * INTO v_project
  FROM public.projects
  WHERE id = p_project_id
  FOR UPDATE;

  IF NOT FOUND OR NOT public._can_author_proposal(v_project.designer_id) THEN
    RAISE EXCEPTION 'project % not found or access denied', p_project_id
      USING ERRCODE = 'insufficient_privilege';
  END IF;
  IF v_project.status = 'archived' THEN
    RETURN v_project;
  END IF;
  IF v_project.status IS DISTINCT FROM p_expected_status THEN
    RAISE EXCEPTION 'project % changed since it was loaded', p_project_id
      USING ERRCODE = 'serialization_failure';
  END IF;
  IF v_project.status NOT IN ('active', 'on_hold', 'completed') THEN
    RAISE EXCEPTION 'project % cannot be archived from status %',
      p_project_id, v_project.status
      USING ERRCODE = 'check_violation';
  END IF;

  PERFORM set_config('app.project_archive_id', p_project_id::text, true);
  UPDATE public.projects
  SET status = 'archived', updated_at = now()
  WHERE id = p_project_id
  RETURNING * INTO v_project;
  PERFORM set_config('app.project_archive_id', '', true);
  RETURN v_project;
END;
$$;
ALTER FUNCTION public.archive_project(uuid,public.project_status) RESET ALL;
ALTER FUNCTION public.archive_project(uuid,public.project_status) SET search_path = pg_catalog, public, pg_temp;
ALTER FUNCTION public.archive_project(uuid,public.project_status) OWNER TO postgres;

CREATE OR REPLACE FUNCTION public.begin_discovery(p_lead_id uuid)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, pg_temp
AS $$
DECLARE
  v_actor uuid := auth.uid();
  v_lead public.leads%ROWTYPE;
  v_relationship public.designer_clients%ROWTYPE;
BEGIN
  IF v_actor IS NULL THEN
    RAISE EXCEPTION 'begin_discovery requires an authenticated user'
      USING ERRCODE = 'insufficient_privilege';
  END IF;

  SELECT * INTO v_lead
  FROM public.leads
  WHERE id = p_lead_id
  FOR UPDATE;

  -- _can_author_proposal is the canonical exact-author helper: owner, or two
  -- active non-guest memberships in the same active design_studio. The older
  -- is_studio_comember helper intentionally includes other organization types.
  IF NOT FOUND OR NOT public._can_author_proposal(v_lead.designer_id) THEN
    RAISE EXCEPTION 'lead % not found or access denied', p_lead_id
      USING ERRCODE = 'insufficient_privilege';
  END IF;

  IF v_lead.status NOT IN ('new', 'viewed', 'contacted', 'accepted') THEN
    RAISE EXCEPTION 'lead % cannot begin discovery from status %',
      p_lead_id, v_lead.status
      USING ERRCODE = 'check_violation';
  END IF;

  UPDATE public.leads
  SET status = 'accepted',
      accepted_at = COALESCE(accepted_at, now()),
      updated_at = now()
  WHERE id = p_lead_id
  RETURNING * INTO v_lead;

  -- The lead_id is the durable idempotency key. A later invite or proposal can
  -- legitimately link a profile and advance this relationship beyond `lead`;
  -- retries must return that exact progressed row without normalizing it back.
  SELECT * INTO v_relationship
  FROM public.designer_clients
  WHERE designer_id = v_lead.designer_id
    AND lead_id = p_lead_id
  ORDER BY created_at, id
  LIMIT 1
  FOR UPDATE;

  IF FOUND THEN
    RETURN jsonb_build_object(
      'lead', to_jsonb(v_lead),
      'designerClientId', v_relationship.id
    );
  END IF;

  IF v_lead.homeowner_id IS NOT NULL THEN
    SELECT * INTO v_relationship
    FROM public.designer_clients
    WHERE designer_id = v_lead.designer_id
      AND client_id = v_lead.homeowner_id
      AND status = 'lead'
      AND lead_id IS NULL
    ORDER BY created_at, id
    LIMIT 1
    FOR UPDATE;

    IF FOUND THEN
      UPDATE public.designer_clients
      SET source = 'lead',
          lead_id = p_lead_id,
          updated_at = now()
      WHERE id = v_relationship.id
      RETURNING * INTO v_relationship;
    ELSE
      INSERT INTO public.designer_clients (
        designer_id, client_id, source, lead_id, status
      ) VALUES (
        v_lead.designer_id, v_lead.homeowner_id, 'lead', p_lead_id, 'lead'
      )
      RETURNING * INTO v_relationship;
    END IF;
  ELSE
    IF v_lead.contact_email IS NOT NULL THEN
      SELECT * INTO v_relationship
      FROM public.designer_clients
      WHERE designer_id = v_lead.designer_id
        AND client_email = v_lead.contact_email
        AND client_id IS NULL
        AND lead_id IS NULL
      ORDER BY created_at, id
      LIMIT 1
      FOR UPDATE;
    END IF;

    IF FOUND THEN
      IF v_relationship.status = 'lead' THEN
        UPDATE public.designer_clients
        SET client_name = v_lead.contact_name,
            client_email = v_lead.contact_email,
            source = 'lead',
            lead_id = p_lead_id,
            updated_at = now()
        WHERE id = v_relationship.id
        RETURNING * INTO v_relationship;
      ELSE
        -- A pre-existing progressed direct contact may be associated with this
        -- lead, but Discovery never rewinds its identity or lifecycle state.
        UPDATE public.designer_clients
        SET lead_id = p_lead_id, updated_at = now()
        WHERE id = v_relationship.id
        RETURNING * INTO v_relationship;
      END IF;
    ELSIF v_lead.contact_email IS NOT NULL THEN
      INSERT INTO public.designer_clients (
        designer_id, client_id, client_name, client_email, source, lead_id, status
      ) VALUES (
        v_lead.designer_id, NULL, v_lead.contact_name, v_lead.contact_email,
        'lead', p_lead_id, 'lead'
      )
      ON CONFLICT (designer_id, client_email)
        WHERE client_email IS NOT NULL AND client_id IS NULL
      DO UPDATE SET
        client_name = CASE
          WHEN designer_clients.status = 'lead' THEN EXCLUDED.client_name
          ELSE designer_clients.client_name
        END,
        source = CASE
          WHEN designer_clients.status = 'lead' THEN 'lead'
          ELSE designer_clients.source
        END,
        lead_id = EXCLUDED.lead_id,
        updated_at = now()
      WHERE designer_clients.lead_id IS NULL
         OR designer_clients.lead_id = EXCLUDED.lead_id
      RETURNING * INTO v_relationship;
      IF v_relationship.id IS NULL THEN
        RAISE EXCEPTION 'contact email is already claimed by another lead'
          USING ERRCODE = 'unique_violation';
      END IF;
    ELSE
      INSERT INTO public.designer_clients (
        designer_id, client_id, client_name, client_email, source, lead_id, status
      ) VALUES (
        v_lead.designer_id, NULL, v_lead.contact_name, NULL,
        'lead', p_lead_id, 'lead'
      )
      RETURNING * INTO v_relationship;
    END IF;
  END IF;

  RETURN jsonb_build_object(
    'lead', to_jsonb(v_lead),
    'designerClientId', v_relationship.id
  );
END;
$$;
ALTER FUNCTION public.begin_discovery(uuid) RESET ALL;
ALTER FUNCTION public.begin_discovery(uuid) SET search_path = pg_catalog, public, pg_temp;
ALTER FUNCTION public.begin_discovery(uuid) OWNER TO postgres;

CREATE OR REPLACE FUNCTION public.begin_proposal_revision(p_proposal_id uuid)
RETURNS public.proposals
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, pg_temp
AS $$
DECLARE
  v_actor uuid := auth.uid();
  v_proposal public.proposals;
BEGIN
  IF v_actor IS NULL THEN
    RAISE EXCEPTION 'begin_proposal_revision requires an authenticated user'
      USING ERRCODE = 'insufficient_privilege';
  END IF;

  SELECT * INTO v_proposal
  FROM public.proposals
  WHERE id = p_proposal_id
  FOR UPDATE;

  IF NOT FOUND OR NOT public._can_author_proposal(v_proposal.designer_id) THEN
    RAISE EXCEPTION
      'begin_proposal_revision: proposal % not found or access denied', p_proposal_id
      USING ERRCODE = 'insufficient_privilege';
  END IF;

  IF v_proposal.status = 'revised' THEN
    RETURN v_proposal;
  END IF;

  IF v_proposal.status NOT IN ('sent', 'viewed', 'declined', 'expired') THEN
    RAISE EXCEPTION 'proposal % cannot begin revision from status %',
      p_proposal_id, v_proposal.status
      USING ERRCODE = 'check_violation';
  END IF;

  PERFORM set_config('app.proposal_revision_id', p_proposal_id::text, true);
  UPDATE public.proposals
  SET status = 'revised', updated_at = now()
  WHERE id = p_proposal_id
  RETURNING * INTO v_proposal;
  PERFORM set_config('app.proposal_revision_id', '', true);

  RETURN v_proposal;
END;
$$;
ALTER FUNCTION public.begin_proposal_revision(uuid) RESET ALL;
ALTER FUNCTION public.begin_proposal_revision(uuid) SET search_path = pg_catalog, public, pg_temp;
ALTER FUNCTION public.begin_proposal_revision(uuid) OWNER TO postgres;

CREATE OR REPLACE FUNCTION public.can_dispatch_proposal_send(p_owner uuid)
RETURNS boolean
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path = public, pg_temp
AS $$
  SELECT p_owner IS NOT NULL AND public._can_author_proposal(p_owner);
$$;
ALTER FUNCTION public.can_dispatch_proposal_send(uuid) RESET ALL;
ALTER FUNCTION public.can_dispatch_proposal_send(uuid) SET search_path = pg_catalog, public, pg_temp;
ALTER FUNCTION public.can_dispatch_proposal_send(uuid) OWNER TO postgres;

CREATE OR REPLACE FUNCTION public.can_manage_invoice(p_invoice_id uuid)
RETURNS boolean
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path = public
AS $$
  SELECT EXISTS (
    SELECT 1 FROM public.invoices i
    WHERE i.id = p_invoice_id
      AND public._can_manage_invoice_owner(i.designer_id)
  );
$$;
ALTER FUNCTION public.can_manage_invoice(uuid) RESET ALL;
ALTER FUNCTION public.can_manage_invoice(uuid) SET search_path = pg_catalog, public, pg_temp;
ALTER FUNCTION public.can_manage_invoice(uuid) OWNER TO postgres;

CREATE OR REPLACE FUNCTION public.can_process_board_item_media(
  p_board_id uuid,
  p_item_id uuid,
  p_reference text
)
RETURNS boolean
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path = public, pg_temp
AS $$
  SELECT auth.uid() IS NOT NULL AND EXISTS (
    SELECT 1
    FROM public.proposal_board_items AS item
    JOIN public.proposal_boards AS board ON board.id = item.board_id
    LEFT JOIN public.proposals AS proposal ON proposal.id = board.proposal_id
    LEFT JOIN public.projects AS project ON project.id = board.project_id
    WHERE item.id = p_item_id
      AND board.id = p_board_id
      AND public.is_design_studio_comember(
        COALESCE(proposal.designer_id, project.designer_id)
      )
      AND p_reference IN (
        item.image_url,
        item.data->>'image_url',
        item.data->>'original_image_url',
        item.data->>'thumbnail_url'
      )
      AND public.board_media_reference_is_allowed(
        p_reference,
        COALESCE(proposal.designer_id, project.designer_id)
      )
  );
$$;
ALTER FUNCTION public.can_process_board_item_media(uuid,uuid,text) RESET ALL;
ALTER FUNCTION public.can_process_board_item_media(uuid,uuid,text) SET search_path = pg_catalog, public, pg_temp;
ALTER FUNCTION public.can_process_board_item_media(uuid,uuid,text) OWNER TO postgres;

CREATE OR REPLACE FUNCTION public.can_read_board_storage_object(p_object_name text)
RETURNS boolean
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path = public, storage, pg_temp
AS $$
  SELECT auth.uid() IS NOT NULL AND (
    -- Working-media author leg: exact active design-studio co-members only.
    EXISTS (
      SELECT 1
      FROM public.proposal_boards AS board
      LEFT JOIN public.proposals AS proposal ON proposal.id = board.proposal_id
      LEFT JOIN public.projects AS project ON project.id = board.project_id
      LEFT JOIN public.profiles AS media_owner
        ON media_owner.id::text = (storage.foldername(p_object_name))[1]
      WHERE (storage.foldername(p_object_name))[2] = 'boards'
        AND board.id::text = (storage.foldername(p_object_name))[3]
        AND (
          (storage.foldername(p_object_name))[1] = COALESCE(
            board.proposal_id, board.project_id
          )::text
          OR public.board_media_owners_share_studio(
            media_owner.id,
            COALESCE(proposal.designer_id, project.designer_id),
            NULL
          )
        )
        AND (
          (board.proposal_id IS NOT NULL
            AND public.is_design_studio_comember(proposal.designer_id))
          OR (board.project_id IS NOT NULL
            AND public.is_design_studio_comember(project.designer_id))
        )
    )
    OR EXISTS (
      SELECT 1
      FROM public.proposal_palettes AS palette
      JOIN public.proposals AS proposal ON proposal.id = palette.proposal_id
      WHERE public.board_storage_reference_path(palette.source_image_url) = p_object_name
        AND public.is_design_studio_comember(proposal.designer_id)
        AND public.board_media_reference_is_allowed(
          palette.source_image_url, proposal.designer_id
        )
    )
    OR EXISTS (
      SELECT 1
      FROM public.proposals AS proposal
      WHERE (storage.foldername(p_object_name))[2] = 'palettes'
        AND proposal.id::text = (storage.foldername(p_object_name))[1]
        AND public.is_design_studio_comember(proposal.designer_id)
    )
    OR EXISTS (
      SELECT 1
      FROM public.board_templates AS template
      WHERE template.kind = 'studio'
        AND template.media_references_validated_at IS NOT NULL
        AND public.is_active_org_member(template.studio_id)
        AND (
          public.board_storage_reference_path(template.cover_url) = p_object_name
          OR public.board_json_has_explicit_media_reference(
            template.items, p_object_name
          )
        )
    )
    OR
    -- Issued proposal media: the client may sign only an exact reference on
    -- the immutable issued composition, never another key in the same folder.
    EXISTS (
      SELECT 1
      FROM public.proposals AS proposal
      JOIN public.proposal_boards AS board ON board.proposal_id = proposal.id
      WHERE proposal.client_id = auth.uid()
        AND proposal.status IN ('sent', 'viewed', 'accepted', 'declined', 'expired')
        AND board.status = 'active'
        AND public.board_media_projection_is_allowed(board.id)
        AND (
          public.board_storage_reference_path(board.cover_image_url) = p_object_name
          OR EXISTS (
            SELECT 1 FROM public.proposal_board_items AS item
            WHERE item.board_id = board.id
              AND (
                public.board_storage_reference_path(item.image_url) = p_object_name
                OR public.board_json_has_explicit_media_reference(
                  item.data, p_object_name
                )
              )
          )
        )
    )
    OR EXISTS (
      SELECT 1
      FROM public.proposals AS proposal
      JOIN public.proposal_palettes AS palette ON palette.proposal_id = proposal.id
      WHERE proposal.client_id = auth.uid()
        AND proposal.status IN ('sent', 'viewed', 'accepted', 'declined', 'expired')
        AND public.board_storage_reference_path(palette.source_image_url) = p_object_name
        AND public.board_media_reference_is_allowed(
          palette.source_image_url, proposal.designer_id
        )
    )
    OR
    -- Activated/signed project snapshots are the project client's release.
    EXISTS (
      SELECT 1
      FROM public.projects AS project
      JOIN public.project_boards AS snapshot ON snapshot.project_id = project.id
      WHERE project.client_id = auth.uid()
        AND public.board_media_reference_is_allowed(
          snapshot.cover_image_url, project.designer_id
        )
        AND public.board_json_media_references_are_allowed(
          snapshot.items, project.designer_id
        )
        AND (
          public.board_storage_reference_path(snapshot.cover_image_url) = p_object_name
          OR public.board_json_has_explicit_media_reference(
            snapshot.items, p_object_name
          )
        )
    )
  );
$$;
ALTER FUNCTION public.can_read_board_storage_object(text) RESET ALL;
ALTER FUNCTION public.can_read_board_storage_object(text) SET search_path = pg_catalog, public, storage, pg_temp;
ALTER FUNCTION public.can_read_board_storage_object(text) OWNER TO postgres;

CREATE OR REPLACE FUNCTION public.clone_proposal(
  p_source_id uuid,
  p_mode text DEFAULT 'revision',
  p_revision_summary text DEFAULT NULL
)
RETURNS uuid
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, pg_temp
AS $$
DECLARE
  v_actor uuid := auth.uid();
  v_source public.proposals%ROWTYPE;
  v_target public.proposals%ROWTYPE;
  v_new_id uuid;
  v_new_phase_id uuid;
  v_phase_map jsonb := '{}'::jsonb;
  v_phase record;
BEGIN
  IF v_actor IS NULL THEN
    RAISE EXCEPTION 'clone_proposal requires an authenticated user'
      USING ERRCODE = 'insufficient_privilege';
  END IF;
  IF p_mode NOT IN ('revision', 'duplicate') THEN
    RAISE EXCEPTION
      'clone_proposal: invalid mode %, expected revision|duplicate', p_mode
      USING ERRCODE = 'invalid_parameter_value';
  END IF;

  SELECT * INTO v_source
  FROM public.proposals
  WHERE id = p_source_id
  FOR UPDATE;
  IF NOT FOUND OR NOT public._can_author_proposal(v_source.designer_id) THEN
    RAISE EXCEPTION
      'clone_proposal: proposal % not found or access denied', p_source_id
      USING ERRCODE = 'insufficient_privilege';
  END IF;

  PERFORM phase.id
  FROM public.proposal_phases AS phase
  WHERE phase.proposal_id = p_source_id
  ORDER BY phase.id
  FOR UPDATE;
  PERFORM public._assert_proposal_phase_topology(
    p_source_id, 'clone_proposal source'
  );

  v_new_id := public._clone_proposal_legacy_00399(
    p_source_id, p_mode, p_revision_summary
  );

  SELECT * INTO STRICT v_target
  FROM public.proposals
  WHERE id = v_new_id
  FOR UPDATE;
  IF v_target.status <> 'draft'
     OR v_target.designer_id IS DISTINCT FROM v_source.designer_id
  THEN
    RAISE EXCEPTION 'clone_proposal produced an invalid target draft'
      USING ERRCODE = 'check_violation';
  END IF;

  -- The frozen implementation created pre-linkage phase rows and copied their
  -- dependent deliverables/gates/payment milestones. Remove only that target
  -- schedule material, then rebuild it from the locked source with every
  -- current chain field. Other deep-copy children remain exactly as 00327.
  DELETE FROM public.proposal_schedule_milestones AS milestone
  USING public.proposal_phases AS phase
  WHERE milestone.phase_id = phase.id
    AND phase.proposal_id = v_new_id;
  DELETE FROM public.proposal_payment_milestones
  WHERE proposal_id = v_new_id;
  DELETE FROM public.proposal_phases
  WHERE proposal_id = v_new_id;

  FOR v_phase IN
    SELECT *
    FROM public.proposal_phases
    WHERE proposal_id = p_source_id
    ORDER BY sort_order, id
  LOOP
    INSERT INTO public.proposal_phases (
      proposal_id, name, phase_key, duration_weeks, duration_days,
      fee_cents, revision_limit, gate_condition, deliverables,
      sort_order, follows_phase_id, anchor_date, lane
    ) VALUES (
      v_new_id, v_phase.name, v_phase.phase_key, v_phase.duration_weeks,
      v_phase.duration_days, v_phase.fee_cents, v_phase.revision_limit,
      v_phase.gate_condition, v_phase.deliverables, v_phase.sort_order,
      NULL, v_phase.anchor_date, v_phase.lane
    )
    RETURNING id INTO v_new_phase_id;
    v_phase_map := v_phase_map || jsonb_build_object(
      v_phase.id::text, v_new_phase_id::text
    );
  END LOOP;

  FOR v_phase IN
    SELECT id, follows_phase_id
    FROM public.proposal_phases
    WHERE proposal_id = p_source_id
    ORDER BY sort_order, id
  LOOP
    UPDATE public.proposal_phases
    SET follows_phase_id = CASE
      WHEN v_phase.follows_phase_id IS NULL THEN NULL
      ELSE (v_phase_map ->> v_phase.follows_phase_id::text)::uuid
    END
    WHERE id = (v_phase_map ->> v_phase.id::text)::uuid;
  END LOOP;

  INSERT INTO public.proposal_phase_deliverables (
    phase_id, label, description, is_required,
    completed_at, completed_by, sort_order
  )
  SELECT
    (v_phase_map ->> deliverable.phase_id::text)::uuid,
    deliverable.label, deliverable.description, deliverable.is_required,
    NULL, NULL, deliverable.sort_order
  FROM public.proposal_phase_deliverables AS deliverable
  JOIN public.proposal_phases AS phase ON phase.id = deliverable.phase_id
  WHERE phase.proposal_id = p_source_id
    AND v_phase_map ? deliverable.phase_id::text;

  INSERT INTO public.proposal_phase_gates (
    phase_id, gate_kind, payload, satisfied_at, satisfied_by,
    override_reason, sort_order
  )
  SELECT
    (v_phase_map ->> gate.phase_id::text)::uuid,
    gate.gate_kind, gate.payload, NULL, NULL, NULL, gate.sort_order
  FROM public.proposal_phase_gates AS gate
  JOIN public.proposal_phases AS phase ON phase.id = gate.phase_id
  WHERE phase.proposal_id = p_source_id
    AND v_phase_map ? gate.phase_id::text;

  INSERT INTO public.proposal_payment_milestones (
    proposal_id, phase_id, label, percentage, amount_cents,
    trigger_condition, sort_order
  )
  SELECT
    v_new_id,
    CASE
      WHEN milestone.phase_id IS NULL THEN NULL
      ELSE (v_phase_map ->> milestone.phase_id::text)::uuid
    END,
    milestone.label, milestone.percentage, milestone.amount_cents,
    milestone.trigger_condition, milestone.sort_order
  FROM public.proposal_payment_milestones AS milestone
  WHERE milestone.proposal_id = p_source_id;

  INSERT INTO public.proposal_schedule_milestones (
    phase_id, name, kind, anchor_date, sort_order
  )
  SELECT
    (v_phase_map ->> milestone.phase_id::text)::uuid,
    milestone.name, milestone.kind, milestone.anchor_date,
    milestone.sort_order
  FROM public.proposal_schedule_milestones AS milestone
  JOIN public.proposal_phases AS phase ON phase.id = milestone.phase_id
  WHERE phase.proposal_id = p_source_id
    AND v_phase_map ? milestone.phase_id::text;

  PERFORM public._assert_proposal_phase_topology(
    v_new_id, 'clone_proposal target'
  );
  PERFORM public._recompute_proposal_total_locked(v_new_id);
  RETURN v_new_id;
END;
$$;
ALTER FUNCTION public.clone_proposal(uuid,text,text) RESET ALL;
ALTER FUNCTION public.clone_proposal(uuid,text,text) SET search_path = pg_catalog, public, pg_temp;
ALTER FUNCTION public.clone_proposal(uuid,text,text) OWNER TO postgres;

CREATE OR REPLACE FUNCTION public.commit_schedule_edit(
  p_project_id UUID,
  p_edits      JSONB,
  p_reason     TEXT DEFAULT NULL
)
RETURNS INTEGER
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $$
BEGIN
  -- Ownership guard, verbatim from 00326:712-717. R105 widening: the
  -- project's designer or a studio comember of the designer.
  IF NOT EXISTS (
    SELECT 1 FROM public.projects
    WHERE id = p_project_id AND public.is_studio_comember(designer_id)
  ) THEN
    RAISE EXCEPTION 'project % not found or not owned by caller', p_project_id;
  END IF;

  RETURN public._commit_schedule_edit_authorized(
    p_project_id, p_edits, p_reason,
    p_disclosed_impact := NULL,
    p_source           := 'manual'
  );
END;
$$;
ALTER FUNCTION public.commit_schedule_edit(uuid,jsonb,text) RESET ALL;
ALTER FUNCTION public.commit_schedule_edit(uuid,jsonb,text) SET search_path = pg_catalog, public, pg_temp;
ALTER FUNCTION public.commit_schedule_edit(uuid,jsonb,text) OWNER TO postgres;

CREATE OR REPLACE FUNCTION public.confirm_install_window(
  p_window_id        uuid,
  p_disclosed_impact jsonb DEFAULT NULL
)
RETURNS uuid
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, pg_temp
AS $$
DECLARE
  v_actor    uuid := auth.uid();
  v_window   public.install_windows%ROWTYPE;
  v_phase_id uuid;
  v_impact   jsonb := p_disclosed_impact;
  v_revision integer;
  v_anchored boolean := false;
  v_rows     integer;
  v_context  jsonb;
BEGIN
  IF v_actor IS NULL THEN
    RAISE EXCEPTION 'confirm_install_window: no authenticated actor';
  END IF;

  -- FOR UPDATE, not a bare read: two tabs confirming the same held window
  -- would both pass a snapshot-read state check and run the whole ceremony
  -- twice, cutting two revisions for one act.
  SELECT * INTO v_window FROM public.install_windows
   WHERE id = p_window_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'install window % not found', p_window_id;
  END IF;

  IF NOT EXISTS (
    SELECT 1 FROM public.projects
    WHERE id = v_window.project_id AND public.is_studio_comember(designer_id)
  ) THEN
    RAISE EXCEPTION 'install window % not found', p_window_id;
  END IF;

  IF v_window.state <> 'held' THEN
    RAISE EXCEPTION 'install window % is % — only a held window can be confirmed', p_window_id, v_window.state;
  END IF;

  v_phase_id := COALESCE(v_window.phase_id, public._install_window_phase(v_window.project_id));

  IF v_phase_id IS NULL THEN
    -- No phase to land on. The confirmation still stands and records what it
    -- wanted — but the commit door only speaks in edits naming a target, so
    -- the target-less proposal 00475 sized idx_schedule_proposals_live_
    -- projectwide for is written here directly rather than through it. Never
    -- a raise: R110's "the ceremony still runs" holds for this case too.
    v_context := COALESCE(p_disclosed_impact, '{}'::jsonb)
      || jsonb_build_object(
           'sourceEvent', 'install-window-confirmed',
           'proposedOn', to_char(current_date, 'YYYY-MM-DD'),
           'disclosed', p_disclosed_impact IS NOT NULL
             AND jsonb_typeof(p_disclosed_impact) = 'object'
             AND COALESCE(btrim(p_disclosed_impact->>'sentence'), '') <> '',
           'noTargetPhase', true);

    INSERT INTO public.schedule_proposals AS sp (
      project_id, source_event, source_ref, target_phase_id,
      proposed_anchor_date, conflicts_with_committed, disclosed_context
    ) VALUES (
      v_window.project_id, 'install-window-confirmed', v_window.id, NULL,
      v_window.starts_on, false, v_context
    )
    ON CONFLICT (project_id, source_event)
      WHERE state = 'proposed'
        AND target_phase_id IS NULL AND target_milestone_id IS NULL
    DO UPDATE SET
      proposed_anchor_date = EXCLUDED.proposed_anchor_date,
      disclosed_context    = EXCLUDED.disclosed_context
    WHERE sp.state = 'proposed';
  ELSE
    -- The door decides: it returns the new revision number when it wrote the
    -- anchor, and NULL when it downgraded to a proposal — for want of a
    -- disclosure (R110) or because the date contradicts one already committed
    -- (R109's third class). That return IS the anchored discriminant.
    v_revision := public._commit_schedule_edit_authorized(
      v_window.project_id,
      jsonb_build_array(jsonb_build_object(
        'kind',        'phase-anchor',
        'phase_id',    v_phase_id,
        'anchor_date', v_window.starts_on,
        'source_ref',  v_window.id,
        -- Never a bare NULL: the proposal branch merges `context` into the
        -- disclosed_context object, and a JSON null there concatenates into an
        -- array instead of an object.
        'context',     COALESCE(p_disclosed_impact, '{}'::jsonb)
      )),
      'Install window confirmed',
      v_impact,
      'ceremony:install-window-confirmed'
    );
    v_anchored := v_revision IS NOT NULL;
  END IF;

  -- State-qualified: the FOR UPDATE above serializes the racers, and this
  -- refuses to write anything if the winner already moved the row.
  UPDATE public.install_windows
     SET state            = 'confirmed',
         phase_id         = v_phase_id,
         anchored         = v_anchored,
         disclosed_impact = p_disclosed_impact
   WHERE id = p_window_id
     AND state = 'held';
  GET DIAGNOSTICS v_rows = ROW_COUNT;
  IF v_rows = 0 THEN
    RAISE EXCEPTION 'install window % was confirmed by another act while this one ran', p_window_id;
  END IF;

  RETURN p_window_id;
END;
$$;
ALTER FUNCTION public.confirm_install_window(uuid,jsonb) RESET ALL;
ALTER FUNCTION public.confirm_install_window(uuid,jsonb) SET search_path = pg_catalog, public, pg_temp;
ALTER FUNCTION public.confirm_install_window(uuid,jsonb) OWNER TO postgres;

CREATE OR REPLACE FUNCTION public.copy_schedule_as_built(
  p_source_project_id uuid,
  p_target_proposal_id uuid DEFAULT NULL,
  p_target_project_id uuid DEFAULT NULL
)
RETURNS SETOF uuid
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, pg_temp
AS $$
DECLARE
  v_actor uuid := auth.uid();
  v_source_project public.projects%ROWTYPE;
  v_target_project public.projects%ROWTYPE;
  v_target_proposal public.proposals%ROWTYPE;
  v_src record;
  v_duration integer;
  v_new_phase_id uuid;
  v_prev_phase_id uuid := NULL;
  v_sort integer := -1;
  v_source_count integer;
  v_exact_replay boolean := false;
  v_return_id uuid;
BEGIN
  IF v_actor IS NULL THEN
    RAISE EXCEPTION 'copy_schedule_as_built requires an authenticated user'
      USING ERRCODE = 'insufficient_privilege';
  END IF;
  IF (p_target_proposal_id IS NULL) = (p_target_project_id IS NULL) THEN
    RAISE EXCEPTION
      'exactly one of p_target_proposal_id / p_target_project_id must be provided'
      USING ERRCODE = 'invalid_parameter_value';
  END IF;

  IF p_target_project_id IS NOT NULL THEN
    PERFORM project.id
    FROM public.projects AS project
    WHERE project.id IN (p_source_project_id, p_target_project_id)
    ORDER BY project.id
    FOR UPDATE;

    SELECT * INTO v_source_project
    FROM public.projects WHERE id = p_source_project_id;
    SELECT * INTO v_target_project
    FROM public.projects WHERE id = p_target_project_id;

    IF v_source_project.id IS NULL
       OR NOT public._can_author_proposal(v_source_project.designer_id) THEN
      RAISE EXCEPTION
        'copy_schedule_as_built: source project not found or access denied'
        USING ERRCODE = 'insufficient_privilege';
    END IF;
    IF v_target_project.id IS NULL
       OR NOT public._can_author_proposal(v_target_project.designer_id) THEN
      RAISE EXCEPTION
        'copy_schedule_as_built: target project not found or access denied'
        USING ERRCODE = 'insufficient_privilege';
    END IF;
    IF EXISTS (
      SELECT 1 FROM public.project_phases
      WHERE project_id = p_target_project_id
    ) THEN
      RAISE EXCEPTION
        'target project % already has phases; the schedule is never rebuilt (R100)',
        p_target_project_id
        USING ERRCODE = 'check_violation';
    END IF;
  ELSE
    SELECT * INTO v_source_project
    FROM public.projects
    WHERE id = p_source_project_id
    FOR UPDATE;
    IF NOT FOUND
       OR NOT public._can_author_proposal(v_source_project.designer_id) THEN
      RAISE EXCEPTION
        'copy_schedule_as_built: source project not found or access denied'
        USING ERRCODE = 'insufficient_privilege';
    END IF;

    SELECT * INTO v_target_proposal
    FROM public.proposals
    WHERE id = p_target_proposal_id
    FOR UPDATE;
    IF NOT FOUND
       OR NOT public._can_author_proposal(v_target_proposal.designer_id) THEN
      RAISE EXCEPTION
        'copy_schedule_as_built: target proposal not found or access denied'
        USING ERRCODE = 'insufficient_privilege';
    END IF;
    IF v_target_proposal.status <> 'draft' THEN
      RAISE EXCEPTION 'proposal % is %, so its authored copy is immutable',
        p_target_proposal_id, v_target_proposal.status
        USING ERRCODE = 'check_violation';
    END IF;

    PERFORM phase.id
    FROM public.proposal_phases AS phase
    WHERE phase.proposal_id = p_target_proposal_id
    ORDER BY phase.id
    FOR UPDATE;
  END IF;

  PERFORM phase.id
  FROM public.project_phases AS phase
  WHERE phase.project_id = p_source_project_id
  ORDER BY phase.id
  FOR UPDATE;
  PERFORM public._assert_project_phase_topology(
    p_source_project_id, 'copy_schedule_as_built source'
  );
  SELECT count(*) INTO v_source_count
  FROM public.project_phases
  WHERE project_id = p_source_project_id;
  IF v_source_count = 0 THEN
    RAISE EXCEPTION 'source project % has no phases to copy', p_source_project_id
      USING ERRCODE = 'check_violation';
  END IF;

  IF p_target_proposal_id IS NOT NULL
     AND EXISTS (
       SELECT 1 FROM public.proposal_phases
       WHERE proposal_id = p_target_proposal_id
     )
  THEN
    PERFORM public._assert_proposal_phase_topology(
      p_target_proposal_id, 'copy_schedule_as_built existing receipt'
    );
    WITH source_rows AS (
      SELECT
        row_number() OVER (ORDER BY phase.sort_order, phase.id) AS ordinal,
        phase.name,
        phase.phase_key,
        CASE
          WHEN phase.start_date IS NOT NULL
           AND COALESCE(phase.completed_at::date, phase.target_end_date) IS NOT NULL
          THEN GREATEST(
            1,
            COALESCE(phase.completed_at::date, phase.target_end_date)
              - phase.start_date
          )
          ELSE COALESCE(
            phase.duration_days, phase.duration_weeks * 7, 14
          )
        END AS duration_days,
        COALESCE(phase.lane, 'main') AS lane
      FROM public.project_phases AS phase
      WHERE phase.project_id = p_source_project_id
    ), target_rows AS (
      SELECT
        row_number() OVER (ORDER BY phase.sort_order, phase.id) AS ordinal,
        phase.*,
        lag(phase.id) OVER (ORDER BY phase.sort_order, phase.id) AS prior_id
      FROM public.proposal_phases AS phase
      WHERE phase.proposal_id = p_target_proposal_id
    )
    SELECT
      (SELECT count(*) FROM source_rows)
        = (SELECT count(*) FROM target_rows)
      AND NOT EXISTS (
        SELECT 1
        FROM source_rows AS source
        FULL JOIN target_rows AS target USING (ordinal)
        WHERE source.ordinal IS NULL
           OR target.ordinal IS NULL
           OR target.name IS DISTINCT FROM source.name
           OR target.phase_key IS DISTINCT FROM source.phase_key
           OR target.duration_days IS DISTINCT FROM source.duration_days
           OR target.lane IS DISTINCT FROM source.lane
           OR target.sort_order IS DISTINCT FROM source.ordinal - 1
           OR target.follows_phase_id IS DISTINCT FROM
                CASE WHEN source.ordinal = 1 THEN NULL ELSE target.prior_id END
      )
    INTO v_exact_replay;

    IF NOT v_exact_replay THEN
      RAISE EXCEPTION
        'target proposal % already has a different schedule; it is never rebuilt (R100)',
        p_target_proposal_id
        USING ERRCODE = 'check_violation';
    END IF;

    PERFORM public._recompute_proposal_total_locked(p_target_proposal_id);
    FOR v_return_id IN
      SELECT phase.id
      FROM public.proposal_phases AS phase
      WHERE phase.proposal_id = p_target_proposal_id
      ORDER BY phase.sort_order, phase.id
    LOOP
      RETURN NEXT v_return_id;
    END LOOP;
    RETURN;
  END IF;

  FOR v_src IN
    SELECT *
    FROM public.project_phases
    WHERE project_id = p_source_project_id
    ORDER BY sort_order, id
  LOOP
    v_sort := v_sort + 1;
    IF v_src.start_date IS NOT NULL
       AND COALESCE(v_src.completed_at::date, v_src.target_end_date) IS NOT NULL
    THEN
      v_duration := GREATEST(
        1,
        COALESCE(v_src.completed_at::date, v_src.target_end_date)
          - v_src.start_date
      );
    ELSE
      v_duration := COALESCE(
        v_src.duration_days, v_src.duration_weeks * 7, 14
      );
    END IF;

    IF p_target_proposal_id IS NOT NULL THEN
      INSERT INTO public.proposal_phases (
        proposal_id, name, phase_key, duration_days, lane,
        follows_phase_id, sort_order
      ) VALUES (
        p_target_proposal_id, v_src.name, v_src.phase_key, v_duration,
        COALESCE(v_src.lane, 'main'), v_prev_phase_id, v_sort
      )
      RETURNING id INTO v_new_phase_id;
    ELSE
      SELECT created.id INTO v_new_phase_id
      FROM public.create_project_phase(
        p_project_id => p_target_project_id,
        p_phase_key => v_src.phase_key,
        p_name => v_src.name,
        p_sort_order => v_sort,
        p_duration_days => v_duration,
        p_follows_phase_id => v_prev_phase_id,
        p_lane => COALESCE(v_src.lane, 'main')
      ) AS created;
    END IF;

    RETURN NEXT v_new_phase_id;
    v_prev_phase_id := v_new_phase_id;
  END LOOP;

  IF p_target_proposal_id IS NOT NULL THEN
    PERFORM public._assert_proposal_phase_topology(
      p_target_proposal_id, 'copy_schedule_as_built result'
    );
    PERFORM public._recompute_proposal_total_locked(p_target_proposal_id);
  END IF;
END;
$$;
ALTER FUNCTION public.copy_schedule_as_built(uuid,uuid,uuid) RESET ALL;
ALTER FUNCTION public.copy_schedule_as_built(uuid,uuid,uuid) SET search_path = pg_catalog, public, pg_temp;
ALTER FUNCTION public.copy_schedule_as_built(uuid,uuid,uuid) OWNER TO postgres;

CREATE OR REPLACE FUNCTION public.create_board_share(
  p_board_id uuid,
  p_label text DEFAULT NULL,
  p_expires_at timestamptz DEFAULT NULL
)
RETURNS TABLE (id uuid, token text)
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, extensions, pg_temp
AS $$
DECLARE
  v_token text;
  v_hash text;
  v_id uuid := extensions.gen_random_uuid();
  v_label text := NULLIF(btrim(p_label), '');
  v_payload jsonb;
  v_previous_capability text := current_setting(
    'app.board_share_capability', true
  );
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'authentication required'
      USING ERRCODE = 'insufficient_privilege';
  END IF;
  IF p_expires_at IS NOT NULL AND p_expires_at <= now() THEN
    RAISE EXCEPTION 'expiry must be in the future'
      USING ERRCODE = 'check_violation';
  END IF;
  IF NOT EXISTS (
    SELECT 1
    FROM public.proposal_boards AS board
    LEFT JOIN public.proposals AS proposal ON proposal.id = board.proposal_id
    LEFT JOIN public.projects AS project ON project.id = board.project_id
    WHERE board.id = p_board_id
      AND board.status = 'active'
      -- Project-board token sharing kept closed per 2026-08-12 ruling.
      AND board.project_id IS NULL
      AND board.proposal_id IS NOT NULL
      AND proposal.status IN ('draft','sent','viewed','accepted','declined','expired')
      AND public.is_design_studio_comember(proposal.designer_id)
  ) THEN
    RAISE EXCEPTION 'board not found or not accessible'
      USING ERRCODE = 'insufficient_privilege';
  END IF;

  v_payload := public.build_board_share_payload(
    p_board_id, v_id, v_label, p_expires_at
  );
  IF v_payload IS NULL THEN
    RAISE EXCEPTION 'board payload could not be captured'
      USING ERRCODE = 'check_violation';
  END IF;
  v_token := encode(extensions.gen_random_bytes(32), 'hex');
  v_hash := encode(extensions.digest(v_token, 'sha256'), 'hex');

  PERFORM set_config(
    'app.board_share_capability',
    format('board_share:%s:%s', v_id, pg_catalog.txid_current()),
    true
  );

  INSERT INTO public.document_shares (
    id, proposal_id, spec_book_artifact_id, board_id,
    token_hash, label, visibility, status, expires_at, created_by,
    board_payload, board_payload_hash
  ) VALUES (
    v_id, NULL, NULL, p_board_id,
    v_hash, v_label, jsonb_build_object('feedbackEnabled', false),
    'active', p_expires_at, auth.uid(),
    v_payload,
    encode(extensions.digest(convert_to(v_payload::text, 'UTF8'), 'sha256'), 'hex')
  );
  PERFORM set_config(
    'app.board_share_capability', COALESCE(v_previous_capability, ''), true
  );
  RETURN QUERY SELECT v_id, v_token;
EXCEPTION WHEN OTHERS THEN
  PERFORM set_config(
    'app.board_share_capability', COALESCE(v_previous_capability, ''), true
  );
  RAISE;
END;
$$;
ALTER FUNCTION public.create_board_share(uuid,text,timestamp with time zone) RESET ALL;
ALTER FUNCTION public.create_board_share(uuid,text,timestamp with time zone) SET search_path = pg_catalog, public, extensions, pg_temp;
ALTER FUNCTION public.create_board_share(uuid,text,timestamp with time zone) OWNER TO postgres;

CREATE OR REPLACE FUNCTION public.create_client_decision(
  p_decision_id uuid,
  p_payload jsonb,
  p_options jsonb DEFAULT '[]'::jsonb,
  p_blocked_ffe_item_ids uuid[] DEFAULT '{}'::uuid[],
  p_blocked_task_ids uuid[] DEFAULT '{}'::uuid[]
)
RETURNS public.client_decisions
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, pg_temp
AS $$
DECLARE
  v_actor uuid := auth.uid();
  v_relationship public.designer_clients%ROWTYPE;
  v_decision public.client_decisions%ROWTYPE;
  v_project_id uuid;
  v_status text;
  v_unknown jsonb;
  v_expected_count integer;
  v_matched_count integer;
  v_existing_payload jsonb;
  v_requested_payload jsonb;
  v_existing_options jsonb;
  v_requested_options jsonb;
  v_existing_ffe_ids uuid[];
  v_requested_ffe_ids uuid[];
  v_existing_task_ids uuid[];
  v_requested_task_ids uuid[];
BEGIN
  IF v_actor IS NULL THEN
    RAISE EXCEPTION 'create_client_decision requires an authenticated user'
      USING ERRCODE = 'insufficient_privilege';
  END IF;
  IF p_decision_id IS NULL THEN
    RAISE EXCEPTION 'p_decision_id is required'
      USING ERRCODE = 'invalid_parameter_value';
  END IF;
  IF p_payload IS NULL OR jsonb_typeof(p_payload) <> 'object' THEN
    RAISE EXCEPTION 'p_payload must be a JSON object'
      USING ERRCODE = 'invalid_parameter_value';
  END IF;
  IF jsonb_typeof(COALESCE(p_options, '[]'::jsonb)) <> 'array' THEN
    RAISE EXCEPTION 'p_options must be a JSON array'
      USING ERRCODE = 'invalid_parameter_value';
  END IF;

  v_unknown := p_payload - ARRAY[
    'designer_client_id', 'project_id', 'title', 'context', 'due_date',
    'linked_phase', 'phase_id', 'room_id', 'section_key', 'decision_type',
    'decision_kind', 'coordination_kind', 'blocking_status', 'blocks_kind',
    'blocks_milestone_id', 'court', 'court_party_id', 'status'
  ];
  IF v_unknown <> '{}'::jsonb THEN
    RAISE EXCEPTION 'unsupported decision payload keys: %', v_unknown
      USING ERRCODE = 'invalid_parameter_value';
  END IF;

  IF btrim(COALESCE(p_payload->>'title', '')) = '' THEN
    RAISE EXCEPTION 'decision title is required'
      USING ERRCODE = 'check_violation';
  END IF;
  v_status := COALESCE(NULLIF(p_payload->>'status', ''), 'pending');
  IF v_status NOT IN ('draft', 'pending') THEN
    RAISE EXCEPTION 'new decisions must start draft or pending'
      USING ERRCODE = 'check_violation';
  END IF;

  SELECT * INTO v_relationship
  FROM public.designer_clients
  WHERE id = NULLIF(p_payload->>'designer_client_id', '')::uuid
  FOR SHARE;
  IF NOT FOUND OR NOT public._can_author_proposal(v_relationship.designer_id) THEN
    RAISE EXCEPTION 'relationship not found or access denied'
      USING ERRCODE = 'insufficient_privilege';
  END IF;
  IF v_status = 'pending' AND v_relationship.client_id IS NULL THEN
    RAISE EXCEPTION 'pending decisions require a registered client recipient'
      USING ERRCODE = 'check_violation';
  END IF;

  v_project_id := NULLIF(p_payload->>'project_id', '')::uuid;

  IF EXISTS (
    SELECT 1
    FROM jsonb_array_elements(COALESCE(p_options, '[]'::jsonb)) AS option(value)
    WHERE jsonb_typeof(option.value) <> 'object'
       OR btrim(COALESCE(option.value->>'name', '')) = ''
       OR COALESCE(NULLIF(option.value->>'quantity', '')::integer, 1) < 1
       OR COALESCE(NULLIF(option.value->>'sort_order', '')::integer, 0) < 0
       OR COALESCE((option.value->>'selected')::boolean, false)
       OR option.value ? 'client_note'
  ) THEN
    RAISE EXCEPTION 'invalid decision option payload'
      USING ERRCODE = 'check_violation';
  END IF;

  -- A reused key is an exact receipt, never permission to overwrite a row.
  SELECT * INTO v_decision
  FROM public.client_decisions
  WHERE id = p_decision_id
  FOR UPDATE;
  IF FOUND THEN
    v_existing_payload := jsonb_build_object(
      'designer_client_id', v_decision.designer_client_id,
      'project_id', v_decision.project_id,
      'title', v_decision.title,
      'context', v_decision.context,
      'due_date', v_decision.due_date,
      'linked_phase', v_decision.linked_phase,
      'phase_id', v_decision.phase_id,
      'room_id', v_decision.room_id,
      'section_key', v_decision.section_key,
      'decision_type', v_decision.decision_type,
      'decision_kind', v_decision.decision_kind,
      'coordination_kind', v_decision.coordination_kind,
      'blocking_status', v_decision.blocking_status,
      'blocks_kind', v_decision.blocks_kind,
      'blocks_milestone_id', v_decision.blocks_milestone_id,
      'court', v_decision.court,
      'court_party_id', v_decision.court_party_id,
      'status', v_decision.status
    );
    v_requested_payload := jsonb_build_object(
      'designer_client_id', v_relationship.id,
      'project_id', v_project_id,
      'title', btrim(p_payload->>'title'),
      'context', p_payload->>'context',
      'due_date', NULLIF(p_payload->>'due_date', '')::timestamptz,
      'linked_phase', p_payload->>'linked_phase',
      'phase_id', NULLIF(p_payload->>'phase_id', '')::uuid,
      'room_id', NULLIF(p_payload->>'room_id', '')::uuid,
      'section_key', p_payload->>'section_key',
      'decision_type', COALESCE(NULLIF(p_payload->>'decision_type', ''), 'product'),
      'decision_kind', COALESCE(NULLIF(p_payload->>'decision_kind', ''), 'choice'),
      'coordination_kind', COALESCE(NULLIF(p_payload->>'coordination_kind', ''), 'selection'),
      'blocking_status', COALESCE(NULLIF(p_payload->>'blocking_status', ''), 'non_blocking'),
      'blocks_kind', COALESCE(NULLIF(p_payload->>'blocks_kind', ''), 'none'),
      'blocks_milestone_id', NULLIF(p_payload->>'blocks_milestone_id', '')::uuid,
      'court', COALESCE(NULLIF(p_payload->>'court', ''), 'client'),
      'court_party_id', NULLIF(p_payload->>'court_party_id', '')::uuid,
      'status', v_status
    );

    SELECT COALESCE(jsonb_agg(jsonb_build_object(
      'name', option.name,
      'image_url', option.image_url,
      'designer_note', option.designer_note,
      'is_recommended', COALESCE(option.is_recommended, false),
      'price', option.price,
      'quantity', COALESCE(option.quantity, 1),
      'cost_delta_cents', option.cost_delta_cents,
      'lead_time_days_delta', option.lead_time_days_delta,
      'product_id', option.product_id,
      'approves', COALESCE(option.approves, false),
      'sort_order', COALESCE(option.sort_order, 0)
    ) ORDER BY option.sort_order, option.id), '[]'::jsonb)
    INTO v_existing_options
    FROM public.client_decision_options AS option
    WHERE option.decision_id = p_decision_id;

    SELECT COALESCE(jsonb_agg(jsonb_build_object(
      'name', btrim(option.value->>'name'),
      'image_url', option.value->>'image_url',
      'designer_note', option.value->>'designer_note',
      'is_recommended', COALESCE((option.value->>'is_recommended')::boolean, false),
      'price', NULLIF(option.value->>'price', '')::integer,
      'quantity', COALESCE(NULLIF(option.value->>'quantity', '')::integer, 1),
      'cost_delta_cents', NULLIF(option.value->>'cost_delta_cents', '')::integer,
      'lead_time_days_delta', NULLIF(option.value->>'lead_time_days_delta', '')::integer,
      'product_id', NULLIF(option.value->>'product_id', '')::uuid,
      'approves', COALESCE((option.value->>'approves')::boolean, false),
      'sort_order', COALESCE(NULLIF(option.value->>'sort_order', '')::integer,
                             option.ordinality::integer - 1)
    ) ORDER BY COALESCE(NULLIF(option.value->>'sort_order', '')::integer,
                        option.ordinality::integer - 1)), '[]'::jsonb)
    INTO v_requested_options
    FROM jsonb_array_elements(COALESCE(p_options, '[]'::jsonb))
         WITH ORDINALITY AS option(value, ordinality);

    SELECT COALESCE(array_agg(item.id ORDER BY item.id), '{}'::uuid[])
    INTO v_existing_ffe_ids
    FROM public.project_ffe_items AS item
    WHERE item.blocked_by_decision_id = p_decision_id;
    SELECT COALESCE(array_agg(DISTINCT id ORDER BY id), '{}'::uuid[])
    INTO v_requested_ffe_ids
    FROM unnest(COALESCE(p_blocked_ffe_item_ids, '{}'::uuid[])) AS id;
    SELECT COALESCE(array_agg(task.id ORDER BY task.id), '{}'::uuid[])
    INTO v_existing_task_ids
    FROM public.project_tasks AS task
    WHERE task.blocked_by_item_id = p_decision_id;
    SELECT COALESCE(array_agg(DISTINCT id ORDER BY id), '{}'::uuid[])
    INTO v_requested_task_ids
    FROM unnest(COALESCE(p_blocked_task_ids, '{}'::uuid[])) AS id;

    IF NOT public._can_author_proposal(v_decision.designer_id)
       OR v_existing_payload IS DISTINCT FROM v_requested_payload
       OR v_existing_options IS DISTINCT FROM v_requested_options
       OR v_existing_ffe_ids IS DISTINCT FROM v_requested_ffe_ids
       OR v_existing_task_ids IS DISTINCT FROM v_requested_task_ids
    THEN
      RAISE EXCEPTION 'p_decision_id was already used for another decision'
        USING ERRCODE = 'serialization_failure';
    END IF;
    IF v_decision.status = 'pending' THEN
      PERFORM public._enqueue_decision_notification(
        p_decision_id, 'decision_required'
      );
    END IF;
    RETURN v_decision;
  END IF;

  PERFORM public.assert_client_decision_reference_integrity(
    p_decision_id,
    v_relationship.id,
    v_relationship.designer_id,
    v_project_id,
    v_status,
    NULLIF(p_payload->>'phase_id', '')::uuid,
    NULLIF(p_payload->>'room_id', '')::uuid,
    NULLIF(p_payload->>'blocks_milestone_id', '')::uuid,
    NULLIF(p_payload->>'court_party_id', '')::uuid,
    NULL,
    NULL
  );

  IF cardinality(COALESCE(p_blocked_ffe_item_ids, '{}'::uuid[])) > 0 THEN
    PERFORM 1
    FROM public.project_ffe_items AS item
    WHERE item.id = ANY(p_blocked_ffe_item_ids)
    ORDER BY item.id
    FOR UPDATE;
    SELECT count(DISTINCT item.id) INTO v_matched_count
    FROM public.project_ffe_items AS item
    WHERE item.id = ANY(p_blocked_ffe_item_ids)
      AND item.project_id IS NOT DISTINCT FROM v_project_id
      AND (item.blocked_by_decision_id IS NULL
           OR item.blocked_by_decision_id = p_decision_id);
    SELECT count(DISTINCT id) INTO v_expected_count
    FROM unnest(p_blocked_ffe_item_ids) AS id;
    IF v_project_id IS NULL OR v_matched_count <> v_expected_count THEN
      RAISE EXCEPTION 'blocked FF&E items must be available in the decision project'
        USING ERRCODE = 'check_violation';
    END IF;
  END IF;

  IF cardinality(COALESCE(p_blocked_task_ids, '{}'::uuid[])) > 0 THEN
    PERFORM 1
    FROM public.project_tasks AS task
    WHERE task.id = ANY(p_blocked_task_ids)
    ORDER BY task.id
    FOR UPDATE;
    SELECT count(DISTINCT task.id) INTO v_matched_count
    FROM public.project_tasks AS task
    WHERE task.id = ANY(p_blocked_task_ids)
      AND task.project_id IS NOT DISTINCT FROM v_project_id
      AND task.status <> 'done'
      AND (task.blocked_by_item_id IS NULL
           OR task.blocked_by_item_id = p_decision_id);
    SELECT count(DISTINCT id) INTO v_expected_count
    FROM unnest(p_blocked_task_ids) AS id;
    IF v_project_id IS NULL OR v_matched_count <> v_expected_count THEN
      RAISE EXCEPTION 'blocked tasks must be open and available in the decision project'
        USING ERRCODE = 'check_violation';
    END IF;
  END IF;

  INSERT INTO public.client_decisions (
    id, designer_client_id, designer_id, project_id, title, context,
    due_date, linked_phase, phase_id, room_id, section_key, decision_type,
    decision_kind, coordination_kind, blocking_status, blocks_kind,
    blocks_milestone_id, court, court_party_id, status, sent_at
  ) VALUES (
    p_decision_id, v_relationship.id, v_relationship.designer_id, v_project_id,
    btrim(p_payload->>'title'), p_payload->>'context',
    NULLIF(p_payload->>'due_date', '')::timestamptz,
    p_payload->>'linked_phase', NULLIF(p_payload->>'phase_id', '')::uuid,
    NULLIF(p_payload->>'room_id', '')::uuid, p_payload->>'section_key',
    COALESCE(NULLIF(p_payload->>'decision_type', ''), 'product'),
    COALESCE(NULLIF(p_payload->>'decision_kind', ''), 'choice'),
    COALESCE(NULLIF(p_payload->>'coordination_kind', ''), 'selection'),
    COALESCE(NULLIF(p_payload->>'blocking_status', ''), 'non_blocking'),
    COALESCE(NULLIF(p_payload->>'blocks_kind', ''), 'none'),
    NULLIF(p_payload->>'blocks_milestone_id', '')::uuid,
    COALESCE(NULLIF(p_payload->>'court', ''), 'client'),
    NULLIF(p_payload->>'court_party_id', '')::uuid,
    v_status, CASE WHEN v_status = 'pending' THEN now() ELSE NULL END
  ) RETURNING * INTO v_decision;

  INSERT INTO public.client_decision_options (
    decision_id, name, image_url, designer_note, is_recommended,
    price, quantity, cost_delta_cents, lead_time_days_delta,
    product_id, approves, configuration_id, selection_snapshot,
    selected, client_note, sort_order
  )
  SELECT
    p_decision_id, btrim(option.value->>'name'), option.value->>'image_url',
    option.value->>'designer_note',
    COALESCE((option.value->>'is_recommended')::boolean, false),
    NULLIF(option.value->>'price', '')::integer,
    COALESCE(NULLIF(option.value->>'quantity', '')::integer, 1),
    NULLIF(option.value->>'cost_delta_cents', '')::integer,
    NULLIF(option.value->>'lead_time_days_delta', '')::integer,
    NULLIF(option.value->>'product_id', '')::uuid,
    COALESCE((option.value->>'approves')::boolean, false),
    NULLIF(option.value->>'configuration_id', '')::uuid,
    -- Never the caller's array verbatim: the client reads this row.
    public._decision_selection_snapshot_safe(option.value->'selection_snapshot'),
    false, NULL,
    COALESCE(NULLIF(option.value->>'sort_order', '')::integer,
             option.ordinality::integer - 1)
  FROM jsonb_array_elements(COALESCE(p_options, '[]'::jsonb))
       WITH ORDINALITY AS option(value, ordinality);

  UPDATE public.project_ffe_items
  SET blocked = true, blocked_by_decision_id = p_decision_id, updated_at = now()
  WHERE id = ANY(COALESCE(p_blocked_ffe_item_ids, '{}'::uuid[]));

  UPDATE public.project_tasks
  SET status = 'blocked', blocked_by_item_id = p_decision_id, updated_at = now()
  WHERE id = ANY(COALESCE(p_blocked_task_ids, '{}'::uuid[]));

  IF v_status = 'pending' THEN
    PERFORM public._enqueue_decision_notification(
      p_decision_id, 'decision_required'
    );
  END IF;

  SELECT * INTO v_decision FROM public.client_decisions
  WHERE id = p_decision_id;
  RETURN v_decision;
END;
$$;
ALTER FUNCTION public.create_client_decision(uuid,jsonb,jsonb,uuid[],uuid[]) RESET ALL;
ALTER FUNCTION public.create_client_decision(uuid,jsonb,jsonb,uuid[],uuid[]) SET search_path = pg_catalog, public, pg_temp;
ALTER FUNCTION public.create_client_decision(uuid,jsonb,jsonb,uuid[],uuid[]) OWNER TO postgres;

CREATE OR REPLACE FUNCTION public.create_plan_issue(
  p_project_id uuid,
  p_name text,
  p_idempotency_key text,
  p_sheet_ids uuid[] DEFAULT NULL
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, extensions, pg_temp
AS $$
DECLARE
  v_name       text := btrim(COALESCE(p_name, ''));
  v_key        text := btrim(COALESCE(p_idempotency_key, ''));
  v_hash       text;
  v_issue      public.plan_issues%ROWTYPE;
  v_prior      public.plan_issues%ROWTYPE;
  v_ids        uuid[];
  v_checksum   text;
  v_missing    text;
  v_idempotent boolean := false;
  v_sheets     jsonb;
  v_added      jsonb;
  v_changed    jsonb;
  v_removed    jsonb;
  v_unchanged  jsonb;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'issuing a set requires an authenticated designer'
      USING errcode = 'insufficient_privilege';
  END IF;
  IF NOT EXISTS (
    SELECT 1 FROM public.projects p
    WHERE p.id = p_project_id AND public.is_design_studio_comember(p.designer_id)
  ) THEN
    RAISE EXCEPTION 'plan room for project % not found or access denied', p_project_id
      USING errcode = 'insufficient_privilege';
  END IF;
  IF length(v_name) NOT BETWEEN 1 AND 120 THEN
    RAISE EXCEPTION 'an issue needs a name of 1 to 120 characters'
      USING errcode = 'check_violation';
  END IF;
  IF v_key = '' THEN
    RAISE EXCEPTION 'an issue needs an idempotency key'
      USING errcode = 'check_violation';
  END IF;

  PERFORM 1 FROM public.projects WHERE id = p_project_id FOR UPDATE;

  v_hash := encode(extensions.digest(public._plan_room_canonical_json(
    jsonb_build_object(
      'name', v_name,
      -- DISTINCT, because the write path dedupes: [A, A, B] and [A, B] resolve
      -- to the same set, so they must not be two different requests under one
      -- idempotency key.
      'sheetIds', CASE
        WHEN p_sheet_ids IS NULL THEN 'null'::jsonb
        ELSE (SELECT COALESCE(
                jsonb_agg(DISTINCT to_jsonb(x::text) ORDER BY to_jsonb(x::text)),
                '[]'::jsonb)
              FROM unnest(p_sheet_ids) AS x)
      END
    )), 'sha256'), 'hex');

  SELECT * INTO v_issue FROM public.plan_issues
  WHERE project_id = p_project_id AND idempotency_key = v_key;

  IF FOUND THEN
    IF v_issue.request_hash IS DISTINCT FROM v_hash THEN
      RAISE EXCEPTION 'idempotency key was reused with a different request'
        USING errcode = 'unique_violation';
    END IF;
    v_idempotent := true;
  ELSE
    SELECT COALESCE(array_agg(s.id ORDER BY upper(btrim(s.sheet_number))), ARRAY[]::uuid[])
      INTO v_ids
      FROM public.plan_sheets s
     WHERE s.project_id = p_project_id
       AND s.current_print_id IS NOT NULL
       AND (p_sheet_ids IS NULL OR s.id = ANY (p_sheet_ids));

    IF p_sheet_ids IS NOT NULL THEN
      SELECT string_agg(x::text, ', ') INTO v_missing
      FROM unnest(p_sheet_ids) AS x
      WHERE NOT EXISTS (
        SELECT 1 FROM public.plan_sheets s
        WHERE s.id = x AND s.project_id = p_project_id AND s.current_print_id IS NOT NULL
      );
      IF v_missing IS NOT NULL THEN
        RAISE EXCEPTION
          'these sheets are not in this plan room, or have nothing filed on them: %', v_missing
          USING errcode = 'check_violation';
      END IF;
    END IF;

    IF cardinality(v_ids) = 0 THEN
      RAISE EXCEPTION 'an issue needs at least one sheet with a filed print'
        USING errcode = 'check_violation';
    END IF;

    SELECT encode(extensions.digest(public._plan_room_canonical_json(
             COALESCE(jsonb_agg(jsonb_build_object(
               'sheetNumber', btrim(s.sheet_number),
               'revLetter', pp.rev_letter,
               'sha256', pp.sha256
             ) ORDER BY upper(btrim(s.sheet_number))), '[]'::jsonb)), 'sha256'), 'hex')
      INTO v_checksum
      FROM public.plan_sheets s
      JOIN public.plan_prints pp ON pp.id = s.current_print_id
     WHERE s.id = ANY (v_ids);

    SELECT * INTO v_prior FROM public.plan_issues
    WHERE project_id = p_project_id
    ORDER BY issue_number DESC
    LIMIT 1;

    INSERT INTO public.plan_issues (
      project_id, issue_number, name, idempotency_key, request_hash,
      prior_issue_id, set_checksum, sheet_count, created_by
    ) VALUES (
      p_project_id, COALESCE(v_prior.issue_number, 0) + 1, v_name, v_key, v_hash,
      v_prior.id, v_checksum, cardinality(v_ids), auth.uid()
    ) RETURNING * INTO v_issue;

    INSERT INTO public.plan_issue_prints (
      issue_id, sheet_id, print_id, sheet_number, sheet_title, rev_letter, sha256
    )
    SELECT v_issue.id, s.id, pp.id, btrim(s.sheet_number), s.title, pp.rev_letter, pp.sha256
    FROM public.plan_sheets s
    JOIN public.plan_prints pp ON pp.id = s.current_print_id
    WHERE s.id = ANY (v_ids);
  END IF;

  -- One DTO tail for both arms: the drift is derived from the issue's own
  -- snapshots against its prior's, so a replay answers exactly what the first
  -- call answered.
  WITH mine AS (
    SELECT ip.sheet_id, ip.print_id, ip.sheet_number, ip.sheet_title,
           ip.rev_letter, ip.sha256
    FROM public.plan_issue_prints ip WHERE ip.issue_id = v_issue.id
  ),
  theirs AS (
    SELECT ip.sheet_id, ip.print_id
    FROM public.plan_issue_prints ip WHERE ip.issue_id = v_issue.prior_issue_id
  ),
  drift AS (
    SELECT COALESCE(m.sheet_id, t.sheet_id) AS sheet_id,
           CASE
             WHEN t.sheet_id IS NULL THEN 'added'
             WHEN m.sheet_id IS NULL THEN 'removed'
             WHEN t.print_id IS DISTINCT FROM m.print_id THEN 'changed'
             ELSE 'unchanged'
           END AS kind
    FROM mine m
    FULL OUTER JOIN theirs t ON t.sheet_id = m.sheet_id
  )
  SELECT
    (SELECT COALESCE(jsonb_agg(jsonb_build_object(
       'sheetId', sheet_id, 'printId', print_id, 'sheetNumber', sheet_number,
       'sheetTitle', sheet_title, 'revLetter', rev_letter, 'sha256', sha256
     ) ORDER BY upper(sheet_number)), '[]'::jsonb) FROM mine),
    (SELECT COALESCE(jsonb_agg(sheet_id), '[]'::jsonb) FROM drift WHERE kind = 'added'),
    (SELECT COALESCE(jsonb_agg(sheet_id), '[]'::jsonb) FROM drift WHERE kind = 'changed'),
    (SELECT COALESCE(jsonb_agg(sheet_id), '[]'::jsonb) FROM drift WHERE kind = 'removed'),
    (SELECT COALESCE(jsonb_agg(sheet_id), '[]'::jsonb) FROM drift WHERE kind = 'unchanged')
  INTO v_sheets, v_added, v_changed, v_removed, v_unchanged;

  RETURN jsonb_build_object(
    'issue', jsonb_build_object(
      'id', v_issue.id,
      'projectId', v_issue.project_id,
      'issueNumber', v_issue.issue_number,
      'name', v_issue.name,
      'issuedAt', v_issue.issued_at,
      'setChecksum', v_issue.set_checksum,
      'sheetCount', v_issue.sheet_count,
      'priorIssueId', v_issue.prior_issue_id),
    'idempotent', v_idempotent,
    'sheets', v_sheets,
    'drift', jsonb_build_object(
      'added', v_added, 'changed', v_changed,
      'removed', v_removed, 'unchanged', v_unchanged)
  );
END;
$$;
ALTER FUNCTION public.create_plan_issue(uuid,text,text,uuid[]) RESET ALL;
ALTER FUNCTION public.create_plan_issue(uuid,text,text,uuid[]) SET search_path = pg_catalog, public, extensions, pg_temp;
ALTER FUNCTION public.create_plan_issue(uuid,text,text,uuid[]) OWNER TO postgres;

CREATE OR REPLACE FUNCTION public.create_plan_transmittal(
  p_issue_id uuid,
  p_purpose text,
  p_party_id uuid DEFAULT NULL,
  p_recipient_name text DEFAULT NULL,
  p_recipient_company text DEFAULT NULL,
  p_message text DEFAULT NULL
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, extensions, pg_temp
AS $$
DECLARE
  v_issue       public.plan_issues%ROWTYPE;
  v_party       public.project_parties%ROWTYPE;
  v_name        text := NULLIF(btrim(COALESCE(p_recipient_name, '')), '');
  v_company     text := NULLIF(btrim(COALESCE(p_recipient_company, '')), '');
  v_transmittal public.plan_transmittals%ROWTYPE;
  v_token       text;
  v_token_row   public.plan_transmittal_tokens%ROWTYPE;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'sending an issue requires an authenticated designer'
      USING errcode = 'insufficient_privilege';
  END IF;

  -- One answer for a missing issue and for another studio's issue: a caller
  -- must not be able to tell the two apart.
  SELECT * INTO v_issue FROM public.plan_issues WHERE id = p_issue_id;
  IF NOT FOUND OR NOT EXISTS (
    SELECT 1 FROM public.projects p
    WHERE p.id = v_issue.project_id AND public.is_design_studio_comember(p.designer_id)
  ) THEN
    RAISE EXCEPTION 'plan issue % not found or access denied', p_issue_id
      USING errcode = 'insufficient_privilege';
  END IF;
  IF p_purpose IS NULL
     OR p_purpose NOT IN ('pricing', 'production', 'information', 'record') THEN
    RAISE EXCEPTION 'a transmittal is for pricing, production, information or record'
      USING errcode = 'check_violation';
  END IF;
  IF (p_party_id IS NULL) = (v_name IS NULL) THEN
    RAISE EXCEPTION 'name exactly one recipient: a roster party or a free-text name'
      USING errcode = 'check_violation';
  END IF;

  IF p_party_id IS NOT NULL THEN
    SELECT * INTO v_party FROM public.project_parties WHERE id = p_party_id;
    IF NOT FOUND OR v_party.project_id IS DISTINCT FROM v_issue.project_id THEN
      RAISE EXCEPTION 'party % does not belong to project %', p_party_id, v_issue.project_id
        USING errcode = 'check_violation';
    END IF;
    -- Snapshotted from the roster: what the record says must be what the roster
    -- said at send, not what it says after somebody corrects a spelling.
    v_name := v_party.display_name;
    v_company := v_party.company_name;
  END IF;

  INSERT INTO public.plan_transmittals (
    project_id, issue_id, party_id, party_display_name, party_company,
    party_email, purpose, message, created_by
  ) VALUES (
    v_issue.project_id, v_issue.id, p_party_id, v_name, v_company,
    CASE WHEN p_party_id IS NOT NULL THEN v_party.email END,
    p_purpose, NULLIF(btrim(COALESCE(p_message, '')), ''), auth.uid()
  ) RETURNING * INTO v_transmittal;

  v_token := encode(extensions.gen_random_bytes(32), 'hex');
  INSERT INTO public.plan_transmittal_tokens (
    transmittal_id, project_id, token_hash, created_by
  ) VALUES (
    v_transmittal.id, v_issue.project_id,
    encode(extensions.digest(v_token, 'sha256'), 'hex'), auth.uid()
  ) RETURNING * INTO v_token_row;

  RETURN jsonb_build_object(
    'transmittal', jsonb_build_object(
      'id', v_transmittal.id,
      'projectId', v_transmittal.project_id,
      'issueId', v_transmittal.issue_id,
      'issueName', v_issue.name,
      'partyId', v_transmittal.party_id,
      'partyDisplayName', v_transmittal.party_display_name,
      'partyCompany', v_transmittal.party_company,
      'partyEmail', v_transmittal.party_email,
      'purpose', v_transmittal.purpose,
      'message', v_transmittal.message,
      'sentAt', v_transmittal.sent_at,
      'expiresAt', v_token_row.expires_at),
    -- Returned ONCE. Only sha256(token) survives this call.
    'token', v_token
  );
END;
$$;
ALTER FUNCTION public.create_plan_transmittal(uuid,text,uuid,text,text,text) RESET ALL;
ALTER FUNCTION public.create_plan_transmittal(uuid,text,uuid,text,text,text) SET search_path = pg_catalog, public, extensions, pg_temp;
ALTER FUNCTION public.create_plan_transmittal(uuid,text,uuid,text,text,text) OWNER TO postgres;

CREATE OR REPLACE FUNCTION public.create_project_phase(
  p_project_id uuid,
  p_phase_key text,
  p_name text,
  p_sort_order integer DEFAULT 0,
  p_duration_days integer DEFAULT NULL,
  p_anchor_date date DEFAULT NULL,
  p_follows_phase_id uuid DEFAULT NULL,
  p_lane text DEFAULT 'main',
  p_duration_weeks integer DEFAULT NULL,
  p_fee_cents integer DEFAULT 0,
  p_revision_limit integer DEFAULT 2,
  p_deliverables jsonb DEFAULT '[]'::jsonb
)
RETURNS public.project_phases
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, pg_temp
AS $$
DECLARE
  v_actor uuid := auth.uid();
  v_project public.projects%ROWTYPE;
  v_created public.project_phases%ROWTYPE;
  v_guard_prior text;
  v_guard_set boolean := false;
BEGIN
  IF v_actor IS NULL THEN
    RAISE EXCEPTION 'create_project_phase requires an authenticated user'
      USING ERRCODE = 'insufficient_privilege';
  END IF;

  IF btrim(COALESCE(p_name, '')) = '' THEN
    RAISE EXCEPTION 'create_project_phase: name is required'
      USING ERRCODE = 'invalid_parameter_value';
  END IF;

  IF p_phase_key IS NOT NULL AND btrim(p_phase_key) = '' THEN
    RAISE EXCEPTION 'create_project_phase: phase_key cannot be blank'
      USING ERRCODE = 'invalid_parameter_value';
  END IF;

  IF p_lane NOT IN ('main', 'thread') THEN
    RAISE EXCEPTION 'create_project_phase: lane must be main or thread'
      USING ERRCODE = 'invalid_parameter_value';
  END IF;

  IF p_duration_days IS NOT NULL AND p_duration_days <= 0 THEN
    RAISE EXCEPTION 'create_project_phase: duration_days must be positive'
      USING ERRCODE = 'invalid_parameter_value';
  END IF;

  IF p_duration_weeks IS NOT NULL AND p_duration_weeks <= 0 THEN
    RAISE EXCEPTION 'create_project_phase: duration_weeks must be positive'
      USING ERRCODE = 'invalid_parameter_value';
  END IF;

  IF p_deliverables IS NULL OR jsonb_typeof(p_deliverables) <> 'array' THEN
    RAISE EXCEPTION 'create_project_phase: deliverables must be a JSON array'
      USING ERRCODE = 'invalid_parameter_value';
  END IF;

  -- Parent first serializes topology writers and conflicts with concurrent
  -- phase FK inserts. The deterministic full-graph lock freezes predecessors,
  -- roots, and main-successor cardinality for both assertions.
  SELECT * INTO v_project
  FROM public.projects
  WHERE id = p_project_id
  FOR UPDATE;

  IF NOT FOUND OR NOT public._can_author_proposal(v_project.designer_id) THEN
    RAISE EXCEPTION 'create_project_phase: project not found or access denied'
      USING ERRCODE = 'insufficient_privilege';
  END IF;

  PERFORM phase.id
  FROM public.project_phases AS phase
  WHERE phase.project_id = p_project_id
  ORDER BY phase.id
  FOR UPDATE;

  PERFORM public._assert_project_phase_topology(
    p_project_id,
    'create_project_phase'
  );

  IF p_follows_phase_id IS NOT NULL AND NOT EXISTS (
    SELECT 1
    FROM public.project_phases AS predecessor
    WHERE predecessor.id = p_follows_phase_id
      AND predecessor.project_id = p_project_id
  ) THEN
    RAISE EXCEPTION
      'create_project_phase: predecessor does not belong to project'
      USING ERRCODE = 'check_violation';
  END IF;

  v_guard_prior := current_setting('app.project_phase_topology_token', true);
  PERFORM set_config(
    'app.project_phase_topology_token',
    format('create_project_phase:%s:%s', p_project_id, pg_catalog.txid_current()),
    true
  );
  v_guard_set := true;

  INSERT INTO public.project_phases (
    project_id,
    phase_key,
    name,
    status,
    progress,
    sort_order,
    duration_days,
    anchor_date,
    follows_phase_id,
    lane,
    duration_weeks,
    fee_cents,
    revision_limit,
    deliverables
  ) VALUES (
    p_project_id,
    CASE WHEN p_phase_key IS NULL THEN NULL ELSE btrim(p_phase_key) END,
    btrim(p_name),
    'pending',
    0,
    p_sort_order,
    p_duration_days,
    p_anchor_date,
    p_follows_phase_id,
    p_lane,
    p_duration_weeks,
    p_fee_cents,
    p_revision_limit,
    p_deliverables
  )
  RETURNING * INTO v_created;

  PERFORM public._assert_project_phase_topology(
    p_project_id,
    'create_project_phase'
  );

  PERFORM set_config(
    'app.project_phase_topology_token', COALESCE(v_guard_prior, ''), true
  );
  v_guard_set := false;
  RETURN v_created;
EXCEPTION WHEN OTHERS THEN
  IF v_guard_set THEN
    PERFORM set_config(
      'app.project_phase_topology_token', COALESCE(v_guard_prior, ''), true
    );
  END IF;
  RAISE;
END;
$$;
ALTER FUNCTION public.create_project_phase(uuid,text,text,integer,integer,date,uuid,text,integer,integer,integer,jsonb) RESET ALL;
ALTER FUNCTION public.create_project_phase(uuid,text,text,integer,integer,date,uuid,text,integer,integer,integer,jsonb) SET search_path = pg_catalog, public, pg_temp;
ALTER FUNCTION public.create_project_phase(uuid,text,text,integer,integer,date,uuid,text,integer,integer,integer,jsonb) OWNER TO postgres;

CREATE OR REPLACE FUNCTION public.create_proposal_phase(
  p_proposal_id uuid,
  p_name text,
  p_phase_key text DEFAULT NULL,
  p_duration_weeks integer DEFAULT NULL,
  p_fee_cents integer DEFAULT 0,
  p_revision_limit integer DEFAULT 2,
  p_gate_condition text DEFAULT NULL,
  p_deliverables jsonb DEFAULT '[]'::jsonb,
  p_duration_days integer DEFAULT NULL,
  p_anchor_date date DEFAULT NULL,
  p_lane text DEFAULT 'main'
)
RETURNS public.proposal_phases
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, pg_temp
AS $$
DECLARE
  v_actor uuid := auth.uid();
  v_proposal public.proposals%ROWTYPE;
  v_phase public.proposal_phases%ROWTYPE;
  v_tail uuid;
  v_sort integer;
BEGIN
  IF v_actor IS NULL THEN
    RAISE EXCEPTION 'create_proposal_phase requires an authenticated user'
      USING ERRCODE = 'insufficient_privilege';
  END IF;
  IF btrim(COALESCE(p_name, '')) = '' THEN
    RAISE EXCEPTION 'phase name is required'
      USING ERRCODE = 'check_violation';
  END IF;
  IF p_lane IS NULL OR p_lane NOT IN ('main', 'thread') THEN
    RAISE EXCEPTION 'phase lane must be main or thread'
      USING ERRCODE = 'invalid_parameter_value';
  END IF;
  IF p_deliverables IS NULL OR jsonb_typeof(p_deliverables) <> 'array' THEN
    RAISE EXCEPTION 'p_deliverables must be a JSON array'
      USING ERRCODE = 'invalid_parameter_value';
  END IF;

  SELECT * INTO v_proposal
  FROM public.proposals
  WHERE id = p_proposal_id
  FOR UPDATE;

  IF NOT FOUND OR NOT public._can_author_proposal(v_proposal.designer_id) THEN
    RAISE EXCEPTION 'proposal % not found or access denied', p_proposal_id
      USING ERRCODE = 'insufficient_privilege';
  END IF;
  IF v_proposal.status <> 'draft' THEN
    RAISE EXCEPTION 'proposal % is %, so its authored copy is immutable',
      p_proposal_id, v_proposal.status
      USING ERRCODE = 'check_violation';
  END IF;

  PERFORM phase.id
  FROM public.proposal_phases AS phase
  WHERE phase.proposal_id = p_proposal_id
  ORDER BY phase.id
  FOR UPDATE;

  v_tail := public._proposal_phase_main_tail(
    p_proposal_id, 'create_proposal_phase precondition'
  );
  SELECT COALESCE(max(sort_order), -1) + 1 INTO v_sort
  FROM public.proposal_phases
  WHERE proposal_id = p_proposal_id;

  INSERT INTO public.proposal_phases (
    proposal_id, name, phase_key, duration_weeks, fee_cents,
    revision_limit, gate_condition, deliverables, sort_order,
    duration_days, anchor_date, follows_phase_id, lane
  ) VALUES (
    p_proposal_id, btrim(p_name), NULLIF(btrim(COALESCE(p_phase_key, '')), ''),
    p_duration_weeks, COALESCE(p_fee_cents, 0),
    COALESCE(p_revision_limit, 2),
    NULLIF(btrim(COALESCE(p_gate_condition, '')), ''), p_deliverables, v_sort,
    p_duration_days, p_anchor_date, v_tail, p_lane
  )
  RETURNING * INTO v_phase;

  PERFORM public._assert_proposal_phase_topology(
    p_proposal_id, 'create_proposal_phase result'
  );

  -- The parent lock also serializes every proposal-child writer through the
  -- draft-copy guard. Recompute the client-facing headline from canonical
  -- children before releasing it so a phase cannot commit without its fee.
  PERFORM public._recompute_proposal_total_locked(p_proposal_id);
  RETURN v_phase;
END;
$$;
ALTER FUNCTION public.create_proposal_phase(uuid,text,text,integer,integer,integer,text,jsonb,integer,date,text) RESET ALL;
ALTER FUNCTION public.create_proposal_phase(uuid,text,text,integer,integer,integer,text,jsonb,integer,date,text) SET search_path = pg_catalog, public, pg_temp;
ALTER FUNCTION public.create_proposal_phase(uuid,text,text,integer,integer,integer,text,jsonb,integer,date,text) OWNER TO postgres;

CREATE OR REPLACE FUNCTION public.create_service_addendum(
  p_project_id uuid,
  p_title text
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, pg_temp
AS $$
DECLARE
  v_actor uuid := auth.uid();
  v_origin public.proposals%ROWTYPE;
  v_source_proposal_id uuid;
  v_proposal_id uuid := extensions.gen_random_uuid();
  v_document_id uuid;
  v_title text := btrim(COALESCE(p_title, ''));
BEGIN
  IF v_actor IS NULL OR char_length(v_title) < 2 THEN
    RAISE EXCEPTION 'service addendum requires an authenticated author and title'
      USING ERRCODE = 'check_violation';
  END IF;
  SELECT origin_proposal.*
  INTO v_origin
  FROM public.project_commercial_documents origin
  JOIN public.proposals origin_proposal ON origin_proposal.id = origin.proposal_id
  WHERE origin.project_id = p_project_id AND origin.is_origin
    AND origin_proposal.commercial_state = 'executed'
    AND public._can_author_proposal(origin_proposal.designer_id)
  LIMIT 1;
  IF v_origin.id IS NULL THEN
    RAISE EXCEPTION 'project % has no executed design-services authority', p_project_id
      USING ERRCODE = 'check_violation';
  END IF;
  SELECT authority.source_proposal_id
  INTO v_source_proposal_id
  FROM public.project_billing_authorities authority
  WHERE authority.project_id = p_project_id AND authority.status = 'active'
  ORDER BY authority.effective_at DESC
  LIMIT 1;
  IF v_source_proposal_id IS NULL THEN
    RAISE EXCEPTION 'project % has no active billing authority', p_project_id
      USING ERRCODE = 'check_violation';
  END IF;

  INSERT INTO public.proposals (
    id, designer_id, client_id, designer_client_id, title, description,
    total_amount, status, version, parent_proposal_id, project_address,
    client_visibility_tier, feedback_enabled, document_kind, commercial_state
  ) VALUES (
    v_proposal_id, v_origin.designer_id, v_origin.client_id,
    v_origin.designer_client_id, v_title, 'Additional design-services authority',
    0, 'draft', 1, v_source_proposal_id, v_origin.project_address,
    v_origin.client_visibility_tier, v_origin.feedback_enabled,
    'service_addendum', 'draft'
  );
  INSERT INTO public.proposal_service_terms (
    proposal_id, scope, deliverables, exclusions, billing_ceiling_cents,
    retainer_amount_cents, retainer_activation_policy, billing_cadence,
    currency, terms, current_rate_version, furnishings_deposit_percent
  ) SELECT
    v_proposal_id, t.scope, t.deliverables, t.exclusions,
    t.billing_ceiling_cents, 0, 'immediate', t.billing_cadence,
    t.currency, t.terms, t.current_rate_version, t.furnishings_deposit_percent
  FROM public.proposal_service_terms t WHERE t.proposal_id = v_source_proposal_id;
  INSERT INTO public.proposal_service_rates (
    proposal_id, version, role_name, hourly_rate_cents, sort_order, effective_at
  ) SELECT v_proposal_id, r.version + 1, r.role_name, r.hourly_rate_cents,
      r.sort_order, now()
  FROM public.proposal_service_rates r WHERE r.proposal_id = v_source_proposal_id;
  UPDATE public.proposal_service_terms SET current_rate_version = current_rate_version + 1
  WHERE proposal_id = v_proposal_id;
  INSERT INTO public.project_commercial_documents (
    project_id, proposal_id, document_kind, source_proposal_id, created_by
  ) VALUES (
    p_project_id, v_proposal_id, 'service_addendum', v_source_proposal_id, v_actor
  ) RETURNING id INTO v_document_id;

  RETURN jsonb_build_object(
    'proposalId', v_proposal_id, 'documentId', v_document_id,
    'projectId', p_project_id, 'documentKind', 'service_addendum',
    'commercialState', 'draft'
  );
END;
$$;
ALTER FUNCTION public.create_service_addendum(uuid,text) RESET ALL;
ALTER FUNCTION public.create_service_addendum(uuid,text) SET search_path = pg_catalog, public, pg_temp;
ALTER FUNCTION public.create_service_addendum(uuid,text) OWNER TO postgres;

CREATE OR REPLACE FUNCTION public.create_spec_book_share(
  p_artifact_id uuid,
  p_label text,
  p_expires_at timestamptz DEFAULT NULL
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, extensions, pg_temp
AS $$
DECLARE
  v_artifact public.spec_book_artifacts;
  v_revision public.spec_book_revisions;
  v_designer_id uuid;
  v_token text;
  v_hash text;
  v_share_id uuid;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'authentication required'
      USING ERRCODE = 'insufficient_privilege';
  END IF;
  IF p_expires_at IS NOT NULL AND p_expires_at <= now() THEN
    RAISE EXCEPTION 'expiry must be in the future'
      USING ERRCODE = 'check_violation';
  END IF;

  SELECT artifact.*
  INTO v_artifact
  FROM public.spec_book_artifacts AS artifact
  JOIN public.spec_book_revisions AS revision
    ON revision.id = artifact.revision_id
  JOIN public.spec_books AS book ON book.id = revision.spec_book_id
  JOIN public.projects AS project ON project.id = book.project_id
  JOIN public.project_documents AS document
    ON document.id = artifact.project_document_id
  WHERE artifact.id = p_artifact_id
    AND artifact.status = 'ready'
    AND revision.status = 'issued'
    AND document.status = 'ready';

  IF NOT FOUND THEN
    RAISE EXCEPTION 'ready issued artifact not found or not accessible'
      USING ERRCODE = 'insufficient_privilege';
  END IF;

  SELECT revision.* INTO v_revision
  FROM public.spec_book_revisions AS revision
  WHERE revision.id = v_artifact.revision_id;

  SELECT project.designer_id INTO v_designer_id
  FROM public.spec_books AS book
  JOIN public.projects AS project ON project.id = book.project_id
  WHERE book.id = v_revision.spec_book_id;

  IF NOT public.is_design_studio_comember(v_designer_id) THEN
    RAISE EXCEPTION 'ready issued artifact not found or not accessible'
      USING ERRCODE = 'insufficient_privilege';
  END IF;

  v_token := encode(extensions.gen_random_bytes(32), 'hex');
  v_hash := encode(extensions.digest(v_token, 'sha256'), 'hex');

  INSERT INTO public.document_shares (
    proposal_id,
    spec_book_artifact_id,
    token_hash,
    label,
    visibility,
    status,
    expires_at,
    created_by
  )
  VALUES (
    NULL,
    p_artifact_id,
    v_hash,
    NULLIF(btrim(p_label), ''),
    jsonb_build_object(
      'audience', v_artifact.audience,
      'format', v_artifact.format
    ),
    'active',
    p_expires_at,
    auth.uid()
  )
  RETURNING id INTO v_share_id;

  RETURN jsonb_build_object(
    'id', v_share_id,
    'token', v_token,
    'artifactId', p_artifact_id,
    'audience', v_artifact.audience,
    'expiresAt', p_expires_at
  );
END;
$$;
ALTER FUNCTION public.create_spec_book_share(uuid,text,timestamp with time zone) RESET ALL;
ALTER FUNCTION public.create_spec_book_share(uuid,text,timestamp with time zone) SET search_path = pg_catalog, public, extensions, pg_temp;
ALTER FUNCTION public.create_spec_book_share(uuid,text,timestamp with time zone) OWNER TO postgres;

CREATE OR REPLACE FUNCTION public.create_trade_scope(
  p_project_id uuid,
  p_title text
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, pg_temp
AS $$
DECLARE
  v_actor uuid := auth.uid();
  v_project public.projects%ROWTYPE;
  v_origin public.proposals%ROWTYPE;
  v_title text := btrim(COALESCE(p_title, ''));
  v_proposal_id uuid := extensions.gen_random_uuid();
  v_document_id uuid;
BEGIN
  IF v_actor IS NULL OR char_length(v_title) < 2 THEN
    RAISE EXCEPTION 'a trade scope requires an authenticated author and a title'
      USING ERRCODE = 'check_violation';
  END IF;

  SELECT * INTO v_project FROM public.projects WHERE id = p_project_id FOR SHARE;
  IF NOT FOUND OR NOT public._can_author_proposal(v_project.designer_id) THEN
    RAISE EXCEPTION 'project % not found or access denied', p_project_id
      USING ERRCODE = 'insufficient_privilege';
  END IF;

  -- The same origin proof the furnishings rail requires, byte-for-byte. A trade
  -- scope is an exercise of commercial authority; a project with no executed
  -- design-services agreement has none to exercise.
  IF NOT EXISTS (
    SELECT 1 FROM public.project_commercial_documents d
    JOIN public.proposals p ON p.id = d.proposal_id
    WHERE d.project_id = p_project_id AND d.is_origin
      AND d.document_kind = 'design_services' AND p.commercial_state = 'executed'
  ) THEN
    RAISE EXCEPTION 'project % has no executed design-services origin', p_project_id
      USING ERRCODE = 'check_violation';
  END IF;

  SELECT origin_proposal.* INTO v_origin
  FROM public.project_commercial_documents origin
  JOIN public.proposals origin_proposal ON origin_proposal.id = origin.proposal_id
  WHERE origin.project_id = p_project_id AND origin.is_origin
    AND origin.document_kind = 'design_services'
    AND origin_proposal.commercial_state = 'executed'
  LIMIT 1;

  INSERT INTO public.proposals (
    id, designer_id, client_id, designer_client_id, title, description,
    subtotal, discount_amount, discount_percent, tax_rate, tax_amount,
    total_amount, deposit_percent, status, version, project_address,
    client_visibility_tier, feedback_enabled, document_kind, commercial_state
  ) VALUES (
    v_proposal_id, v_project.designer_id, v_project.client_id,
    v_origin.designer_client_id, v_title,
    'Trade work priced as a scope against a named party.',
    0, 0, 0, 0, 0, 0, 0, 'draft', 1,
    v_origin.project_address, 'full', v_origin.feedback_enabled,
    'trade_scope', 'draft'
  );

  -- The skeleton. Price and party arrive through the studio's editing surface
  -- and set_trade_scope_party / select_trade_bid; what matters here is that the
  -- row EXISTS, so every later read has one shape to answer with.
  INSERT INTO public.trade_scope_terms (proposal_id) VALUES (v_proposal_id);

  INSERT INTO public.project_commercial_documents (
    project_id, proposal_id, document_kind, created_by
  ) VALUES (
    p_project_id, v_proposal_id, 'trade_scope', v_actor
  ) RETURNING id INTO v_document_id;

  RETURN jsonb_build_object(
    'proposalId', v_proposal_id,
    'documentId', v_document_id,
    'projectId', p_project_id,
    'title', v_title,
    'commercialState', 'draft',
    'progressState', 'none',
    'documentFingerprint', public._commercial_document_fingerprint(v_proposal_id)
  );
END;
$$;
ALTER FUNCTION public.create_trade_scope(uuid,text) RESET ALL;
ALTER FUNCTION public.create_trade_scope(uuid,text) SET search_path = pg_catalog, public, pg_temp;
ALTER FUNCTION public.create_trade_scope(uuid,text) OWNER TO postgres;

CREATE OR REPLACE FUNCTION public.cut_schedule_revision(
  p_project_id UUID,
  p_reason     TEXT DEFAULT NULL
)
RETURNS INTEGER
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
  v_actor    UUID := auth.uid();   -- derived HERE, never caller-supplied (banner §1)
  v_snapshot JSONB;
  v_new_v    INTEGER;
BEGIN
  -- NULL hard-fail: no JWT (raw service_role / anonymous session) means no
  -- attributable actor — an append-only audit ledger never takes an
  -- unattributed row. Real callers (sign_proposal as the client,
  -- record_offline_signature / commit_schedule_edit as the designer) always
  -- carry a valid auth.uid() through the DEFINER hop.
  IF v_actor IS NULL THEN
    RAISE EXCEPTION 'schedule revision refused: no authenticated actor (auth.uid() is NULL)';
  END IF;

  -- Actor guard: designer (or a studio comember of the designer) OR client
  -- of the project (see banner §1). R105: designer_id = v_actor widened to
  -- is_studio_comember(p.designer_id) — is_studio_comember's own self-branch
  -- (p_owner = auth.uid()) still covers the plain designer-owns-it case, so
  -- this is a strict widening, not a behavior change for a solo studio.
  -- Neither → raise.
  IF NOT EXISTS (
    SELECT 1 FROM public.projects p
    WHERE p.id = p_project_id
      AND (public.is_studio_comember(p.designer_id) OR p.client_id = v_actor)
  ) THEN
    RAISE EXCEPTION 'schedule revision refused: actor % is neither designer nor client of project % (or the project does not exist)',
      v_actor, p_project_id;
  END IF;

  -- Snapshot the resolver-input field set: an ARRAY of phases (ordered by
  -- sort_order) each embedding its milestones ARRAY. COALESCE guarantees a
  -- jsonb ARRAY even for a project with zero phases (00323 CHECK).
  SELECT COALESCE(jsonb_agg(
           jsonb_build_object(
             'id',               ph.id,
             'name',             ph.name,
             'phase_key',        ph.phase_key,
             'duration_days',    ph.duration_days,
             'duration_weeks',   ph.duration_weeks,
             'follows_phase_id', ph.follows_phase_id,
             'anchor_date',      ph.anchor_date,
             'lane',             ph.lane,
             'start_date',       ph.start_date,
             'target_end_date',  ph.target_end_date,
             'sort_order',       ph.sort_order,
             'status',           ph.status,
             'milestones', COALESCE((
               SELECT jsonb_agg(
                        jsonb_build_object(
                          'id',          sm.id,
                          'name',        sm.name,
                          'kind',        sm.kind,
                          'offset_days', sm.offset_days,
                          'anchor_date', sm.anchor_date,
                          'status',      sm.status,
                          'sort_order',  sm.sort_order
                        ) ORDER BY sm.sort_order, sm.id
                      )
               FROM public.schedule_milestones sm
               WHERE sm.phase_id = ph.id
             ), '[]'::jsonb)
           ) ORDER BY ph.sort_order, ph.id
         ), '[]'::jsonb)
    INTO v_snapshot
    FROM public.project_phases ph
   WHERE ph.project_id = p_project_id;

  -- v = next per-project sequence, computed inline. Benign race; the
  -- UNIQUE(project_id, v) backstop (00323) fails a loser rather than
  -- overwriting (see banner §1).
  INSERT INTO public.schedule_revisions (project_id, v, actor, reason, phase_snapshots)
  SELECT p_project_id,
         COALESCE(MAX(v), 0) + 1,
         v_actor,
         COALESCE(p_reason, 'Schedule revised'),
         v_snapshot
    FROM public.schedule_revisions
   WHERE project_id = p_project_id
  RETURNING v INTO v_new_v;

  RETURN v_new_v;
END;
$$;
ALTER FUNCTION public.cut_schedule_revision(uuid,text) RESET ALL;
ALTER FUNCTION public.cut_schedule_revision(uuid,text) SET search_path = pg_catalog, public, pg_temp;
ALTER FUNCTION public.cut_schedule_revision(uuid,text) OWNER TO postgres;

CREATE OR REPLACE FUNCTION public.delete_client_decision_draft(p_decision_id uuid)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, pg_temp
AS $$
DECLARE
  v_decision public.client_decisions%ROWTYPE;
  v_cleared_ffe integer;
  v_cleared_tasks integer;
BEGIN
  SELECT * INTO v_decision
  FROM public.client_decisions
  WHERE id = p_decision_id
  FOR UPDATE;
  IF NOT FOUND OR NOT public._can_author_proposal(v_decision.designer_id) THEN
    RAISE EXCEPTION 'decision % not found or access denied', p_decision_id
      USING ERRCODE = 'insufficient_privilege';
  END IF;
  IF v_decision.status <> 'draft' THEN
    RAISE EXCEPTION 'only draft decisions may be deleted'
      USING ERRCODE = 'check_violation';
  END IF;

  UPDATE public.project_ffe_items
  SET blocked = false,
      blocked_reason = NULL,
      blocked_by_decision_id = NULL,
      updated_at = now()
  WHERE blocked_by_decision_id = p_decision_id;
  GET DIAGNOSTICS v_cleared_ffe = ROW_COUNT;

  UPDATE public.project_tasks
  SET status = 'todo', blocked_by_item_id = NULL, updated_at = now()
  WHERE blocked_by_item_id = p_decision_id;
  GET DIAGNOSTICS v_cleared_tasks = ROW_COUNT;

  PERFORM set_config('app.client_decision_write_id', p_decision_id::text, true);
  DELETE FROM public.client_decisions WHERE id = p_decision_id;
  PERFORM set_config('app.client_decision_write_id', '', true);

  RETURN jsonb_build_object(
    'deleted_decision_id', p_decision_id,
    'project_id', v_decision.project_id,
    'designer_client_id', v_decision.designer_client_id,
    'cleared_ffe_items', v_cleared_ffe,
    'cleared_tasks', v_cleared_tasks
  );
END;
$$;
ALTER FUNCTION public.delete_client_decision_draft(uuid) RESET ALL;
ALTER FUNCTION public.delete_client_decision_draft(uuid) SET search_path = pg_catalog, public, pg_temp;
ALTER FUNCTION public.delete_client_decision_draft(uuid) OWNER TO postgres;

CREATE OR REPLACE FUNCTION public.delete_plan_sheet(p_sheet_id uuid)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, extensions, pg_temp
AS $$
DECLARE
  v_sheet public.plan_sheets%ROWTYPE;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'retiring a plan sheet requires an authenticated designer'
      USING errcode = 'insufficient_privilege';
  END IF;

  -- Authority before the lock, one answer for both misses — see the same note
  -- on set_plan_sheet_state.
  IF NOT EXISTS (
    SELECT 1 FROM public.plan_sheets s
    JOIN public.projects p ON p.id = s.project_id
    WHERE s.id = p_sheet_id AND public.is_design_studio_comember(p.designer_id)
  ) THEN
    RAISE EXCEPTION 'plan sheet % not found or access denied', p_sheet_id
      USING errcode = 'insufficient_privilege';
  END IF;

  SELECT * INTO v_sheet FROM public.plan_sheets WHERE id = p_sheet_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'plan sheet % not found or access denied', p_sheet_id
      USING errcode = 'insufficient_privilege';
  END IF;
  IF EXISTS (SELECT 1 FROM public.plan_prints pp WHERE pp.sheet_id = v_sheet.id) THEN
    RAISE EXCEPTION 'sheet % has filed prints and cannot be deleted', v_sheet.sheet_number
      USING errcode = 'check_violation';
  END IF;

  PERFORM set_config('app.plan_room_sheet_maintenance', v_sheet.id::text, true);
  DELETE FROM public.plan_sheets WHERE id = v_sheet.id;
  PERFORM set_config('app.plan_room_sheet_maintenance', '', true);

  RETURN jsonb_build_object('deleted', true);
END;
$$;
ALTER FUNCTION public.delete_plan_sheet(uuid) RESET ALL;
ALTER FUNCTION public.delete_plan_sheet(uuid) SET search_path = pg_catalog, public, extensions, pg_temp;
ALTER FUNCTION public.delete_plan_sheet(uuid) OWNER TO postgres;

CREATE OR REPLACE FUNCTION public.delete_project_phase(
  p_project_id uuid,
  p_phase_id uuid
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, pg_temp
AS $$
DECLARE
  v_actor uuid := auth.uid();
  v_project public.projects%ROWTYPE;
  v_target public.project_phases%ROWTYPE;
  v_predecessor_phase_id uuid;
  v_follower_ids uuid[] := ARRAY[]::uuid[];
  v_follower_count integer := 0;
  v_rows integer := 0;
  v_guard_prior text;
  v_guard_set boolean := false;
BEGIN
  IF v_actor IS NULL THEN
    RAISE EXCEPTION 'delete_project_phase requires an authenticated user'
      USING ERRCODE = 'insufficient_privilege';
  END IF;

  -- Project → complete project phase graph → every direct follower is the
  -- global lock order shared by all 00398 mutation boundaries. The target row
  -- lock conflicts with new FK children, so no follower can appear after the
  -- server derives the complete relink set.
  SELECT * INTO v_project
  FROM public.projects
  WHERE id = p_project_id
  FOR UPDATE;

  IF NOT FOUND OR NOT public._can_author_proposal(v_project.designer_id) THEN
    RAISE EXCEPTION 'delete_project_phase: project not found or access denied'
      USING ERRCODE = 'insufficient_privilege';
  END IF;

  PERFORM phase.id
  FROM public.project_phases AS phase
  WHERE phase.project_id = p_project_id
  ORDER BY phase.id
  FOR UPDATE;

  SELECT * INTO v_target
  FROM public.project_phases AS phase
  WHERE phase.id = p_phase_id
    AND phase.project_id = p_project_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'delete_project_phase: phase does not belong to project'
      USING ERRCODE = 'check_violation';
  END IF;

  -- Lock direct followers explicitly, including corrupt foreign followers.
  -- The topology assertion below then fails closed before any mutation.
  PERFORM follower.id
  FROM public.project_phases AS follower
  WHERE follower.follows_phase_id = p_phase_id
  ORDER BY follower.id
  FOR UPDATE;

  PERFORM public._assert_project_phase_topology(
    p_project_id,
    'delete_project_phase'
  );

  IF v_target.status <> 'pending' THEN
    RAISE EXCEPTION 'delete_project_phase: only pending phases may be deleted'
      USING ERRCODE = 'check_violation';
  END IF;

  v_predecessor_phase_id := v_target.follows_phase_id;

  SELECT COALESCE(array_agg(follower.id ORDER BY follower.id), ARRAY[]::uuid[]),
         count(*)
  INTO v_follower_ids, v_follower_count
  FROM public.project_phases AS follower
  WHERE follower.project_id = p_project_id
    AND follower.follows_phase_id = p_phase_id;

  v_guard_prior := current_setting('app.project_phase_topology_token', true);
  PERFORM set_config(
    'app.project_phase_topology_token',
    format('delete_project_phase:%s:%s', p_project_id, pg_catalog.txid_current()),
    true
  );
  v_guard_set := true;

  UPDATE public.project_phases AS follower
  SET follows_phase_id = v_predecessor_phase_id,
      updated_at = clock_timestamp()
  WHERE follower.project_id = p_project_id
    AND follower.follows_phase_id = p_phase_id;
  GET DIAGNOSTICS v_rows = ROW_COUNT;

  IF v_rows <> v_follower_count THEN
    RAISE EXCEPTION 'delete_project_phase: follower set changed during relink'
      USING ERRCODE = 'serialization_failure';
  END IF;

  DELETE FROM public.project_phases AS phase
  WHERE phase.id = p_phase_id
    AND phase.project_id = p_project_id
    AND phase.status = 'pending';
  GET DIAGNOSTICS v_rows = ROW_COUNT;

  IF v_rows <> 1 THEN
    RAISE EXCEPTION 'delete_project_phase: phase changed during delete'
      USING ERRCODE = 'serialization_failure';
  END IF;

  PERFORM public._assert_project_phase_topology(
    p_project_id,
    'delete_project_phase'
  );

  PERFORM set_config(
    'app.project_phase_topology_token', COALESCE(v_guard_prior, ''), true
  );
  v_guard_set := false;

  RETURN jsonb_build_object(
    'deleted_phase_id', p_phase_id,
    'predecessor_phase_id', v_predecessor_phase_id,
    'relinked_phase_ids', v_follower_ids
  );
EXCEPTION WHEN OTHERS THEN
  IF v_guard_set THEN
    PERFORM set_config(
      'app.project_phase_topology_token', COALESCE(v_guard_prior, ''), true
    );
  END IF;
  RAISE;
END;
$$;
ALTER FUNCTION public.delete_project_phase(uuid,uuid) RESET ALL;
ALTER FUNCTION public.delete_project_phase(uuid,uuid) SET search_path = pg_catalog, public, pg_temp;
ALTER FUNCTION public.delete_project_phase(uuid,uuid) OWNER TO postgres;

CREATE OR REPLACE FUNCTION public.derive_working_budget_draft(p_project_id uuid)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, pg_temp
AS $$
DECLARE
  v_actor uuid := auth.uid();
  v_project public.projects%ROWTYPE;
  v_version public.project_budget_versions%ROWTYPE;
BEGIN
  SELECT * INTO v_project FROM public.projects WHERE id = p_project_id FOR SHARE;
  IF NOT FOUND OR v_actor IS NULL
     OR NOT public.is_studio_comember(v_project.designer_id) THEN
    RAISE EXCEPTION 'project % not found or access denied', p_project_id
      USING ERRCODE = 'insufficient_privilege';
  END IF;

  SELECT * INTO v_version FROM public.project_budget_versions
  WHERE project_id = p_project_id
  ORDER BY version DESC LIMIT 1 FOR UPDATE;
  IF v_version.id IS NULL OR v_version.status <> 'draft' THEN
    INSERT INTO public.project_budget_versions (project_id, version, created_by)
    VALUES (p_project_id, COALESCE(v_version.version, 0) + 1, v_actor)
    RETURNING * INTO v_version;
  END IF;

  -- Additive only. A studio target the designer typed is a JUDGEMENT; the
  -- schedule rollup is an OBSERVATION. Re-deriving must never overwrite the
  -- judgement, so an existing (version, room, category) line is left alone and
  -- only genuinely new room×category pairs appear.
  --
  -- The conflict key is the ROOM ID, not the room name: two rooms both called
  -- "Bedroom" are two rooms, and the old name key silently discarded the
  -- second one's rollup — leaving its schedule lines permanently un-releasable
  -- against an id-keyed coverage proof.
  INSERT INTO public.project_budget_lines (
    budget_version_id, project_room_id, room_name, category,
    low_cents, target_cents, high_cents, sort_order
  )
  SELECT
    v_version.id, rollup.room_id, rollup.room_name, rollup.category,
    0,
    public._cents_to_int4(rollup.target,
      format('the scheduled rollup for %s · %s', rollup.room_name, rollup.category)),
    0,
    rollup.sort_order
  FROM (
    SELECT
      room.id AS room_id, room.name AS room_name,
      COALESCE(item.ffe_category, 'Uncategorized') AS category,
      room.sort_order AS sort_order,
      SUM(CASE
        WHEN item.item_type = 'fixed' THEN COALESCE(item.line_total_cents, 0)
        WHEN item.item_type = 'allowance' THEN COALESCE(item.budget_max_cents, 0)
        ELSE 0 END)::bigint AS target
    FROM public.project_ffe_items item
    JOIN public.project_rooms room ON room.id = item.project_room_id
    WHERE item.project_id = p_project_id
      -- 00423 delta: a trade scope's presence lines are not furnishings, and
      -- this is a FURNISHING budget. Without this predicate the rollup mints a
      -- 'trade work' budget line out of them — which is also what let the
      -- presence lines into publish_budget_checkpoint's scheduled stamp, since
      -- that stamp matches a schedule line to a budget line on category.
      AND item.trade_scope_document_id IS NULL
    GROUP BY room.id, room.name, COALESCE(item.ffe_category, 'Uncategorized'),
             room.sort_order
  ) rollup
  -- A legacy line carrying no project_room_id still owns its (name, category)
  -- pair on this version. Re-deriving must not shadow that judgement with a
  -- second, id-keyed line for the same room and category.
  WHERE NOT EXISTS (
    SELECT 1 FROM public.project_budget_lines legacy
    WHERE legacy.budget_version_id = v_version.id
      AND legacy.project_room_id IS NULL
      AND legacy.room_name = rollup.room_name
      AND legacy.category = rollup.category
  )
  ON CONFLICT (budget_version_id, project_room_id, category)
    WHERE project_room_id IS NOT NULL
  DO NOTHING;

  RETURN public.get_project_working_budget(p_project_id);
END;
$$;
ALTER FUNCTION public.derive_working_budget_draft(uuid) RESET ALL;
ALTER FUNCTION public.derive_working_budget_draft(uuid) SET search_path = pg_catalog, public, pg_temp;
ALTER FUNCTION public.derive_working_budget_draft(uuid) OWNER TO postgres;

CREATE OR REPLACE FUNCTION public.duplicate_proposal_board(
  p_proposal_id uuid,
  p_board_id uuid
)
RETURNS public.proposal_boards
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, pg_temp
AS $$
DECLARE
  v_actor uuid := auth.uid();
  v_proposal public.proposals%ROWTYPE;
  v_source public.proposal_boards%ROWTYPE;
  v_new_board public.proposal_boards%ROWTYPE;
  v_next_sort_order integer;
BEGIN
  IF v_actor IS NULL THEN
    RAISE EXCEPTION 'duplicate_proposal_board requires an authenticated user'
      USING ERRCODE = 'insufficient_privilege';
  END IF;

  -- The parent lock serializes copies within this proposal and prevents a
  -- concurrent parent delete while the complete child graph is validated.
  SELECT * INTO v_proposal
  FROM public.proposals
  WHERE id = p_proposal_id
  FOR UPDATE;

  IF NOT FOUND OR NOT public._can_author_proposal(v_proposal.designer_id) THEN
    RAISE EXCEPTION
      'duplicate_proposal_board: proposal % not found or access denied',
      p_proposal_id
      USING ERRCODE = 'insufficient_privilege';
  END IF;

  -- A proposal copy may never be sourced from a project-owned board or from a
  -- board attached to a different proposal.
  SELECT * INTO v_source
  FROM public.proposal_boards
  WHERE id = p_board_id
    AND proposal_id = p_proposal_id
    AND project_id IS NULL
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION
      'duplicate_proposal_board: board % does not belong to proposal %',
      p_board_id, p_proposal_id
      USING ERRCODE = 'check_violation';
  END IF;

  IF v_source.scope_room_id IS NOT NULL THEN
    PERFORM 1
    FROM public.proposal_scope_rooms AS room
    WHERE room.id = v_source.scope_room_id
      AND room.proposal_id = p_proposal_id
    FOR UPDATE;

    IF NOT FOUND THEN
      RAISE EXCEPTION
        'duplicate_proposal_board: board scope room does not belong to proposal %',
        p_proposal_id
        USING ERRCODE = 'check_violation';
    END IF;
  END IF;

  -- Freeze the exact item snapshot. The board FOR UPDATE lock also blocks new
  -- FK children until this transaction ends; these row locks block edits to
  -- existing items while validation and INSERT ... SELECT run.
  PERFORM 1
  FROM public.proposal_board_items AS item
  WHERE item.board_id = p_board_id
  ORDER BY item.id
  FOR UPDATE;

  -- Stabilize referenced proposal-scoped rows too. Without these locks a
  -- concurrent author could move a palette/capture to another proposal after
  -- validation but before the copied item rows are inserted.
  PERFORM 1
  FROM public.proposal_palettes AS palette
  WHERE palette.id IN (
    SELECT item.palette_id
    FROM public.proposal_board_items AS item
    WHERE item.board_id = p_board_id
      AND item.palette_id IS NOT NULL
  )
  ORDER BY palette.id
  FOR UPDATE;

  PERFORM 1
  FROM public.proposal_captures AS capture
  WHERE capture.id IN (
    SELECT item.capture_id
    FROM public.proposal_board_items AS item
    WHERE item.board_id = p_board_id
      AND item.capture_id IS NOT NULL
  )
  ORDER BY capture.id
  FOR UPDATE;

  IF EXISTS (
    SELECT 1
    FROM public.proposal_board_items AS item
    LEFT JOIN public.proposal_palettes AS palette
      ON palette.id = item.palette_id
    WHERE item.board_id = p_board_id
      AND item.palette_id IS NOT NULL
      AND (
        palette.id IS NULL
        OR palette.proposal_id IS DISTINCT FROM p_proposal_id
      )
  ) THEN
    RAISE EXCEPTION
      'duplicate_proposal_board: board contains a palette from another proposal'
      USING ERRCODE = 'check_violation';
  END IF;

  IF EXISTS (
    SELECT 1
    FROM public.proposal_board_items AS item
    LEFT JOIN public.proposal_captures AS capture
      ON capture.id = item.capture_id
    WHERE item.board_id = p_board_id
      AND item.capture_id IS NOT NULL
      AND (
        capture.id IS NULL
        OR capture.proposal_id IS DISTINCT FROM p_proposal_id
      )
  ) THEN
    RAISE EXCEPTION
      'duplicate_proposal_board: board contains a capture from another proposal'
      USING ERRCODE = 'check_violation';
  END IF;

  SELECT COALESCE(max(board.sort_order), -1) + 1
  INTO v_next_sort_order
  FROM public.proposal_boards AS board
  WHERE board.proposal_id = p_proposal_id;

  INSERT INTO public.proposal_boards (
    proposal_id,
    project_id,
    name,
    scope_room_id,
    cover_image_url,
    canvas_width,
    canvas_height,
    background_color,
    sort_order,
    sections,
    status
  ) VALUES (
    p_proposal_id,
    NULL,
    v_source.name || ' (Copy)',
    v_source.scope_room_id,
    v_source.cover_image_url,
    v_source.canvas_width,
    v_source.canvas_height,
    v_source.background_color,
    v_next_sort_order,
    v_source.sections,
    'active'
  )
  RETURNING * INTO v_new_board;

  INSERT INTO public.proposal_board_items (
    board_id,
    type,
    x,
    y,
    width,
    height,
    z_index,
    rotation,
    locked,
    product_id,
    capture_id,
    palette_id,
    image_url,
    content,
    data
  )
  SELECT
    v_new_board.id,
    item.type,
    item.x,
    item.y,
    item.width,
    item.height,
    item.z_index,
    item.rotation,
    item.locked,
    item.product_id,
    item.capture_id,
    item.palette_id,
    item.image_url,
    item.content,
    item.data
  FROM public.proposal_board_items AS item
  WHERE item.board_id = p_board_id
  ORDER BY item.id;

  RETURN v_new_board;
END;
$$;
ALTER FUNCTION public.duplicate_proposal_board(uuid,uuid) RESET ALL;
ALTER FUNCTION public.duplicate_proposal_board(uuid,uuid) SET search_path = pg_catalog, public, pg_temp;
ALTER FUNCTION public.duplicate_proposal_board(uuid,uuid) OWNER TO postgres;

CREATE OR REPLACE FUNCTION public.engage_trade_scope(
  p_proposal_id uuid,
  p_disclosed_impact jsonb DEFAULT NULL
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, pg_temp
AS $$
DECLARE
  v_proposal public.proposals%ROWTYPE;
  v_document public.project_commercial_documents%ROWTYPE;
  v_terms public.trade_scope_terms%ROWTYPE;
  v_section record;
  v_room_label text;
  v_first boolean := true;
  v_created integer := 0;
  v_previous_progress text := current_setting('app.trade_scope_progress_id', true);
  v_anchor_phase_id uuid;   -- 00475
BEGIN
  SELECT * INTO v_proposal FROM public.proposals WHERE id = p_proposal_id FOR UPDATE;
  IF NOT FOUND OR v_proposal.document_kind <> 'trade_scope'
     OR auth.uid() IS NULL
     OR NOT public._can_author_proposal(v_proposal.designer_id)
  THEN
    RAISE EXCEPTION 'trade scope % not found or access denied', p_proposal_id
      USING ERRCODE = 'insufficient_privilege';
  END IF;
  SELECT * INTO v_document FROM public.project_commercial_documents
  WHERE proposal_id = p_proposal_id FOR UPDATE;
  IF v_proposal.commercial_state IS DISTINCT FROM 'executed'
     OR v_document.executed_at IS NULL THEN
    RAISE EXCEPTION 'a trade scope must be executed before it can be engaged'
      USING ERRCODE = 'check_violation';
  END IF;
  IF NOT EXISTS (
    SELECT 1 FROM public.invoices i
    WHERE i.id = v_document.deposit_invoice_id
      AND i.status = 'paid' AND i.amount_paid_cents >= i.total_cents
  ) THEN
    RAISE EXCEPTION 'the trade scope deposit invoice must be paid before engagement'
      USING ERRCODE = 'check_violation';
  END IF;

  SELECT * INTO v_terms FROM public.trade_scope_terms
  WHERE proposal_id = p_proposal_id FOR UPDATE;

  -- Idempotent: a scope already engaged (or further along) answers with where it
  -- is and mints nothing. Re-calling must never double the presence lines.
  IF v_terms.progress_state <> 'none' THEN
    RETURN jsonb_build_object(
      'proposalId', p_proposal_id,
      'documentId', v_document.id,
      'progressState', v_terms.progress_state,
      'engagedAt', v_terms.engaged_at,
      'presenceLineIds', COALESCE((
        SELECT jsonb_agg(i.id ORDER BY i.sort_order, i.id)
        FROM public.project_ffe_items i
        WHERE i.trade_scope_document_id = v_document.id), '[]'::jsonb),
      'newlyEngaged', false
    );
  END IF;

  PERFORM set_config('app.trade_scope_progress_id', p_proposal_id::text, true);
  UPDATE public.trade_scope_terms SET
    progress_state = 'engaged', engaged_at = now()
  WHERE proposal_id = p_proposal_id RETURNING * INTO v_terms;
  PERFORM set_config('app.trade_scope_progress_id', COALESCE(v_previous_progress, ''), true);

  FOR v_section IN
    SELECT s.*, r.name AS live_room_name
    FROM public.trade_scope_sections s
    LEFT JOIN public.project_rooms r ON r.id = s.project_room_id
    WHERE s.proposal_id = p_proposal_id
    ORDER BY s.sort_order, s.id
  LOOP
    v_room_label := NULLIF(btrim(COALESCE(v_section.room_name, v_section.live_room_name, '')), '');
    INSERT INTO public.project_ffe_items (
      project_id, project_room_id, name, ffe_category, item_type, status,
      quantity, unit_price_cents, line_total_cents,
      trade_price_cents, markup_percent, added_via, sort_order,
      trade_scope_document_id
    ) VALUES (
      v_document.project_id, v_section.project_room_id,
      v_proposal.title || COALESCE(' — ' || v_room_label, ''),
      'trade work', 'fixed', 'approved', 1,
      -- Allocation where the studio apportioned the price; otherwise the whole
      -- price rides on the FIRST section and the rest carry zero. A trade scope
      -- is ONE price — summing the presence lines must return that price, never
      -- a multiple of it.
      COALESCE(v_section.allocation_cents,
               CASE WHEN v_first THEN v_terms.client_price_cents ELSE 0 END),
      COALESCE(v_section.allocation_cents,
               CASE WHEN v_first THEN v_terms.client_price_cents ELSE 0 END),
      NULL, NULL, 'trade-scope', v_section.sort_order,
      v_document.id
    );
    v_first := false;
    v_created := v_created + 1;
  END LOOP;

  -- 00475 (R109 ceremony class): engagement is where the trade thread starts.
  v_anchor_phase_id := public._schedule_thread_phase(v_document.project_id);
  IF v_anchor_phase_id IS NOT NULL THEN
    PERFORM public._commit_schedule_edit_authorized(
      v_document.project_id,
      jsonb_build_array(jsonb_build_object(
        'kind', 'phase-anchor',
        'phase_id', v_anchor_phase_id,
        'anchor_date', to_char(v_terms.engaged_at::date, 'YYYY-MM-DD'),
        'source_ref', p_proposal_id
      )),
      'Trade scope engaged',
      p_disclosed_impact,
      'ceremony:trade-scope-engaged'
    );
  END IF;

  RETURN jsonb_build_object(
    'proposalId', p_proposal_id,
    'documentId', v_document.id,
    'progressState', v_terms.progress_state,
    'engagedAt', v_terms.engaged_at,
    'presenceLineCount', v_created,
    'presenceLineIds', COALESCE((
      SELECT jsonb_agg(i.id ORDER BY i.sort_order, i.id)
      FROM public.project_ffe_items i
      WHERE i.trade_scope_document_id = v_document.id), '[]'::jsonb),
    'newlyEngaged', true
  );
EXCEPTION WHEN OTHERS THEN
  PERFORM set_config('app.trade_scope_progress_id', COALESCE(v_previous_progress, ''), true);
  RAISE;
END;
$$;
ALTER FUNCTION public.engage_trade_scope(uuid,jsonb) RESET ALL;
ALTER FUNCTION public.engage_trade_scope(uuid,jsonb) SET search_path = pg_catalog, public, pg_temp;
ALTER FUNCTION public.engage_trade_scope(uuid,jsonb) OWNER TO postgres;

CREATE OR REPLACE FUNCTION public.ensure_project_spec_book(p_project_id uuid)
RETURNS public.spec_books
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, extensions, pg_temp
AS $$
DECLARE
  v_project public.projects;
  v_template_id uuid;
  v_book public.spec_books;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'authentication required' USING errcode = 'insufficient_privilege';
  END IF;

  SELECT * INTO v_project
  FROM public.projects
  WHERE id = p_project_id
  FOR SHARE;

  IF NOT FOUND OR NOT public.is_studio_comember(v_project.designer_id) THEN
    RAISE EXCEPTION 'project not found or not accessible'
      USING errcode = 'insufficient_privilege';
  END IF;

  SELECT id INTO v_template_id
  FROM public.spec_book_templates
  WHERE template_key = 'residential'
    AND studio_id IS NULL
    AND is_active
  ORDER BY version DESC
  LIMIT 1;

  IF v_template_id IS NULL THEN
    RAISE EXCEPTION 'residential spec-book template is unavailable'
      USING errcode = 'object_not_in_prerequisite_state';
  END IF;

  INSERT INTO public.spec_books (
    project_id, title, template_id, default_audiences, created_by
  )
  VALUES (
    p_project_id, v_project.name || ' — Spec Book', v_template_id,
    ARRAY['client']::text[], auth.uid()
  )
  ON CONFLICT (project_id) DO NOTHING;

  SELECT * INTO v_book FROM public.spec_books WHERE project_id = p_project_id;

  INSERT INTO public.spec_book_chapters (
    spec_book_id, project_room_id, title, position
  )
  SELECT v_book.id, r.id, r.name, r.sort_order
  FROM public.project_rooms r
  WHERE r.project_id = p_project_id
  ON CONFLICT (spec_book_id, project_room_id)
    WHERE project_room_id IS NOT NULL
  DO NOTHING;

  INSERT INTO public.spec_book_item_settings (
    spec_book_id, ffe_item_id, chapter_id, position
  )
  SELECT
    v_book.id,
    i.id,
    c.id,
    i.sort_order
  FROM public.project_ffe_items i
  LEFT JOIN public.spec_book_chapters c
    ON c.spec_book_id = v_book.id
   AND c.project_room_id = i.project_room_id
  WHERE i.project_id = p_project_id
  ON CONFLICT (spec_book_id, ffe_item_id) DO NOTHING;

  RETURN v_book;
END;
$$;
ALTER FUNCTION public.ensure_project_spec_book(uuid) RESET ALL;
ALTER FUNCTION public.ensure_project_spec_book(uuid) SET search_path = pg_catalog, public, extensions, pg_temp;
ALTER FUNCTION public.ensure_project_spec_book(uuid) OWNER TO postgres;

CREATE OR REPLACE FUNCTION public.expire_client_decision(p_decision_id uuid)
RETURNS public.client_decisions
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, pg_temp
AS $$
DECLARE
  v_decision public.client_decisions%ROWTYPE;
BEGIN
  SELECT * INTO v_decision
  FROM public.client_decisions
  WHERE id = p_decision_id
  FOR UPDATE;

  IF NOT FOUND OR NOT public._can_author_proposal(v_decision.designer_id) THEN
    RAISE EXCEPTION 'decision % not found or access denied', p_decision_id
      USING ERRCODE = 'insufficient_privilege';
  END IF;
  IF v_decision.approval_contract = 'project_artifact_v1' THEN
    RAISE EXCEPTION 'Stage-2 project approvals require checked withdraw/supersede'
      USING ERRCODE = 'check_violation';
  END IF;
  IF v_decision.status = 'expired' THEN
    RETURN v_decision;
  END IF;
  IF v_decision.status <> 'pending' THEN
    RAISE EXCEPTION 'decision % cannot expire from status %',
      p_decision_id, v_decision.status
      USING ERRCODE = 'check_violation';
  END IF;

  PERFORM set_config('app.client_decision_write_id', p_decision_id::text, true);
  UPDATE public.client_decisions
  SET status = 'expired', updated_at = now()
  WHERE id = p_decision_id
  RETURNING * INTO v_decision;
  PERFORM set_config('app.client_decision_write_id', '', true);
  RETURN v_decision;
END;
$$;
ALTER FUNCTION public.expire_client_decision(uuid) RESET ALL;
ALTER FUNCTION public.expire_client_decision(uuid) SET search_path = pg_catalog, public, pg_temp;
ALTER FUNCTION public.expire_client_decision(uuid) OWNER TO postgres;

CREATE OR REPLACE FUNCTION public.extend_and_reopen_client_decision(
  p_decision_id uuid,
  p_due_date timestamptz,
  p_expected_updated_at timestamptz
)
RETURNS public.client_decisions
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, pg_temp
AS $$
DECLARE
  v_decision public.client_decisions%ROWTYPE;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION
      'extend_and_reopen_client_decision requires an authenticated user'
      USING ERRCODE = 'insufficient_privilege';
  END IF;
  IF p_due_date IS NULL THEN
    RAISE EXCEPTION 'p_due_date is required'
      USING ERRCODE = 'invalid_parameter_value';
  END IF;
  IF p_expected_updated_at IS NULL THEN
    RAISE EXCEPTION 'p_expected_updated_at is required'
      USING ERRCODE = 'invalid_parameter_value';
  END IF;

  SELECT * INTO v_decision
  FROM public.client_decisions
  WHERE id = p_decision_id
  FOR UPDATE;

  IF NOT FOUND OR NOT public._can_author_proposal(v_decision.designer_id) THEN
    RAISE EXCEPTION 'decision % not found or access denied', p_decision_id
      USING ERRCODE = 'insufficient_privilege';
  END IF;
  IF v_decision.approval_contract = 'project_artifact_v1' THEN
    RAISE EXCEPTION 'Stage-2 project approvals cannot use generic extend/reopen'
      USING ERRCODE = 'check_violation';
  END IF;
  IF v_decision.linked_proposal_id IS NOT NULL THEN
    RAISE EXCEPTION 'proposal approval decisions are terminal'
      USING ERRCODE = 'check_violation';
  END IF;

  IF v_decision.status = 'pending' THEN
    IF v_decision.due_date IS NOT DISTINCT FROM p_due_date THEN
      RETURN v_decision;
    END IF;
    RAISE EXCEPTION
      'decision % already reflects a different extend-and-reopen effect',
      p_decision_id
      USING ERRCODE = 'serialization_failure';
  END IF;
  IF v_decision.status <> 'expired' THEN
    RAISE EXCEPTION 'decision % cannot extend-and-reopen from status %',
      p_decision_id, v_decision.status
      USING ERRCODE = 'check_violation';
  END IF;
  IF v_decision.updated_at IS DISTINCT FROM p_expected_updated_at THEN
    RAISE EXCEPTION 'decision % changed since it was loaded', p_decision_id
      USING ERRCODE = 'serialization_failure';
  END IF;
  IF p_due_date <= now() THEN
    RAISE EXCEPTION 'an extended due date must be in the future'
      USING ERRCODE = 'check_violation';
  END IF;

  PERFORM set_config('app.client_decision_write_id', p_decision_id::text, true);
  UPDATE public.client_decision_options
  SET selected = false, client_note = NULL
  WHERE decision_id = p_decision_id;

  UPDATE public.client_decisions
  SET status = 'pending',
      due_date = p_due_date,
      responded_at = NULL,
      viewed_at = NULL,
      reminder_sent_at = NULL,
      selected_by = NULL,
      answer = NULL,
      answered_at = NULL,
      answered_by = NULL,
      client_consent_method = NULL,
      client_consented_at = NULL,
      client_signature = NULL,
      updated_at = now()
  WHERE id = p_decision_id
  RETURNING * INTO v_decision;
  PERFORM set_config('app.client_decision_write_id', '', true);

  PERFORM public._enqueue_decision_notification(
    p_decision_id, 'decision_required'
  );
  RETURN v_decision;
END;
$$;
ALTER FUNCTION public.extend_and_reopen_client_decision(uuid,timestamp with time zone,timestamp with time zone) RESET ALL;
ALTER FUNCTION public.extend_and_reopen_client_decision(uuid,timestamp with time zone,timestamp with time zone) SET search_path = pg_catalog, public, pg_temp;
ALTER FUNCTION public.extend_and_reopen_client_decision(uuid,timestamp with time zone,timestamp with time zone) OWNER TO postgres;

CREATE OR REPLACE FUNCTION public.file_plan_prints(
  p_project_id uuid,
  p_idempotency_key text,
  p_entries jsonb,
  p_source_filename text DEFAULT NULL
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, extensions, pg_temp
AS $$
DECLARE
  v_key          text := btrim(COALESCE(p_idempotency_key, ''));
  v_source       text := NULLIF(btrim(COALESCE(p_source_filename, '')), '');
  v_hash         text;
  v_batch        public.plan_print_batches%ROWTYPE;
  v_entry        jsonb;
  v_ord          integer;
  v_kind         text;
  v_print        jsonb;
  v_number       text;
  v_norm         text;
  v_title        text;
  v_discipline   text;
  v_sheet_id     uuid;
  v_sheet        public.plan_sheets%ROWTYPE;
  v_path         text;
  v_plan         jsonb := '[]'::jsonb;
  v_seen_sheets  uuid[] := ARRAY[]::uuid[];
  v_seen_numbers text[] := ARRAY[]::text[];
  v_seen_paths   text[] := ARRAY[]::text[];
  v_confirmed    uuid[] := ARRAY[]::uuid[];
  v_created      uuid[] := ARRAY[]::uuid[];
  v_sort         integer;
  v_item         jsonb;
  v_n            integer;
  v_rev          text;
  v_doc_id       uuid;
  v_prior_doc_id uuid;
  v_print_id     uuid;
  v_flipped      uuid[] := ARRAY[]::uuid[];
  v_results      jsonb := '[]'::jsonb;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'filing drawings requires an authenticated designer'
      USING errcode = 'insufficient_privilege';
  END IF;
  IF NOT EXISTS (
    SELECT 1 FROM public.projects p
    WHERE p.id = p_project_id AND public.is_design_studio_comember(p.designer_id)
  ) THEN
    RAISE EXCEPTION 'plan room for project % not found or access denied', p_project_id
      USING errcode = 'insufficient_privilege';
  END IF;
  IF v_key = '' THEN
    RAISE EXCEPTION 'a filing needs an idempotency key'
      USING errcode = 'check_violation';
  END IF;
  IF jsonb_typeof(p_entries) <> 'array'
     OR jsonb_array_length(p_entries) < 1
     OR jsonb_array_length(p_entries) > 64
  THEN
    RAISE EXCEPTION 'a filing carries between 1 and 64 entries'
      USING errcode = 'check_violation';
  END IF;

  PERFORM 1 FROM public.projects WHERE id = p_project_id FOR UPDATE;

  -- The filename is part of the request, so it is part of the hash: the same
  -- entries arriving under a different source file is a different filing, and a
  -- caller that reused the key for it wants to hear about it.
  v_hash := encode(extensions.digest(public._plan_room_canonical_json(
    jsonb_build_object('sourceFilename', to_jsonb(v_source), 'entries', p_entries)
  ), 'sha256'), 'hex');

  SELECT * INTO v_batch FROM public.plan_print_batches
  WHERE project_id = p_project_id AND idempotency_key = v_key;

  IF FOUND THEN
    IF v_batch.request_hash IS DISTINCT FROM v_hash THEN
      RAISE EXCEPTION 'idempotency key was reused with a different request'
        USING errcode = 'unique_violation';
    END IF;

    -- A replay answers with the act as it landed, read straight off the record
    -- of it. Nothing here is re-derived from live state: what a filing DID is a
    -- fact about that moment, and a later repair or reshare must not be able to
    -- change the answer a retry gets.
    SELECT COALESCE(jsonb_agg(jsonb_build_object(
             'sheetId', s.id,
             'sheetNumber', s.sheet_number,
             'isNewSheet', s.id = ANY (v_batch.created_sheet_ids),
             'printId', pp.id,
             'printNumber', pp.print_number,
             'revLetter', pp.rev_letter,
             'projectDocumentId', pp.project_document_id
           ) ORDER BY upper(btrim(s.sheet_number)), pp.print_number), '[]'::jsonb)
      INTO v_results
      FROM public.plan_prints pp
      JOIN public.plan_sheets s ON s.id = pp.sheet_id
     WHERE pp.batch_id = v_batch.id;

    RETURN jsonb_build_object(
      'batchId', v_batch.id,
      'idempotent', true,
      'prints', v_results,
      'flippedSheetIds', to_jsonb(v_batch.flipped_sheet_ids)
    );
  END IF;

  -- ── Validate every entry ────────────────────────────────────────────────
  FOR v_entry, v_ord IN
    SELECT e.value, e.ordinality
    FROM jsonb_array_elements(p_entries) WITH ORDINALITY AS e(value, ordinality)
  LOOP
    v_number := NULL;
    v_title := NULL;
    v_discipline := NULL;
    v_sheet_id := NULL;

    IF jsonb_typeof(v_entry) <> 'object' THEN
      RAISE EXCEPTION 'entry %: each entry must be an object', v_ord
        USING errcode = 'check_violation';
    END IF;
    v_kind := v_entry->>'kind';
    IF v_kind IS NULL OR v_kind NOT IN ('new_sheet', 'revision', 'confirm_current') THEN
      RAISE EXCEPTION 'entry %: kind must be new_sheet, revision or confirm_current', v_ord
        USING errcode = 'check_violation';
    END IF;

    IF v_kind IN ('revision', 'confirm_current') THEN
      IF COALESCE(v_entry->>'sheet_id', '')
         !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
        RAISE EXCEPTION 'entry %: a sheet_id is required', v_ord
          USING errcode = 'check_violation';
      END IF;
      v_sheet_id := (v_entry->>'sheet_id')::uuid;
      SELECT * INTO v_sheet FROM public.plan_sheets
      WHERE id = v_sheet_id AND project_id = p_project_id;
      IF NOT FOUND THEN
        RAISE EXCEPTION 'entry %: sheet % is not in this plan room', v_ord, v_sheet_id
          USING errcode = 'check_violation';
      END IF;
      IF v_sheet_id = ANY (v_seen_sheets) THEN
        RAISE EXCEPTION 'entry %: sheet % is named twice in one filing', v_ord, v_sheet.sheet_number
          USING errcode = 'check_violation';
      END IF;
      v_seen_sheets := array_append(v_seen_sheets, v_sheet_id);
      v_number := v_sheet.sheet_number;
    END IF;

    IF v_kind = 'confirm_current' THEN
      IF v_sheet.current_print_id IS NULL THEN
        RAISE EXCEPTION 'entry %: sheet % has no filed print to confirm', v_ord, v_sheet.sheet_number
          USING errcode = 'check_violation';
      END IF;
      v_confirmed := array_append(v_confirmed, v_sheet_id);
      v_plan := v_plan || jsonb_build_array(jsonb_build_object(
        'ord', v_ord, 'kind', v_kind,
        'sheetId', v_sheet_id, 'sheetNumber', v_number));
      CONTINUE;
    END IF;

    -- ── The print, for both new_sheet and revision ────────────────────────
    v_print := v_entry->'print';
    IF v_print IS NULL OR jsonb_typeof(v_print) <> 'object' THEN
      RAISE EXCEPTION 'entry %: a print is required', v_ord
        USING errcode = 'check_violation';
    END IF;

    v_path := btrim(COALESCE(v_print->>'storage_path', ''));
    IF v_path = '' THEN
      RAISE EXCEPTION 'entry %: a print needs a storage_path', v_ord
        USING errcode = 'check_violation';
    END IF;
    -- A drawing filed from another project's prefix is either a mistake or an
    -- attempt to mount someone else's file into this folio.
    IF split_part(v_path, '/', 1) <> p_project_id::text THEN
      RAISE EXCEPTION 'entry %: a plan file must live under its own project''s storage prefix', v_ord
        USING errcode = 'check_violation';
    END IF;
    IF v_path = ANY (v_seen_paths) THEN
      RAISE EXCEPTION 'entry %: the same file is filed twice in one batch', v_ord
        USING errcode = 'check_violation';
    END IF;
    IF NOT EXISTS (
      SELECT 1 FROM storage.objects o
      WHERE o.bucket_id = 'project-documents' AND o.name = v_path
    ) THEN
      RAISE EXCEPTION 'entry %: nothing has been uploaded at %', v_ord, v_path
        USING errcode = 'check_violation';
    END IF;
    IF EXISTS (
      SELECT 1 FROM public.project_documents d WHERE d.storage_path = v_path
    ) THEN
      RAISE EXCEPTION 'entry %: % is already filed against a document', v_ord, v_path
        USING errcode = 'check_violation';
    END IF;
    IF COALESCE(v_print->>'sha256', '') !~ '^[0-9a-f]{64}$' THEN
      RAISE EXCEPTION 'entry %: a print needs a lowercase hex sha256', v_ord
        USING errcode = 'check_violation';
    END IF;
    IF v_print->>'text_sha256' IS NOT NULL
       AND v_print->>'text_sha256' !~ '^[0-9a-f]{64}$' THEN
      RAISE EXCEPTION 'entry %: text_sha256 must be a lowercase hex sha256', v_ord
        USING errcode = 'check_violation';
    END IF;
    IF v_print ? 'page_index' AND v_print->'page_index' <> 'null'::jsonb
       AND (jsonb_typeof(v_print->'page_index') <> 'number'
            OR (v_print->>'page_index')::numeric < 0) THEN
      RAISE EXCEPTION 'entry %: page_index must be a non-negative number', v_ord
        USING errcode = 'check_violation';
    END IF;
    IF v_print ? 'size_bytes' AND v_print->'size_bytes' <> 'null'::jsonb
       AND (jsonb_typeof(v_print->'size_bytes') <> 'number'
            OR (v_print->>'size_bytes')::numeric < 0) THEN
      RAISE EXCEPTION 'entry %: size_bytes must be a non-negative number', v_ord
        USING errcode = 'check_violation';
    END IF;
    v_seen_paths := array_append(v_seen_paths, v_path);

    IF v_kind = 'new_sheet' THEN
      v_number := btrim(COALESCE(v_entry#>>'{sheet,number}', ''));
      IF length(v_number) NOT BETWEEN 1 AND 32 THEN
        RAISE EXCEPTION 'entry %: a new sheet needs a number of 1 to 32 characters', v_ord
          USING errcode = 'check_violation';
      END IF;
      v_title := btrim(COALESCE(v_entry#>>'{sheet,title}', ''));
      IF length(v_title) NOT BETWEEN 1 AND 200 THEN
        RAISE EXCEPTION 'entry %: a new sheet needs a title of 1 to 200 characters', v_ord
          USING errcode = 'check_violation';
      END IF;
      v_discipline := NULLIF(btrim(COALESCE(v_entry#>>'{sheet,discipline}', '')), '');
      v_norm := upper(v_number);
      IF v_norm = ANY (v_seen_numbers) THEN
        RAISE EXCEPTION 'entry %: sheet number % appears twice in one filing', v_ord, v_number
          USING errcode = 'check_violation';
      END IF;
      -- Caught here rather than left to uniq_plan_sheets_number, so the caller
      -- reads a sentence instead of a 23505 on an expression index.
      IF EXISTS (
        SELECT 1 FROM public.plan_sheets s
        WHERE s.project_id = p_project_id AND upper(btrim(s.sheet_number)) = v_norm
      ) THEN
        RAISE EXCEPTION 'entry %: sheet % already exists — file it as a revision', v_ord, v_number
          USING errcode = 'check_violation';
      END IF;
      v_seen_numbers := array_append(v_seen_numbers, v_norm);
      -- Minted here so the plan can name the sheet before it exists.
      v_sheet_id := extensions.gen_random_uuid();
      v_created := array_append(v_created, v_sheet_id);
    ELSIF v_sheet.state = 'shared' AND v_sheet.current_print_id IS NOT NULL THEN
      -- Decided here, under the project mutex, so the batch can RECORD the flip
      -- rather than have a later reader guess at it. The write loop below is
      -- driven off this same array, so the record and the act cannot diverge.
      v_flipped := array_append(v_flipped, v_sheet_id);
    END IF;

    v_plan := v_plan || jsonb_build_array(jsonb_build_object(
      'ord', v_ord, 'kind', v_kind,
      'sheetId', v_sheet_id, 'sheetNumber', v_number,
      'sheetTitle', v_title, 'discipline', v_discipline,
      'print', v_print));
  END LOOP;

  -- ── Write ───────────────────────────────────────────────────────────────
  INSERT INTO public.plan_print_batches (
    project_id, idempotency_key, request_hash, source_filename,
    confirmed_sheet_ids, created_sheet_ids, flipped_sheet_ids, item_count, created_by
  ) VALUES (
    p_project_id, v_key, v_hash, v_source,
    v_confirmed, v_created, v_flipped, jsonb_array_length(p_entries), auth.uid()
  ) RETURNING * INTO v_batch;

  SELECT COALESCE(max(sort_order), -1) + 1 INTO v_sort
  FROM public.plan_sheets WHERE project_id = p_project_id;

  INSERT INTO public.plan_sheets (
    id, project_id, sheet_number, title, discipline, state, sort_order, created_by
  )
  SELECT (e.value->>'sheetId')::uuid, p_project_id, e.value->>'sheetNumber',
         e.value->>'sheetTitle', e.value->>'discipline', 'draft',
         v_sort + (row_number() OVER (ORDER BY (e.value->>'ord')::integer))::integer - 1,
         auth.uid()
  FROM jsonb_array_elements(v_plan) AS e(value)
  WHERE e.value->>'kind' = 'new_sheet';

  FOR v_item IN
    SELECT e.value
    FROM jsonb_array_elements(v_plan) AS e(value)
    WHERE e.value ? 'print'
    ORDER BY upper(btrim(e.value->>'sheetNumber')), (e.value->>'ord')::integer
  LOOP
    SELECT * INTO v_sheet FROM public.plan_sheets
    WHERE id = (v_item->>'sheetId')::uuid FOR UPDATE;

    v_n := v_sheet.current_print_number + 1;
    v_rev := public._plan_room_rev_letter(v_n);
    v_print := v_item->'print';

    v_prior_doc_id := NULL;
    IF v_sheet.current_print_id IS NOT NULL THEN
      SELECT pp.project_document_id INTO v_prior_doc_id
      FROM public.plan_prints pp WHERE pp.id = v_sheet.current_print_id;
    END IF;

    INSERT INTO public.project_documents (
      project_id, title, doc_type, category, storage_path, size_bytes, status,
      anchor_kind, section_key, client_visible, uploaded_by
    ) VALUES (
      p_project_id,
      v_sheet.sheet_number || ' · Rev ' || v_rev || ' — ' || v_sheet.title,
      COALESCE(NULLIF(btrim(COALESCE(v_print->>'doc_type', '')), ''), 'pdf'),
      'drawing',
      v_print->>'storage_path',
      CASE WHEN jsonb_typeof(v_print->'size_bytes') = 'number'
           THEN (v_print->>'size_bytes')::bigint END,
      'ready', 'section', 'plan-room',
      -- The print lands already sharing exactly as its sheet shares. A shared
      -- sheet whose newest revision is invisible is the failure this replaces.
      v_sheet.state = 'shared',
      auth.uid()
    ) RETURNING id INTO v_doc_id;
    -- The folio TITLE is baked here and never rewritten. A sheet renamed after
    -- filing leaves its old prints titled with the old number, which is honest
    -- for issued revisions and merely stale for unissued ones. Repairing the
    -- stale ones is a fast-follow RPC; v1 deliberately does not rewrite history
    -- as a side effect of a rename.

    INSERT INTO public.plan_prints (
      sheet_id, batch_id, print_number, rev_letter, project_document_id,
      sha256, text_sha256, page_index, source_filename, created_by
    ) VALUES (
      v_sheet.id, v_batch.id, v_n, v_rev, v_doc_id,
      v_print->>'sha256',
      NULLIF(btrim(COALESCE(v_print->>'text_sha256', '')), ''),
      CASE WHEN jsonb_typeof(v_print->'page_index') = 'number'
           THEN (v_print->>'page_index')::integer END,
      COALESCE(NULLIF(btrim(COALESCE(v_print->>'source_filename', '')), ''), v_source),
      auth.uid()
    ) RETURNING id INTO v_print_id;

    PERFORM set_config('app.plan_room_sheet_maintenance', v_sheet.id::text, true);
    UPDATE public.plan_sheets
       SET current_print_number = v_n, current_print_id = v_print_id
     WHERE id = v_sheet.id;
    PERFORM set_config('app.plan_room_sheet_maintenance', '', true);

    -- Superseding is a two-sided act on a shared sheet: the new print appears
    -- in the client's folio and the old one leaves it, in the same call. The
    -- pointer moved above, so the folio guard's derivation already says this
    -- doc is no longer visible — which is why the write is accepted.
    IF v_sheet.id = ANY (v_flipped) AND v_prior_doc_id IS NOT NULL THEN
      PERFORM public._plan_room_set_doc_visibility(v_prior_doc_id, false);
    END IF;

    v_results := v_results || jsonb_build_array(jsonb_build_object(
      'sheetId', v_sheet.id,
      'sheetNumber', v_sheet.sheet_number,
      'isNewSheet', v_item->>'kind' = 'new_sheet',
      'printId', v_print_id,
      'printNumber', v_n,
      'revLetter', v_rev,
      'projectDocumentId', v_doc_id));
  END LOOP;

  RETURN jsonb_build_object(
    'batchId', v_batch.id,
    'idempotent', false,
    'prints', v_results,
    'flippedSheetIds', to_jsonb(v_flipped)
  );
END;
$$;
ALTER FUNCTION public.file_plan_prints(uuid,text,jsonb,text) RESET ALL;
ALTER FUNCTION public.file_plan_prints(uuid,text,jsonb,text) SET search_path = pg_catalog, public, extensions, pg_temp;
ALTER FUNCTION public.file_plan_prints(uuid,text,jsonb,text) OWNER TO postgres;

CREATE OR REPLACE FUNCTION public.get_client_commercial_document_bundle(p_proposal_id uuid)
RETURNS jsonb
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path = public, pg_temp
AS $$
DECLARE
  v_proposal public.proposals%ROWTYPE;
  v_document public.project_commercial_documents%ROWTYPE;
BEGIN
  SELECT * INTO v_proposal FROM public.proposals WHERE id = p_proposal_id;
  IF NOT FOUND OR auth.uid() IS NULL OR NOT (
    v_proposal.client_id IS NOT DISTINCT FROM auth.uid()
    OR public.is_studio_comember(v_proposal.designer_id)
  ) THEN
    RAISE EXCEPTION 'commercial document % not found or access denied', p_proposal_id
      USING ERRCODE = 'insufficient_privilege';
  END IF;
  -- A client never sees an unsent document. Legacy editions carry no
  -- commercial_state, so their draft-ness lives in status.
  --
  -- 00422: nor does a client see a document that was never ISSUED. Voiding
  -- writes commercial_state 'superseded' and deliberately leaves status alone,
  -- so a never-sent draft that the studio priced and thought better of used to
  -- pass the `= 'draft'` test the moment it was retired — the void itself
  -- published it. A terminal edition is client-visible only if it was sent.
  IF v_proposal.client_id IS NOT DISTINCT FROM auth.uid()
     AND (
       (v_proposal.document_kind = 'legacy' AND v_proposal.status = 'draft')
       OR (v_proposal.document_kind <> 'legacy'
           AND COALESCE(v_proposal.commercial_state, 'draft') = 'draft')
       OR (v_proposal.document_kind <> 'legacy'
           AND COALESCE(v_proposal.commercial_state, 'draft') IN ('superseded', 'declined')
           AND v_proposal.sent_at IS NULL)
     ) THEN
    RAISE EXCEPTION 'commercial document % not found or access denied', p_proposal_id
      USING ERRCODE = 'insufficient_privilege';
  END IF;

  -- 00414: a legacy edition is not an error, it is a retired document.
  IF v_proposal.document_kind = 'legacy' THEN
    RETURN jsonb_build_object(
      'document', jsonb_build_object(
        'id', v_proposal.id,
        'documentKind', 'legacy',
        'kind', 'legacy',
        'retired', true,
        'title', v_proposal.title,
        'status', v_proposal.status,
        'commercialState', v_proposal.commercial_state,
        'supersededAt', v_proposal.superseded_at,
        'replacementProposalId', v_proposal.replacement_proposal_id,
        'validUntil', v_proposal.valid_until,
        'sentAt', v_proposal.sent_at
      )
    );
  END IF;

  SELECT * INTO v_document FROM public.project_commercial_documents
  WHERE proposal_id = p_proposal_id;

  RETURN jsonb_build_object(
    'document', jsonb_build_object(
      'id', v_proposal.id, 'projectId', COALESCE(v_document.project_id, v_proposal.project_id),
      'title', v_proposal.title, 'description', v_proposal.description,
      'documentKind', v_proposal.document_kind,
      'commercialState', v_proposal.commercial_state,
      'status', v_proposal.status, 'totalAmountCents', v_proposal.total_amount,
      'depositPercent', v_proposal.deposit_percent,
      'validUntil', v_proposal.valid_until, 'sentAt', v_proposal.sent_at,
      'sent_at', v_proposal.sent_at,
      'proposalSendDispatchId', v_proposal.proposal_send_dispatch_id,
      'proposal_send_dispatch_id', v_proposal.proposal_send_dispatch_id,
      'executedAt', v_document.executed_at,
      'supersededAt', v_proposal.superseded_at,
      'replacementProposalId', v_proposal.replacement_proposal_id,
      'createdAt', v_proposal.created_at, 'updatedAt', v_proposal.updated_at
    ),
    'serviceTerms', (SELECT jsonb_build_object(
      'scope', t.scope, 'deliverables', t.deliverables, 'exclusions', t.exclusions,
      'billingCeilingCents', t.billing_ceiling_cents,
      'retainerAmountCents', t.retainer_amount_cents,
      'retainerActivationPolicy', t.retainer_activation_policy,
      'billingCadence', t.billing_cadence, 'currency', t.currency,
      'terms', t.terms, 'currentRateVersion', t.current_rate_version,
      'furnishingsDepositPercent', t.furnishings_deposit_percent
    ) FROM public.proposal_service_terms t WHERE t.proposal_id = p_proposal_id),
    'rates', COALESCE((SELECT jsonb_agg(jsonb_build_object(
      'id', r.id, 'version', r.version, 'roleName', r.role_name,
      'hourlyRateCents', r.hourly_rate_cents, 'sortOrder', r.sort_order,
      'effectiveAt', r.effective_at
    ) ORDER BY r.version DESC, r.sort_order, r.role_name)
      FROM public.proposal_service_rates r WHERE r.proposal_id = p_proposal_id), '[]'::jsonb),
    'signatures', COALESCE((SELECT jsonb_agg(jsonb_build_object(
      'id', s.id, 'partyRole', s.party_role,
      'signedName', s.signed_name, 'signedAt', s.signed_at,
      'evidenceFingerprint', s.evidence_fingerprint,
      -- 00425: the paper tell, projected as a BOOLEAN and nothing more. Raw
      -- metadata never crosses this edge — it carries recordedBy, which is a
      -- studio member's uuid, and the client has no business with it.
      'signedOnPaper', COALESCE((s.metadata->>'executedOnPaper')::boolean, false),
      -- 00425: THE DATE ON THE PAPER, and it is the one the client's copy must
      -- print as the signing date. signed_at is when the STUDIO wrote the act
      -- down, which on this rail is a different day — often weeks later — so a
      -- copy that renders signed_at as "SIGNED <date>" tells the client they
      -- signed on a day they did not. Projected as the bare yyyy-mm-dd text the
      -- studio typed (no timestamp, no zone: a calendar date has neither), and
      -- NULL on portal rows, which carry no such key because there the record
      -- moment IS the signing moment.
      'paperSignedOn', s.metadata->>'paperSignedOn',
      -- The scan pointer is projected ONLY when the folio row is flagged
      -- client_visible AND still anchored to THIS document. This body is
      -- SECURITY DEFINER, so project_documents RLS is not in force here; both
      -- facts have to be read explicitly or an unshared scan of the client's own
      -- signature page leaks its id, or a pointer at somebody else's folio row
      -- is handed to this client as if it were their signature page. The record
      -- rails validate the anchor at write time and the folio guard freezes it
      -- afterwards; this is the read edge saying so on its own authority rather
      -- than trusting two other seams to have held.
      'paperScanDocumentId', (
        SELECT scan.id FROM public.project_documents scan
        WHERE scan.id = (s.metadata->>'paperScanDocumentId')::uuid
          AND scan.proposal_id = p_proposal_id
          AND scan.client_visible
      )
    ) ORDER BY s.signed_at, s.id) FROM public.commercial_document_signatures s
      WHERE s.proposal_id = p_proposal_id), '[]'::jsonb),
    'furnishings', CASE WHEN v_document.document_kind = 'furnishings_authorization'
      THEN jsonb_build_object(
        'documentId', v_document.id, 'waveName', v_document.wave_name,
        'proposalSendDispatchId', v_proposal.proposal_send_dispatch_id,
        'proposal_send_dispatch_id', v_proposal.proposal_send_dispatch_id,
        'sentAt', v_proposal.sent_at, 'sent_at', v_proposal.sent_at,
        'checkpointId', v_document.budget_checkpoint_id,
        'budgetCheckpointId', v_document.budget_checkpoint_id,
        'depositInvoiceId', v_document.deposit_invoice_id,
        'depositRequiredCents', COALESCE((SELECT i.total_cents
          FROM public.invoices i WHERE i.id = v_document.deposit_invoice_id),
          round(v_proposal.total_amount * v_proposal.deposit_percent / 100.0)::bigint),
        'deposit_required_cents', COALESCE((SELECT i.total_cents
          FROM public.invoices i WHERE i.id = v_document.deposit_invoice_id),
          round(v_proposal.total_amount * v_proposal.deposit_percent / 100.0)::bigint),
        'depositPaidCents', COALESCE((SELECT i.amount_paid_cents
          FROM public.invoices i WHERE i.id = v_document.deposit_invoice_id), 0),
        'deposit_paid_cents', COALESCE((SELECT i.amount_paid_cents
          FROM public.invoices i WHERE i.id = v_document.deposit_invoice_id), 0),
        'items', COALESCE((SELECT jsonb_agg(jsonb_build_object(
          'id', a.id, 'name', a.name, 'roomName', a.room_name,
          'category', a.category, 'itemType', a.item_type, 'quantity', a.quantity,
          'clientUnitPriceCents', a.client_unit_price_cents,
          'clientLineTotalCents', a.client_line_total_cents,
          'sourceFfeItemId', a.source_ffe_item_id, 'sortOrder', a.sort_order
        ) ORDER BY a.sort_order, a.id) FROM public.furnishing_authorization_items a
          WHERE a.commercial_document_id = v_document.id), '[]'::jsonb)
      ) ELSE NULL END,
    'replacement', (SELECT jsonb_build_object(
      'id', replacement.id, 'title', replacement.title,
      'documentKind', replacement.document_kind,
      'commercialState', replacement.commercial_state
    ) FROM public.proposals replacement WHERE replacement.id = v_proposal.replacement_proposal_id)
  ) || CASE WHEN v_document.document_kind = 'trade_scope'
      -- COALESCE, not a bare subquery: `object || NULL` is NULL in jsonb, so a
      -- scope somehow missing its terms row would blank the WHOLE bundle rather
      -- than one key. create_trade_scope always writes one; this is the belt.
      THEN COALESCE((SELECT jsonb_build_object('tradeScope', jsonb_build_object(
        'documentId', v_document.id,
        'sentAt', v_proposal.sent_at, 'sent_at', v_proposal.sent_at,
        'proposalSendDispatchId', v_proposal.proposal_send_dispatch_id,
        'proposal_send_dispatch_id', v_proposal.proposal_send_dispatch_id,
        'partyDisplayName', t.party_display_name,
        'partyCompanyName', t.party_company_name,
        'partyTrade', t.party_trade,
        'clientPriceCents', t.client_price_cents,
        'currency', t.currency,
        'terms', t.terms,
        'depositInvoiceId', v_document.deposit_invoice_id,
        'sections', COALESCE((SELECT jsonb_agg(jsonb_build_object(
          'id', s.id, 'roomId', s.project_room_id, 'roomName', s.room_name,
          'prose', s.prose, 'allocationCents', s.allocation_cents,
          'sortOrder', s.sort_order
        ) ORDER BY s.sort_order, s.id)
          FROM public.trade_scope_sections s WHERE s.proposal_id = p_proposal_id), '[]'::jsonb),
        'draws', COALESCE((SELECT jsonb_agg(jsonb_build_object(
          'id', w.id, 'label', w.label, 'percentage', w.percentage,
          'amountCents', w.amount_cents, 'sortOrder', w.sort_order,
          'gatesOnAcceptance', w.gates_on_acceptance,
          'invoiceId', w.invoice_id,
          'invoiceStatus', (SELECT i.status FROM public.invoices i WHERE i.id = w.invoice_id),
          'invoicePaidCents', (SELECT i.amount_paid_cents FROM public.invoices i WHERE i.id = w.invoice_id)
        ) ORDER BY w.sort_order, w.id)
          FROM public.trade_scope_draws w WHERE w.proposal_id = p_proposal_id), '[]'::jsonb),
        'progress', jsonb_build_object(
          'state', t.progress_state,
          'engagedAt', t.engaged_at,
          'substantialCompletionAt', t.substantial_completion_at,
          -- 00425: on a PAPER acceptance this IS the date on the paper —
          -- record_paper_trade_acceptance writes `accepted_at =
          -- p_paper_signed_on::timestamptz`, i.e. midnight UTC on the day the
          -- client signed, not the moment of typing. So the acceptance leg
          -- needs no paper-date twin the way signatures do; it needs its
          -- readers to format the DATE COMPONENT and not shift it west.
          'acceptedAt', t.accepted_at,
          'acceptedSignedName', t.accepted_signed_name,
          -- 00425: acceptance recorded from a printed copy says so, and carries
          -- the page — scoped exactly like the signature scan above: shared, and
          -- still anchored to this document.
          'acceptedOnPaper', t.accepted_on_paper,
          'acceptanceScanDocumentId', (
            SELECT scan.id FROM public.project_documents scan
            WHERE scan.id = t.acceptance_scan_document_id
              AND scan.proposal_id = p_proposal_id
              AND scan.client_visible
          )
        )
      )) FROM public.trade_scope_terms t WHERE t.proposal_id = p_proposal_id),
      '{}'::jsonb)
      ELSE '{}'::jsonb END;
END;
$$;
ALTER FUNCTION public.get_client_commercial_document_bundle(uuid) RESET ALL;
ALTER FUNCTION public.get_client_commercial_document_bundle(uuid) SET search_path = pg_catalog, public, pg_temp;
ALTER FUNCTION public.get_client_commercial_document_bundle(uuid) OWNER TO postgres;

CREATE OR REPLACE FUNCTION public.get_client_project_selections(p_project_id uuid)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'public','pg_temp' AS $$
DECLARE v_actor uuid:=auth.uid(); v_project public.projects%ROWTYPE;
BEGIN
  IF v_actor IS NULL THEN RAISE EXCEPTION 'authentication required' USING ERRCODE='insufficient_privilege'; END IF;
  SELECT * INTO v_project FROM public.projects WHERE id=p_project_id;
  IF NOT FOUND OR NOT(v_project.client_id=v_actor OR public.is_studio_comember(v_project.designer_id)) THEN
    RAISE EXCEPTION 'project not found or not accessible' USING ERRCODE='insufficient_privilege';
  END IF;
  RETURN jsonb_build_object('projectId',v_project.id,'projectName',v_project.name,'selections',COALESCE((
    SELECT jsonb_agg(jsonb_strip_nulls(jsonb_build_object(
      'id',item.id,'threadId',item.selection_thread_id,'name',item.name,
      'category',item.ffe_category,'assignmentScope',item.assignment_scope,
      'roomId',item.project_room_id,'roomName',room.name,'quantity',item.quantity,
      'productId',item.product_id,'logisticsStatus',item.status
    )) ORDER BY room.sort_order NULLS FIRST,item.sort_order,item.created_at,item.id)
    FROM public.project_ffe_items item
    LEFT JOIN public.project_rooms room ON room.id=item.project_room_id
    WHERE item.project_id=p_project_id AND item.removed_at IS NULL
      AND item.design_disposition='selected'
  ),'[]'::jsonb));
END;
$$;
ALTER FUNCTION public.get_client_project_selections(uuid) RESET ALL;
ALTER FUNCTION public.get_client_project_selections(uuid) SET search_path = pg_catalog, public, pg_temp;
ALTER FUNCTION public.get_client_project_selections(uuid) OWNER TO postgres;

CREATE OR REPLACE FUNCTION public.get_commercial_document_send_snapshot(p_proposal_id uuid)
RETURNS jsonb
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path = public, pg_temp
AS $$
DECLARE
  v_proposal public.proposals%ROWTYPE;
BEGIN
  SELECT * INTO v_proposal FROM public.proposals WHERE id = p_proposal_id;
  IF NOT FOUND OR v_proposal.document_kind = 'legacy'
     OR NOT public._can_author_proposal(v_proposal.designer_id)
  THEN
    RAISE EXCEPTION 'commercial document % not found or access denied', p_proposal_id
      USING ERRCODE = 'insufficient_privilege';
  END IF;
  RETURN jsonb_build_object(
    'proposalId', v_proposal.id,
    'updatedAt', v_proposal.updated_at,
    'documentFingerprint', public._commercial_document_fingerprint(v_proposal.id)
  );
END;
$$;
ALTER FUNCTION public.get_commercial_document_send_snapshot(uuid) RESET ALL;
ALTER FUNCTION public.get_commercial_document_send_snapshot(uuid) SET search_path = pg_catalog, public, pg_temp;
ALTER FUNCTION public.get_commercial_document_send_snapshot(uuid) OWNER TO postgres;

CREATE OR REPLACE FUNCTION public.get_invoice_payment_options(p_invoice_id uuid)
RETURNS jsonb
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path = public, pg_temp
AS $$
DECLARE
  v_uid uuid := (select auth.uid());
  v_invoice invoices%ROWTYPE;
  v_project_client uuid;
  v_bps integer;
  v_remit text;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'invoice_not_found';
  END IF;

  SELECT * INTO v_invoice FROM invoices WHERE id = p_invoice_id;
  IF NOT FOUND OR v_invoice.status = 'draft' THEN
    RAISE EXCEPTION 'invoice_not_found';
  END IF;

  SELECT client_id INTO v_project_client
  FROM projects WHERE id = v_invoice.project_id;

  IF NOT (
    v_uid = coalesce(v_invoice.client_id, v_project_client)
    OR v_uid = v_invoice.designer_id
    OR public.is_active_studio_member(v_invoice.studio_id)
  ) THEN
    RAISE EXCEPTION 'invoice_not_found';
  END IF;

  SELECT card_surcharge_bps, check_remit_to INTO v_bps, v_remit
  FROM studio_billing_settings
  WHERE studio_id = v_invoice.studio_id;

  RETURN jsonb_build_object(
    'card_surcharge_bps', coalesce(v_bps, 300),
    'check_remit_to', v_remit
  );
END;
$$;
ALTER FUNCTION public.get_invoice_payment_options(uuid) RESET ALL;
ALTER FUNCTION public.get_invoice_payment_options(uuid) SET search_path = pg_catalog, public, pg_temp;
ALTER FUNCTION public.get_invoice_payment_options(uuid) OWNER TO postgres;

CREATE OR REPLACE FUNCTION public.get_plan_room_holdings(p_project_id uuid)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, extensions, pg_temp
AS $$
DECLARE
  v_out jsonb;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'reading holdings requires an authenticated designer'
      USING errcode = 'insufficient_privilege';
  END IF;
  IF NOT EXISTS (
    SELECT 1 FROM public.projects p
    WHERE p.id = p_project_id AND public.is_design_studio_comember(p.designer_id)
  ) THEN
    RAISE EXCEPTION 'plan room for project % not found or access denied', p_project_id
      USING errcode = 'insufficient_privilege';
  END IF;

  WITH latest AS (
    SELECT DISTINCT ON (COALESCE(t.party_id::text, lower(btrim(t.party_display_name))))
           t.*
    FROM public.plan_transmittals t
    WHERE t.project_id = p_project_id
    ORDER BY COALESCE(t.party_id::text, lower(btrim(t.party_display_name))),
             t.sent_at DESC, t.id DESC
  ),
  holds AS (
    SELECT l.id AS transmittal_id,
           ip.sheet_id,
           ip.sheet_number,
           ip.rev_letter AS held_rev,
           cp.rev_letter AS current_rev,
           (s.current_print_id IS DISTINCT FROM ip.print_id) AS behind
    FROM latest l
    JOIN public.plan_issue_prints ip ON ip.issue_id = l.issue_id
    JOIN public.plan_sheets s ON s.id = ip.sheet_id
    LEFT JOIN public.plan_prints cp ON cp.id = s.current_print_id
  ),
  -- Revoke-then-mint means at most one live token per send; expiry is REPORTED
  -- rather than filtered, so a studio can see that a link died of old age.
  link AS (
    SELECT DISTINCT ON (tk.transmittal_id) tk.*
    FROM public.plan_transmittal_tokens tk
    JOIN latest l ON l.id = tk.transmittal_id
    WHERE tk.status = 'active'
    ORDER BY tk.transmittal_id, tk.created_at DESC
  )
  SELECT jsonb_build_object('parties', COALESCE(jsonb_agg(jsonb_build_object(
           'partyId', l.party_id,
           'partyDisplayName', l.party_display_name,
           'partyCompany', l.party_company,
           'purpose', l.purpose,
           'sentAt', l.sent_at,
           'issueId', l.issue_id,
           'issueName', i.name,
           'activeLink', CASE WHEN k.id IS NULL THEN NULL ELSE jsonb_build_object(
             'status', k.status,
             'expiresAt', k.expires_at,
             'firstOpenedAt', k.first_opened_at,
             'viewCount', k.view_count) END,
           'holds', COALESCE((
             SELECT jsonb_agg(jsonb_build_object(
               'sheetId', h.sheet_id,
               'sheetNumber', h.sheet_number,
               'heldRev', h.held_rev,
               'currentRev', h.current_rev,
               'behind', h.behind
             ) ORDER BY upper(h.sheet_number))
             FROM holds h WHERE h.transmittal_id = l.id), '[]'::jsonb),
           'behindCount', (
             SELECT count(*) FROM holds h
             WHERE h.transmittal_id = l.id AND h.behind)
         ) ORDER BY l.sent_at DESC, l.id DESC), '[]'::jsonb))
    INTO v_out
    FROM latest l
    JOIN public.plan_issues i ON i.id = l.issue_id
    LEFT JOIN link k ON k.transmittal_id = l.id;

  RETURN v_out;
END;
$$;
ALTER FUNCTION public.get_plan_room_holdings(uuid) RESET ALL;
ALTER FUNCTION public.get_plan_room_holdings(uuid) SET search_path = pg_catalog, public, extensions, pg_temp;
ALTER FUNCTION public.get_plan_room_holdings(uuid) OWNER TO postgres;

CREATE OR REPLACE FUNCTION public.get_project_approval_artifact_candidates(
  p_project_id uuid
)
RETURNS jsonb
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path = public, pg_temp
AS $$
DECLARE
  v_actor uuid := auth.uid();
  v_project public.projects%ROWTYPE;
  v_result jsonb;
BEGIN
  IF v_actor IS NULL THEN
    RAISE EXCEPTION 'artifact candidates require an authenticated studio actor'
      USING ERRCODE = 'insufficient_privilege';
  END IF;
  SELECT * INTO v_project
  FROM public.projects AS project
  WHERE project.id = p_project_id;
  IF NOT FOUND OR NOT public.is_design_studio_comember(v_project.designer_id) THEN
    RAISE EXCEPTION 'project artifact candidates not found or access denied'
      USING ERRCODE = 'insufficient_privilege';
  END IF;

  SELECT COALESCE(
    jsonb_agg(
      jsonb_build_object(
        'artifactKind', candidate.source_kind,
        'artifactId', candidate.source_id,
        'artifactVersion', resolved.source_version,
        'artifactChecksum', resolved.artifact_hash,
        'artifactTitle', resolved.artifact_title,
        'issuedAt', candidate.issued_at,
        'publishedAt', candidate.published_at
      )
      ORDER BY candidate.source_timestamp DESC,
               candidate.source_kind,
               resolved.source_version DESC,
               candidate.source_id
    ),
    '[]'::jsonb
  ) INTO v_result
  FROM (
    SELECT
      'plan_issue'::text AS source_kind,
      issue.id AS source_id,
      issue.issued_at,
      NULL::timestamptz AS published_at,
      issue.issued_at AS source_timestamp
    FROM public.plan_issues AS issue
    WHERE issue.project_id = p_project_id

    UNION ALL

    SELECT
      'spec_book_artifact'::text,
      artifact.id,
      revision.issued_at,
      NULL::timestamptz,
      revision.issued_at
    FROM public.spec_book_artifacts AS artifact
    JOIN public.spec_book_revisions AS revision
      ON revision.id = artifact.revision_id
    JOIN public.spec_books AS book ON book.id = revision.spec_book_id
    JOIN public.project_documents AS document
      ON document.id = artifact.project_document_id
    WHERE book.project_id = p_project_id
      AND revision.status = 'issued'
      AND revision.issued_at IS NOT NULL
      AND artifact.audience = 'client'
      AND artifact.format = 'pdf'
      AND artifact.status = 'ready'
      AND artifact.checksum_sha256 IS NOT NULL
      AND artifact.rendered_at IS NOT NULL
      AND document.project_id = p_project_id
      AND document.status = 'ready'
      AND document.storage_path IS NOT DISTINCT FROM artifact.storage_path

    UNION ALL

    SELECT
      'budget_version'::text,
      budget.id,
      NULL::timestamptz,
      checkpoint.published_at,
      checkpoint.published_at
    FROM public.project_budget_versions AS budget
    JOIN public.project_budget_checkpoints AS checkpoint
      ON checkpoint.project_id = budget.project_id
     AND checkpoint.budget_version_id = budget.id
    WHERE budget.project_id = p_project_id
      AND budget.status = 'published'
      AND budget.published_at IS NOT NULL
      AND checkpoint.snapshot_fingerprint IS NOT DISTINCT FROM
          public._budget_version_fingerprint(budget.id)
  ) AS candidate
  CROSS JOIN LATERAL public._resolve_project_approval_artifact(
    p_project_id, candidate.source_kind, candidate.source_id
  ) AS resolved;

  RETURN v_result;
END;
$$;
ALTER FUNCTION public.get_project_approval_artifact_candidates(uuid) RESET ALL;
ALTER FUNCTION public.get_project_approval_artifact_candidates(uuid) SET search_path = pg_catalog, public, pg_temp;
ALTER FUNCTION public.get_project_approval_artifact_candidates(uuid) OWNER TO postgres;

CREATE OR REPLACE FUNCTION public.get_project_authority_summary(p_project_id uuid)
RETURNS jsonb
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path = public, pg_temp
AS $$
DECLARE
  v_project public.projects%ROWTYPE;
  v_authority public.project_billing_authorities%ROWTYPE;
  v_currency text := 'USD';
  v_accrued bigint := 0;
  v_invoiced bigint := 0;
  v_pending bigint := 0;
  v_retainer_paid_cents bigint := 0;
  v_active_rate_version integer := 1;
  v_furnishings_deposit numeric;
  v_billing_through timestamptz;
  v_state text;
BEGIN
  SELECT * INTO v_project FROM public.projects WHERE id = p_project_id;
  IF NOT FOUND OR auth.uid() IS NULL OR NOT (
    v_project.client_id IS NOT DISTINCT FROM auth.uid()
    OR public.is_studio_comember(v_project.designer_id)
  ) THEN
    RAISE EXCEPTION 'project % not found or access denied', p_project_id
      USING ERRCODE = 'insufficient_privilege';
  END IF;
  SELECT * INTO v_authority FROM public.project_billing_authorities
  WHERE project_id = p_project_id
  ORDER BY (status = 'active') DESC, effective_at DESC, id DESC LIMIT 1;
  IF v_authority.id IS NULL THEN RETURN NULL; END IF;

  SELECT COALESCE(t.currency, 'USD'), COALESCE(t.current_rate_version, 1),
         t.furnishings_deposit_percent
  INTO v_currency, v_active_rate_version, v_furnishings_deposit
  FROM public.proposal_service_terms t
  WHERE t.proposal_id = v_authority.source_proposal_id;

  SELECT
    COALESCE(sum(rated_amount_cents) FILTER (WHERE billing_state = 'authorized'), 0),
    COALESCE(sum(rated_amount_cents) FILTER (WHERE billing_state = 'pending_authorization'), 0),
    COALESCE(sum(rated_amount_cents) FILTER (
      WHERE billing_state = 'authorized' AND invoice_id IS NOT NULL
        AND invoice_status IS DISTINCT FROM 'void'
    ), 0),
    max(started_at) FILTER (
      WHERE billing_state = 'authorized' AND invoice_id IS NOT NULL
        AND invoice_status IS DISTINCT FROM 'void'
    )
  INTO v_accrued, v_pending, v_invoiced, v_billing_through
  FROM (
    SELECT te.*, invoice.status AS invoice_status
    FROM public.project_time_entries te
    LEFT JOIN public.invoices invoice ON invoice.id = te.invoice_id
    WHERE te.project_id = p_project_id AND te.billable
      AND te.duration_minutes IS NOT NULL
  ) rated;

  IF v_authority.retainer_invoice_id IS NOT NULL THEN
    SELECT least(COALESCE(i.amount_paid_cents, 0), v_authority.retainer_amount_cents)
    INTO v_retainer_paid_cents
    FROM public.invoices i WHERE i.id = v_authority.retainer_invoice_id;
  END IF;
  v_retainer_paid_cents := COALESCE(v_retainer_paid_cents, 0);
  v_state := CASE
    WHEN v_authority.status = 'superseded' THEN 'superseded'
    WHEN v_authority.status = 'exhausted'
      OR v_accrued >= v_authority.billing_ceiling_cents THEN 'exhausted'
    WHEN v_authority.retainer_activation_policy = 'retainer_paid'
      AND v_retainer_paid_cents < v_authority.retainer_amount_cents
      THEN 'retainer_pending'
    ELSE 'active'
  END;

  RETURN jsonb_build_object(
    'id', v_authority.id,
    'projectId', v_authority.project_id,
    'agreementId', v_authority.source_proposal_id,
    'state', v_state,
    'currency', v_currency,
    'ceilingCents', v_authority.billing_ceiling_cents,
    'authorizedCents', v_authority.billing_ceiling_cents,
    'accruedCents', v_accrued,
    'invoicedCents', v_invoiced,
    'pendingAuthorizationCents', v_pending,
    'remainingCents', greatest(v_authority.billing_ceiling_cents - v_accrued, 0),
    'retainerAmountCents', v_authority.retainer_amount_cents,
    'retainerPaidCents', v_retainer_paid_cents,
    'retainerActivationPolicy', v_authority.retainer_activation_policy,
    'activeRateVersion', v_active_rate_version,
    'furnishingsDepositPercent', v_furnishings_deposit,
    'billingThrough', v_billing_through,
    'rates', COALESCE((SELECT jsonb_agg(jsonb_build_object(
      'id', r.id, 'proposalId', v_authority.source_proposal_id,
      'version', r.version, 'roleName', r.role_name,
      'hourlyRateCents', r.hourly_rate_cents,
      'effectiveAt', source.effective_at
    ) ORDER BY r.version DESC, r.role_name) FROM public.project_billing_authority_rates r
      JOIN public.proposal_service_rates source ON source.id = r.source_rate_id
      WHERE r.billing_authority_id = v_authority.id), '[]'::jsonb),
    'includesRawEntries', false
  );
END;
$$;
ALTER FUNCTION public.get_project_authority_summary(uuid) RESET ALL;
ALTER FUNCTION public.get_project_authority_summary(uuid) SET search_path = pg_catalog, public, pg_temp;
ALTER FUNCTION public.get_project_authority_summary(uuid) OWNER TO postgres;

CREATE OR REPLACE FUNCTION public.get_project_contextual_handoffs(
  p_project_id uuid
)
RETURNS jsonb
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path = public, pg_temp
AS $$
DECLARE
  v_actor uuid := auth.uid();
  v_result jsonb;
BEGIN
  -- Existence-safe for every authenticated non-studio actor. The ACL is also
  -- explicit so anonymous and service callers have no direct PostgREST rail.
  IF v_actor IS NULL OR NOT EXISTS (
    SELECT 1
    FROM public.projects AS project
    WHERE project.id = p_project_id
      AND public.is_design_studio_comember(project.designer_id)
  ) THEN
    RETURN '[]'::jsonb;
  END IF;

  WITH approval_rows AS (
    SELECT
      decision.id AS source_id,
      decision.project_id,
      decision.phase_id,
      phase.canonical_stage_key,
      phase.workflow_track,
      CASE
        WHEN decision.status = 'draft'
             AND confirmations.completed_count < confirmations.required_count
          THEN 'review_required'
        WHEN decision.status = 'draft'
          THEN 'ready_to_publish'
        WHEN decision.status = 'pending'
          THEN 'response_required'
        ELSE selected.approval_outcome
      END AS source_state,
      CASE
        WHEN decision.status = 'draft'
             AND confirmations.completed_count < confirmations.required_count
          THEN 'confirm_artifact_review'
        WHEN decision.status = 'draft'
          THEN 'publish_confirmed_approval'
        WHEN decision.status = 'pending'
          THEN 'select_approval_outcome'
        WHEN selected.approval_outcome = 'changes_requested'
          THEN 'revise_and_resubmit'
        ELSE 'resolve_client_discussion'
      END AS expected_response,
      CASE
        WHEN decision.status = 'draft'
             AND confirmations.completed_count < confirmations.required_count
          THEN 'open_approval_review'
        WHEN decision.status = 'draft'
          THEN 'publish_approval_request'
        WHEN decision.status = 'pending'
          THEN 'open_approval_response'
        WHEN selected.approval_outcome = 'changes_requested'
          THEN 'supersede_approval_request'
        ELSE 'open_approval_discussion'
      END AS action_kind,
      CASE
        WHEN decision.status = 'pending'
          OR (
            decision.status = 'draft'
            AND confirmations.completed_count < confirmations.required_count
          )
          THEN 'studio'
        ELSE 'client'
      END AS sender,
      CASE
        WHEN decision.status = 'pending'
          OR (
            decision.status = 'draft'
            AND confirmations.completed_count < confirmations.required_count
          )
          THEN 'client'
        ELSE 'studio'
      END AS recipient,
      CASE
        WHEN decision.status = 'pending'
          OR (
            decision.status = 'draft'
            AND confirmations.completed_count < confirmations.required_count
          )
          THEN 'client'
        ELSE 'studio'
      END
        AS current_owner,
      artifact.due_at,
      COALESCE(
        decision.status = 'pending' AND artifact.due_at < now(), false
      ) AS is_overdue,
      jsonb_build_object(
        'kind', artifact.source_kind,
        'version', artifact.source_version,
        'checksum', artifact.artifact_hash,
        'title', artifact.artifact_title
      ) AS artifact,
      decision.updated_at
    FROM public.client_decisions AS decision
    JOIN public.project_decision_authority_snapshots AS authority
      ON authority.decision_id = decision.id
     AND authority.project_id = decision.project_id
    JOIN public.project_approval_artifacts AS artifact
      ON artifact.decision_id = decision.id
     AND artifact.project_id = decision.project_id
     AND artifact.phase_id = decision.phase_id
     AND artifact.due_at IS NOT DISTINCT FROM decision.due_date
    JOIN public.project_phases AS phase
      ON phase.id = decision.phase_id
     AND phase.project_id = decision.project_id
    JOIN LATERAL (
      SELECT
        count(*)::integer AS total_count,
        count(*) FILTER (
          WHERE option.approval_outcome IN (
            'approved', 'changes_requested', 'needs_discussion'
          )
            AND option.cost_cents_delta = artifact.cost_cents_delta
            AND option.schedule_days_delta = artifact.schedule_days_delta
            AND option.lead_time_days_delta = artifact.lead_time_days_delta
            AND option.approves IS NOT DISTINCT FROM
                (option.approval_outcome = 'approved')
        )::integer AS canonical_count,
        count(*) FILTER (WHERE option.selected)::integer AS selected_count
      FROM public.client_decision_options AS option
      WHERE option.decision_id = decision.id
    ) AS option_counts ON true
    LEFT JOIN LATERAL (
      SELECT option.id, option.approval_outcome
      FROM public.client_decision_options AS option
      WHERE option.decision_id = decision.id
        AND option.selected
      ORDER BY option.id
      LIMIT 1
    ) AS selected ON true
    JOIN LATERAL (
      SELECT
        count(*) FILTER (
          WHERE confirmation.authority_revision = authority.authority_revision
            AND confirmation.artifact_hash = artifact.artifact_hash
            AND (
              (
                confirmation.approver_role = 'lead'
                AND confirmation.approver_id = authority.decision_lead_id
              )
              OR (
                confirmation.approver_role = 'coapprover'
                AND authority.required_coapprover_id IS NOT NULL
                AND confirmation.approver_id = authority.required_coapprover_id
              )
            )
        )::integer AS completed_count,
        (1 + CASE WHEN authority.required_coapprover_id IS NULL
                  THEN 0 ELSE 1 END)::integer AS required_count
      FROM public.project_decision_review_confirmations AS confirmation
      WHERE confirmation.decision_id = decision.id
        AND confirmation.project_id = decision.project_id
    ) AS confirmations ON true
    JOIN LATERAL (
      SELECT count(*)::integer AS receipt_count
      FROM public.project_approval_action_receipts AS receipt
      WHERE receipt.decision_id = decision.id
        AND receipt.project_id = decision.project_id
        AND receipt.action_kind = 'created'
        AND receipt.actor_id IS NOT NULL
    ) AS created_receipt ON created_receipt.receipt_count = 1
    JOIN LATERAL (
      SELECT count(*)::integer AS receipt_count
      FROM public.project_approval_action_receipts AS receipt
      WHERE receipt.decision_id = decision.id
        AND receipt.project_id = decision.project_id
        AND receipt.action_kind = 'published'
        AND receipt.successor_decision_id IS NULL
    ) AS published_receipt ON true
    LEFT JOIN LATERAL (
      SELECT count(*)::integer AS receipt_count
      FROM public.project_approval_action_receipts AS receipt
      WHERE receipt.decision_id = decision.id
        AND receipt.project_id = decision.project_id
        AND receipt.action_kind = 'responded'
        AND receipt.successor_decision_id IS NULL
        AND receipt.actor_id = authority.decision_lead_id
        AND receipt.result->>'decisionId' = decision.id::text
        AND receipt.result->>'projectId' = decision.project_id::text
        AND receipt.result->>'optionId' = selected.id::text
        AND receipt.result->>'outcome' = selected.approval_outcome
    ) AS response_receipt ON true
    WHERE decision.project_id = p_project_id
      AND decision.approval_contract = 'project_artifact_v1'
      AND decision.status IN ('draft', 'pending', 'responded')
      AND option_counts.total_count = 3
      AND option_counts.canonical_count = 3
      AND (
        (
          decision.status = 'draft'
          AND option_counts.selected_count = 0
          AND published_receipt.receipt_count = 0
        )
        OR (
          decision.status = 'pending'
          AND option_counts.selected_count = 0
          AND published_receipt.receipt_count = 1
          AND confirmations.completed_count = confirmations.required_count
        )
        OR (
          decision.status = 'responded'
          AND option_counts.selected_count = 1
          AND published_receipt.receipt_count = 1
          AND selected.approval_outcome IN (
            'changes_requested', 'needs_discussion'
          )
          AND response_receipt.receipt_count = 1
        )
      )
      AND NOT EXISTS (
        SELECT 1
        FROM public.project_approval_action_receipts AS terminal_receipt
        WHERE terminal_receipt.decision_id = decision.id
          AND terminal_receipt.project_id = decision.project_id
          AND terminal_receipt.action_kind IN ('withdrawn', 'superseded')
      )
  ),
  site_rows AS (
    SELECT
      request.id AS source_id,
      request.project_id,
      request.status AS source_state,
      CASE request.status
        WHEN 'awaiting_consent' THEN 'provide_sms_consent'
        WHEN 'sent' THEN 'acknowledge_and_begin'
        WHEN 'in_progress' THEN 'deliver_current_item_versions'
        WHEN 'delivered' THEN 'review_delivered_items'
        ELSE 'close_completed_request'
      END AS expected_response,
      CASE request.status
        WHEN 'awaiting_consent' THEN 'open_site_request'
        WHEN 'sent' THEN 'open_site_request'
        WHEN 'in_progress' THEN 'continue_site_request'
        WHEN 'delivered' THEN 'review_site_request'
        ELSE 'close_site_request'
      END AS action_kind,
      CASE WHEN request.status IN ('awaiting_consent', 'sent', 'in_progress')
           THEN 'site_party' ELSE 'studio' END AS current_owner,
      CASE WHEN request.status IN ('awaiting_consent', 'sent', 'in_progress')
           THEN 'studio' ELSE 'site_party' END AS sender,
      CASE WHEN request.status IN ('awaiting_consent', 'sent', 'in_progress')
           THEN 'site_party' ELSE 'studio' END AS recipient,
      request.assignee_name_snapshot,
      request.due_at,
      COALESCE(
        request.status IN ('sent', 'in_progress', 'delivered')
          AND request.due_at < now(), false
      ) AS is_overdue,
      jsonb_build_object(
        'nudgeSent', request.last_nudged_at IS NOT NULL,
        'dueReminderSent', request.due_reminder_sent_at IS NOT NULL
      ) AS escalation,
      jsonb_build_object(
        'kind', 'site_request_item_set',
        'dueContext', request.due_context,
        'itemCount', item_evidence.item_count,
        'items', item_evidence.items
      ) AS artifact,
      request.updated_at
    FROM public.site_requests AS request
    JOIN public.project_parties AS party
      ON party.id = request.assignee_party_id
     AND party.project_id = request.project_id
    JOIN LATERAL (
      SELECT
        count(item.id)::integer AS item_count,
        COALESCE(
          jsonb_agg(
            jsonb_build_object(
              'title', version.title,
              'kitCode', version.kit_code,
              'version', version.version_number,
              'status', item.status,
              'hasDeliveredEvidence', EXISTS (
                SELECT 1
                FROM public.site_deliverables AS deliverable
                WHERE deliverable.request_id = request.id
                  AND deliverable.item_id = item.id
                  AND deliverable.item_version_id = version.id
                  AND deliverable.status = 'delivered'
              ),
              'hasApprovedEvidence', EXISTS (
                SELECT 1
                FROM public.site_binder_entries AS binder
                WHERE binder.project_id = request.project_id
                  AND binder.request_id = request.id
                  AND binder.item_id = item.id
                  AND binder.item_version_id = version.id
              )
            ) ORDER BY item.sort_order, item.id
          ) FILTER (WHERE item.id IS NOT NULL),
          '[]'::jsonb
        ) AS items
      FROM public.site_request_items AS item
      JOIN public.site_request_item_versions AS version
        ON version.id = item.current_version_id
       AND version.item_id = item.id
       AND version.version_number = item.current_version_number
      WHERE item.request_id = request.id
    ) AS item_evidence ON true
    WHERE request.project_id = p_project_id
      AND request.status IN (
        'awaiting_consent', 'sent', 'in_progress', 'delivered', 'completed'
      )
      AND request.created_by IS NOT NULL
  ),
  handoffs AS (
    SELECT
      approval.source_id,
      approval.due_at,
      'project_approval'::text AS source_kind,
      jsonb_build_object(
        'sourceKind', 'project_approval',
        'sourceId', approval.source_id,
        'projectId', approval.project_id,
        'phaseId', approval.phase_id,
        'canonicalStageKey', approval.canonical_stage_key,
        'workflowTrack', approval.workflow_track,
        'stageAttribution', 'exact_project_phase',
        'sourceState', approval.source_state,
        'responsibility', jsonb_build_object(
          'sender', jsonb_build_object('kind', approval.sender),
          'recipient', jsonb_build_object(
            'kind', approval.recipient, 'label', NULL
          ),
          'currentOwner', jsonb_build_object('kind', approval.current_owner)
        ),
        'expectedResponse', approval.expected_response,
        'dueAt', approval.due_at,
        'isOverdue', approval.is_overdue,
        'escalation', NULL,
        'artifact', approval.artifact,
        'actionKind', approval.action_kind,
        'updatedAt', approval.updated_at
      ) AS item
    FROM approval_rows AS approval

    UNION ALL

    SELECT
      site.source_id,
      site.due_at,
      'site_request'::text AS source_kind,
      jsonb_build_object(
        'sourceKind', 'site_request',
        'sourceId', site.source_id,
        'projectId', site.project_id,
        'phaseId', NULL,
        'canonicalStageKey', 'contract_administration',
        'workflowTrack', NULL,
        'stageAttribution', 'source_domain',
        'sourceState', site.source_state,
        'responsibility', jsonb_build_object(
          'sender', jsonb_build_object(
            'kind', site.sender,
            'label', CASE WHEN site.sender = 'site_party'
                          THEN site.assignee_name_snapshot ELSE NULL END
          ),
          'recipient', jsonb_build_object(
            'kind', site.recipient,
            'label', CASE WHEN site.recipient = 'site_party'
                          THEN site.assignee_name_snapshot ELSE NULL END
          ),
          'currentOwner', jsonb_build_object('kind', site.current_owner)
        ),
        'expectedResponse', site.expected_response,
        'dueAt', site.due_at,
        'isOverdue', site.is_overdue,
        'escalation', site.escalation,
        'artifact', site.artifact,
        'actionKind', site.action_kind,
        'updatedAt', site.updated_at
      ) AS item
    FROM site_rows AS site
  )
  SELECT COALESCE(
    jsonb_agg(handoff.item ORDER BY handoff.due_at, handoff.source_kind,
                                      handoff.source_id),
    '[]'::jsonb
  )
  INTO v_result
  FROM handoffs AS handoff;

  RETURN v_result;
END;
$$;
ALTER FUNCTION public.get_project_contextual_handoffs(uuid) RESET ALL;
ALTER FUNCTION public.get_project_contextual_handoffs(uuid) SET search_path = pg_catalog, public, pg_temp;
ALTER FUNCTION public.get_project_contextual_handoffs(uuid) OWNER TO postgres;

CREATE OR REPLACE FUNCTION public.get_project_decision_reviews(
  p_project_id uuid
)
RETURNS jsonb
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path = public, pg_temp
AS $$
DECLARE
  v_actor uuid := auth.uid();
  v_project public.projects%ROWTYPE;
  v_is_studio boolean := false;
  v_result jsonb;
BEGIN
  IF v_actor IS NULL THEN
    RAISE EXCEPTION 'project decision reviews require an authenticated actor'
      USING ERRCODE = 'insufficient_privilege';
  END IF;

  SELECT * INTO v_project
  FROM public.projects AS project
  WHERE project.id = p_project_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'project decision reviews not found or access denied'
      USING ERRCODE = 'insufficient_privilege';
  END IF;

  v_is_studio := public.is_design_studio_comember(v_project.designer_id);
  IF NOT v_is_studio
     AND NOT EXISTS (
       SELECT 1
       FROM public.project_decision_authority_snapshots AS snapshot
       WHERE snapshot.project_id = p_project_id
         AND snapshot.decision_lead_id = v_actor
     )
  THEN
    RAISE EXCEPTION 'project decision reviews not found or access denied'
      USING ERRCODE = 'insufficient_privilege';
  END IF;

  SELECT COALESCE(jsonb_agg(review.item ORDER BY review.created_at, review.id),
                  '[]'::jsonb)
  INTO v_result
  FROM (
    SELECT decision.id,
           decision.created_at,
           jsonb_build_object(
             'decisionId', decision.id,
             'projectId', decision.project_id,
             'phaseId', decision.phase_id,
             'sectionKey', decision.section_key,
             'authorityRevision', snapshot.authority_revision,
             'artifactKind', artifact.source_kind,
             'artifactId', artifact.source_id,
             'artifactVersion', artifact.source_version,
             'artifactChecksum', artifact.artifact_hash,
             'artifactTitle', artifact.artifact_title,
             'question', artifact.question,
             'context', artifact.context,
             'dueAt', artifact.due_at,
             'costCentsDelta', artifact.cost_cents_delta,
             'scheduleDaysDelta', artifact.schedule_days_delta,
             'leadTimeDaysDelta', artifact.lead_time_days_delta,
             'lifecycleStatus', decision.status,
             'outcome', selected.approval_outcome,
             'disposition', CASE
               WHEN superseded.successor_decision_id IS NOT NULL THEN 'superseded'
               WHEN withdrawn.id IS NOT NULL THEN 'withdrawn'
               ELSE 'active'
             END,
             'isOverdue',
               decision.status = 'pending'
               AND decision.due_date IS NOT NULL
               AND decision.due_date < now(),
             'completedReviewCount', COALESCE(review_counts.completed_count, 0),
             'requiredReviewCount',
               1 + CASE WHEN snapshot.required_coapprover_id IS NULL THEN 0 ELSE 1 END,
             'predecessorDecisionId', decision.predecessor_decision_id,
             'successorDecisionId', superseded.successor_decision_id,
             'createdAt', decision.created_at,
             'sentAt', decision.sent_at,
             'respondedAt', decision.responded_at,
             'updatedAt', decision.updated_at
           ) AS item
    FROM public.client_decisions AS decision
    JOIN public.project_decision_authority_snapshots AS snapshot
      ON snapshot.decision_id = decision.id
     AND snapshot.project_id = decision.project_id
    JOIN public.project_approval_artifacts AS artifact
      ON artifact.decision_id = decision.id
     AND artifact.project_id = decision.project_id
    LEFT JOIN LATERAL (
      SELECT option.approval_outcome
      FROM public.client_decision_options AS option
      WHERE option.decision_id = decision.id
        AND option.selected
      ORDER BY option.id
      LIMIT 1
    ) AS selected ON true
    LEFT JOIN LATERAL (
      SELECT receipt.id, receipt.successor_decision_id
      FROM public.project_approval_action_receipts AS receipt
      WHERE receipt.decision_id = decision.id
        AND receipt.project_id = decision.project_id
        AND receipt.action_kind = 'superseded'
      ORDER BY receipt.created_at, receipt.id
      LIMIT 1
    ) AS superseded ON true
    LEFT JOIN LATERAL (
      SELECT receipt.id
      FROM public.project_approval_action_receipts AS receipt
      WHERE receipt.decision_id = decision.id
        AND receipt.project_id = decision.project_id
        AND receipt.action_kind = 'withdrawn'
      ORDER BY receipt.created_at, receipt.id
      LIMIT 1
    ) AS withdrawn ON true
    LEFT JOIN LATERAL (
      SELECT count(*)::integer AS completed_count
      FROM public.project_decision_review_confirmations AS confirmation
      WHERE confirmation.decision_id = decision.id
        AND confirmation.project_id = decision.project_id
        AND confirmation.authority_revision = snapshot.authority_revision
        AND confirmation.artifact_hash = artifact.artifact_hash
        AND (
          (
            confirmation.approver_role = 'lead'
            AND confirmation.approver_id = snapshot.decision_lead_id
          )
          OR (
            confirmation.approver_role = 'coapprover'
            AND snapshot.required_coapprover_id IS NOT NULL
            AND confirmation.approver_id
                  IS NOT DISTINCT FROM snapshot.required_coapprover_id
          )
        )
    ) AS review_counts ON true
    WHERE decision.project_id = p_project_id
      AND decision.approval_contract = 'project_artifact_v1'
      AND (v_is_studio OR snapshot.decision_lead_id = v_actor)
  ) AS review;

  RETURN v_result;
END;
$$;
ALTER FUNCTION public.get_project_decision_reviews(uuid) RESET ALL;
ALTER FUNCTION public.get_project_decision_reviews(uuid) SET search_path = pg_catalog, public, pg_temp;
ALTER FUNCTION public.get_project_decision_reviews(uuid) OWNER TO postgres;

CREATE OR REPLACE FUNCTION public.get_project_workflow(p_project_id uuid)
RETURNS TABLE (
  phase_id uuid,
  source_proposal_phase_id uuid,
  sort_order integer,
  phase_key text,
  canonical_stage_key text,
  workflow_track text,
  phase_name text,
  phase_status text,
  progress integer,
  lane text,
  follows_phase_id uuid,
  start_date date,
  target_end_date date,
  completed_at timestamptz,
  gate_note text,
  deliverables jsonb,
  template_provenance jsonb,
  advance_blocker_count integer,
  blocks_advance boolean,
  current_blockers jsonb
)
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path = public, pg_temp
AS $$
DECLARE
  v_actor uuid := auth.uid();
  v_project public.projects%ROWTYPE;
BEGIN
  IF v_actor IS NULL THEN
    RAISE EXCEPTION
      'get_project_workflow requires an authenticated designer'
      USING ERRCODE = 'insufficient_privilege';
  END IF;

  SELECT * INTO v_project
  FROM public.projects
  WHERE id = p_project_id;

  IF NOT FOUND OR NOT public._can_author_proposal(v_project.designer_id) THEN
    RAISE EXCEPTION
      'get_project_workflow: project not found or access denied'
      USING ERRCODE = 'insufficient_privilege';
  END IF;

  RETURN QUERY
  SELECT phase.id,
         phase.source_proposal_phase_id,
         phase.sort_order,
         phase.phase_key,
         phase.canonical_stage_key,
         phase.workflow_track,
         phase.name,
         phase.status,
         COALESCE(phase.progress, 0),
         phase.lane,
         phase.follows_phase_id,
         phase.start_date,
         phase.target_end_date,
         phase.completed_at,
         phase.gate_condition,
         COALESCE(deliverable_rollup.items, phase.deliverables, '[]'::jsonb),
         CASE
           WHEN phase.source_template_slug IS NULL THEN '{}'::jsonb
           ELSE jsonb_build_object(
             'slug', phase.source_template_slug,
             'version', phase.source_template_version
           )
         END,
         jsonb_array_length(blocker_rollup.phase_items),
         jsonb_array_length(blocker_rollup.phase_items) > 0,
         jsonb_build_object(
           'count',
             jsonb_array_length(blocker_rollup.phase_items)
             + jsonb_array_length(blocker_rollup.task_items)
             + jsonb_array_length(blocker_rollup.ffe_items),
           'phase', blocker_rollup.phase_items,
           'tasks', blocker_rollup.task_items,
           'ffe', blocker_rollup.ffe_items
         )
  FROM public.project_phases AS phase
  LEFT JOIN LATERAL (
    SELECT jsonb_agg(
             jsonb_build_object(
               'sourceDeliverableId', deliverable.id,
               'label', deliverable.label,
               'description', deliverable.description,
               'isRequired', deliverable.is_required,
               'sortOrder', deliverable.sort_order,
               'completedAt', deliverable.completed_at
             )
             ORDER BY deliverable.sort_order, deliverable.id
           ) AS items
    FROM public.proposal_phase_deliverables AS deliverable
    WHERE deliverable.phase_id = phase.source_proposal_phase_id
  ) AS deliverable_rollup ON true
  CROSS JOIN LATERAL (
    SELECT
      COALESCE((
        SELECT jsonb_agg(
                 jsonb_build_object(
                   'id', decision.id,
                   'kind', 'coordination',
                   'title', decision.title,
                   'status', decision.status,
                   'approvalOutcome', (
                     SELECT option.approval_outcome
                     FROM public.client_decision_options AS option
                     WHERE option.decision_id = decision.id
                       AND option.selected
                     ORDER BY option.id
                     LIMIT 1
                   ),
                   'coordinationKind', decision.coordination_kind,
                   'court', decision.court,
                   'dueDate', decision.due_date,
                   'isOverdue',
                     decision.status = 'pending'
                     AND decision.due_date IS NOT NULL
                     AND decision.due_date < now()
                 )
                 ORDER BY decision.due_date NULLS LAST,
                          decision.created_at, decision.id
               )
        FROM public.client_decisions AS decision
        WHERE decision.project_id = phase.project_id
          AND decision.phase_id = phase.id
          AND public._client_decision_blocks_phase(decision)
      ), '[]'::jsonb) AS phase_items,
      COALESCE((
        SELECT jsonb_agg(
                 jsonb_build_object(
                   'id', task.id,
                   'kind', 'task',
                   'title', task.title,
                   'status', task.status,
                   'owner', task.owner,
                   'dueDate', task.due_date,
                   'isOverdue',
                     task.due_date IS NOT NULL
                     AND task.due_date < CURRENT_DATE,
                   'blockedByCoordinationId', task.blocked_by_item_id
                 )
                 ORDER BY task.due_date NULLS LAST,
                          task.sort_order, task.id
               )
        FROM public.project_tasks AS task
        WHERE task.project_id = phase.project_id
          AND task.status = 'blocked'
          AND (
            (
              phase.phase_key IS NOT NULL
              AND task.phase_key = phase.phase_key
              AND (
                SELECT count(*)
                FROM public.project_phases AS same_key
                WHERE same_key.project_id = phase.project_id
                  AND same_key.phase_key = phase.phase_key
              ) = 1
            )
            OR EXISTS (
              SELECT 1
              FROM public.client_decisions AS blocker
              WHERE blocker.id = task.blocked_by_item_id
                AND blocker.project_id = phase.project_id
                AND blocker.phase_id = phase.id
            )
          )
      ), '[]'::jsonb) AS task_items,
      COALESCE((
        SELECT jsonb_agg(
                 jsonb_build_object(
                   'id', item.id,
                   'kind', 'ffe',
                   'title', item.name,
                   'status', item.status,
                   'eta', item.eta,
                   'isOverdue',
                     item.eta IS NOT NULL AND item.eta < CURRENT_DATE,
                   'reason', item.blocked_reason,
                   'blockedByCoordinationId', item.blocked_by_decision_id
                 )
                 ORDER BY item.eta NULLS LAST, item.sort_order, item.id
               )
        FROM public.project_ffe_items AS item
        JOIN public.client_decisions AS blocker
          ON blocker.id = item.blocked_by_decision_id
         AND blocker.project_id = phase.project_id
         AND blocker.phase_id = phase.id
        WHERE item.project_id = phase.project_id
          AND item.blocked
      ), '[]'::jsonb) AS ffe_items
  ) AS blocker_rollup
  WHERE phase.project_id = v_project.id
  ORDER BY phase.sort_order, phase.id;
END;
$$;
ALTER FUNCTION public.get_project_workflow(uuid) RESET ALL;
ALTER FUNCTION public.get_project_workflow(uuid) SET search_path = pg_catalog, public, pg_temp;
ALTER FUNCTION public.get_project_workflow(uuid) OWNER TO postgres;

CREATE OR REPLACE FUNCTION public.get_project_working_budget(p_project_id uuid)
RETURNS jsonb
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path = public, pg_temp
AS $$
DECLARE
  v_project public.projects%ROWTYPE;
  v_version public.project_budget_versions%ROWTYPE;
  v_checkpoint public.project_budget_checkpoints%ROWTYPE;
  v_is_studio boolean;
BEGIN
  SELECT * INTO v_project FROM public.projects WHERE id = p_project_id;
  IF NOT FOUND OR auth.uid() IS NULL OR NOT (
    v_project.client_id IS NOT DISTINCT FROM auth.uid()
    OR public.is_studio_comember(v_project.designer_id)
  ) THEN
    RAISE EXCEPTION 'project % not found or access denied', p_project_id
      USING ERRCODE = 'insufficient_privilege';
  END IF;
  v_is_studio := public.is_studio_comember(v_project.designer_id);
  SELECT * INTO v_version FROM public.project_budget_versions
  WHERE project_id = p_project_id
    AND (status = 'published' OR public.is_studio_comember(v_project.designer_id))
  ORDER BY version DESC LIMIT 1;
  IF v_version.id IS NULL THEN RETURN NULL; END IF;
  SELECT * INTO v_checkpoint FROM public.project_budget_checkpoints
  WHERE budget_version_id = v_version.id;
  -- 00414: the version note is the studio's internal working commentary, and
  -- the override actor/reason is the studio's audited rationale for proceeding
  -- past an unacknowledged checkpoint. Neither is client copy. The client's own
  -- acknowledgement (acknowledgedBy/acknowledgedAt) stays — that is their act.
  RETURN jsonb_build_object(
    'version', jsonb_build_object(
      'id', v_version.id, 'projectId', v_version.project_id,
      'version', v_version.version, 'status', v_version.status,
      'lowTotalCents', v_version.low_total_cents,
      'targetTotalCents', v_version.target_total_cents,
      'highTotalCents', v_version.high_total_cents,
      'currency', 'USD', 'note', v_version.note,
      'liveAuthorizedTotalCents', COALESCE((
        SELECT SUM(a.client_line_total_cents)
        FROM public.furnishing_authorization_items a
        JOIN public.project_commercial_documents d ON d.id = a.commercial_document_id
        JOIN public.proposals p ON p.id = d.proposal_id
        WHERE d.project_id = p_project_id
          AND d.executed_at IS NOT NULL
          AND p.commercial_state = 'executed'
      ), 0),
      'createdAt', v_version.created_at, 'publishedAt', v_version.published_at
    ) - CASE WHEN v_is_studio THEN '{}'::text[] ELSE ARRAY['note'] END,
    'lines', COALESCE((SELECT jsonb_agg(jsonb_build_object(
      'id', l.id, 'projectRoomId', l.project_room_id, 'roomName', l.room_name,
      'category', l.category, 'lowCents', l.low_cents,
      'targetCents', l.target_cents, 'highCents', l.high_cents,
      'scheduledCents', l.scheduled_cents, 'authorizedCents', l.authorized_cents,
      -- The publish stamp's `authorized` rollup, run at read time instead of at
      -- publication. Kept character-for-character the same shape on purpose: if
      -- one of the two ever needs a fix, the other needs the identical fix.
      'liveAuthorizedCents', COALESCE((
        SELECT SUM(a.client_line_total_cents)
        FROM public.furnishing_authorization_items a
        JOIN public.project_commercial_documents d ON d.id = a.commercial_document_id
        JOIN public.proposals p ON p.id = d.proposal_id
        WHERE d.project_id = p_project_id
          AND d.executed_at IS NOT NULL
          AND p.commercial_state = 'executed'
          AND CASE
                WHEN l.project_room_id IS NOT NULL AND a.project_room_id IS NOT NULL
                  THEN a.project_room_id = l.project_room_id
                ELSE COALESCE(a.room_name, '') = l.room_name
              END
          AND COALESCE(a.category, 'Uncategorized') = l.category
      ), 0),
      'sortOrder', l.sort_order
    ) ORDER BY l.sort_order, l.id) FROM public.project_budget_lines l
      WHERE l.budget_version_id = v_version.id), '[]'::jsonb),
    'checkpoint', CASE WHEN v_checkpoint.id IS NULL THEN NULL ELSE jsonb_build_object(
      'id', v_checkpoint.id, 'projectId', v_checkpoint.project_id,
      'versionId', v_checkpoint.budget_version_id,
      'checkpointCode', v_checkpoint.checkpoint_code,
      'status', v_checkpoint.status, 'snapshotFingerprint', v_checkpoint.snapshot_fingerprint,
      'publishedAt', v_checkpoint.published_at,
      'acknowledgedBy', v_checkpoint.acknowledged_by,
      'acknowledgedAt', v_checkpoint.acknowledged_at,
      'overrideBy', v_checkpoint.override_by,
      'overrideReason', v_checkpoint.override_reason,
      'overriddenAt', v_checkpoint.overridden_at
    ) - CASE WHEN v_is_studio THEN '{}'::text[]
             ELSE ARRAY['overrideBy', 'overrideReason'] END
    END,
    'isPurchaseAuthority', false
  );
END;
$$;
ALTER FUNCTION public.get_project_working_budget(uuid) RESET ALL;
ALTER FUNCTION public.get_project_working_budget(uuid) SET search_path = pg_catalog, public, pg_temp;
ALTER FUNCTION public.get_project_working_budget(uuid) OWNER TO postgres;

CREATE OR REPLACE FUNCTION public.get_proposal_send_dispatch_status(
  p_proposal_id uuid,
  p_dispatch_id uuid,
  p_sent_at timestamptz
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, pg_temp
AS $$
DECLARE
  v_dispatch public.proposal_send_dispatches%ROWTYPE;
  v_now timestamptz := clock_timestamp();
  v_retry_exhausted boolean;
  v_retryable boolean;
BEGIN
  IF COALESCE(auth.role(), '') <> 'authenticated' OR auth.uid() IS NULL THEN
    RAISE EXCEPTION 'proposal send status not found or access denied'
      USING ERRCODE = 'insufficient_privilege';
  END IF;

  SELECT * INTO v_dispatch
  FROM public.proposal_send_dispatches
  WHERE proposal_id = p_proposal_id
    AND id = p_dispatch_id
    AND sent_at = p_sent_at
  FOR UPDATE;

  IF NOT FOUND OR NOT public._can_author_proposal(v_dispatch.designer_id) THEN
    RAISE EXCEPTION 'proposal send status not found or access denied'
      USING ERRCODE = 'insufficient_privilege';
  END IF;

  -- A reopened sheet is also a recovery observer. Never surface a dead lease
  -- as permanently in-flight: pre-provider work restores the claimed semantic
  -- state, while a started provider upload becomes ambiguous.
  IF v_dispatch.state = 'in_flight'
     AND (
       v_dispatch.lease_expires_at IS NULL
       OR v_dispatch.lease_expires_at <= v_now
     )
  THEN
    UPDATE public.proposal_send_dispatches
    SET state = CASE
          WHEN provider_started_at IS NULL
            THEN COALESCE(claimed_from_state, 'pending')
          ELSE 'ambiguous'
        END,
        claim_token = NULL,
        lease_expires_at = NULL,
        claimed_from_state = NULL,
        last_error = CASE
          WHEN provider_started_at IS NULL THEN last_error
          ELSE COALESCE(last_error, 'provider attempt lease expired')
        END,
        updated_at = v_now
    WHERE id = v_dispatch.id
    RETURNING * INTO v_dispatch;
  END IF;

  IF v_dispatch.state = 'ambiguous'
     AND (
       v_dispatch.provider_attempt_count >= 3
       OR (
         v_dispatch.provider_attempt_count > 0
         AND v_dispatch.retry_deadline IS NULL
       )
       OR v_dispatch.retry_deadline <= v_now
     )
  THEN
    UPDATE public.proposal_send_dispatches
    SET state = 'unconfirmed',
        claim_token = NULL,
        lease_expires_at = NULL,
        claimed_from_state = NULL,
        last_error = COALESCE(
          last_error,
          'provider delivery could not be confirmed before retry exhaustion'
        ),
        updated_at = v_now
    WHERE id = v_dispatch.id
    RETURNING * INTO v_dispatch;

  END IF;

  v_retry_exhausted := v_dispatch.state = 'unconfirmed'
    OR (
      v_dispatch.state = 'failed'
      AND (
        v_dispatch.provider_attempt_count >= 3
        OR (
          v_dispatch.provider_attempt_count > 0
          AND v_dispatch.retry_deadline IS NULL
        )
        OR v_dispatch.retry_deadline <= v_now
      )
    );
  v_retryable := v_dispatch.state IN ('pending', 'in_flight')
    OR (
      v_dispatch.state IN ('failed', 'ambiguous')
      AND NOT v_retry_exhausted
    );

  -- Any terminal state observed here is reconciled in the same transaction;
  -- an expired ambiguity can therefore never remain logged as sending.
  IF v_dispatch.state IN ('delivered', 'suppressed', 'unconfirmed')
     OR (v_dispatch.state = 'failed' AND v_retry_exhausted)
  THEN
    PERFORM public._sync_proposal_send_email_log(v_dispatch.id);
  END IF;

  RETURN jsonb_build_object(
    'delivery_state', v_dispatch.state,
    'attempt_count', v_dispatch.provider_attempt_count,
    'retryable', v_retryable,
    'retry_exhausted', v_retry_exhausted,
    'last_error', v_dispatch.last_error
  );
END;
$$;
ALTER FUNCTION public.get_proposal_send_dispatch_status(uuid,uuid,timestamp with time zone) RESET ALL;
ALTER FUNCTION public.get_proposal_send_dispatch_status(uuid,uuid,timestamp with time zone) SET search_path = pg_catalog, public, pg_temp;
ALTER FUNCTION public.get_proposal_send_dispatch_status(uuid,uuid,timestamp with time zone) OWNER TO postgres;

CREATE OR REPLACE FUNCTION public.get_proposal_send_snapshot(
  p_proposal_id uuid
)
RETURNS TABLE (
  proposal_updated_at timestamptz,
  proposal_total_amount integer,
  schedule_fingerprint text
)
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path = public, pg_temp
AS $$
DECLARE
  v_actor uuid := auth.uid();
  v_proposal public.proposals%ROWTYPE;
BEGIN
  IF v_actor IS NULL THEN
    RETURN;
  END IF;

  SELECT * INTO v_proposal
  FROM public.proposals
  WHERE id = p_proposal_id;

  -- Preserve the prior RLS-shaped result: a foreign proposal returns no row.
  -- The explicit check is required because the function now runs as definer so
  -- studio co-members see the same complete child token as the send boundary.
  IF NOT FOUND OR NOT public._can_author_proposal(v_proposal.designer_id) THEN
    RETURN;
  END IF;

  RETURN QUERY SELECT
    v_proposal.updated_at,
    v_proposal.total_amount,
    public._proposal_review_fingerprint(v_proposal.id);
END;
$$;
ALTER FUNCTION public.get_proposal_send_snapshot(uuid) RESET ALL;
ALTER FUNCTION public.get_proposal_send_snapshot(uuid) SET search_path = pg_catalog, public, pg_temp;
ALTER FUNCTION public.get_proposal_send_snapshot(uuid) OWNER TO postgres;

CREATE OR REPLACE FUNCTION public.get_site_request_action_detail(
  p_project_id uuid,
  p_request_id uuid
)
RETURNS jsonb
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path TO 'public', 'pg_temp'
AS $$
DECLARE
  v_actor uuid := auth.uid();
  v_request_status text;
  v_item_count integer;
  v_current_count integer;
  v_missing_evidence_count integer;
  v_items jsonb;
  v_rooms jsonb;
BEGIN
  IF v_actor IS NULL OR NOT EXISTS (
    SELECT 1
    FROM public.projects AS project
    WHERE project.id = p_project_id
      AND public.is_design_studio_comember(project.designer_id)
  ) THEN
    RETURN jsonb_build_object(
      'projectId', p_project_id,
      'requestId', p_request_id,
      'coherent', false,
      'items', '[]'::jsonb,
      'rooms', '[]'::jsonb
    );
  END IF;

  SELECT request.status
  INTO v_request_status
  FROM public.site_requests AS request
  WHERE request.id = p_request_id
    AND request.project_id = p_project_id;

  IF NOT FOUND OR v_request_status NOT IN (
    'sent', 'in_progress', 'delivered', 'completed'
  ) THEN
    RETURN jsonb_build_object(
      'projectId', p_project_id,
      'requestId', p_request_id,
      'coherent', false,
      'items', '[]'::jsonb,
      'rooms', '[]'::jsonb
    );
  END IF;

  SELECT count(*)::integer
  INTO v_item_count
  FROM public.site_request_items AS item
  WHERE item.request_id = p_request_id;

  IF v_item_count < 1 OR v_item_count > 100 THEN
    RETURN jsonb_build_object(
      'projectId', p_project_id,
      'requestId', p_request_id,
      'coherent', false,
      'items', '[]'::jsonb,
      'rooms', '[]'::jsonb
    );
  END IF;

  SELECT count(*)::integer
  INTO v_current_count
  FROM public.site_request_items AS item
  JOIN public.site_request_item_versions AS version
    ON version.id = item.current_version_id
   AND version.item_id = item.id
   AND version.version_number = item.current_version_number
  WHERE item.request_id = p_request_id;

  IF v_current_count <> v_item_count THEN
    RETURN jsonb_build_object(
      'projectId', p_project_id,
      'requestId', p_request_id,
      'coherent', false,
      'items', '[]'::jsonb,
      'rooms', '[]'::jsonb
    );
  END IF;

  SELECT count(*)::integer
  INTO v_missing_evidence_count
  FROM public.site_request_items AS item
  JOIN public.site_request_item_versions AS version
    ON version.id = item.current_version_id
   AND version.item_id = item.id
   AND version.version_number = item.current_version_number
  LEFT JOIN LATERAL (
    SELECT deliverable.id
    FROM public.site_deliverables AS deliverable
    WHERE deliverable.request_id = p_request_id
      AND deliverable.item_id = item.id
      AND deliverable.item_version_id = version.id
      AND deliverable.status = 'delivered'
    ORDER BY deliverable.attempt_number DESC, deliverable.id DESC
    LIMIT 1
  ) AS latest_delivery ON true
  WHERE item.request_id = p_request_id
    AND item.status IN ('delivered', 'approved')
    AND latest_delivery.id IS NULL;

  IF v_missing_evidence_count <> 0 THEN
    RETURN jsonb_build_object(
      'projectId', p_project_id,
      'requestId', p_request_id,
      'coherent', false,
      'items', '[]'::jsonb,
      'rooms', '[]'::jsonb
    );
  END IF;

  SELECT COALESCE(
    jsonb_agg(
      jsonb_build_object(
        'itemId', item.id,
        'title', version.title,
        'kitCode', version.kit_code,
        'version', version.version_number,
        'roomId', version.room_id,
        'status', item.status,
        'deliverableId', latest_delivery.id
      ) ORDER BY item.sort_order, item.id
    ),
    '[]'::jsonb
  )
  INTO v_items
  FROM public.site_request_items AS item
  JOIN public.site_request_item_versions AS version
    ON version.id = item.current_version_id
   AND version.item_id = item.id
   AND version.version_number = item.current_version_number
  LEFT JOIN LATERAL (
    SELECT deliverable.id
    FROM public.site_deliverables AS deliverable
    WHERE deliverable.request_id = p_request_id
      AND deliverable.item_id = item.id
      AND deliverable.item_version_id = version.id
      AND deliverable.status = 'delivered'
    ORDER BY deliverable.attempt_number DESC, deliverable.id DESC
    LIMIT 1
  ) AS latest_delivery ON true
  WHERE item.request_id = p_request_id;

  IF jsonb_array_length(v_items) <> v_item_count THEN
    RETURN jsonb_build_object(
      'projectId', p_project_id,
      'requestId', p_request_id,
      'coherent', false,
      'items', '[]'::jsonb,
      'rooms', '[]'::jsonb
    );
  END IF;

  SELECT COALESCE(
    jsonb_agg(
      jsonb_build_object('id', room.id, 'name', room.name)
      ORDER BY room.sort_order, room.id
    ),
    '[]'::jsonb
  )
  INTO v_rooms
  FROM public.project_rooms AS room
  WHERE room.project_id = p_project_id;

  RETURN jsonb_build_object(
    'projectId', p_project_id,
    'requestId', p_request_id,
    'coherent', true,
    'items', v_items,
    'rooms', v_rooms
  );
END;
$$;
ALTER FUNCTION public.get_site_request_action_detail(uuid,uuid) RESET ALL;
ALTER FUNCTION public.get_site_request_action_detail(uuid,uuid) SET search_path = pg_catalog, public, pg_temp;
ALTER FUNCTION public.get_site_request_action_detail(uuid,uuid) OWNER TO postgres;

CREATE OR REPLACE FUNCTION public.guard_client_decision_authority()
RETURNS trigger
LANGUAGE plpgsql
SECURITY INVOKER
SET search_path = public, pg_temp
AS $$
DECLARE
  v_maintenance boolean := current_user IS NOT DISTINCT FROM 'postgres'
    AND auth.uid() IS NULL
    AND COALESCE(auth.role(), '') NOT IN ('authenticated', 'service_role');
  v_protected_change boolean;
  v_actor_is_studio boolean;
  v_actor_is_client boolean;
  v_previous_decision_capability text;
  v_previous_compat_reopen text;
BEGIN
  IF TG_OP = 'DELETE' THEN
    IF current_user IS NOT DISTINCT FROM 'authenticated'
       AND OLD.status = 'draft'
       AND public.is_design_studio_comember(OLD.designer_id)
    THEN
      -- Rollback web bundles delete only authored drafts. Keep that exact
      -- operation during the expand phase without restoring terminal-row
      -- deletion authority.
      PERFORM set_config(
        'app.client_decision_delete_cascade_id', OLD.id::text, true
      );
      RETURN OLD;
    END IF;

    IF NOT v_maintenance
       AND (
         current_user IS DISTINCT FROM 'postgres'
         OR current_setting('app.client_decision_write_id', true)
            IS DISTINCT FROM OLD.id::text
       )
    THEN
      RAISE EXCEPTION
        'client decisions may only be deleted through delete_client_decision_draft'
        USING ERRCODE = 'check_violation';
    END IF;
    PERFORM set_config(
      'app.client_decision_delete_cascade_id', OLD.id::text, true
    );
    RETURN OLD;
  END IF;

  IF TG_OP = 'INSERT' THEN
    PERFORM public.assert_client_decision_reference_integrity(
      NEW.id,
      NEW.designer_client_id,
      NEW.designer_id,
      NEW.project_id,
      NEW.status,
      NEW.phase_id,
      NEW.room_id,
      NEW.blocks_milestone_id,
      NEW.court_party_id,
      NEW.linked_proposal_id,
      NEW.recommended_option_id
    );

    -- Every row, including a trusted workflow insert, must bind to the exact
    -- designer↔client relationship named by its denormalized designer_id.
    IF NOT EXISTS (
      SELECT 1
      FROM public.designer_clients AS relationship
      WHERE relationship.id = NEW.designer_client_id
        AND relationship.designer_id IS NOT DISTINCT FROM NEW.designer_id
    ) THEN
      RAISE EXCEPTION
        'client decision designer identity does not match its relationship'
        USING ERRCODE = 'check_violation';
    END IF;

    IF v_maintenance THEN
      RETURN NEW;
    END IF;

    IF NEW.status IN ('responded', 'expired')
       OR NEW.responded_at IS NOT NULL
       OR NEW.selected_by IS NOT NULL
       OR NEW.answer IS NOT NULL
       OR NEW.answered_at IS NOT NULL
       OR NEW.answered_by IS NOT NULL
       OR NEW.client_consent_method IS NOT NULL
       OR NEW.client_consented_at IS NOT NULL
       OR NEW.client_signature IS NOT NULL
    THEN
      IF current_user IS DISTINCT FROM 'postgres'
         OR current_setting('app.client_decision_insert_id', true)
            IS DISTINCT FROM NEW.id::text
      THEN
        RAISE EXCEPTION
          'resolved decision truth may only be inserted by a canonical workflow'
          USING ERRCODE = 'check_violation';
      END IF;
      RETURN NEW;
    END IF;

    IF current_user IS DISTINCT FROM 'postgres' THEN
      -- Browser-created rows may supply every insertable column, but audit
      -- birth timestamps are server evidence rather than caller metadata.
      NEW.created_at := now();
      NEW.updated_at := now();

      IF NOT public.is_design_studio_comember(NEW.designer_id) THEN
        RAISE EXCEPTION 'not authorized to create a client decision'
          USING ERRCODE = 'insufficient_privilege';
      END IF;
      IF NEW.status NOT IN ('draft', 'pending') THEN
        RAISE EXCEPTION 'client decision inserts must start draft or pending'
          USING ERRCODE = 'check_violation';
      END IF;
      IF NEW.status = 'draft' AND NEW.sent_at IS NOT NULL THEN
        RAISE EXCEPTION 'draft client decisions cannot be pre-published'
          USING ERRCODE = 'check_violation';
      END IF;
      IF NEW.decision_type = 'approval' AND NEW.linked_proposal_id IS NOT NULL THEN
        RAISE EXCEPTION
          'proposal approval decisions may only be inserted by signature authority'
          USING ERRCODE = 'check_violation';
      END IF;

      -- Installed extension/web bundles create pending rows directly and send
      -- browser timestamps. Preserve that birth shape while owning delivery
      -- and keeping client-view/reminder evidence empty until their real acts.
      IF NEW.status = 'pending' THEN
        NEW.sent_at := now();
      END IF;
      NEW.viewed_at := NULL;
      NEW.reminder_sent_at := NULL;
    END IF;

    RETURN NEW;
  END IF;

  -- Metadata-only installed-client PATCHes do not need to re-read the private
  -- designer_clients relationship. Revalidate the reference graph only when
  -- one of its inputs (or the lifecycle status used by the check) changes.
  IF NEW.designer_client_id IS DISTINCT FROM OLD.designer_client_id
     OR NEW.designer_id IS DISTINCT FROM OLD.designer_id
     OR NEW.project_id IS DISTINCT FROM OLD.project_id
     OR NEW.status IS DISTINCT FROM OLD.status
     OR NEW.phase_id IS DISTINCT FROM OLD.phase_id
     OR NEW.room_id IS DISTINCT FROM OLD.room_id
     OR NEW.blocks_milestone_id IS DISTINCT FROM OLD.blocks_milestone_id
     OR NEW.court_party_id IS DISTINCT FROM OLD.court_party_id
     OR NEW.linked_proposal_id IS DISTINCT FROM OLD.linked_proposal_id
     OR NEW.recommended_option_id IS DISTINCT FROM OLD.recommended_option_id
  THEN
    PERFORM public.assert_client_decision_reference_integrity(
      NEW.id,
      NEW.designer_client_id,
      NEW.designer_id,
      NEW.project_id,
      NEW.status,
      NEW.phase_id,
      NEW.room_id,
      NEW.blocks_milestone_id,
      NEW.court_party_id,
      NEW.linked_proposal_id,
      NEW.recommended_option_id
    );
  END IF;

  v_protected_change :=
       NEW.id IS DISTINCT FROM OLD.id
    OR NEW.designer_client_id IS DISTINCT FROM OLD.designer_client_id
    OR NEW.designer_id IS DISTINCT FROM OLD.designer_id
    OR NEW.project_id IS DISTINCT FROM OLD.project_id
    OR NEW.linked_proposal_id IS DISTINCT FROM OLD.linked_proposal_id
    OR NEW.title IS DISTINCT FROM OLD.title
    OR NEW.context IS DISTINCT FROM OLD.context
    OR NEW.due_date IS DISTINCT FROM OLD.due_date
    OR NEW.linked_phase IS DISTINCT FROM OLD.linked_phase
    OR NEW.phase_id IS DISTINCT FROM OLD.phase_id
    OR NEW.room_id IS DISTINCT FROM OLD.room_id
    OR NEW.section_key IS DISTINCT FROM OLD.section_key
    OR NEW.decision_type IS DISTINCT FROM OLD.decision_type
    OR NEW.decision_kind IS DISTINCT FROM OLD.decision_kind
    OR NEW.coordination_kind IS DISTINCT FROM OLD.coordination_kind
    OR NEW.blocking_status IS DISTINCT FROM OLD.blocking_status
    OR NEW.blocks_kind IS DISTINCT FROM OLD.blocks_kind
    OR NEW.blocks_milestone_id IS DISTINCT FROM OLD.blocks_milestone_id
    OR NEW.court IS DISTINCT FROM OLD.court
    OR NEW.court_party_id IS DISTINCT FROM OLD.court_party_id
    OR NEW.recommended_option_id IS DISTINCT FROM OLD.recommended_option_id
    OR NEW.status IS DISTINCT FROM OLD.status
    OR NEW.sent_at IS DISTINCT FROM OLD.sent_at
    OR NEW.responded_at IS DISTINCT FROM OLD.responded_at
    OR NEW.selected_by IS DISTINCT FROM OLD.selected_by
    OR NEW.answer IS DISTINCT FROM OLD.answer
    OR NEW.answered_at IS DISTINCT FROM OLD.answered_at
    OR NEW.answered_by IS DISTINCT FROM OLD.answered_by
    OR NEW.client_consent_method IS DISTINCT FROM OLD.client_consent_method
    OR NEW.client_consented_at IS DISTINCT FROM OLD.client_consented_at
    OR NEW.client_signature IS DISTINCT FROM OLD.client_signature
    OR NEW.created_at IS DISTINCT FROM OLD.created_at
    OR NEW.viewed_at IS DISTINCT FROM OLD.viewed_at
    OR NEW.reminder_sent_at IS DISTINCT FROM OLD.reminder_sent_at;

  v_actor_is_studio := current_user IS NOT DISTINCT FROM 'authenticated'
    AND public.is_design_studio_comember(OLD.designer_id);
  v_actor_is_client := current_user IS NOT DISTINCT FROM 'authenticated'
    AND public.is_addressed_client_decision(OLD.id);

  -- Deleting a recommended option applies its ON DELETE SET NULL action to
  -- the parent from inside PostgreSQL's FK trigger. The direct draft editor
  -- sets this decision-scoped capability in the option guard below (stable
  -- across its multi-row replacement DELETE); trigger depth distinguishes the
  -- FK action from a caller-authored parent PATCH.
  IF v_protected_change
     AND public.is_design_studio_comember(OLD.designer_id)
     AND OLD.status = 'draft'
     AND NEW.status = 'draft'
     AND NEW.recommended_option_id IS NULL
     AND OLD.recommended_option_id IS NOT NULL
     AND pg_trigger_depth() > 1
     AND current_setting(
           'app.client_decision_option_delete_decision_id', true
         ) IS NOT DISTINCT FROM OLD.id::text
     AND (
       to_jsonb(NEW) - ARRAY['recommended_option_id', 'updated_at']
     ) IS NOT DISTINCT FROM (
       to_jsonb(OLD) - ARRAY['recommended_option_id', 'updated_at']
     )
  THEN
    RETURN NEW;
  END IF;

  -- Rollback designer bundles edit authored draft payload directly. RLS
  -- scopes the row; this fail-closed shape comparison limits the writable
  -- columns to the historical editor contract.
  IF v_protected_change
     AND v_actor_is_studio
     AND OLD.status = 'draft'
     AND NEW.status = 'draft'
     AND (
       to_jsonb(NEW) - ARRAY[
         'title', 'context', 'due_date', 'linked_phase', 'decision_type',
         'blocking_status', 'project_id', 'coordination_kind', 'court',
         'court_party_id', 'blocks_kind', 'phase_id', 'updated_at'
       ]
     ) IS NOT DISTINCT FROM (
       to_jsonb(OLD) - ARRAY[
         'title', 'context', 'due_date', 'linked_phase', 'decision_type',
         'blocking_status', 'project_id', 'coordination_kind', 'court',
         'court_party_id', 'blocks_kind', 'phase_id', 'updated_at'
       ]
     )
  THEN
    IF NEW.decision_type = 'approval'
       AND NEW.linked_proposal_id IS NOT NULL
    THEN
      RAISE EXCEPTION
        'proposal approval decisions may only be authored by signature authority'
        USING ERRCODE = 'check_violation';
    END IF;
    RETURN NEW;
  END IF;

  -- The old publish mutation changed only status and sent_at. Stamp the
  -- authoritative delivery time at the database boundary.
  IF v_protected_change
     AND v_actor_is_studio
     AND OLD.status = 'draft'
     AND NEW.status = 'pending'
     AND (
       to_jsonb(NEW) - ARRAY['status', 'sent_at', 'updated_at']
     ) IS NOT DISTINCT FROM (
       to_jsonb(OLD) - ARRAY['status', 'sent_at', 'updated_at']
     )
  THEN
    -- The parent UPDATE already owns the decision row. Lock every existing
    -- child before making the sent-copy boundary visible, preserving the
    -- canonical parent -> children order. A concurrent direct option edit or
    -- delete therefore commits into the draft first or observes pending and
    -- rejects; it cannot mutate the sent copy afterward.
    PERFORM 1
    FROM public.client_decision_options AS option
    WHERE option.decision_id = OLD.id
    ORDER BY option.id
    FOR UPDATE;
    NEW.sent_at := now();
    RETURN NEW;
  END IF;

  -- Rollback coordination editors reassign the court or extend a still-open
  -- due date directly. These metadata-only changes cannot resolve/reopen a
  -- decision and reference integrity has already been checked above.
  IF v_protected_change
     AND v_actor_is_studio
     AND OLD.status = 'pending'
     AND NEW.status = 'pending'
     AND (
       to_jsonb(NEW) - ARRAY[
         'due_date', 'court', 'court_party_id', 'updated_at'
       ]
     ) IS NOT DISTINCT FROM (
       to_jsonb(OLD) - ARRAY[
         'due_date', 'court', 'court_party_id', 'updated_at'
       ]
     )
  THEN
    IF NEW.due_date IS DISTINCT FROM OLD.due_date
       AND NEW.due_date IS NOT NULL
       AND NEW.due_date <= now()
       AND NEW.due_date::date = current_date
    THEN
      -- Rollback date inputs submit bare YYYY-MM-DD values at midnight. Treat
      -- "today" as end-of-day so the default Extend act remains meaningful.
      NEW.due_date := (current_date + 1)::timestamptz
        - interval '1 microsecond';
    END IF;
    IF NEW.due_date IS DISTINCT FROM OLD.due_date
       AND (NEW.due_date IS NULL OR NEW.due_date <= now())
    THEN
      RAISE EXCEPTION 'an extended due date must be in the future'
        USING ERRCODE = 'check_violation';
    END IF;
    RETURN NEW;
  END IF;

  -- The rollback margin action extends an expired deadline and then reopens
  -- it in a second PATCH. Preserve that wire contract while making the reopen
  -- itself safe: require a future deadline and clear every prior response
  -- field/option selection in the status-transition transaction.
  IF v_protected_change
     AND v_actor_is_studio
     AND OLD.status = 'expired'
     AND NEW.status = 'expired'
     AND (
       to_jsonb(NEW) - ARRAY[
         'due_date', 'reminder_sent_at', 'updated_at'
       ]
     ) IS NOT DISTINCT FROM (
       to_jsonb(OLD) - ARRAY[
         'due_date', 'reminder_sent_at', 'updated_at'
       ]
     )
  THEN
    IF NEW.due_date IS DISTINCT FROM OLD.due_date
       AND NEW.due_date IS NOT NULL
       AND NEW.due_date <= now()
       AND NEW.due_date::date = current_date
    THEN
      NEW.due_date := (current_date + 1)::timestamptz
        - interval '1 microsecond';
    END IF;
    IF NEW.due_date IS DISTINCT FROM OLD.due_date
       AND (NEW.due_date IS NULL OR NEW.due_date <= now())
    THEN
      RAISE EXCEPTION 'an extended due date must be in the future'
        USING ERRCODE = 'check_violation';
    END IF;
    IF NEW.reminder_sent_at IS DISTINCT FROM OLD.reminder_sent_at THEN
      NEW.reminder_sent_at := now();
    END IF;
    RETURN NEW;
  END IF;

  IF v_protected_change
     AND v_actor_is_studio
     AND OLD.status = 'expired'
     AND NEW.status = 'pending'
     AND NEW.due_date IS NOT NULL
     AND NEW.due_date > now()
     AND (
       to_jsonb(NEW) - ARRAY['status', 'updated_at']
     ) IS NOT DISTINCT FROM (
       to_jsonb(OLD) - ARRAY['status', 'updated_at']
     )
  THEN
    v_previous_decision_capability := current_setting(
      'app.client_decision_write_id', true
    );
    v_previous_compat_reopen := current_setting(
      'app.client_decision_compat_reopen_id', true
    );
    PERFORM set_config('app.client_decision_write_id', OLD.id::text, true);
    PERFORM set_config(
      'app.client_decision_compat_reopen_id', OLD.id::text, true
    );
    UPDATE public.client_decision_options
    SET selected = false,
        client_note = NULL
    WHERE decision_id = OLD.id;
    PERFORM set_config(
      'app.client_decision_compat_reopen_id',
      COALESCE(v_previous_compat_reopen, ''), true
    );
    PERFORM set_config(
      'app.client_decision_write_id',
      COALESCE(v_previous_decision_capability, ''), true
    );

    NEW.responded_at := NULL;
    NEW.viewed_at := NULL;
    NEW.reminder_sent_at := NULL;
    NEW.selected_by := NULL;
    NEW.answer := NULL;
    NEW.answered_at := NULL;
    NEW.answered_by := NULL;
    NEW.client_consent_method := NULL;
    NEW.client_consented_at := NULL;
    NEW.client_signature := NULL;
    RETURN NEW;
  END IF;

  -- Legacy reminder bookkeeping is studio-owned metadata, never client-owned
  -- lifecycle truth. Normalize the caller timestamp to server time.
  IF v_protected_change
     AND v_actor_is_studio
     AND OLD.status = 'pending'
     AND NEW.status = 'pending'
     AND (
       to_jsonb(NEW) - ARRAY['reminder_sent_at', 'updated_at']
     ) IS NOT DISTINCT FROM (
       to_jsonb(OLD) - ARRAY['reminder_sent_at', 'updated_at']
     )
  THEN
    NEW.reminder_sent_at := now();
    RETURN NEW;
  END IF;

  -- Installed client builds mark a decision viewed with a direct PATCH.
  -- Permit only the first null->timestamp transition and own the timestamp.
  IF v_protected_change
     AND v_actor_is_client
     AND OLD.status IN ('pending', 'responded', 'expired')
     AND NEW.status = OLD.status
     AND (
       to_jsonb(NEW) - ARRAY['viewed_at', 'updated_at']
     ) IS NOT DISTINCT FROM (
       to_jsonb(OLD) - ARRAY['viewed_at', 'updated_at']
     )
  THEN
    NEW.viewed_at := COALESCE(OLD.viewed_at, now());
    RETURN NEW;
  END IF;

  -- Old web builds record consent immediately before apply_decision; installed
  -- iOS builds historically recorded it immediately after. Both are the
  -- addressed client's own evidence. Accept a one-time value in either state,
  -- require an electronic signature when that method is chosen, and replace
  -- the caller-supplied evidence time with server time.
  IF v_protected_change
     AND v_actor_is_client
     AND OLD.status IN ('pending', 'responded')
     AND NEW.status = OLD.status
     AND OLD.coordination_kind = 'selection'
     AND OLD.court = 'client'
     AND (
       OLD.status = 'pending'
       OR (
         OLD.selected_by IS NOT DISTINCT FROM auth.uid()
       )
     )
     AND (
       to_jsonb(NEW) - ARRAY[
         'client_consent_method', 'client_consented_at',
         'client_signature', 'updated_at'
       ]
     ) IS NOT DISTINCT FROM (
       to_jsonb(OLD) - ARRAY[
         'client_consent_method', 'client_consented_at',
         'client_signature', 'updated_at'
       ]
     )
  THEN
    IF NEW.client_consent_method IS NULL
       OR NEW.client_consent_method NOT IN (
         'electronic_signature', 'click_through'
       )
    THEN
      RAISE EXCEPTION 'invalid client consent method %',
        NEW.client_consent_method
        USING ERRCODE = 'check_violation';
    END IF;
    IF NEW.client_consent_method = 'electronic_signature' THEN
      IF btrim(COALESCE(NEW.client_signature, '')) = '' THEN
        RAISE EXCEPTION 'electronic consent requires a signature'
          USING ERRCODE = 'check_violation';
      END IF;
      IF OLD.status = 'pending'
         AND char_length(btrim(NEW.client_signature)) < 2
      THEN
        -- Pre-apply rollback web consent flows into the canonical core, whose
        -- signed-name contract is >=2. Installed iOS writes consent after the
        -- response and historically accepts any non-empty signature.
        RAISE EXCEPTION
          'an electronic signature of at least 2 characters is required before apply'
          USING ERRCODE = 'check_violation';
      END IF;
    END IF;
    NEW.client_signature := CASE
      WHEN NEW.client_consent_method = 'electronic_signature'
        THEN btrim(NEW.client_signature)
      ELSE NULL
    END;

    IF OLD.client_consent_method IS NULL
       AND OLD.client_consented_at IS NULL
       AND OLD.client_signature IS NULL
    THEN
      NEW.client_consented_at := now();
      RETURN NEW;
    END IF;

    IF NEW.client_consent_method IS NOT DISTINCT FROM OLD.client_consent_method
       AND NEW.client_signature IS NOT DISTINCT FROM OLD.client_signature
    THEN
      NEW.client_consented_at := OLD.client_consented_at;
      RETURN NEW;
    END IF;
  END IF;

  IF v_protected_change
     AND NOT v_maintenance
     AND (
       current_user IS DISTINCT FROM 'postgres'
       OR current_setting('app.client_decision_write_id', true)
          IS DISTINCT FROM NEW.id::text
     )
  THEN
    RAISE EXCEPTION
      'client decision business truth may only change through a canonical workflow'
      USING ERRCODE = 'check_violation';
  END IF;

  RETURN NEW;
END;
$$;
ALTER FUNCTION public.guard_client_decision_authority() RESET ALL;
ALTER FUNCTION public.guard_client_decision_authority() SET search_path = pg_catalog, public, pg_temp;
ALTER FUNCTION public.guard_client_decision_authority() OWNER TO postgres;

CREATE OR REPLACE FUNCTION public.guard_client_decision_option_authority()
RETURNS trigger
LANGUAGE plpgsql
SECURITY INVOKER
SET search_path = public, pg_temp
AS $$
DECLARE
  v_decision_id uuid := CASE WHEN TG_OP = 'DELETE' THEN OLD.decision_id
                             ELSE NEW.decision_id END;
  v_decision public.client_decisions%ROWTYPE;
  v_parent_locked boolean := false;
  v_maintenance boolean := current_user IS NOT DISTINCT FROM 'postgres'
    AND auth.uid() IS NULL
    AND COALESCE(auth.role(), '') NOT IN ('authenticated', 'service_role');
BEGIN
  IF TG_OP = 'INSERT'
     AND current_user IS NOT DISTINCT FROM 'authenticated'
  THEN
    -- New children have no row for a publisher/apply workflow to lock. Join
    -- the parent-first protocol explicitly so a concurrent apply completes
    -- first and this guard rechecks the resulting terminal status.
    v_parent_locked := public.lock_client_decision_option_parent(
      v_decision_id, 'studio_option_insert'
    );
    SELECT * INTO v_decision
    FROM public.client_decisions
    WHERE id = v_decision_id;
  ELSIF TG_OP = 'INSERT' AND current_user IS DISTINCT FROM 'postgres' THEN
    -- Preserve trusted non-browser callers while authenticated compatibility
    -- traffic uses the exact lock helper above.
    SELECT * INTO v_decision
    FROM public.client_decisions
    WHERE id = v_decision_id
    FOR UPDATE;
  ELSE
    SELECT * INTO v_decision
    FROM public.client_decisions
    WHERE id = v_decision_id;
  END IF;

  IF NOT FOUND THEN
    IF TG_OP = 'DELETE'
       AND pg_trigger_depth() > 1
       AND current_setting('app.client_decision_delete_cascade_id', true)
             IS NOT DISTINCT FROM v_decision_id::text
    THEN
      -- ON DELETE CASCADE removes options after the permitted parent draft
      -- delete has made the parent invisible. The parent guard minted this
      -- exact decision-scoped capability before the cascade began.
      RETURN OLD;
    END IF;
    RAISE EXCEPTION 'decision % not found for option write', v_decision_id
      USING ERRCODE = 'foreign_key_violation';
  END IF;

  IF v_maintenance THEN
    IF TG_OP = 'DELETE' THEN
      RETURN OLD;
    END IF;
    RETURN NEW;
  END IF;

  -- SECURITY DEFINER workflows and direct database maintenance execute as
  -- postgres even when a JWT claim remains set on the transaction. Their
  -- function bodies own option creation; end-user table inserts execute as
  -- authenticated and still take the exact-author branch below.
  IF TG_OP = 'INSERT' AND current_user IS NOT DISTINCT FROM 'postgres' THEN
    RETURN NEW;
  END IF;

  IF TG_OP = 'INSERT' AND current_user IS DISTINCT FROM 'postgres' THEN
    -- Direct extension/web births cannot backdate their audit record.
    NEW.created_at := now();

    IF NOT public.is_design_studio_comember(v_decision.designer_id)
       OR v_decision.status NOT IN ('draft', 'pending')
    THEN
      RAISE EXCEPTION 'not authorized to add an option to decision %', v_decision_id
        USING ERRCODE = 'insufficient_privilege';
    END IF;
    IF current_user IS NOT DISTINCT FROM 'authenticated'
       AND NOT v_parent_locked
    THEN
      RAISE EXCEPTION 'not authorized to add an option to decision %', v_decision_id
        USING ERRCODE = 'insufficient_privilege';
    END IF;
    IF COALESCE(NEW.selected, false) OR NEW.client_note IS NOT NULL THEN
      RAISE EXCEPTION 'new decision options cannot preload client selection truth'
        USING ERRCODE = 'check_violation';
    END IF;
    IF NEW.quantity IS NOT NULL AND NEW.quantity < 1 THEN
      RAISE EXCEPTION 'decision option quantity must be at least 1'
        USING ERRCODE = 'check_violation';
    END IF;
    IF v_decision.status = 'pending'
       AND (
         v_decision.decision_type IS DISTINCT FROM 'product'
         OR NEW.sort_order IS DISTINCT FROM 0
         OR NEW.is_recommended IS DISTINCT FROM true
         OR NEW.product_id IS NULL
         OR NEW.quantity IS DISTINCT FROM 1
         OR EXISTS (
           SELECT 1
           FROM public.client_decision_options AS existing_option
           WHERE existing_option.decision_id = v_decision_id
         )
       )
    THEN
      RAISE EXCEPTION
        'pending extension decisions accept only their one canonical captured-product option'
        USING ERRCODE = 'check_violation';
    END IF;
    RETURN NEW;
  END IF;

  IF TG_OP = 'UPDATE'
     AND current_user IS NOT DISTINCT FROM 'authenticated'
     AND v_decision.status = 'expired'
     AND public.is_design_studio_comember(v_decision.designer_id)
     AND current_setting('app.client_decision_write_id', true)
           IS NOT DISTINCT FROM v_decision_id::text
     AND current_setting('app.client_decision_compat_reopen_id', true)
           IS NOT DISTINCT FROM v_decision_id::text
     AND (
       to_jsonb(NEW) - ARRAY['selected', 'client_note']
     ) IS NOT DISTINCT FROM (
       to_jsonb(OLD) - ARRAY['selected', 'client_note']
     )
  THEN
    RETURN NEW;
  END IF;

  IF TG_OP = 'UPDATE'
     AND current_user IS NOT DISTINCT FROM 'authenticated'
     AND v_decision.status = 'draft'
     AND public.is_design_studio_comember(v_decision.designer_id)
     AND (
       to_jsonb(NEW) - ARRAY[
         'name', 'image_url', 'designer_note', 'is_recommended',
         'sort_order', 'price', 'quantity', 'cost_delta_cents',
         'lead_time_days_delta', 'product_id', 'approves'
       ]
     ) IS NOT DISTINCT FROM (
       to_jsonb(OLD) - ARRAY[
         'name', 'image_url', 'designer_note', 'is_recommended',
         'sort_order', 'price', 'quantity', 'cost_delta_cents',
         'lead_time_days_delta', 'product_id', 'approves'
       ]
     )
  THEN
    IF NEW.quantity IS NOT NULL AND NEW.quantity < 1 THEN
      RAISE EXCEPTION 'decision option quantity must be at least 1'
        USING ERRCODE = 'check_violation';
    END IF;
    RETURN NEW;
  END IF;

  IF TG_OP = 'DELETE'
     AND current_user IS NOT DISTINCT FROM 'authenticated'
     AND v_decision.status = 'draft'
     AND public.is_design_studio_comember(v_decision.designer_id)
  THEN
    PERFORM set_config(
      'app.client_decision_option_delete_decision_id',
      OLD.decision_id::text,
      true
    );
    RETURN OLD;
  END IF;

  -- Rollback client bundles persist note/quantity immediately before calling
  -- apply_decision. The row and columns are separately narrowed by RLS/ACL;
  -- the trigger also verifies the exact addressed client and write shape.
  IF TG_OP = 'UPDATE'
     AND current_user IS NOT DISTINCT FROM 'authenticated'
     AND v_decision.status = 'pending'
     AND v_decision.coordination_kind = 'selection'
     AND v_decision.court = 'client'
     AND public.is_addressed_client_decision(v_decision_id)
     AND (
       to_jsonb(NEW) - ARRAY['client_note', 'quantity']
     ) IS NOT DISTINCT FROM (
       to_jsonb(OLD) - ARRAY['client_note', 'quantity']
     )
  THEN
    IF NEW.quantity IS NOT NULL AND NEW.quantity < 1 THEN
      RAISE EXCEPTION 'decision option quantity must be at least 1'
        USING ERRCODE = 'check_violation';
    END IF;
    RETURN NEW;
  END IF;

  IF current_user IS DISTINCT FROM 'postgres'
     OR current_setting('app.client_decision_write_id', true)
        IS DISTINCT FROM v_decision_id::text
  THEN
    RAISE EXCEPTION
      'decision options may only change through a canonical decision workflow'
      USING ERRCODE = 'check_violation';
  END IF;

  IF TG_OP = 'UPDATE' AND NEW.decision_id IS DISTINCT FROM OLD.decision_id THEN
    RAISE EXCEPTION 'decision option ownership is immutable'
      USING ERRCODE = 'check_violation';
  END IF;

  IF TG_OP = 'DELETE' THEN
    RETURN OLD;
  END IF;
  RETURN NEW;
END;
$$;
ALTER FUNCTION public.guard_client_decision_option_authority() RESET ALL;
ALTER FUNCTION public.guard_client_decision_option_authority() SET search_path = pg_catalog, public, pg_temp;
ALTER FUNCTION public.guard_client_decision_option_authority() OWNER TO postgres;

CREATE OR REPLACE FUNCTION public.guard_decision_override_authority()
RETURNS trigger
LANGUAGE plpgsql
SECURITY INVOKER
SET search_path = public, pg_temp
AS $$
DECLARE
  v_decision public.client_decisions%ROWTYPE;
  v_parent_locked boolean := false;
BEGIN
  IF current_user IS DISTINCT FROM 'postgres' THEN
    -- Evidence is a child of the lifecycle row. Lock/recheck the parent first
    -- so it cannot become responded between validation and receipt insertion.
    IF current_user IS NOT DISTINCT FROM 'authenticated' THEN
      v_parent_locked := public.lock_client_decision_option_parent(
        NEW.decision_id, 'studio_override_insert'
      );
      SELECT * INTO v_decision
      FROM public.client_decisions
      WHERE id = NEW.decision_id;
    ELSE
      SELECT * INTO v_decision
      FROM public.client_decisions
      WHERE id = NEW.decision_id
      FOR UPDATE;
    END IF;

    IF NOT FOUND
       OR (
         current_user IS NOT DISTINCT FROM 'authenticated'
         AND NOT public.is_design_studio_comember(v_decision.designer_id)
       )
       OR (
         current_user IS NOT DISTINCT FROM 'authenticated'
         AND NEW.acted_by IS DISTINCT FROM auth.uid()
       )
    THEN
      RAISE EXCEPTION 'not authorized to record a decision override'
        USING ERRCODE = 'insufficient_privilege';
    END IF;
    IF v_decision.status <> 'pending' THEN
      RAISE EXCEPTION 'override evidence requires a pending decision'
        USING ERRCODE = 'check_violation';
    END IF;
    IF v_decision.coordination_kind IS DISTINCT FROM 'selection'
       OR v_decision.court IS DISTINCT FROM 'client'
    THEN
      RAISE EXCEPTION
        'override evidence requires a client-court selection decision'
        USING ERRCODE = 'check_violation';
    END IF;
    IF current_user IS NOT DISTINCT FROM 'authenticated'
       AND NOT v_parent_locked
    THEN
      RAISE EXCEPTION 'not authorized to record a decision override'
        USING ERRCODE = 'insufficient_privilege';
    END IF;
    IF NEW.option_id IS NULL
       OR NOT EXISTS (
         SELECT 1
         FROM public.client_decision_options AS option
         WHERE option.id = NEW.option_id
           AND option.decision_id = NEW.decision_id
       )
    THEN
      RAISE EXCEPTION 'override option must belong to its decision'
        USING ERRCODE = 'check_violation';
    END IF;
    IF NEW.consent_method NOT IN (
         'verbal', 'written', 'text_excerpt', 'email_excerpt'
       )
       OR btrim(COALESCE(NEW.consent_evidence, '')) = ''
    THEN
      RAISE EXCEPTION 'valid override consent evidence is required'
        USING ERRCODE = 'check_violation';
    END IF;
    NEW.consent_evidence := btrim(NEW.consent_evidence);
    NEW.created_at := now();
  END IF;
  RETURN NEW;
END;
$$;
ALTER FUNCTION public.guard_decision_override_authority() RESET ALL;
ALTER FUNCTION public.guard_decision_override_authority() SET search_path = pg_catalog, public, pg_temp;
ALTER FUNCTION public.guard_decision_override_authority() OWNER TO postgres;

CREATE OR REPLACE FUNCTION public.guard_document_share_board_payload()
RETURNS trigger
LANGUAGE plpgsql
SET search_path = public, pg_temp
AS $$
DECLARE
  v_expected_payload jsonb;
  v_expected_capability text;
BEGIN
  IF TG_OP = 'UPDATE' THEN
    IF NEW.board_id IS DISTINCT FROM OLD.board_id
       OR NEW.board_payload IS DISTINCT FROM OLD.board_payload
       OR NEW.board_payload_hash IS DISTINCT FROM OLD.board_payload_hash
       OR (
         OLD.board_id IS NOT NULL
         AND NEW.token_hash IS DISTINCT FROM OLD.token_hash
       )
    THEN
      RAISE EXCEPTION 'board share editions are immutable'
        USING ERRCODE = 'object_not_in_prerequisite_state';
    END IF;
    RETURN NEW;
  END IF;

  -- Generic document shares retain their existing writers. Only board shares
  -- are an edition-minting authority and therefore require this ceremony.
  IF NEW.board_id IS NULL THEN
    RETURN NEW;
  END IF;

  IF current_user = 'postgres'
     AND session_user = 'postgres'
     AND COALESCE(current_setting('role', true), 'none') = 'none'
  THEN
    RETURN NEW;
  END IF;

  v_expected_capability := format(
    'board_share:%s:%s', NEW.id, pg_catalog.txid_current()
  );
  v_expected_payload := public.build_board_share_payload(
    NEW.board_id, NEW.id, NEW.label, NEW.expires_at
  );
  IF current_user IS DISTINCT FROM 'postgres'
     OR auth.uid() IS NULL
     OR NEW.created_by IS DISTINCT FROM auth.uid()
     OR current_setting('app.board_share_capability', true)
          IS DISTINCT FROM v_expected_capability
     OR v_expected_payload IS NULL
     OR NEW.board_payload IS DISTINCT FROM v_expected_payload
     OR NEW.board_payload_hash IS DISTINCT FROM encode(
       extensions.digest(convert_to(v_expected_payload::text, 'UTF8'), 'sha256'),
       'hex'
     )
     OR NEW.proposal_id IS NOT NULL
     OR NEW.spec_book_artifact_id IS NOT NULL
     OR NEW.status IS DISTINCT FROM 'active'
     OR NOT EXISTS (
       SELECT 1
       FROM public.proposal_boards AS board
       LEFT JOIN public.proposals AS proposal ON proposal.id = board.proposal_id
       LEFT JOIN public.projects AS project ON project.id = board.project_id
       WHERE board.id = NEW.board_id
         AND board.status = 'active'
         AND public.board_media_projection_is_allowed(board.id)
         AND (
           (board.proposal_id IS NOT NULL
             AND public.is_design_studio_comember(proposal.designer_id))
           OR (board.project_id IS NOT NULL
             AND public.is_design_studio_comember(project.designer_id))
         )
     )
  THEN
    RAISE EXCEPTION 'board shares are inserted only by the canonical edition mint'
      USING ERRCODE = 'insufficient_privilege';
  END IF;
  RETURN NEW;
END;
$$;
ALTER FUNCTION public.guard_document_share_board_payload() RESET ALL;
ALTER FUNCTION public.guard_document_share_board_payload() SET search_path = pg_catalog, public, pg_temp;
ALTER FUNCTION public.guard_document_share_board_payload() OWNER TO postgres;

CREATE OR REPLACE FUNCTION public.guard_project_approval_evidence_edge()
RETURNS trigger
LANGUAGE plpgsql
SET search_path = public, pg_temp
AS $$
DECLARE
  v_decision public.client_decisions%ROWTYPE;
  v_authority public.project_decision_authorities%ROWTYPE;
  v_snapshot public.project_decision_authority_snapshots%ROWTYPE;
  v_artifact public.project_approval_artifacts%ROWTYPE;
  v_source record;
  v_decision_id uuid := CASE WHEN TG_OP = 'DELETE' THEN OLD.decision_id
                             ELSE NEW.decision_id END;
BEGIN
  IF TG_OP IN ('UPDATE', 'DELETE') THEN
    RAISE EXCEPTION 'project approval evidence is immutable'
      USING ERRCODE = 'check_violation';
  END IF;
  IF current_user IS DISTINCT FROM 'postgres'
     OR current_setting(
       'app.project_approval_evidence_decision_id', true
     ) IS DISTINCT FROM NEW.decision_id::text
  THEN
    RAISE EXCEPTION 'project approval evidence requires canonical authority'
      USING ERRCODE = 'insufficient_privilege';
  END IF;

  SELECT * INTO v_decision
  FROM public.client_decisions AS decision
  WHERE decision.id = v_decision_id
    AND decision.approval_contract = 'project_artifact_v1';
  IF NOT FOUND OR NEW.project_id IS DISTINCT FROM v_decision.project_id THEN
    RAISE EXCEPTION 'approval evidence parent is not coherent'
      USING ERRCODE = 'check_violation';
  END IF;

  IF TG_TABLE_NAME = 'project_decision_authority_snapshots' THEN
    IF auth.uid() IS NULL
       OR NOT public.is_design_studio_comember(v_decision.designer_id)
    THEN
      RAISE EXCEPTION 'authority snapshot requires the authenticated studio writer'
        USING ERRCODE = 'insufficient_privilege';
    END IF;
    SELECT * INTO v_authority
    FROM public.project_decision_authorities AS authority
    WHERE authority.project_id = v_decision.project_id;
    IF NOT FOUND
       OR NEW.decision_lead_id IS DISTINCT FROM v_authority.decision_lead_id
       OR NEW.required_coapprover_id
            IS DISTINCT FROM v_authority.required_coapprover_id
       OR NEW.authority_revision IS DISTINCT FROM v_authority.revision
       OR NEW.assigned_by IS DISTINCT FROM v_authority.assigned_by
    THEN
      RAISE EXCEPTION 'authority snapshot does not match the locked assignment'
        USING ERRCODE = 'check_violation';
    END IF;
    NEW.snapshotted_at := now();
    RETURN NEW;
  ELSIF TG_TABLE_NAME = 'project_approval_artifacts' THEN
    IF auth.uid() IS NULL
       OR NOT public.is_design_studio_comember(v_decision.designer_id)
       OR NEW.context IS DISTINCT FROM v_decision.context
       OR NEW.due_at IS DISTINCT FROM v_decision.due_date
       OR NEW.phase_id IS DISTINCT FROM v_decision.phase_id
       OR (
         SELECT count(*)
         FROM public.client_decision_options AS option
         WHERE option.decision_id = v_decision.id
           AND option.approval_outcome IS NOT NULL
       ) <> 3
       OR EXISTS (
         SELECT 1
         FROM public.client_decision_options AS option
         WHERE option.decision_id = v_decision.id
           AND (
             option.cost_cents_delta IS DISTINCT FROM NEW.cost_cents_delta
             OR option.schedule_days_delta
                  IS DISTINCT FROM NEW.schedule_days_delta
             OR option.lead_time_days_delta
                  IS DISTINCT FROM NEW.lead_time_days_delta
           )
       )
    THEN
      RAISE EXCEPTION 'artifact question, due date, phase, or impacts are incoherent'
        USING ERRCODE = 'check_violation';
    END IF;

    SELECT * INTO v_source
    FROM public._resolve_project_approval_artifact(
      NEW.project_id, NEW.source_kind, NEW.source_id
    );
    IF NOT FOUND
       OR NEW.source_version IS DISTINCT FROM v_source.source_version
       OR NEW.artifact_hash IS DISTINCT FROM v_source.artifact_hash
       OR NEW.artifact_title IS DISTINCT FROM v_source.artifact_title
       OR NEW.source_snapshot IS DISTINCT FROM v_source.safe_snapshot
    THEN
      RAISE EXCEPTION 'artifact evidence does not match its immutable source'
        USING ERRCODE = 'check_violation';
    END IF;
    NEW.created_at := now();
    RETURN NEW;
  ELSIF TG_TABLE_NAME = 'project_decision_review_confirmations' THEN
    SELECT * INTO v_snapshot
    FROM public.project_decision_authority_snapshots AS snapshot
    WHERE snapshot.decision_id = NEW.decision_id;
    SELECT * INTO v_artifact
    FROM public.project_approval_artifacts AS artifact
    WHERE artifact.decision_id = NEW.decision_id;
    IF auth.uid() IS NULL
       OR NEW.approver_id IS DISTINCT FROM auth.uid()
       OR v_snapshot.id IS NULL
       OR v_artifact.id IS NULL
       OR NEW.authority_revision IS DISTINCT FROM v_snapshot.authority_revision
       OR NEW.artifact_hash IS DISTINCT FROM v_artifact.artifact_hash
       OR NEW.review_method <> 'portal_clickthrough'
       OR NOT (
         (
           NEW.approver_role = 'lead'
           AND NEW.approver_id IS NOT DISTINCT FROM v_snapshot.decision_lead_id
         )
         OR (
           NEW.approver_role = 'coapprover'
           AND v_snapshot.required_coapprover_id IS NOT NULL
           AND NEW.approver_id
                 IS NOT DISTINCT FROM v_snapshot.required_coapprover_id
         )
       )
    THEN
      RAISE EXCEPTION 'review confirmation does not match frozen authority/artifact'
        USING ERRCODE = 'check_violation';
    END IF;
    NEW.confirmed_at := now();
    RETURN NEW;
  ELSIF TG_TABLE_NAME = 'project_approval_action_receipts' THEN
    IF NEW.actor_id IS DISTINCT FROM auth.uid()
       OR NEW.request_hash !~ '^[0-9a-f]{64}$'
       OR jsonb_typeof(NEW.result) <> 'object'
       OR (
         NEW.successor_decision_id IS NOT NULL
         AND NOT EXISTS (
           SELECT 1 FROM public.client_decisions AS successor
           WHERE successor.id = NEW.successor_decision_id
             AND successor.project_id = NEW.project_id
             AND successor.predecessor_decision_id = NEW.decision_id
             AND successor.approval_contract = 'project_artifact_v1'
         )
       )
    THEN
      RAISE EXCEPTION 'approval action receipt is not coherent'
        USING ERRCODE = 'check_violation';
    END IF;
    NEW.created_at := now();
    RETURN NEW;
  END IF;

  RAISE EXCEPTION 'unsupported project approval evidence table %', TG_TABLE_NAME
    USING ERRCODE = 'check_violation';
END;
$$;
ALTER FUNCTION public.guard_project_approval_evidence_edge() RESET ALL;
ALTER FUNCTION public.guard_project_approval_evidence_edge() SET search_path = pg_catalog, public, pg_temp;
ALTER FUNCTION public.guard_project_approval_evidence_edge() OWNER TO postgres;

CREATE OR REPLACE FUNCTION public.guard_project_decision_authority_edge()
RETURNS trigger
LANGUAGE plpgsql
SET search_path = public, pg_temp
AS $$
DECLARE
  v_project public.projects%ROWTYPE;
  v_capability text := current_setting(
    'app.project_decision_authority_project_id', true
  );
BEGIN
  IF TG_OP = 'DELETE' THEN
    RAISE EXCEPTION 'project decision authority assignments cannot be deleted'
      USING ERRCODE = 'check_violation';
  END IF;
  IF current_user IS DISTINCT FROM 'postgres'
     OR v_capability IS DISTINCT FROM NEW.project_id::text
  THEN
    RAISE EXCEPTION 'project decision authority changes require the checked RPC'
      USING ERRCODE = 'insufficient_privilege';
  END IF;

  SELECT * INTO v_project
  FROM public.projects WHERE id = NEW.project_id;
  IF NOT FOUND
     OR auth.uid() IS NULL
     OR NOT public.is_design_studio_comember(v_project.designer_id)
     OR v_project.client_id IS NULL
     OR NEW.decision_lead_id IS DISTINCT FROM v_project.client_id
     OR NEW.required_coapprover_id IS NOT NULL
     OR NEW.assigned_by IS DISTINCT FROM auth.uid()
  THEN
    RAISE EXCEPTION 'project decision authority identity is not coherent'
      USING ERRCODE = 'check_violation';
  END IF;

  IF TG_OP = 'INSERT' THEN
    IF NEW.revision <> 1 THEN
      RAISE EXCEPTION 'first authority revision must be 1'
        USING ERRCODE = 'check_violation';
    END IF;
    NEW.assigned_at := now();
    NEW.updated_at := NEW.assigned_at;
    RETURN NEW;
  END IF;

  IF NEW.project_id IS DISTINCT FROM OLD.project_id
     OR NEW.revision IS DISTINCT FROM OLD.revision + 1
     OR NEW.assigned_at IS DISTINCT FROM OLD.assigned_at
  THEN
    RAISE EXCEPTION 'authority updates must advance one immutable project revision'
      USING ERRCODE = 'check_violation';
  END IF;
  NEW.updated_at := now();
  RETURN NEW;
END;
$$;
ALTER FUNCTION public.guard_project_decision_authority_edge() RESET ALL;
ALTER FUNCTION public.guard_project_decision_authority_edge() SET search_path = pg_catalog, public, pg_temp;
ALTER FUNCTION public.guard_project_decision_authority_edge() OWNER TO postgres;

CREATE OR REPLACE FUNCTION public.guard_project_ffe_configuration_integrity()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, pg_temp
AS $$
DECLARE
  v_spec public.project_ffe_specs;
  v_configuration public.product_configurations;
  v_project public.projects;
  v_mode text;
  v_expected_unit integer;
  v_expected_trade integer;
  v_snapshot_retail integer;
  v_snapshot_trade integer;
  v_sku text;
  v_material text;
  v_finish text;
  v_locked_instrument text;
BEGIN
  SELECT * INTO v_spec
  FROM public.project_ffe_specs WHERE ffe_item_id = OLD.id FOR UPDATE;
  IF NOT FOUND OR v_spec.configuration_id IS NULL THEN
    RETURN NEW;
  END IF;
  IF v_spec.configuration_locked_at IS NOT NULL AND (
    NEW.project_id IS DISTINCT FROM OLD.project_id
    OR NEW.product_id IS DISTINCT FROM OLD.product_id
    OR NEW.quantity IS DISTINCT FROM OLD.quantity
    OR NEW.unit_price_cents IS DISTINCT FROM OLD.unit_price_cents
    OR NEW.trade_price_cents IS DISTINCT FROM OLD.trade_price_cents
    OR NEW.line_total_cents IS DISTINCT FROM OLD.line_total_cents
  ) THEN
    RAISE EXCEPTION 'configuration-derived project line fields are locked; create a configuration revision'
      USING errcode = 'object_not_in_prerequisite_state';
  END IF;
  -- 00422: the authorization-execution link. See the header above.
  --
  -- Two conjuncts carry the whole gate, and both are NULL-hostile on purpose.
  -- app.commercial_document_id is set only inside the canonical SECURITY
  -- DEFINER rails (_execute_furnishings_authorization_authorized, void, send)
  -- and restored to '' on the way out; no PostgREST path can set it. An unset
  -- GUC reads NULL and an exhausted one reads '', so NULLIF(...) IS NOT NULL
  -- is what separates "inside the execution rail" from "an ordinary UPDATE" —
  -- an IS NOT DISTINCT FROM comparison would have matched NULL against the
  -- NULL a missing document yields, and waved every stamp through.
  IF NEW.source_commercial_document_id IS NOT NULL
     AND NEW.source_authorization_item_id IS NOT NULL
     AND OLD.source_authorization_item_id IS NULL
     AND NULLIF(current_setting('app.commercial_document_id', true), '') IS NOT NULL
     AND NULLIF(current_setting('app.commercial_document_id', true), '') = (
       SELECT d.proposal_id::text FROM public.project_commercial_documents d
       WHERE d.id = NEW.source_commercial_document_id
     )
  THEN
    RETURN NEW;
  END IF;
  IF NOT (OLD.status IS DISTINCT FROM NEW.status AND NEW.status = 'approved') THEN
    RETURN NEW;
  END IF;
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'authentication required to approve a configured project line'
      USING errcode = 'insufficient_privilege';
  END IF;
  SELECT * INTO v_project FROM public.projects WHERE id = NEW.project_id FOR SHARE;
  IF NOT FOUND OR NOT public.is_design_studio_comember(v_project.designer_id) THEN
    RAISE EXCEPTION 'project not found or not accessible' USING errcode = 'insufficient_privilege';
  END IF;
  IF NOT public._can_access_product_configuration(v_spec.configuration_id) THEN
    RAISE EXCEPTION 'configuration not found or not accessible' USING errcode = 'insufficient_privilege';
  END IF;
  SELECT c.*
  INTO v_configuration
  FROM public.product_configurations c
  WHERE c.id = v_spec.configuration_id
  FOR UPDATE OF c;
  SELECT configuration_mode INTO v_mode
  FROM public.products WHERE id = v_configuration.product_id;
  IF v_configuration.product_id IS DISTINCT FROM NEW.product_id
     OR (v_configuration.project_id IS NOT NULL AND v_configuration.project_id <> NEW.project_id)
     OR (v_configuration.ffe_item_id IS NOT NULL AND v_configuration.ffe_item_id <> NEW.id) THEN
    RAISE EXCEPTION 'configuration, project, product, and FF&E line do not agree'
      USING errcode = 'check_violation';
  END IF;
  IF NOT v_configuration.is_valid OR NOT v_configuration.is_complete THEN
    RAISE EXCEPTION 'configuration must be valid and complete before project approval'
      USING errcode = 'object_not_in_prerequisite_state';
  END IF;
  IF v_spec.configuration_snapshot IS DISTINCT FROM v_configuration.snapshot
     OR v_spec.configuration_snapshot_hash IS DISTINCT FROM v_configuration.snapshot_hash
     OR v_configuration.snapshot_hash IS DISTINCT FROM public._configuration_snapshot_hash(v_configuration.snapshot) THEN
    RAISE EXCEPTION 'configuration snapshot or hash does not match its approved source'
      USING errcode = 'object_not_in_prerequisite_state';
  END IF;
  v_snapshot_retail := NULLIF(v_configuration.snapshot->>'retailPriceCents', '')::integer;
  v_snapshot_trade := NULLIF(v_configuration.snapshot->>'tradePriceCents', '')::integer;
  IF v_snapshot_retail IS DISTINCT FROM v_configuration.retail_price_cents
     OR v_snapshot_trade IS DISTINCT FROM v_configuration.trade_price_cents THEN
    RAISE EXCEPTION 'configuration commercial columns diverge from the immutable snapshot'
      USING errcode = 'object_not_in_prerequisite_state';
  END IF;
  IF v_mode = 'custom' THEN
    IF v_configuration.status NOT IN ('approved', 'issued') THEN
      RAISE EXCEPTION 'custom commission must complete its approval workflow first'
        USING errcode = 'object_not_in_prerequisite_state';
    END IF;
  ELSIF v_configuration.status = 'saved' THEN
    UPDATE public.product_configurations
    SET status = 'approved', approved_by = auth.uid(), approved_at = now(), updated_at = now()
    WHERE id = v_configuration.id;
  ELSIF v_configuration.status NOT IN ('approved', 'issued') THEN
    RAISE EXCEPTION 'configuration cannot be approved from status %', v_configuration.status
      USING errcode = 'object_not_in_prerequisite_state';
  END IF;

  -- 00422: this branch is about to REWRITE the line's money from the
  -- configuration snapshot. aac_guard_ffe_schedule_soft_lock fires before this
  -- trigger, compared OLD against NEW, found the money unchanged and returned —
  -- so without this check a status→approved on a configured line would move the
  -- price of a line a client is looking at, and the refusal the studio was
  -- promised would never appear. Same predicate, same sentence as the soft lock.
  SELECT d.wave_name INTO v_locked_instrument
  FROM public.furnishing_authorization_items a
  JOIN public.project_commercial_documents d ON d.id = a.commercial_document_id
  JOIN public.proposals p ON p.id = d.proposal_id
  WHERE a.source_ffe_item_id = OLD.id
    AND p.commercial_state = 'sent'
  ORDER BY d.bound_at, d.id
  LIMIT 1;
  IF v_locked_instrument IS NOT NULL THEN
    RAISE EXCEPTION 'schedule line quantity or price is locked while it sits on sent authorization "%"; void the authorization to edit', v_locked_instrument
      USING ERRCODE = 'check_violation';
  END IF;

  v_expected_unit := COALESCE(v_snapshot_retail, v_snapshot_trade);
  v_expected_trade := COALESCE(v_snapshot_trade, v_snapshot_retail);
  NEW.unit_price_cents := v_expected_unit;
  NEW.trade_price_cents := v_expected_trade;
  NEW.line_total_cents := CASE WHEN v_expected_unit IS NULL THEN NULL
    ELSE NEW.quantity * v_expected_unit END;
  v_sku := COALESCE(NULLIF(v_configuration.snapshot#>>'{variant,vendorSku}', ''),
    NULLIF(v_configuration.snapshot#>>'{variant,sku}', ''));
  SELECT string_agg(selection->>'valueLabel', ', ' ORDER BY ordinality)
  INTO v_material
  FROM jsonb_array_elements(COALESCE(v_configuration.snapshot->'selections', '[]'::jsonb))
       WITH ORDINALITY AS chosen(selection, ordinality)
  WHERE lower(selection->>'groupCode') = 'material';
  SELECT string_agg(selection->>'valueLabel', ', ' ORDER BY ordinality)
  INTO v_finish
  FROM jsonb_array_elements(COALESCE(v_configuration.snapshot->'selections', '[]'::jsonb))
       WITH ORDINALITY AS chosen(selection, ordinality)
  WHERE lower(selection->>'groupCode') = 'finish';
  PERFORM set_config('patina.configuration_spec_workflow', '00403', true);
  UPDATE public.project_ffe_specs
  SET configuration_locked_at = COALESCE(configuration_locked_at, now()),
      selected_dimensions = v_configuration.resolved_dimensions,
      sku = COALESCE(v_sku, sku),
      material = COALESCE(v_material, material),
      finish = COALESCE(v_finish, finish),
      color_fabric = COALESCE(NULLIF(public._configuration_com_color_fabric(
        COALESCE(v_configuration.com_details, v_configuration.snapshot->'comDetails')), ''), color_fabric),
      updated_by = auth.uid(), updated_at = now()
  WHERE id = v_spec.id;
  PERFORM set_config('patina.configuration_spec_workflow', '', true);
  RETURN NEW;
END;
$$;
ALTER FUNCTION public.guard_project_ffe_configuration_integrity() RESET ALL;
ALTER FUNCTION public.guard_project_ffe_configuration_integrity() SET search_path = pg_catalog, public, pg_temp;
ALTER FUNCTION public.guard_project_ffe_configuration_integrity() OWNER TO postgres;

CREATE OR REPLACE FUNCTION public.guard_stage2_client_decision_edge()
RETURNS trigger
LANGUAGE plpgsql
SET search_path = public, pg_temp
AS $$
DECLARE
  v_is_old_stage2 boolean := CASE
    WHEN TG_OP IN ('UPDATE', 'DELETE')
      THEN OLD.approval_contract IS NOT DISTINCT FROM 'project_artifact_v1'
    ELSE false
  END;
  v_is_new_stage2 boolean := CASE
    WHEN TG_OP IN ('INSERT', 'UPDATE')
      THEN NEW.approval_contract IS NOT DISTINCT FROM 'project_artifact_v1'
    ELSE false
  END;
BEGIN
  IF TG_OP = 'DELETE' THEN
    IF v_is_old_stage2 THEN
      RAISE EXCEPTION 'Stage-2 project approval decisions are immutable evidence'
        USING ERRCODE = 'check_violation';
    END IF;
    RETURN OLD;
  END IF;

  IF TG_OP = 'INSERT' THEN
    IF NOT v_is_new_stage2 THEN
      IF NEW.predecessor_decision_id IS NOT NULL THEN
        RAISE EXCEPTION 'legacy decisions cannot carry Stage-2 lineage'
          USING ERRCODE = 'check_violation';
      END IF;
      RETURN NEW;
    END IF;

    IF current_user IS DISTINCT FROM 'postgres'
       OR current_setting(
            'app.project_approval_decision_insert_id', true
          ) IS DISTINCT FROM NEW.id::text
    THEN
      RAISE EXCEPTION 'Stage-2 decisions are inserted only by canonical authority'
        USING ERRCODE = 'insufficient_privilege';
    END IF;
    IF NEW.status <> 'draft'
       OR NEW.project_id IS NULL
       OR NEW.linked_proposal_id IS NOT NULL
       OR NEW.recommended_option_id IS NOT NULL
       OR NEW.sent_at IS NOT NULL
       OR NEW.responded_at IS NOT NULL
       OR NEW.selected_by IS NOT NULL
       OR NEW.client_consent_method IS NOT NULL
       OR NEW.client_consented_at IS NOT NULL
       OR NEW.client_signature IS NOT NULL
       OR NEW.answer IS NOT NULL
       OR NEW.answered_at IS NOT NULL
       OR NEW.answered_by IS NOT NULL
    THEN
      RAISE EXCEPTION 'new Stage-2 decisions must be unevidenced drafts'
        USING ERRCODE = 'check_violation';
    END IF;
    IF auth.uid() IS NULL
       OR NOT EXISTS (
         SELECT 1
         FROM public.projects AS project
         JOIN public.project_phases AS phase
           ON phase.id = NEW.phase_id
          AND phase.project_id = project.id
         JOIN public.designer_clients AS relationship
           ON relationship.id = NEW.designer_client_id
          AND relationship.designer_id = project.designer_id
          AND relationship.client_id = project.client_id
          AND relationship.status = 'active'
         WHERE project.id = NEW.project_id
           AND NEW.designer_id = project.designer_id
           AND public.is_design_studio_comember(project.designer_id)
       )
    THEN
      RAISE EXCEPTION 'Stage-2 project, phase, actor, and relationship are not coherent'
        USING ERRCODE = 'check_violation';
    END IF;
    IF NEW.predecessor_decision_id IS NOT NULL
       AND NOT EXISTS (
         SELECT 1 FROM public.client_decisions AS predecessor
         WHERE predecessor.id = NEW.predecessor_decision_id
           AND predecessor.project_id = NEW.project_id
           AND predecessor.approval_contract = 'project_artifact_v1'
       )
    THEN
      RAISE EXCEPTION 'Stage-2 predecessor must belong to the same project'
        USING ERRCODE = 'check_violation';
    END IF;
    RETURN NEW;
  END IF;

  IF v_is_old_stage2 OR v_is_new_stage2 THEN
    IF NOT (v_is_old_stage2 AND v_is_new_stage2)
       OR current_user IS DISTINCT FROM 'postgres'
       OR current_setting(
            'app.project_approval_decision_write_id', true
          ) IS DISTINCT FROM NEW.id::text
    THEN
      RAISE EXCEPTION 'Stage-2 decision changes require the Stage-2 lifecycle rail'
        USING ERRCODE = 'insufficient_privilege';
    END IF;
    IF (
      to_jsonb(NEW) - ARRAY[
        'status', 'sent_at', 'responded_at', 'selected_by',
        'client_consent_method', 'client_consented_at', 'client_signature',
        'answer', 'answered_at', 'answered_by', 'viewed_at',
        'reminder_sent_at', 'updated_at'
      ]
    ) IS DISTINCT FROM (
      to_jsonb(OLD) - ARRAY[
        'status', 'sent_at', 'responded_at', 'selected_by',
        'client_consent_method', 'client_consented_at', 'client_signature',
        'answer', 'answered_at', 'answered_by', 'viewed_at',
        'reminder_sent_at', 'updated_at'
      ]
    ) THEN
      RAISE EXCEPTION 'Stage-2 request identity and frozen question are immutable'
        USING ERRCODE = 'check_violation';
    END IF;
  ELSIF NEW.approval_contract IS NOT NULL
        OR NEW.predecessor_decision_id IS NOT NULL
  THEN
    RAISE EXCEPTION 'legacy decisions cannot be reclassified as Stage-2'
      USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END;
$$;
ALTER FUNCTION public.guard_stage2_client_decision_edge() RESET ALL;
ALTER FUNCTION public.guard_stage2_client_decision_edge() SET search_path = pg_catalog, public, pg_temp;
ALTER FUNCTION public.guard_stage2_client_decision_edge() OWNER TO postgres;

CREATE OR REPLACE FUNCTION public.hold_install_window(
  p_project_id uuid,
  p_starts_on  date,
  p_ends_on    date
)
RETURNS uuid
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, pg_temp
AS $$
DECLARE
  v_actor  uuid := auth.uid();
  v_live   public.install_windows%ROWTYPE;
  v_id     uuid;
BEGIN
  IF v_actor IS NULL THEN
    RAISE EXCEPTION 'hold_install_window: no authenticated actor';
  END IF;

  IF NOT EXISTS (
    SELECT 1 FROM public.projects
    WHERE id = p_project_id AND public.is_studio_comember(designer_id)
  ) THEN
    RAISE EXCEPTION 'project % not found or not owned by caller', p_project_id;
  END IF;

  IF p_starts_on IS NULL OR p_ends_on IS NULL THEN
    RAISE EXCEPTION 'hold_install_window: a window needs both a start and an end';
  END IF;
  IF p_ends_on < p_starts_on THEN
    RAISE EXCEPTION 'hold_install_window: the window ends (%) before it starts (%)', p_ends_on, p_starts_on;
  END IF;

  -- The partial unique index is the real guard; this reads it back as a
  -- sentence naming the window that already stands.
  SELECT * INTO v_live FROM public.install_windows
   WHERE project_id = p_project_id AND state <> 'released'
   LIMIT 1;
  IF FOUND THEN
    RAISE EXCEPTION
      'an install window is already % on this project (% – %) — release it before holding another',
      v_live.state, v_live.starts_on, v_live.ends_on;
  END IF;

  -- No anchor write: a hold is not a commitment (R112).
  INSERT INTO public.install_windows (project_id, starts_on, ends_on, state, held_by)
  VALUES (p_project_id, p_starts_on, p_ends_on, 'held', v_actor)
  RETURNING id INTO v_id;

  RETURN v_id;
END;
$$;
ALTER FUNCTION public.hold_install_window(uuid,date,date) RESET ALL;
ALTER FUNCTION public.hold_install_window(uuid,date,date) SET search_path = pg_catalog, public, pg_temp;
ALTER FUNCTION public.hold_install_window(uuid,date,date) OWNER TO postgres;

CREATE OR REPLACE FUNCTION app_private.is_decision_comment_client(
  p_decision_id uuid
)
RETURNS boolean
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path = public, pg_temp
AS $$
  SELECT auth.uid() IS NOT NULL
    AND EXISTS (
      SELECT 1
      FROM public.client_decisions AS decision
      LEFT JOIN public.project_decision_authority_snapshots AS snapshot
        ON snapshot.decision_id = decision.id
       AND snapshot.project_id = decision.project_id
      LEFT JOIN public.designer_clients AS relationship
        ON relationship.id = decision.designer_client_id
      WHERE decision.id = p_decision_id
        AND (
          (
            decision.approval_contract = 'project_artifact_v1'
            AND (
              snapshot.decision_lead_id = auth.uid()
              OR public.is_design_studio_comember(decision.designer_id)
            )
          )
          OR (
            decision.approval_contract
                  IS DISTINCT FROM 'project_artifact_v1'
            AND (
              relationship.designer_id = auth.uid()
              OR relationship.client_id = auth.uid()
            )
          )
        )
    );
$$;
ALTER FUNCTION app_private.is_decision_comment_client(uuid) RESET ALL;
ALTER FUNCTION app_private.is_decision_comment_client(uuid) SET search_path = pg_catalog, public, pg_temp;
ALTER FUNCTION app_private.is_decision_comment_client(uuid) OWNER TO postgres;

CREATE OR REPLACE FUNCTION public.list_furnishings_authorizations(p_project_id uuid)
RETURNS jsonb
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path = public, pg_temp
AS $$
DECLARE v_project public.projects%ROWTYPE;
BEGIN
  SELECT * INTO v_project FROM public.projects WHERE id = p_project_id;
  IF NOT FOUND OR auth.uid() IS NULL OR NOT (
    v_project.client_id IS NOT DISTINCT FROM auth.uid()
    OR public.is_studio_comember(v_project.designer_id)
  ) THEN
    RAISE EXCEPTION 'project % not found or access denied', p_project_id
      USING ERRCODE = 'insufficient_privilege';
  END IF;
  RETURN COALESCE((
    SELECT jsonb_agg(jsonb_build_object(
      'documentId', d.id, 'proposalId', d.proposal_id, 'waveName', d.wave_name,
      'number', numbered.number, 'supersededByNumber', NULL::integer,
      'commercialState', p.commercial_state, 'status', p.status,
      'totalAmountCents', p.total_amount, 'depositPercent', p.deposit_percent,
      'depositInvoiceId', d.deposit_invoice_id, 'executedAt', d.executed_at,
      'proposalSendDispatchId', p.proposal_send_dispatch_id,
      'proposal_send_dispatch_id', p.proposal_send_dispatch_id,
      'sentAt', p.sent_at, 'sent_at', p.sent_at,
      'checkpointId', d.budget_checkpoint_id,
      'budgetCheckpointId', d.budget_checkpoint_id,
      'coveredRoomIds', COALESCE((SELECT jsonb_agg(DISTINCT l.project_room_id)
        FROM public.project_budget_checkpoints c
        JOIN public.project_budget_lines l ON l.budget_version_id = c.budget_version_id
        WHERE c.id = d.budget_checkpoint_id AND l.project_room_id IS NOT NULL),
        '[]'::jsonb),
      'depositPaid', COALESCE((SELECT i.status = 'paid'
          AND i.amount_paid_cents >= i.total_cents
        FROM public.invoices i WHERE i.id = d.deposit_invoice_id), false),
      'depositRequiredCents', COALESCE((SELECT i.total_cents
        FROM public.invoices i WHERE i.id = d.deposit_invoice_id),
        round(p.total_amount * p.deposit_percent / 100.0)::bigint),
      'deposit_required_cents', COALESCE((SELECT i.total_cents
        FROM public.invoices i WHERE i.id = d.deposit_invoice_id),
        round(p.total_amount * p.deposit_percent / 100.0)::bigint),
      'depositPaidCents', COALESCE((SELECT i.amount_paid_cents
        FROM public.invoices i WHERE i.id = d.deposit_invoice_id), 0),
      'deposit_paid_cents', COALESCE((SELECT i.amount_paid_cents
        FROM public.invoices i WHERE i.id = d.deposit_invoice_id), 0),
      'itemCount', (SELECT count(*) FROM public.furnishing_authorization_items a
        WHERE a.commercial_document_id = d.id),
      'items', (SELECT COALESCE(jsonb_agg(jsonb_build_object(
        'id', a.id, 'name', a.name, 'roomName', a.room_name, 'category', a.category,
        'itemType', a.item_type, 'quantity', a.quantity,
        'clientUnitPriceCents', a.client_unit_price_cents,
        'clientLineTotalCents', a.client_line_total_cents,
        'sourceFfeItemId', a.source_ffe_item_id,
        'projectRoomId', a.project_room_id, 'sortOrder', a.sort_order
      ) ORDER BY a.sort_order, a.id), '[]'::jsonb)
        FROM public.furnishing_authorization_items a WHERE a.commercial_document_id = d.id)
    ) ORDER BY d.bound_at, d.id)
    FROM public.project_commercial_documents d
    JOIN public.proposals p ON p.id = d.proposal_id
    JOIN (
      -- Numbering is over EVERY furnishing instrument on the project, voided
      -- ones included, so a client and a studio always mean the same "two".
      -- The key is (bound_at, id) — the same key this function orders its
      -- output by, so number and position can never disagree. project_
      -- commercial_documents has no created_at; bound_at is when the
      -- instrument became a thing on this project, which is the right clock.
      SELECT n.id, row_number() OVER (ORDER BY n.bound_at, n.id) AS number
      FROM public.project_commercial_documents n
      WHERE n.project_id = p_project_id
        AND n.document_kind = 'furnishings_authorization'
    ) numbered ON numbered.id = d.id
    WHERE d.project_id = p_project_id AND d.document_kind = 'furnishings_authorization'
      -- 00422: `<> 'draft'` alone let a VOID publish a never-sent instrument —
      -- void writes 'superseded', which passes that test. A terminal edition
      -- reaches the client only if it was actually issued (sent_at). The
      -- numbering above is deliberately outside this filter: an instrument the
      -- client cannot see still spends its number, so studio and client never
      -- disagree about which one is "release two".
      AND (
        public.is_studio_comember(v_project.designer_id)
        OR (
          COALESCE(p.commercial_state, 'draft') <> 'draft'
          AND (COALESCE(p.commercial_state, 'draft') NOT IN ('superseded', 'declined')
               OR p.sent_at IS NOT NULL)
        )
      )),
  '[]'::jsonb);
END;
$$;
ALTER FUNCTION public.list_furnishings_authorizations(uuid) RESET ALL;
ALTER FUNCTION public.list_furnishings_authorizations(uuid) SET search_path = pg_catalog, public, pg_temp;
ALTER FUNCTION public.list_furnishings_authorizations(uuid) OWNER TO postgres;

CREATE OR REPLACE FUNCTION public.list_my_project_decision_reviews()
RETURNS jsonb
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path = public, pg_temp
AS $$
DECLARE
  v_actor uuid := auth.uid();
  v_result jsonb;
BEGIN
  IF v_actor IS NULL THEN
    RETURN '[]'::jsonb;
  END IF;

  SELECT COALESCE(
    jsonb_agg(
      item.value
      ORDER BY item.value->>'createdAt', item.value->>'decisionId'
    ),
    '[]'::jsonb
  )
  INTO v_result
  FROM (
    SELECT DISTINCT decision.project_id
    FROM public.client_decisions AS decision
    LEFT JOIN public.project_decision_authority_snapshots AS snapshot
      ON snapshot.decision_id = decision.id
     AND snapshot.project_id = decision.project_id
    WHERE decision.approval_contract = 'project_artifact_v1'
      AND decision.project_id IS NOT NULL
      AND (
        snapshot.decision_lead_id = v_actor
        OR public.is_design_studio_comember(decision.designer_id)
      )
  ) AS authorized_project
  CROSS JOIN LATERAL jsonb_array_elements(
    public.get_project_decision_reviews(authorized_project.project_id)
  ) AS item(value);

  RETURN v_result;
END;
$$;
ALTER FUNCTION public.list_my_project_decision_reviews() RESET ALL;
ALTER FUNCTION public.list_my_project_decision_reviews() SET search_path = pg_catalog, public, pg_temp;
ALTER FUNCTION public.list_my_project_decision_reviews() OWNER TO postgres;

CREATE OR REPLACE FUNCTION public.list_trade_scopes(p_project_id uuid)
RETURNS jsonb
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path = public, pg_temp
AS $$
DECLARE v_project public.projects%ROWTYPE;
BEGIN
  SELECT * INTO v_project FROM public.projects WHERE id = p_project_id;
  IF NOT FOUND OR auth.uid() IS NULL
     OR NOT public.is_studio_comember(v_project.designer_id) THEN
    RAISE EXCEPTION 'project % not found or access denied', p_project_id
      USING ERRCODE = 'insufficient_privilege';
  END IF;
  RETURN COALESCE((
    SELECT jsonb_agg(jsonb_build_object(
      'proposalId', d.proposal_id,
      'documentId', d.id,
      'number', numbered.number,
      'title', p.title,
      'state', COALESCE(p.commercial_state, 'draft'),
      'status', p.status,
      'progressState', COALESCE(t.progress_state, 'none'),
      'partyId', t.party_id,
      'partyDisplayName', t.party_display_name,
      'partyCompanyName', t.party_company_name,
      'partyTrade', t.party_trade,
      'clientPriceCents', COALESCE(t.client_price_cents, 0),
      'currency', COALESCE(t.currency, 'USD'),
      'sentAt', p.sent_at,
      'executedAt', d.executed_at,
      'engagedAt', t.engaged_at,
      'substantialCompletionAt', t.substantial_completion_at,
      'acceptedAt', t.accepted_at,
      'depositInvoiceId', d.deposit_invoice_id,
      'depositPaid', COALESCE((SELECT i.status = 'paid'
          AND i.amount_paid_cents >= i.total_cents
        FROM public.invoices i WHERE i.id = d.deposit_invoice_id), false),
      'depositPaidCents', COALESCE((SELECT i.amount_paid_cents
        FROM public.invoices i WHERE i.id = d.deposit_invoice_id), 0),
      'sectionCount', (SELECT count(*) FROM public.trade_scope_sections s
        WHERE s.proposal_id = d.proposal_id),
      'sectionRoomIds', COALESCE((SELECT jsonb_agg(DISTINCT s.project_room_id)
        FROM public.trade_scope_sections s
        WHERE s.proposal_id = d.proposal_id AND s.project_room_id IS NOT NULL),
        '[]'::jsonb),
      'draws', COALESCE((SELECT jsonb_agg(jsonb_build_object(
        'id', w.id, 'label', w.label, 'percentage', w.percentage,
        'amountCents', w.amount_cents, 'sortOrder', w.sort_order,
        'gatesOnAcceptance', w.gates_on_acceptance,
        'invoiceId', w.invoice_id,
        'invoiceStatus', (SELECT i.status FROM public.invoices i WHERE i.id = w.invoice_id),
        'invoicePaidCents', (SELECT i.amount_paid_cents FROM public.invoices i WHERE i.id = w.invoice_id)
      ) ORDER BY w.sort_order, w.id)
        FROM public.trade_scope_draws w WHERE w.proposal_id = d.proposal_id), '[]'::jsonb)
    ) ORDER BY d.bound_at, d.id)
    FROM public.project_commercial_documents d
    JOIN public.proposals p ON p.id = d.proposal_id
    LEFT JOIN public.trade_scope_terms t ON t.proposal_id = d.proposal_id
    JOIN (
      -- Numbering over EVERY trade scope on the project, voided ones included,
      -- so studio and client always mean the same "scope two". Same (bound_at,
      -- id) key the output is ordered by, so number and position agree.
      SELECT n.id, row_number() OVER (ORDER BY n.bound_at, n.id) AS number
      FROM public.project_commercial_documents n
      WHERE n.project_id = p_project_id AND n.document_kind = 'trade_scope'
    ) numbered ON numbered.id = d.id
    WHERE d.project_id = p_project_id AND d.document_kind = 'trade_scope'),
  '[]'::jsonb);
END;
$$;
ALTER FUNCTION public.list_trade_scopes(uuid) RESET ALL;
ALTER FUNCTION public.list_trade_scopes(uuid) SET search_path = pg_catalog, public, pg_temp;
ALTER FUNCTION public.list_trade_scopes(uuid) OWNER TO postgres;

CREATE OR REPLACE FUNCTION public.lock_client_decision_option_parent(
  p_decision_id uuid,
  p_path text
)
RETURNS boolean
LANGUAGE plpgsql
VOLATILE
SECURITY DEFINER
SET search_path = public, pg_temp
AS $$
DECLARE
  v_decision public.client_decisions%ROWTYPE;
BEGIN
  IF COALESCE(auth.role(), '') <> 'authenticated'
     OR auth.uid() IS NULL
  THEN
    RETURN false;
  END IF;

  SELECT decision.* INTO v_decision
  FROM public.client_decisions AS decision
  WHERE decision.id = p_decision_id
    AND CASE p_path
      WHEN 'studio_draft_delete' THEN
        decision.status = 'draft'
        AND public.is_design_studio_comember(decision.designer_id)
      WHEN 'studio_option_insert' THEN
        decision.status IN ('draft', 'pending')
        AND public.is_design_studio_comember(decision.designer_id)
      WHEN 'studio_override_insert' THEN
        decision.status = 'pending'
        AND decision.coordination_kind = 'selection'
        AND decision.court = 'client'
        AND public.is_design_studio_comember(decision.designer_id)
      WHEN 'client_pending_update' THEN
        decision.status = 'pending'
        AND decision.coordination_kind = 'selection'
        AND decision.court = 'client'
        AND public.is_addressed_client_decision(decision.id)
      WHEN 'studio_expired_reopen_update' THEN
        decision.status = 'expired'
        AND public.is_design_studio_comember(decision.designer_id)
      ELSE false
    END
  FOR UPDATE;

  RETURN FOUND;
END;
$$;
ALTER FUNCTION public.lock_client_decision_option_parent(uuid,text) RESET ALL;
ALTER FUNCTION public.lock_client_decision_option_parent(uuid,text) SET search_path = pg_catalog, public, pg_temp;
ALTER FUNCTION public.lock_client_decision_option_parent(uuid,text) OWNER TO postgres;

CREATE OR REPLACE FUNCTION public.lock_proposal_authored_parent(
  p_proposal_id uuid
)
RETURNS boolean
LANGUAGE plpgsql
VOLATILE
SECURITY DEFINER
SET search_path = public, pg_temp
AS $$
DECLARE
  v_locked_id uuid;
BEGIN
  IF p_proposal_id IS NULL
     OR auth.uid() IS NULL
     OR auth.role() IS DISTINCT FROM 'authenticated'
  THEN
    RETURN false;
  END IF;

  SELECT proposal.id
  INTO v_locked_id
  FROM public.proposals AS proposal
  WHERE proposal.id = p_proposal_id
    AND proposal.status = 'draft'
    AND public.is_design_studio_comember(proposal.designer_id)
  FOR UPDATE;

  RETURN v_locked_id IS NOT NULL;
END;
$$;
ALTER FUNCTION public.lock_proposal_authored_parent(uuid) RESET ALL;
ALTER FUNCTION public.lock_proposal_authored_parent(uuid) SET search_path = pg_catalog, public, pg_temp;
ALTER FUNCTION public.lock_proposal_authored_parent(uuid) OWNER TO postgres;

CREATE OR REPLACE FUNCTION public.log_po_acknowledgment(
  p_po_id uuid, p_vendor_po_number text DEFAULT NULL, p_confirmed_eta date DEFAULT NULL
)
RETURNS public.purchase_orders
LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'public', 'pg_temp' AS $$
DECLARE v_po public.purchase_orders%ROWTYPE;
BEGIN
  SELECT * INTO v_po FROM public.purchase_orders WHERE id = p_po_id FOR UPDATE;
  IF NOT FOUND OR NOT public.is_studio_comember(v_po.designer_id) THEN
    RAISE EXCEPTION 'log_po_acknowledgment: purchase order % not found or access denied', p_po_id;
  END IF;
  IF v_po.needs_repricing THEN
    RAISE EXCEPTION 'replacement purchase order must be repriced before acknowledgment'
      USING ERRCODE = 'check_violation';
  END IF;
  IF v_po.status NOT IN ('draft','confirmed','in_production','shipped','delivered') THEN
    RAISE EXCEPTION 'log_po_acknowledgment: purchase order % is %, cancelled orders cannot be acknowledged',
      p_po_id, v_po.status USING ERRCODE = 'check_violation';
  END IF;
  PERFORM set_config('app.ffe_mutation_rpc', 'on', true);
  UPDATE public.purchase_orders SET
    acknowledged_at = COALESCE(acknowledged_at, now()),
    status = CASE WHEN status = 'draft' THEN 'confirmed' ELSE status END,
    vendor_po_number = COALESCE(p_vendor_po_number, vendor_po_number),
    confirmed_eta = COALESCE(p_confirmed_eta, confirmed_eta)
  WHERE id = p_po_id RETURNING * INTO v_po;
  RETURN v_po;
END;
$$;
ALTER FUNCTION public.log_po_acknowledgment(uuid,text,date) RESET ALL;
ALTER FUNCTION public.log_po_acknowledgment(uuid,text,date) SET search_path = pg_catalog, public, pg_temp;
ALTER FUNCTION public.log_po_acknowledgment(uuid,text,date) OWNER TO postgres;

CREATE OR REPLACE FUNCTION public.mark_trade_scope_in_progress(p_proposal_id uuid)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, pg_temp
AS $$
DECLARE
  v_proposal public.proposals%ROWTYPE;
  v_terms public.trade_scope_terms%ROWTYPE;
  v_previous_progress text := current_setting('app.trade_scope_progress_id', true);
BEGIN
  SELECT * INTO v_proposal FROM public.proposals WHERE id = p_proposal_id FOR UPDATE;
  IF NOT FOUND OR v_proposal.document_kind <> 'trade_scope'
     OR auth.uid() IS NULL
     OR NOT public._can_author_proposal(v_proposal.designer_id)
  THEN
    RAISE EXCEPTION 'trade scope % not found or access denied', p_proposal_id
      USING ERRCODE = 'insufficient_privilege';
  END IF;
  SELECT * INTO v_terms FROM public.trade_scope_terms
  WHERE proposal_id = p_proposal_id FOR UPDATE;
  IF v_terms.progress_state = 'in_progress' THEN
    RETURN jsonb_build_object('proposalId', p_proposal_id,
      'progressState', v_terms.progress_state, 'changed', false);
  END IF;
  IF v_terms.progress_state <> 'engaged' THEN
    RAISE EXCEPTION 'a trade scope must be engaged before it can be in progress'
      USING ERRCODE = 'check_violation';
  END IF;

  PERFORM set_config('app.trade_scope_progress_id', p_proposal_id::text, true);
  UPDATE public.trade_scope_terms SET progress_state = 'in_progress'
  WHERE proposal_id = p_proposal_id RETURNING * INTO v_terms;
  PERFORM set_config('app.trade_scope_progress_id', COALESCE(v_previous_progress, ''), true);

  RETURN jsonb_build_object('proposalId', p_proposal_id,
    'progressState', v_terms.progress_state, 'changed', true);
EXCEPTION WHEN OTHERS THEN
  PERFORM set_config('app.trade_scope_progress_id', COALESCE(v_previous_progress, ''), true);
  RAISE;
END;
$$;
ALTER FUNCTION public.mark_trade_scope_in_progress(uuid) RESET ALL;
ALTER FUNCTION public.mark_trade_scope_in_progress(uuid) SET search_path = pg_catalog, public, pg_temp;
ALTER FUNCTION public.mark_trade_scope_in_progress(uuid) OWNER TO postgres;

CREATE OR REPLACE FUNCTION public.materialize_board_template(
  p_template_id uuid,
  p_proposal_id uuid DEFAULT NULL,
  p_project_id uuid DEFAULT NULL,
  p_name text DEFAULT NULL,
  p_scope_room_id uuid DEFAULT NULL
)
RETURNS uuid
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, pg_temp
AS $$
DECLARE
  v_template public.board_templates%ROWTYPE;
  v_board_id uuid;
  v_sort_order integer;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'authentication required'
      USING ERRCODE = 'insufficient_privilege';
  END IF;

  IF num_nonnulls(p_proposal_id, p_project_id) <> 1 THEN
    RAISE EXCEPTION 'exactly one board owner is required'
      USING ERRCODE = 'check_violation';
  END IF;

  SELECT template.* INTO v_template
  FROM public.board_templates AS template
  WHERE template.id = p_template_id
    AND (
      template.kind = 'seeded'
      OR (
        template.kind = 'studio'
        AND EXISTS (
          SELECT 1
          FROM public.organizations AS studio
          JOIN public.organization_members AS membership
            ON membership.organization_id = studio.id
           AND membership.user_id = auth.uid()
           AND membership.status = 'active'
           AND membership.role <> 'guest'
          WHERE studio.id = template.studio_id
            AND studio.type = 'design_studio'
            AND studio.status = 'active'
        )
      )
    );

  IF NOT FOUND THEN
    RAISE EXCEPTION 'template not found or not accessible'
      USING ERRCODE = 'insufficient_privilege';
  END IF;

  IF p_proposal_id IS NOT NULL THEN
    IF NOT EXISTS (
      SELECT 1
      FROM public.proposals AS proposal
      WHERE proposal.id = p_proposal_id
        AND proposal.status = 'draft'
        AND public.is_design_studio_comember(proposal.designer_id)
    ) THEN
      RAISE EXCEPTION 'draft proposal not found or not accessible'
        USING ERRCODE = 'insufficient_privilege';
    END IF;

    IF p_scope_room_id IS NOT NULL AND NOT EXISTS (
      SELECT 1
      FROM public.proposal_scope_rooms AS room
      WHERE room.id = p_scope_room_id
        AND room.proposal_id = p_proposal_id
    ) THEN
      RAISE EXCEPTION 'scope room does not belong to the target proposal'
        USING ERRCODE = 'check_violation';
    END IF;
  ELSE
    IF p_scope_room_id IS NOT NULL THEN
      RAISE EXCEPTION 'project-owned boards cannot target a proposal scope room'
        USING ERRCODE = 'check_violation';
    END IF;

    IF NOT EXISTS (
      SELECT 1
      FROM public.projects AS project
      WHERE project.id = p_project_id
        AND public.is_design_studio_comember(project.designer_id)
    ) THEN
      RAISE EXCEPTION 'project not found or not accessible'
        USING ERRCODE = 'insufficient_privilege';
    END IF;
  END IF;

  SELECT COALESCE(max(board.sort_order), -1) + 1
  INTO v_sort_order
  FROM public.proposal_boards AS board
  WHERE board.proposal_id IS NOT DISTINCT FROM p_proposal_id
    AND board.project_id IS NOT DISTINCT FROM p_project_id;

  INSERT INTO public.proposal_boards (
    proposal_id,
    project_id,
    name,
    scope_room_id,
    cover_image_url,
    canvas_width,
    canvas_height,
    background_color,
    sort_order,
    sections,
    status
  )
  VALUES (
    p_proposal_id,
    p_project_id,
    COALESCE(NULLIF(btrim(p_name), ''), v_template.name),
    p_scope_room_id,
    v_template.cover_url,
    v_template.canvas_width,
    v_template.canvas_height,
    v_template.background_color,
    v_sort_order,
    public.sanitize_board_template_json(v_template.sections),
    'active'
  )
  RETURNING id INTO v_board_id;

  IF EXISTS (
    SELECT 1
    FROM jsonb_array_elements(v_template.items) AS item
    WHERE item->>'type' IS NULL
       OR item->>'type' NOT IN (
         'product', 'capture', 'image', 'palette', 'note', 'room_scan'
       )
  ) THEN
    RAISE EXCEPTION 'template contains an invalid board item type'
      USING ERRCODE = 'check_violation';
  END IF;

  INSERT INTO public.proposal_board_items (
    board_id,
    type,
    x,
    y,
    width,
    height,
    z_index,
    rotation,
    locked,
    product_id,
    capture_id,
    palette_id,
    image_url,
    content,
    data
  )
  SELECT
    v_board_id,
    item->>'type',
    COALESCE((item->>'x')::numeric, 0),
    COALESCE((item->>'y')::numeric, 0),
    COALESCE((item->>'width')::numeric, 240),
    CASE
      WHEN item->>'height' IS NULL THEN NULL
      ELSE (item->>'height')::numeric
    END,
    COALESCE((item->>'z_index')::integer, 0),
    COALESCE((item->>'rotation')::numeric, 0),
    COALESCE((item->>'locked')::boolean, false),
    NULL,
    NULL,
    NULL,
    item->>'image_url',
    item->>'content',
    COALESCE(
      public.sanitize_board_template_json(item->'data'),
      '{}'::jsonb
    )
  FROM jsonb_array_elements(v_template.items) AS item;

  RETURN v_board_id;
END;
$$;
ALTER FUNCTION public.materialize_board_template(uuid,uuid,uuid,text,uuid) RESET ALL;
ALTER FUNCTION public.materialize_board_template(uuid,uuid,uuid,text,uuid) SET search_path = pg_catalog, public, pg_temp;
ALTER FUNCTION public.materialize_board_template(uuid,uuid,uuid,text,uuid) OWNER TO postgres;

CREATE OR REPLACE FUNCTION public.materialize_schedule_dates(
  p_project_id uuid,
  p_phases     jsonb
)
RETURNS integer
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $$
BEGIN
  -- Same ownership guard as commit_schedule_edit (00475) and every
  -- install-window RPC (00476): the project's designer or a studio comember
  -- of the designer.
  IF NOT EXISTS (
    SELECT 1 FROM public.projects
    WHERE id = p_project_id AND public.is_studio_comember(designer_id)
  ) THEN
    RAISE EXCEPTION 'project % not found or not owned by caller', p_project_id;
  END IF;

  RETURN public._materialize_schedule_dates_impl(p_project_id, p_phases);
END;
$$;
