ALTER FUNCTION public.notify_decision_updated(uuid) SET search_path = pg_catalog, public, pg_temp;
ALTER FUNCTION public.notify_decision_updated(uuid) OWNER TO postgres;

CREATE OR REPLACE FUNCTION public.nudge_proposal(p_proposal_id uuid)
RETURNS timestamptz
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, pg_temp
AS $$
DECLARE
  v_stamp timestamptz := clock_timestamp();
  v_proposal public.proposals%ROWTYPE;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'nudge_proposal requires an authenticated user'
      USING ERRCODE = 'insufficient_privilege';
  END IF;

  SELECT * INTO v_proposal
  FROM public.proposals
  WHERE id = p_proposal_id
  FOR UPDATE;

  IF NOT FOUND OR NOT public._can_author_proposal(v_proposal.designer_id) THEN
    RAISE EXCEPTION 'proposal % not found or access denied', p_proposal_id
      USING ERRCODE = 'insufficient_privilege';
  END IF;

  IF v_proposal.status NOT IN ('sent', 'viewed') THEN
    RAISE EXCEPTION
      'nudge_proposal: proposal % is "%" — only sent/viewed proposals can be nudged',
      p_proposal_id, v_proposal.status
      USING ERRCODE = 'check_violation';
  END IF;

  IF v_proposal.last_nudged_at IS NOT NULL
     AND v_proposal.last_nudged_at > v_stamp - interval '3 days'
  THEN
    RAISE EXCEPTION
      'nudge_proposal: proposal % was nudged on % — wait before nudging again',
      p_proposal_id, v_proposal.last_nudged_at
      USING ERRCODE = 'check_violation';
  END IF;

  PERFORM set_config('app.proposal_nudge_id', p_proposal_id::text, true);
  UPDATE public.proposals
  SET last_nudged_at = v_stamp,
      nudge_count = nudge_count + 1,
      updated_at = now()
  WHERE id = p_proposal_id;
  PERFORM set_config('app.proposal_nudge_id', '', true);

  RETURN v_stamp;
END;
$$;
ALTER FUNCTION public.nudge_proposal(uuid) RESET ALL;
ALTER FUNCTION public.nudge_proposal(uuid) SET search_path = pg_catalog, public, pg_temp;
ALTER FUNCTION public.nudge_proposal(uuid) OWNER TO postgres;

CREATE OR REPLACE FUNCTION public.override_budget_checkpoint(
  p_checkpoint_id uuid,
  p_reason text
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, pg_temp
AS $$
DECLARE
  v_actor uuid := auth.uid();
  v_checkpoint public.project_budget_checkpoints%ROWTYPE;
  v_reason text := btrim(COALESCE(p_reason, ''));
  v_newly boolean := false;
BEGIN
  IF char_length(v_reason) < 5 THEN
    RAISE EXCEPTION 'budget override requires a meaningful reason'
      USING ERRCODE = 'check_violation';
  END IF;
  SELECT c.* INTO v_checkpoint
  FROM public.project_budget_checkpoints c
  JOIN public.projects p ON p.id = c.project_id
  WHERE c.id = p_checkpoint_id AND public.is_studio_comember(p.designer_id)
  FOR UPDATE OF c;
  IF NOT FOUND OR v_actor IS NULL THEN
    RAISE EXCEPTION 'budget checkpoint % not found or access denied', p_checkpoint_id
      USING ERRCODE = 'insufficient_privilege';
  END IF;
  IF v_checkpoint.snapshot_fingerprint IS DISTINCT FROM
     public._budget_version_fingerprint(v_checkpoint.budget_version_id)
  THEN
    RAISE EXCEPTION 'budget checkpoint fingerprint no longer matches its published version'
      USING ERRCODE = 'check_violation';
  END IF;
  IF v_checkpoint.status = 'open' THEN
    UPDATE public.project_budget_checkpoints
    SET status = 'overridden', override_by = v_actor,
        override_reason = v_reason, overridden_at = now()
    WHERE id = p_checkpoint_id RETURNING * INTO v_checkpoint;
    v_newly := true;
  ELSIF v_checkpoint.status <> 'overridden'
        OR v_checkpoint.override_by IS DISTINCT FROM v_actor
        OR v_checkpoint.override_reason IS DISTINCT FROM v_reason THEN
    RAISE EXCEPTION 'budget checkpoint % cannot be overridden from %',
      p_checkpoint_id, v_checkpoint.status USING ERRCODE = 'check_violation';
  END IF;
  RETURN jsonb_build_object(
    'checkpointId', v_checkpoint.id,
    'status', v_checkpoint.status,
    'overrideReason', v_checkpoint.override_reason,
    'overriddenAt', v_checkpoint.overridden_at,
    'newlyOverridden', v_newly
  );
END;
$$;
ALTER FUNCTION public.override_budget_checkpoint(uuid,text) RESET ALL;
ALTER FUNCTION public.override_budget_checkpoint(uuid,text) SET search_path = pg_catalog, public, pg_temp;
ALTER FUNCTION public.override_budget_checkpoint(uuid,text) OWNER TO postgres;

CREATE OR REPLACE FUNCTION public.prepare_trade_rfq(
  p_proposal_id uuid,
  p_party_id uuid,
  p_message text DEFAULT NULL,
  p_timeline text DEFAULT NULL
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, extensions, pg_temp
AS $$
DECLARE
  v_proposal public.proposals%ROWTYPE;
  v_document public.project_commercial_documents%ROWTYPE;
  v_party public.project_parties%ROWTYPE;
  v_request public.trade_rfq_requests%ROWTYPE;
  v_snapshot jsonb;
  v_hash text;
BEGIN
  SELECT * INTO v_proposal FROM public.proposals
  WHERE id = p_proposal_id FOR SHARE;
  IF NOT FOUND OR v_proposal.document_kind <> 'trade_scope'
     OR auth.uid() IS NULL
     OR NOT public._can_author_proposal(v_proposal.designer_id)
  THEN
    RAISE EXCEPTION 'trade scope % not found or access denied', p_proposal_id
      USING ERRCODE = 'insufficient_privilege';
  END IF;
  IF v_proposal.commercial_state NOT IN ('draft', 'sent') THEN
    RAISE EXCEPTION 'a trade scope may only be put out for bid while it is a draft or out for signature'
      USING ERRCODE = 'check_violation';
  END IF;

  SELECT * INTO v_document FROM public.project_commercial_documents
  WHERE proposal_id = p_proposal_id;
  IF v_document.id IS NULL THEN
    RAISE EXCEPTION 'trade scope has no project binding'
      USING ERRCODE = 'check_violation';
  END IF;

  -- The same party-scoping set_trade_scope_party and select_trade_bid enforce
  -- (00423:1413-1418, 1490-1495). An RFQ is the third way a party's identity
  -- reaches this document, and it is the one that puts a live link in their
  -- hands — so it gets the same check, not a weaker one.
  SELECT * INTO v_party FROM public.project_parties WHERE id = p_party_id;
  IF NOT FOUND OR v_party.project_id IS DISTINCT FROM v_document.project_id THEN
    RAISE EXCEPTION 'party % does not belong to project %',
      p_party_id, v_document.project_id
      USING ERRCODE = 'check_violation';
  END IF;

  v_snapshot := public._trade_rfq_scope_snapshot(p_proposal_id);
  v_hash := encode(extensions.digest(convert_to(v_snapshot::text, 'UTF8'), 'sha256'), 'hex');

  SELECT * INTO v_request FROM public.trade_rfq_requests
  WHERE proposal_id = p_proposal_id AND party_id = p_party_id AND status = 'draft'
  FOR UPDATE;

  IF FOUND THEN
    -- A draft ask is normally private paperwork — nobody outside the studio has
    -- seen it, so revising it revises nothing anyone was told. A LIVE LINK
    -- changes that: the question is in the party's hands, and re-snapshotting it
    -- would silently move the words a sub is quoting against while they are
    -- quoting against them. (The ordinary send stamps the ask 'sent', so this
    -- only bites the draft-with-a-live-link shape a partial send leaves behind —
    -- which is exactly the shape where the freeze matters most, because the link
    -- went out and the bookkeeping did not.) Revoke the link, then revise.
    IF EXISTS (
      SELECT 1 FROM public.trade_rfq_tokens t
      WHERE t.rfq_request_id = v_request.id
        AND t.status = 'active'
        AND t.expires_at > now()
    ) THEN
      RAISE EXCEPTION 'the request is already in the party''s hands — revoke its link before revising'
        USING ERRCODE = 'check_violation';
    END IF;

    -- COALESCE only on ABSENT (NULL). An explicit empty string is a studio
    -- deleting the words it wrote, and a form that cannot clear a field is a
    -- form that makes its own last draft permanent.
    UPDATE public.trade_rfq_requests SET
      party_display_name = v_party.display_name,
      message = CASE WHEN p_message IS NULL THEN message
                     ELSE NULLIF(btrim(p_message), '') END,
      timeline = CASE WHEN p_timeline IS NULL THEN timeline
                      ELSE NULLIF(btrim(p_timeline), '') END,
      scope_snapshot = v_snapshot,
      scope_snapshot_hash = v_hash
    WHERE id = v_request.id
    RETURNING * INTO v_request;
  ELSE
    INSERT INTO public.trade_rfq_requests (
      proposal_id, party_id, party_display_name, message, timeline,
      scope_snapshot, scope_snapshot_hash, status, created_by
    ) VALUES (
      p_proposal_id, p_party_id, v_party.display_name,
      NULLIF(btrim(COALESCE(p_message, '')), ''),
      NULLIF(btrim(COALESCE(p_timeline, '')), ''),
      v_snapshot, v_hash, 'draft', auth.uid()
    ) RETURNING * INTO v_request;
  END IF;

  RETURN jsonb_build_object(
    'id', v_request.id,
    'proposalId', v_request.proposal_id,
    'projectId', v_document.project_id,
    'partyId', v_request.party_id,
    'partyDisplayName', v_request.party_display_name,
    'status', v_request.status,
    'message', v_request.message,
    'timeline', v_request.timeline,
    'scopeSnapshotHash', v_request.scope_snapshot_hash,
    'sentAt', v_request.sent_at,
    'respondedAt', v_request.responded_at,
    'createdAt', v_request.created_at,
    'updatedAt', v_request.updated_at
  );
END;
$$;
ALTER FUNCTION public.prepare_trade_rfq(uuid,uuid,text,text) RESET ALL;
ALTER FUNCTION public.prepare_trade_rfq(uuid,uuid,text,text) SET search_path = pg_catalog, public, extensions, pg_temp;
ALTER FUNCTION public.prepare_trade_rfq(uuid,uuid,text,text) OWNER TO postgres;

CREATE OR REPLACE FUNCTION public.preview_plan_issue(
  p_project_id uuid,
  p_sheet_ids uuid[] DEFAULT NULL
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, extensions, pg_temp
AS $$
DECLARE
  v_sheets   jsonb;
  v_checksum text;
  v_prior    jsonb;
  v_added    jsonb;
  v_changed  jsonb;
  v_removed  jsonb;
  v_unchanged jsonb;
  v_missing  text;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'previewing an issue requires an authenticated designer'
      USING errcode = 'insufficient_privilege';
  END IF;
  IF NOT EXISTS (
    SELECT 1 FROM public.projects p
    WHERE p.id = p_project_id AND public.is_design_studio_comember(p.designer_id)
  ) THEN
    RAISE EXCEPTION 'plan room for project % not found or access denied', p_project_id
      USING errcode = 'insufficient_privilege';
  END IF;

  IF p_sheet_ids IS NOT NULL THEN
    SELECT string_agg(x::text, ', ') INTO v_missing
    FROM unnest(p_sheet_ids) AS x
    WHERE NOT EXISTS (
      SELECT 1 FROM public.plan_sheets s
      WHERE s.id = x AND s.project_id = p_project_id AND s.current_print_id IS NOT NULL
    );
    IF v_missing IS NOT NULL THEN
      RAISE EXCEPTION
        'these sheets are not in this plan room, or have nothing filed on them: %', v_missing
        USING errcode = 'check_violation';
    END IF;
  END IF;

  WITH cur AS (
    SELECT s.id AS sheet_id,
           btrim(s.sheet_number) AS number,
           upper(btrim(s.sheet_number)) AS norm,
           s.title,
           pp.id AS print_id,
           pp.rev_letter,
           pp.sha256
    FROM public.plan_sheets s
    JOIN public.plan_prints pp ON pp.id = s.current_print_id
    WHERE s.project_id = p_project_id
      AND (p_sheet_ids IS NULL OR s.id = ANY (p_sheet_ids))
  ),
  prior AS (
    SELECT i.id, i.name, i.issue_number, i.issued_at
    FROM public.plan_issues i
    WHERE i.project_id = p_project_id
    ORDER BY i.issue_number DESC
    LIMIT 1
  ),
  snap AS (
    SELECT ip.sheet_id, ip.print_id
    FROM public.plan_issue_prints ip
    JOIN prior ON prior.id = ip.issue_id
  ),
  drift AS (
    SELECT COALESCE(c.sheet_id, s.sheet_id) AS sheet_id,
           CASE
             WHEN s.sheet_id IS NULL THEN 'added'
             WHEN c.sheet_id IS NULL THEN 'removed'
             WHEN s.print_id IS DISTINCT FROM c.print_id THEN 'changed'
             ELSE 'unchanged'
           END AS kind
    FROM cur c
    FULL OUTER JOIN snap s ON s.sheet_id = c.sheet_id
  )
  SELECT
    (SELECT COALESCE(jsonb_agg(jsonb_build_object(
       'sheetId', sheet_id, 'sheetNumber', number, 'sheetTitle', title,
       'revLetter', rev_letter, 'sha256', sha256, 'printId', print_id
     ) ORDER BY norm), '[]'::jsonb) FROM cur),
    (SELECT encode(extensions.digest(public._plan_room_canonical_json(
       COALESCE(jsonb_agg(jsonb_build_object(
         'sheetNumber', number, 'revLetter', rev_letter, 'sha256', sha256
       ) ORDER BY norm), '[]'::jsonb)), 'sha256'), 'hex') FROM cur),
    (SELECT jsonb_build_object('id', p.id, 'name', p.name,
       'issueNumber', p.issue_number, 'issuedAt', p.issued_at) FROM prior p),
    (SELECT COALESCE(jsonb_agg(sheet_id), '[]'::jsonb) FROM drift WHERE kind = 'added'),
    (SELECT COALESCE(jsonb_agg(sheet_id), '[]'::jsonb) FROM drift WHERE kind = 'changed'),
    (SELECT COALESCE(jsonb_agg(sheet_id), '[]'::jsonb) FROM drift WHERE kind = 'removed'),
    (SELECT COALESCE(jsonb_agg(sheet_id), '[]'::jsonb) FROM drift WHERE kind = 'unchanged')
  INTO v_sheets, v_checksum, v_prior, v_added, v_changed, v_removed, v_unchanged;

  RETURN jsonb_build_object(
    'sheets', v_sheets,
    'checksumPreview', v_checksum,
    'priorIssue', v_prior,
    'drift', jsonb_build_object(
      'added', v_added, 'changed', v_changed,
      'removed', v_removed, 'unchanged', v_unchanged)
  );
END;
$$;
ALTER FUNCTION public.preview_plan_issue(uuid,uuid[]) RESET ALL;
ALTER FUNCTION public.preview_plan_issue(uuid,uuid[]) SET search_path = pg_catalog, public, extensions, pg_temp;
ALTER FUNCTION public.preview_plan_issue(uuid,uuid[]) OWNER TO postgres;

CREATE OR REPLACE FUNCTION app_private.project_decision_review_for_actor(
  p_decision_id uuid,
  p_actor uuid
)
RETURNS jsonb
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path = public, pg_temp
AS $$
DECLARE
  v_project_id uuid;
  v_item jsonb;
BEGIN
  IF p_actor IS NULL OR p_actor IS DISTINCT FROM auth.uid() THEN
    RETURN NULL;
  END IF;

  SELECT decision.project_id
  INTO v_project_id
  FROM public.client_decisions AS decision
  LEFT JOIN public.project_decision_authority_snapshots AS snapshot
    ON snapshot.decision_id = decision.id
   AND snapshot.project_id = decision.project_id
  WHERE decision.id = p_decision_id
    AND decision.approval_contract = 'project_artifact_v1'
    AND (
      public.is_design_studio_comember(decision.designer_id)
      OR snapshot.decision_lead_id = p_actor
    );

  IF NOT FOUND THEN
    RETURN NULL;
  END IF;

  SELECT review.value
  INTO v_item
  FROM jsonb_array_elements(
    public.get_project_decision_reviews(v_project_id)
  ) AS review(value)
  WHERE review.value->>'decisionId' = p_decision_id::text;

  RETURN v_item;
END;
$$;
ALTER FUNCTION app_private.project_decision_review_for_actor(uuid,uuid) RESET ALL;
ALTER FUNCTION app_private.project_decision_review_for_actor(uuid,uuid) SET search_path = pg_catalog, public, pg_temp;
ALTER FUNCTION app_private.project_decision_review_for_actor(uuid,uuid) OWNER TO postgres;

CREATE OR REPLACE FUNCTION public.publish_budget_checkpoint(
  p_project_id uuid,
  p_version_id uuid
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, pg_temp
AS $$
DECLARE
  v_actor uuid := auth.uid();
  v_version public.project_budget_versions%ROWTYPE;
  v_checkpoint public.project_budget_checkpoints%ROWTYPE;
  v_low bigint;
  v_target bigint;
  v_high bigint;
  v_stamp record;
  v_fingerprint text;
  v_previous_publish text := current_setting('app.budget_publish_id', true);
BEGIN
  SELECT v.* INTO v_version
  FROM public.project_budget_versions v
  JOIN public.projects p ON p.id = v.project_id
  WHERE v.id = p_version_id AND v.project_id = p_project_id
    AND public.is_studio_comember(p.designer_id)
  FOR UPDATE OF v;
  IF NOT FOUND OR v_actor IS NULL OR v_version.status <> 'draft' THEN
    RAISE EXCEPTION 'draft budget version % not found or access denied', p_version_id
      USING ERRCODE = 'insufficient_privilege';
  END IF;
  -- 00414: a checkpoint is an act of signed commercial authority — it is what a
  -- furnishing wave is built on. A legacy project has no such authority, so it
  -- can no longer publish one.
  IF NOT EXISTS (
    SELECT 1 FROM public.project_commercial_documents d
    JOIN public.proposals p ON p.id = d.proposal_id
    WHERE d.project_id = p_project_id AND d.is_origin
      AND d.document_kind = 'design_services' AND p.commercial_state = 'executed'
  ) THEN
    RAISE EXCEPTION 'project % has no executed design-services origin', p_project_id
      USING ERRCODE = 'check_violation';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM public.project_budget_lines l WHERE l.budget_version_id = p_version_id) THEN
    RAISE EXCEPTION 'budget version % has no lines', p_version_id
      USING ERRCODE = 'check_violation';
  END IF;

  -- 00422: freeze the coverage picture INTO the version, so the checkpoint the
  -- client acknowledges says what was scheduled and what was already authorized
  -- against each line — not just what was targeted.
  --
  -- Both rollups match on the ROOM ID wherever both sides carry one, and fall
  -- back to the name only for a legacy row that has no id (a budget line filed
  -- before 00412's project_room_id, or a proposal-sourced snapshot that never
  -- had one). Matching on name alone double-counted every pair of rooms that
  -- happened to share a name, and froze that inflated figure into the hash the
  -- client acknowledges. Written as a loop, not one UPDATE, so the narrowing to
  -- the integer columns can name which rollup overflowed.
  FOR v_stamp IN
    SELECT
      l.id AS line_id, l.room_name AS room_name, l.category AS category,
      COALESCE((
        SELECT SUM(CASE
          WHEN i.item_type = 'fixed' THEN COALESCE(i.line_total_cents, 0)
          WHEN i.item_type = 'allowance' THEN COALESCE(i.budget_max_cents, 0)
          ELSE 0 END)
        FROM public.project_ffe_items i
        LEFT JOIN public.project_rooms r ON r.id = i.project_room_id
        WHERE i.project_id = p_project_id
          -- 00423 delta: same exclusion as derive_working_budget_draft, and it
          -- is load-bearing independently. derive is not the only way a
          -- 'trade work' budget line can exist — a studio can type any category
          -- by hand, and a version derived before 00423 already carries one —
          -- so the stamp must refuse the presence lines on its own account.
          AND i.trade_scope_document_id IS NULL
          AND CASE
                WHEN l.project_room_id IS NOT NULL AND i.project_room_id IS NOT NULL
                  THEN i.project_room_id = l.project_room_id
                ELSE COALESCE(r.name, '') = l.room_name
              END
          AND COALESCE(i.ffe_category, 'Uncategorized') = l.category
      ), 0) AS scheduled,
      COALESCE((
        SELECT SUM(a.client_line_total_cents)
        FROM public.furnishing_authorization_items a
        JOIN public.project_commercial_documents d ON d.id = a.commercial_document_id
        JOIN public.proposals p ON p.id = d.proposal_id
        WHERE d.project_id = p_project_id
          AND d.executed_at IS NOT NULL
          AND p.commercial_state = 'executed'
          AND CASE
                WHEN l.project_room_id IS NOT NULL AND a.project_room_id IS NOT NULL
                  THEN a.project_room_id = l.project_room_id
                ELSE COALESCE(a.room_name, '') = l.room_name
              END
          AND COALESCE(a.category, 'Uncategorized') = l.category
      ), 0) AS authorized
    FROM public.project_budget_lines l
    WHERE l.budget_version_id = p_version_id
  LOOP
    UPDATE public.project_budget_lines SET
      scheduled_cents = public._cents_to_int4(v_stamp.scheduled,
        format('the scheduled rollup for %s · %s', v_stamp.room_name, v_stamp.category)),
      authorized_cents = public._cents_to_int4(v_stamp.authorized,
        format('the authorized rollup for %s · %s', v_stamp.room_name, v_stamp.category))
    WHERE id = v_stamp.line_id;
  END LOOP;

  SELECT sum(low_cents), sum(target_cents), sum(high_cents)
  INTO v_low, v_target, v_high
  FROM public.project_budget_lines WHERE budget_version_id = p_version_id;

  PERFORM set_config('app.budget_publish_id', p_version_id::text, true);
  UPDATE public.project_budget_versions SET
    low_total_cents = public._cents_to_int4(v_low, 'this budget version''s low total'),
    target_total_cents = public._cents_to_int4(v_target, 'this budget version''s target total'),
    high_total_cents = public._cents_to_int4(v_high, 'this budget version''s high total'),
    status = 'published', published_at = now()
  WHERE id = p_version_id RETURNING * INTO v_version;
  v_fingerprint := public._budget_version_fingerprint(p_version_id);

  INSERT INTO public.project_budget_checkpoints (
    project_id, budget_version_id, checkpoint_code, snapshot_fingerprint,
    published_by, published_at
  ) VALUES (
    p_project_id, p_version_id, 'B-' || lpad(v_version.version::text, 3, '0'),
    v_fingerprint, v_actor, v_version.published_at
  ) RETURNING * INTO v_checkpoint;
  PERFORM set_config('app.budget_publish_id', COALESCE(v_previous_publish, ''), true);

  RETURN jsonb_build_object(
    'checkpointId', v_checkpoint.id,
    'projectId', p_project_id,
    'versionId', p_version_id,
    'checkpointCode', v_checkpoint.checkpoint_code,
    'status', v_checkpoint.status,
    'snapshotFingerprint', v_checkpoint.snapshot_fingerprint,
    'publishedAt', v_checkpoint.published_at
  );
EXCEPTION WHEN OTHERS THEN
  PERFORM set_config('app.budget_publish_id', COALESCE(v_previous_publish, ''), true);
  RAISE;
END;
$$;
ALTER FUNCTION public.publish_budget_checkpoint(uuid,uuid) RESET ALL;
ALTER FUNCTION public.publish_budget_checkpoint(uuid,uuid) SET search_path = pg_catalog, public, pg_temp;
ALTER FUNCTION public.publish_budget_checkpoint(uuid,uuid) OWNER TO postgres;

CREATE OR REPLACE FUNCTION public.publish_client_decision(p_decision_id uuid)
RETURNS public.client_decisions
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, pg_temp
AS $$
DECLARE
  v_decision public.client_decisions%ROWTYPE;
  v_snapshot public.project_decision_authority_snapshots%ROWTYPE;
  v_artifact public.project_approval_artifacts%ROWTYPE;
  v_receipt public.project_approval_action_receipts%ROWTYPE;
  v_actor uuid := auth.uid();
  v_key text := 'publish-v1:' || p_decision_id::text;
  v_request_hash text;
  v_result jsonb;
  v_receipt_id uuid := extensions.gen_random_uuid();
  v_previous_parent_write text := current_setting(
    'app.project_approval_decision_write_id', true
  );
  v_previous_legacy_write text := current_setting(
    'app.client_decision_write_id', true
  );
  v_previous_evidence_write text := current_setting(
    'app.project_approval_evidence_decision_id', true
  );
BEGIN
  SELECT * INTO v_decision
  FROM public.client_decisions
  WHERE id = p_decision_id
  FOR UPDATE;

  IF v_decision.approval_contract = 'project_artifact_v1' THEN
    IF NOT FOUND OR v_actor IS NULL
       OR NOT public._can_author_proposal(v_decision.designer_id)
    THEN
      RAISE EXCEPTION 'decision % not found or access denied', p_decision_id
        USING ERRCODE = 'insufficient_privilege';
    END IF;

    SELECT * INTO v_snapshot
    FROM public.project_decision_authority_snapshots AS snapshot
    WHERE snapshot.decision_id = p_decision_id;
    SELECT * INTO v_artifact
    FROM public.project_approval_artifacts AS artifact
    WHERE artifact.decision_id = p_decision_id;
    IF v_snapshot.id IS NULL
       OR v_artifact.id IS NULL
       OR v_snapshot.project_id IS DISTINCT FROM v_decision.project_id
       OR v_artifact.project_id IS DISTINCT FROM v_decision.project_id
       OR v_artifact.phase_id IS DISTINCT FROM v_decision.phase_id
    THEN
      RAISE EXCEPTION 'project approval evidence is incomplete or malformed'
        USING ERRCODE = 'check_violation';
    END IF;

    v_request_hash := public._project_approval_hash(jsonb_build_object(
      'decisionId', p_decision_id,
      'artifactHash', v_artifact.artifact_hash,
      'authorityRevision', v_snapshot.authority_revision
    ));
    SELECT * INTO v_receipt
    FROM public.project_approval_action_receipts AS receipt
    WHERE receipt.decision_id = p_decision_id
      AND receipt.action_kind = 'published'
      AND receipt.idempotency_key = v_key
    FOR UPDATE;
    IF FOUND THEN
      IF v_receipt.request_hash IS DISTINCT FROM v_request_hash
         OR v_receipt.actor_id IS DISTINCT FROM v_actor
      THEN
        RAISE EXCEPTION 'publish receipt conflicts with the current request'
          USING ERRCODE = 'serialization_failure';
      END IF;
      RETURN v_decision;
    END IF;

    IF v_decision.status <> 'draft' THEN
      RAISE EXCEPTION 'decision % cannot publish from status %',
        p_decision_id, v_decision.status
        USING ERRCODE = 'check_violation';
    END IF;
    IF NOT EXISTS (
         SELECT 1
         FROM public.project_decision_review_confirmations AS confirmation
         WHERE confirmation.decision_id = p_decision_id
           AND confirmation.approver_role = 'lead'
           AND confirmation.approver_id = v_snapshot.decision_lead_id
           AND confirmation.authority_revision = v_snapshot.authority_revision
           AND confirmation.artifact_hash = v_artifact.artifact_hash
       )
       OR (
         v_snapshot.required_coapprover_id IS NOT NULL
         AND NOT EXISTS (
           SELECT 1
           FROM public.project_decision_review_confirmations AS confirmation
           WHERE confirmation.decision_id = p_decision_id
             AND confirmation.approver_role = 'coapprover'
             AND confirmation.approver_id = v_snapshot.required_coapprover_id
             AND confirmation.authority_revision = v_snapshot.authority_revision
             AND confirmation.artifact_hash = v_artifact.artifact_hash
         )
       )
    THEN
      RAISE EXCEPTION 'every frozen required reviewer must confirm before publish'
        USING ERRCODE = 'check_violation';
    END IF;
    IF (
         SELECT count(*)
         FROM public.client_decision_options AS option
         WHERE option.decision_id = p_decision_id
           AND option.approval_outcome IN (
             'approved', 'changes_requested', 'needs_discussion'
           )
           AND option.cost_cents_delta = v_artifact.cost_cents_delta
           AND option.schedule_days_delta = v_artifact.schedule_days_delta
           AND option.lead_time_days_delta = v_artifact.lead_time_days_delta
           AND option.approves IS NOT DISTINCT FROM
               (option.approval_outcome = 'approved')
       ) <> 3
       OR (
         SELECT count(*) FROM public.client_decision_options AS option
         WHERE option.decision_id = p_decision_id
       ) <> 3
    THEN
      RAISE EXCEPTION 'canonical approval outcomes are malformed'
        USING ERRCODE = 'check_violation';
    END IF;

    PERFORM 1
    FROM public.client_decision_options AS option
    WHERE option.decision_id = p_decision_id
    ORDER BY option.id
    FOR UPDATE;

    PERFORM set_config(
      'app.project_approval_decision_write_id', p_decision_id::text, true
    );
    PERFORM set_config(
      'app.client_decision_write_id', p_decision_id::text, true
    );
    UPDATE public.client_decisions
    SET status = 'pending', sent_at = COALESCE(sent_at, now()), updated_at = now()
    WHERE id = p_decision_id
    RETURNING * INTO v_decision;

    v_result := jsonb_build_object(
      'receiptId', v_receipt_id,
      'projectId', v_decision.project_id,
      'decisionId', v_decision.id,
      'status', v_decision.status,
      'updatedAt', v_decision.updated_at
    );
    PERFORM set_config(
      'app.project_approval_evidence_decision_id', p_decision_id::text, true
    );
    INSERT INTO public.project_approval_action_receipts (
      id, project_id, decision_id, action_kind, idempotency_key,
      request_hash, actor_id, result
    ) VALUES (
      v_receipt_id, v_decision.project_id, p_decision_id, 'published', v_key,
      v_request_hash, v_actor, v_result
    );

    PERFORM set_config(
      'app.project_approval_decision_write_id',
      COALESCE(v_previous_parent_write, ''), true
    );
    PERFORM set_config(
      'app.client_decision_write_id', COALESCE(v_previous_legacy_write, ''), true
    );
    PERFORM set_config(
      'app.project_approval_evidence_decision_id',
      COALESCE(v_previous_evidence_write, ''), true
    );
    PERFORM public._enqueue_decision_notification(
      p_decision_id, 'decision_required'
    );
    RETURN v_decision;
  END IF;

  IF NOT FOUND OR NOT public._can_author_proposal(v_decision.designer_id) THEN
    RAISE EXCEPTION 'decision % not found or access denied', p_decision_id
      USING ERRCODE = 'insufficient_privilege';
  END IF;
  IF v_decision.status = 'pending' THEN
    PERFORM public._enqueue_decision_notification(
      p_decision_id, 'decision_required'
    );
    RETURN v_decision;
  END IF;
  IF v_decision.status <> 'draft' THEN
    RAISE EXCEPTION 'decision % cannot publish from status %',
      p_decision_id, v_decision.status
      USING ERRCODE = 'check_violation';
  END IF;

  PERFORM 1
  FROM public.client_decision_options AS option
  WHERE option.decision_id = p_decision_id
  ORDER BY option.id
  FOR UPDATE;

  PERFORM set_config('app.client_decision_write_id', p_decision_id::text, true);
  UPDATE public.client_decisions
  SET status = 'pending', sent_at = COALESCE(sent_at, now()), updated_at = now()
  WHERE id = p_decision_id
  RETURNING * INTO v_decision;
  PERFORM set_config('app.client_decision_write_id', '', true);
  PERFORM public._enqueue_decision_notification(
    p_decision_id, 'decision_required'
  );
  RETURN v_decision;
EXCEPTION WHEN OTHERS THEN
  PERFORM set_config(
    'app.project_approval_decision_write_id',
    COALESCE(v_previous_parent_write, ''), true
  );
  PERFORM set_config(
    'app.client_decision_write_id', COALESCE(v_previous_legacy_write, ''), true
  );
  PERFORM set_config(
    'app.project_approval_evidence_decision_id',
    COALESCE(v_previous_evidence_write, ''), true
  );
  RAISE;
END;
$$;
