CREATE OR REPLACE FUNCTION public.record_paper_trade_acceptance(
  p_proposal_id uuid,
  p_signed_name text,
  p_paper_signed_on date,
  p_scan_document_id uuid DEFAULT NULL
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, pg_temp
AS $$
DECLARE
  -- 00425 DELTA 1 (actor). accepted_by stays the CLIENT — they accepted the
  -- work, on paper. v_recorder is the studio author writing it down.
  v_actor uuid;
  v_recorder uuid := auth.uid();
  v_proposal public.proposals%ROWTYPE;
  v_terms public.trade_scope_terms%ROWTYPE;
  v_name text := btrim(COALESCE(p_signed_name, ''));
  v_previous_progress text := current_setting('app.trade_scope_progress_id', true);
  v_project_id uuid;        -- 00475
  v_milestone_id uuid;      -- 00475
BEGIN
  IF v_recorder IS NULL OR char_length(v_name) < 2 THEN
    RAISE EXCEPTION 'recording a paper trade scope acceptance requires an authenticated studio author and legal name'
      USING ERRCODE = 'insufficient_privilege';
  END IF;
  SELECT * INTO v_proposal FROM public.proposals WHERE id = p_proposal_id FOR UPDATE;
  IF NOT FOUND OR v_proposal.document_kind <> 'trade_scope'
     OR NOT public._can_author_proposal(v_proposal.designer_id)
     OR v_proposal.client_id IS NULL
  THEN
    RAISE EXCEPTION 'trade scope % not found or access denied', p_proposal_id
      USING ERRCODE = 'insufficient_privilege';
  END IF;
  v_actor := v_proposal.client_id;
  -- 00425 DELTA 2 (terminal). A retired or declined instrument is not a thing
  -- a paper acceptance can be recorded against.
  IF COALESCE(v_proposal.commercial_state, 'draft') IN ('superseded', 'declined') THEN
    RAISE EXCEPTION 'trade scope % is % and can no longer be recorded on paper',
      p_proposal_id, v_proposal.commercial_state
      USING ERRCODE = 'check_violation';
  END IF;
  -- The same helper the signature rails use, given the same three facts: the
  -- date must be there and not invented, and a scan pointer must belong to THIS
  -- document. One validation, four acts.
  PERFORM public._assert_paper_provenance(
    p_proposal_id, p_paper_signed_on, p_scan_document_id
  );
  SELECT * INTO v_terms FROM public.trade_scope_terms
  WHERE proposal_id = p_proposal_id FOR UPDATE;
  IF v_terms.progress_state = 'accepted' THEN
    RETURN jsonb_build_object('proposalId', p_proposal_id,
      'progressState', v_terms.progress_state,
      'acceptedAt', v_terms.accepted_at,
      'acceptedSignedName', v_terms.accepted_signed_name,
      'acceptanceFingerprint', v_terms.acceptance_fingerprint,
      'acceptedOnPaper', v_terms.accepted_on_paper,
      'acceptanceScanDocumentId', v_terms.acceptance_scan_document_id,
      'changed', false);
  END IF;
  IF v_terms.progress_state <> 'substantially_complete' THEN
    RAISE EXCEPTION 'a trade scope must be substantially complete before the client accepts it'
      USING ERRCODE = 'check_violation';
  END IF;

  PERFORM set_config('app.trade_scope_progress_id', p_proposal_id::text, true);
  UPDATE public.trade_scope_terms SET
    progress_state = 'accepted',
    -- 00425 DELTA 3 (paper stamps). accepted_at becomes the date on the paper,
    -- not the moment of typing; accepted_on_paper and acceptance_recorded_by
    -- say who wrote it down; acceptance_scan_document_id is the page itself.
    -- All three new columns move only under the progress GUC.
    accepted_at = p_paper_signed_on::timestamptz,
    accepted_by = v_actor,
    accepted_signed_name = v_name,
    acceptance_fingerprint = public._commercial_document_fingerprint(p_proposal_id),
    accepted_on_paper = true,
    acceptance_recorded_by = v_recorder,
    acceptance_scan_document_id = p_scan_document_id
  WHERE proposal_id = p_proposal_id RETURNING * INTO v_terms;
  PERFORM set_config('app.trade_scope_progress_id', COALESCE(v_previous_progress, ''), true);

  -- 00475 (R109 ceremony class): the client's acceptance, recorded. It is the
  -- client's act either way, so it proposes the thread-completion date and
  -- never pins it — the same downgrade the digital rail takes.
  SELECT d.project_id INTO v_project_id
  FROM public.project_commercial_documents d
  WHERE d.proposal_id = p_proposal_id;
  IF v_project_id IS NOT NULL THEN
    v_milestone_id := public._schedule_thread_completion_milestone(v_project_id);
    IF v_milestone_id IS NOT NULL THEN
      PERFORM public._commit_schedule_edit_authorized(
        v_project_id,
        jsonb_build_array(jsonb_build_object(
          'kind', 'milestone-anchor',
          'milestone_id', v_milestone_id,
          'anchor_date', to_char(p_paper_signed_on, 'YYYY-MM-DD'),
          'source_ref', p_proposal_id
        )),
        'Trade scope accepted',
        NULL,
        'ceremony:trade-scope-accepted'
      );
    END IF;
  END IF;

  RETURN jsonb_build_object('proposalId', p_proposal_id,
    'progressState', v_terms.progress_state,
    'acceptedAt', v_terms.accepted_at,
    'acceptedBy', v_terms.accepted_by,
    'acceptedSignedName', v_terms.accepted_signed_name,
    'acceptanceFingerprint', v_terms.acceptance_fingerprint,
    'acceptedOnPaper', v_terms.accepted_on_paper,
    'acceptanceRecordedBy', v_terms.acceptance_recorded_by,
    'acceptanceScanDocumentId', v_terms.acceptance_scan_document_id,
    'changed', true);
EXCEPTION WHEN OTHERS THEN
  PERFORM set_config('app.trade_scope_progress_id', COALESCE(v_previous_progress, ''), true);
  RAISE;
END;
$$;
ALTER FUNCTION public.record_paper_trade_acceptance(uuid,text,date,uuid) RESET ALL;
ALTER FUNCTION public.record_paper_trade_acceptance(uuid,text,date,uuid) SET search_path = pg_catalog, public, pg_temp;
ALTER FUNCTION public.record_paper_trade_acceptance(uuid,text,date,uuid) OWNER TO postgres;

CREATE OR REPLACE FUNCTION public.record_trade_scope_substantial_completion(
  p_proposal_id uuid
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, pg_temp
AS $$
DECLARE
  v_actor uuid := auth.uid();
  v_proposal public.proposals%ROWTYPE;
  v_terms public.trade_scope_terms%ROWTYPE;
  v_previous_progress text := current_setting('app.trade_scope_progress_id', true);
BEGIN
  SELECT * INTO v_proposal FROM public.proposals WHERE id = p_proposal_id FOR UPDATE;
  IF NOT FOUND OR v_proposal.document_kind <> 'trade_scope'
     OR v_actor IS NULL
     OR NOT public._can_author_proposal(v_proposal.designer_id)
  THEN
    RAISE EXCEPTION 'trade scope % not found or access denied', p_proposal_id
      USING ERRCODE = 'insufficient_privilege';
  END IF;
  SELECT * INTO v_terms FROM public.trade_scope_terms
  WHERE proposal_id = p_proposal_id FOR UPDATE;
  IF v_terms.progress_state = 'substantially_complete' THEN
    RETURN jsonb_build_object('proposalId', p_proposal_id,
      'progressState', v_terms.progress_state,
      'substantialCompletionAt', v_terms.substantial_completion_at,
      'changed', false);
  END IF;
  IF v_terms.progress_state NOT IN ('engaged', 'in_progress') THEN
    RAISE EXCEPTION 'a trade scope must be engaged before substantial completion'
      USING ERRCODE = 'check_violation';
  END IF;

  PERFORM set_config('app.trade_scope_progress_id', p_proposal_id::text, true);
  UPDATE public.trade_scope_terms SET
    progress_state = 'substantially_complete',
    substantial_completion_at = now(),
    substantial_completion_by = v_actor
  WHERE proposal_id = p_proposal_id RETURNING * INTO v_terms;
  PERFORM set_config('app.trade_scope_progress_id', COALESCE(v_previous_progress, ''), true);

  RETURN jsonb_build_object('proposalId', p_proposal_id,
    'progressState', v_terms.progress_state,
    'substantialCompletionAt', v_terms.substantial_completion_at,
    'substantialCompletionBy', v_terms.substantial_completion_by,
    'changed', true);
EXCEPTION WHEN OTHERS THEN
  PERFORM set_config('app.trade_scope_progress_id', COALESCE(v_previous_progress, ''), true);
  RAISE;
END;
$$;
ALTER FUNCTION public.record_trade_scope_substantial_completion(uuid) RESET ALL;
ALTER FUNCTION public.record_trade_scope_substantial_completion(uuid) SET search_path = pg_catalog, public, pg_temp;
ALTER FUNCTION public.record_trade_scope_substantial_completion(uuid) OWNER TO postgres;

CREATE OR REPLACE FUNCTION public.reissue_plan_transmittal_link(p_transmittal_id uuid)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, extensions, pg_temp
AS $$
DECLARE
  v_transmittal public.plan_transmittals%ROWTYPE;
  v_token       text;
  v_token_row   public.plan_transmittal_tokens%ROWTYPE;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'reissuing a link requires an authenticated designer'
      USING errcode = 'insufficient_privilege';
  END IF;

  SELECT * INTO v_transmittal FROM public.plan_transmittals WHERE id = p_transmittal_id;
  IF NOT FOUND OR NOT EXISTS (
    SELECT 1 FROM public.projects p
    WHERE p.id = v_transmittal.project_id AND public.is_design_studio_comember(p.designer_id)
  ) THEN
    RAISE EXCEPTION 'transmittal % not found or access denied', p_transmittal_id
      USING errcode = 'insufficient_privilege';
  END IF;

  UPDATE public.plan_transmittal_tokens SET status = 'revoked'
  WHERE transmittal_id = p_transmittal_id AND status = 'active';

  v_token := encode(extensions.gen_random_bytes(32), 'hex');
  INSERT INTO public.plan_transmittal_tokens (
    transmittal_id, project_id, token_hash, created_by
  ) VALUES (
    p_transmittal_id, v_transmittal.project_id,
    encode(extensions.digest(v_token, 'sha256'), 'hex'), auth.uid()
  ) RETURNING * INTO v_token_row;

  RETURN jsonb_build_object(
    'transmittalId', p_transmittal_id,
    'token', v_token,
    'expiresAt', v_token_row.expires_at
  );
END;
$$;
ALTER FUNCTION public.reissue_plan_transmittal_link(uuid) RESET ALL;
ALTER FUNCTION public.reissue_plan_transmittal_link(uuid) SET search_path = pg_catalog, public, extensions, pg_temp;
ALTER FUNCTION public.reissue_plan_transmittal_link(uuid) OWNER TO postgres;

CREATE OR REPLACE FUNCTION public.release_install_window(
  p_window_id        uuid,
  p_reason           text,
  p_disclosed_impact jsonb DEFAULT NULL
)
RETURNS uuid
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, pg_temp
AS $$
DECLARE
  v_actor   uuid := auth.uid();
  v_window  public.install_windows%ROWTYPE;
  v_current date;
  v_impact  jsonb;
  v_rows    integer;
BEGIN
  IF v_actor IS NULL THEN
    RAISE EXCEPTION 'release_install_window: no authenticated actor';
  END IF;

  SELECT * INTO v_window FROM public.install_windows
   WHERE id = p_window_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'install window % not found', p_window_id;
  END IF;

  IF NOT EXISTS (
    SELECT 1 FROM public.projects
    WHERE id = v_window.project_id AND public.is_studio_comember(designer_id)
  ) THEN
    RAISE EXCEPTION 'install window % not found', p_window_id;
  END IF;

  IF v_window.state = 'released' THEN
    RAISE EXCEPTION 'install window % is already released', p_window_id;
  END IF;

  -- I126: a release unpins what THIS window pinned, and nothing else.
  --
  -- Three states have to be told apart. A window that never anchored (a hold,
  -- or a confirmation the door downgraded) has nothing to remove — releasing
  -- it is bookkeeping. A window that anchored and whose date still stands
  -- unpins for real, disclosing its impact like any other movement. A window
  -- that anchored but whose phase now carries a DIFFERENT date was overtaken
  -- by another act: clearing there would destroy a date this ceremony never
  -- wrote, so the release proposes instead — forcing the NULL-impact branch
  -- records the wanted unpin without performing it.
  IF v_window.anchored AND v_window.phase_id IS NOT NULL THEN
    SELECT anchor_date INTO v_current
      FROM public.project_phases WHERE id = v_window.phase_id;

    IF v_current IS NOT NULL THEN
      v_impact := CASE WHEN v_current = v_window.starts_on
                       THEN p_disclosed_impact
                       ELSE NULL END;

      PERFORM public._commit_schedule_edit_authorized(
        v_window.project_id,
        jsonb_build_array(jsonb_build_object(
          'kind',       'phase-anchor',
          'phase_id',   v_window.phase_id,
          -- The unpin is stated, never implied: 00475's door raises on a bare
          -- or null date and takes `"clear": true` as the whole act. It is
          -- also why a release is never read as contradicting the anchor it
          -- removes.
          'clear',      true,
          'source_ref', v_window.id,
          'context',    COALESCE(p_disclosed_impact, '{}'::jsonb)
        )),
        COALESCE(NULLIF(btrim(p_reason), ''), 'Install window released'),
        v_impact,
        'ceremony:install-window-released'
      );
    END IF;
  END IF;

  UPDATE public.install_windows
     SET state                    = 'released',
         release_disclosed_impact = p_disclosed_impact
   WHERE id = p_window_id
     AND state <> 'released';
  GET DIAGNOSTICS v_rows = ROW_COUNT;
  IF v_rows = 0 THEN
    RAISE EXCEPTION 'install window % was released by another act while this one ran', p_window_id;
  END IF;

  RETURN p_window_id;
END;
$$;
ALTER FUNCTION public.release_install_window(uuid,text,jsonb) RESET ALL;
ALTER FUNCTION public.release_install_window(uuid,text,jsonb) SET search_path = pg_catalog, public, pg_temp;
ALTER FUNCTION public.release_install_window(uuid,text,jsonb) OWNER TO postgres;

CREATE OR REPLACE FUNCTION public.remove_proposal_phase(
  p_phase_id uuid,
  p_proposal_id uuid,
  p_expected_updated_at timestamptz
)
RETURNS public.proposal_phases
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, pg_temp
AS $$
DECLARE
  v_proposal public.proposals%ROWTYPE;
  v_phase public.proposal_phases%ROWTYPE;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'remove_proposal_phase requires an authenticated user'
      USING ERRCODE = 'insufficient_privilege';
  END IF;
  IF p_expected_updated_at IS NULL THEN
    RAISE EXCEPTION 'p_expected_updated_at is required'
      USING ERRCODE = 'invalid_parameter_value';
  END IF;

  SELECT * INTO v_proposal
  FROM public.proposals
  WHERE id = p_proposal_id
  FOR UPDATE;
  IF NOT FOUND OR NOT public._can_author_proposal(v_proposal.designer_id) THEN
    RAISE EXCEPTION 'proposal % not found or access denied', p_proposal_id
      USING ERRCODE = 'insufficient_privilege';
  END IF;
  IF v_proposal.status <> 'draft' THEN
    RAISE EXCEPTION 'proposal % is %, so its authored copy is immutable',
      p_proposal_id, v_proposal.status
      USING ERRCODE = 'check_violation';
  END IF;

  PERFORM phase.id
  FROM public.proposal_phases AS phase
  WHERE phase.proposal_id = p_proposal_id
  ORDER BY phase.id
  FOR UPDATE;
  PERFORM public._assert_proposal_phase_topology(
    p_proposal_id, 'remove_proposal_phase precondition'
  );

  SELECT * INTO v_phase
  FROM public.proposal_phases
  WHERE id = p_phase_id
    AND proposal_id = p_proposal_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'proposal phase % not found in proposal %',
      p_phase_id, p_proposal_id
      USING ERRCODE = 'insufficient_privilege';
  END IF;
  IF v_phase.updated_at IS DISTINCT FROM p_expected_updated_at THEN
    RAISE EXCEPTION 'proposal phase % changed since it was loaded', p_phase_id
      USING ERRCODE = 'serialization_failure';
  END IF;

  -- Preserve every direct branch. A main successor takes the deleted phase's
  -- predecessor; thread children are re-anchored to the same predecessor.
  UPDATE public.proposal_phases
  SET follows_phase_id = v_phase.follows_phase_id,
      updated_at = now()
  WHERE proposal_id = p_proposal_id
    AND follows_phase_id = p_phase_id;

  DELETE FROM public.proposal_phases
  WHERE id = p_phase_id
    AND proposal_id = p_proposal_id;

  PERFORM public._assert_proposal_phase_topology(
    p_proposal_id, 'remove_proposal_phase result'
  );
  PERFORM public._recompute_proposal_total_locked(p_proposal_id);
  RETURN v_phase;
END;
$$;
ALTER FUNCTION public.remove_proposal_phase(uuid,uuid,timestamp with time zone) RESET ALL;
ALTER FUNCTION public.remove_proposal_phase(uuid,uuid,timestamp with time zone) SET search_path = pg_catalog, public, pg_temp;
ALTER FUNCTION public.remove_proposal_phase(uuid,uuid,timestamp with time zone) OWNER TO postgres;

CREATE OR REPLACE FUNCTION public.reopen_client_decision(p_decision_id uuid)
RETURNS public.client_decisions
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, pg_temp
AS $$
DECLARE
  v_decision public.client_decisions%ROWTYPE;
BEGIN
  SELECT * INTO v_decision
  FROM public.client_decisions
  WHERE id = p_decision_id
  FOR UPDATE;

  IF NOT FOUND OR NOT public._can_author_proposal(v_decision.designer_id) THEN
    RAISE EXCEPTION 'decision % not found or access denied', p_decision_id
      USING ERRCODE = 'insufficient_privilege';
  END IF;
  IF v_decision.approval_contract = 'project_artifact_v1' THEN
    RAISE EXCEPTION 'Stage-2 project approvals cannot use generic reopen'
      USING ERRCODE = 'check_violation';
  END IF;
  IF v_decision.status = 'pending' THEN
    RETURN v_decision;
  END IF;
  IF v_decision.status NOT IN ('responded', 'expired') THEN
    RAISE EXCEPTION 'decision % cannot reopen from status %',
      p_decision_id, v_decision.status
      USING ERRCODE = 'check_violation';
  END IF;
  IF v_decision.linked_proposal_id IS NOT NULL THEN
    RAISE EXCEPTION 'proposal approval decisions are terminal'
      USING ERRCODE = 'check_violation';
  END IF;

  PERFORM set_config('app.client_decision_write_id', p_decision_id::text, true);
  UPDATE public.client_decision_options
  SET selected = false, client_note = NULL
  WHERE decision_id = p_decision_id;

  UPDATE public.client_decisions
  SET status = 'pending',
      due_date = CASE
        WHEN due_date IS NULL OR due_date > now() THEN due_date
        ELSE NULL
      END,
      responded_at = NULL,
      viewed_at = NULL,
      reminder_sent_at = NULL,
      selected_by = NULL,
      answer = NULL,
      answered_at = NULL,
      answered_by = NULL,
      client_consent_method = NULL,
      client_consented_at = NULL,
      client_signature = NULL,
      updated_at = now()
  WHERE id = p_decision_id
  RETURNING * INTO v_decision;
  PERFORM set_config('app.client_decision_write_id', '', true);
  PERFORM public._enqueue_decision_notification(
    p_decision_id, 'decision_required'
  );
  RETURN v_decision;
END;
$$;
ALTER FUNCTION public.reopen_client_decision(uuid) RESET ALL;
ALTER FUNCTION public.reopen_client_decision(uuid) SET search_path = pg_catalog, public, pg_temp;
ALTER FUNCTION public.reopen_client_decision(uuid) OWNER TO postgres;

CREATE OR REPLACE FUNCTION public.reorder_palette_swatches(
  p_proposal_id uuid,
  p_palette_id uuid,
  p_ordered_ids uuid[]
)
RETURNS void
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, pg_temp
AS $$
DECLARE
  v_actor uuid := auth.uid();
  v_proposal public.proposals%ROWTYPE;
  v_palette public.proposal_palettes%ROWTYPE;
  v_ids uuid[] := COALESCE(p_ordered_ids, ARRAY[]::uuid[]);
  v_expected integer;
  v_distinct integer;
  v_actual integer;
  v_matched integer;
  v_updated integer;
BEGIN
  IF v_actor IS NULL THEN
    RAISE EXCEPTION 'reorder_palette_swatches requires an authenticated user'
      USING ERRCODE = 'insufficient_privilege';
  END IF;

  SELECT * INTO v_proposal
  FROM public.proposals
  WHERE id = p_proposal_id
  FOR UPDATE;

  IF NOT FOUND OR NOT public._can_author_proposal(v_proposal.designer_id) THEN
    RAISE EXCEPTION
      'reorder_palette_swatches: proposal % not found or access denied',
      p_proposal_id
      USING ERRCODE = 'insufficient_privilege';
  END IF;

  -- Locking the palette blocks concurrent FK inserts, making the exact-set
  -- cardinality check stable through the single-statement update.
  SELECT * INTO v_palette
  FROM public.proposal_palettes
  WHERE id = p_palette_id
    AND proposal_id = p_proposal_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION
      'reorder_palette_swatches: palette % does not belong to proposal %',
      p_palette_id, p_proposal_id
      USING ERRCODE = 'check_violation';
  END IF;

  PERFORM 1
  FROM public.palette_swatches AS swatch
  WHERE swatch.palette_id = p_palette_id
  ORDER BY swatch.id
  FOR UPDATE;

  v_expected := cardinality(v_ids);

  IF array_position(v_ids, NULL::uuid) IS NOT NULL THEN
    RAISE EXCEPTION 'reorder_palette_swatches: ordering contains a null id'
      USING ERRCODE = 'check_violation';
  END IF;

  SELECT count(DISTINCT supplied.id)
  INTO v_distinct
  FROM unnest(v_ids) AS supplied(id);

  IF v_distinct <> v_expected THEN
    RAISE EXCEPTION
      'reorder_palette_swatches: ordering contains duplicate ids'
      USING ERRCODE = 'check_violation';
  END IF;

  SELECT count(*)
  INTO v_actual
  FROM public.palette_swatches AS swatch
  WHERE swatch.palette_id = p_palette_id;

  SELECT count(*)
  INTO v_matched
  FROM public.palette_swatches AS swatch
  WHERE swatch.palette_id = p_palette_id
    AND swatch.id = ANY(v_ids);

  IF v_expected <> v_actual OR v_matched <> v_actual THEN
    RAISE EXCEPTION
      'reorder_palette_swatches: ordering must contain the exact palette swatch set (% supplied, % matched, % required)',
      v_expected, v_matched, v_actual
      USING ERRCODE = 'check_violation';
  END IF;

  UPDATE public.palette_swatches AS swatch
  SET sort_order = supplied.ordinality - 1
  FROM unnest(v_ids) WITH ORDINALITY AS supplied(id, ordinality)
  WHERE swatch.id = supplied.id
    AND swatch.palette_id = p_palette_id;

  GET DIAGNOSTICS v_updated = ROW_COUNT;
  IF v_updated <> v_actual THEN
    RAISE EXCEPTION
      'reorder_palette_swatches: atomic update changed % of % rows',
      v_updated, v_actual
      USING ERRCODE = 'check_violation';
  END IF;
END;
$$;
ALTER FUNCTION public.reorder_palette_swatches(uuid,uuid,uuid[]) RESET ALL;
ALTER FUNCTION public.reorder_palette_swatches(uuid,uuid,uuid[]) SET search_path = pg_catalog, public, pg_temp;
ALTER FUNCTION public.reorder_palette_swatches(uuid,uuid,uuid[]) OWNER TO postgres;

CREATE OR REPLACE FUNCTION public.revise_project_ffe_configuration(
  p_project_id uuid,
  p_ffe_item_id uuid,
  p_expected_configuration_id uuid,
  p_expected_configuration_version integer,
  p_expected_snapshot_hash text,
  p_new_configuration_id uuid,
  p_expected_new_version integer
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, pg_temp
AS $$
DECLARE
  v_project public.projects;
  v_item public.project_ffe_items;
  v_spec public.project_ffe_specs;
  v_current public.product_configurations;
  v_new public.product_configurations;
  v_new_mode text;
  v_expected_unit integer;
  v_expected_trade integer;
  v_history jsonb;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'authentication required' USING errcode = 'insufficient_privilege';
  END IF;
  SELECT * INTO v_project FROM public.projects WHERE id = p_project_id FOR SHARE;
  IF NOT FOUND OR NOT public.is_design_studio_comember(v_project.designer_id) THEN
    RAISE EXCEPTION 'project not found or not accessible' USING errcode = 'insufficient_privilege';
  END IF;
  SELECT * INTO v_item FROM public.project_ffe_items
  WHERE id = p_ffe_item_id AND project_id = p_project_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'FF&E line not found in project' USING errcode = 'no_data_found';
  END IF;
  IF v_item.purchase_order_id IS NOT NULL
     OR v_item.status IN ('ordered','production','shipped','delivered','installed') THEN
    RAISE EXCEPTION 'ordered or fulfilled lines require a new FF&E line, not an in-place revision'
      USING errcode = 'object_not_in_prerequisite_state';
  END IF;
  SELECT * INTO v_spec FROM public.project_ffe_specs
  WHERE ffe_item_id = p_ffe_item_id FOR UPDATE;
  IF NOT FOUND OR v_spec.configuration_id IS DISTINCT FROM p_expected_configuration_id
     OR v_spec.configuration_snapshot_hash IS DISTINCT FROM p_expected_snapshot_hash THEN
    RAISE EXCEPTION 'project specification changed in another session'
      USING errcode = 'serialization_failure';
  END IF;
  IF NOT public._can_access_product_configuration(p_expected_configuration_id)
     OR NOT public._can_access_product_configuration(p_new_configuration_id) THEN
    RAISE EXCEPTION 'configuration not found or not accessible' USING errcode = 'insufficient_privilege';
  END IF;
  SELECT * INTO STRICT v_current FROM public.product_configurations
  WHERE id = p_expected_configuration_id FOR SHARE;
  SELECT * INTO STRICT v_new FROM public.product_configurations
  WHERE id = p_new_configuration_id FOR UPDATE;
  SELECT configuration_mode INTO STRICT v_new_mode
  FROM public.products WHERE id = v_new.product_id;
  IF v_new_mode = 'custom' THEN
    RAISE EXCEPTION 'custom commission changes require their approval/issuance lifecycle and a new project line'
      USING errcode = 'object_not_in_prerequisite_state';
  END IF;
  IF v_current.version <> p_expected_configuration_version
     OR v_new.version <> p_expected_new_version THEN
    RAISE EXCEPTION 'configuration version changed in another session'
      USING errcode = 'serialization_failure';
  END IF;
  IF v_spec.configuration_snapshot IS DISTINCT FROM v_current.snapshot
     OR v_current.snapshot_hash IS DISTINCT FROM p_expected_snapshot_hash
     OR v_current.snapshot_hash IS DISTINCT FROM public._configuration_snapshot_hash(v_current.snapshot) THEN
    RAISE EXCEPTION 'current project snapshot does not match its configuration source'
      USING errcode = 'object_not_in_prerequisite_state';
  END IF;
  IF v_new.id = v_current.id OR v_new.status <> 'saved'
     OR v_new.is_library_template
     OR v_new.project_id IS DISTINCT FROM p_project_id
     OR v_new.product_id IS DISTINCT FROM v_item.product_id
     OR (v_new.ffe_item_id IS NOT NULL AND v_new.ffe_item_id <> v_item.id)
     OR NOT v_new.is_valid OR NOT v_new.is_complete
     OR v_new.snapshot_hash IS DISTINCT FROM public._configuration_snapshot_hash(v_new.snapshot) THEN
    RAISE EXCEPTION 'replacement must be a valid, complete saved configuration instantiated for this project and product'
      USING errcode = 'object_not_in_prerequisite_state';
  END IF;

  v_expected_unit := COALESCE(v_new.retail_price_cents, v_new.trade_price_cents);
  v_expected_trade := COALESCE(v_new.trade_price_cents, v_new.retail_price_cents);
  v_history := COALESCE(v_spec.routing_source->'configurationHistory', '[]'::jsonb)
    || jsonb_build_array(jsonb_build_object(
      'fromConfigurationId', v_current.id,
      'fromVersion', v_current.version,
      'fromSnapshotHash', v_current.snapshot_hash,
      'toConfigurationId', v_new.id,
      'toVersion', v_new.version,
      'toSnapshotHash', v_new.snapshot_hash,
      'revisedBy', auth.uid(),
      'revisedAt', now()
    ));
  UPDATE public.product_configurations
  SET ffe_item_id = COALESCE(ffe_item_id, v_item.id), updated_at = now()
  WHERE id = v_new.id;

  PERFORM set_config('patina.configuration_spec_workflow', '00403', true);
  UPDATE public.project_ffe_specs
  SET configuration_id = v_new.id,
      configuration_snapshot = v_new.snapshot,
      configuration_snapshot_hash = v_new.snapshot_hash,
      configuration_locked_at = NULL,
      selected_dimensions = v_new.resolved_dimensions,
      sku = COALESCE(NULLIF(v_new.snapshot#>>'{variant,vendorSku}', ''),
        NULLIF(v_new.snapshot#>>'{variant,sku}', ''), sku),
      material = COALESCE((
        SELECT string_agg(selection->>'valueLabel', ', ' ORDER BY ordinality)
        FROM jsonb_array_elements(COALESCE(v_new.snapshot->'selections', '[]'::jsonb))
             WITH ORDINALITY AS chosen(selection, ordinality)
        WHERE lower(selection->>'groupCode') = 'material'
      ), material),
      finish = COALESCE((
        SELECT string_agg(selection->>'valueLabel', ', ' ORDER BY ordinality)
        FROM jsonb_array_elements(COALESCE(v_new.snapshot->'selections', '[]'::jsonb))
             WITH ORDINALITY AS chosen(selection, ordinality)
        WHERE lower(selection->>'groupCode') = 'finish'
      ), finish),
      color_fabric = COALESCE(NULLIF(public._configuration_com_color_fabric(
        COALESCE(v_new.com_details, v_new.snapshot->'comDetails')), ''), color_fabric),
      routing_source = routing_source || jsonb_build_object('configurationHistory', v_history),
      updated_by = auth.uid(), updated_at = now()
  WHERE id = v_spec.id;
  PERFORM set_config('patina.configuration_spec_workflow', '', true);
  UPDATE public.project_ffe_items
  SET status = 'specified',
      unit_price_cents = v_expected_unit,
      trade_price_cents = v_expected_trade,
      line_total_cents = CASE WHEN v_expected_unit IS NULL THEN NULL
        ELSE quantity * v_expected_unit END,
      updated_at = now()
  WHERE id = v_item.id;

  RETURN jsonb_build_object(
    'projectId', p_project_id,
    'ffeItemId', v_item.id,
    'specId', v_spec.id,
    'configurationId', v_new.id,
    'configurationVersion', v_new.version,
    'configurationSnapshotHash', v_new.snapshot_hash,
    'status', 'specified',
    'requiresApproval', true
  );
END;
$$;
ALTER FUNCTION public.revise_project_ffe_configuration(uuid,uuid,uuid,integer,text,uuid,integer) RESET ALL;
ALTER FUNCTION public.revise_project_ffe_configuration(uuid,uuid,uuid,integer,text,uuid,integer) SET search_path = pg_catalog, public, pg_temp;
ALTER FUNCTION public.revise_project_ffe_configuration(uuid,uuid,uuid,integer,text,uuid,integer) OWNER TO postgres;

CREATE OR REPLACE FUNCTION public.revoke_document_share(p_share_id uuid)
RETURNS boolean
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, pg_temp
AS $$
DECLARE
  v_n integer;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'authentication required'
      USING ERRCODE = 'insufficient_privilege';
  END IF;

  UPDATE public.document_shares AS share
  SET status = 'revoked'
  WHERE share.id = p_share_id
    AND (
      (
        share.proposal_id IS NOT NULL
        AND EXISTS (
          SELECT 1 FROM public.proposals AS proposal
          WHERE proposal.id = share.proposal_id
            AND public.is_design_studio_comember(proposal.designer_id)
        )
      )
      OR (
        share.spec_book_artifact_id IS NOT NULL
        AND EXISTS (
          SELECT 1
          FROM public.spec_book_artifacts AS artifact
          JOIN public.spec_book_revisions AS revision
            ON revision.id = artifact.revision_id
          JOIN public.spec_books AS book ON book.id = revision.spec_book_id
          JOIN public.projects AS project ON project.id = book.project_id
          WHERE artifact.id = share.spec_book_artifact_id
            AND public.is_design_studio_comember(project.designer_id)
        )
      )
      OR (
        share.board_id IS NOT NULL
        AND EXISTS (
          SELECT 1
          FROM public.proposal_boards AS board
          LEFT JOIN public.proposals AS proposal
            ON proposal.id = board.proposal_id
          LEFT JOIN public.projects AS project
            ON project.id = board.project_id
          WHERE board.id = share.board_id
            AND (
              (
                board.proposal_id IS NOT NULL
                AND public.is_design_studio_comember(proposal.designer_id)
              )
              OR (
                board.project_id IS NOT NULL
                AND public.is_design_studio_comember(project.designer_id)
              )
            )
        )
      )
    );

  GET DIAGNOSTICS v_n = ROW_COUNT;
  IF v_n = 0 THEN
    RAISE EXCEPTION 'share not found or not owned'
      USING ERRCODE = 'no_data_found';
  END IF;
  RETURN true;
END;
$$;
ALTER FUNCTION public.revoke_document_share(uuid) RESET ALL;
ALTER FUNCTION public.revoke_document_share(uuid) SET search_path = pg_catalog, public, pg_temp;
ALTER FUNCTION public.revoke_document_share(uuid) OWNER TO postgres;

CREATE OR REPLACE FUNCTION public.revoke_plan_transmittal_link(p_transmittal_id uuid)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, extensions, pg_temp
AS $$
DECLARE
  v_transmittal public.plan_transmittals%ROWTYPE;
  v_count       integer;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'revoking a link requires an authenticated designer'
      USING errcode = 'insufficient_privilege';
  END IF;

  SELECT * INTO v_transmittal FROM public.plan_transmittals WHERE id = p_transmittal_id;
  IF NOT FOUND OR NOT EXISTS (
    SELECT 1 FROM public.projects p
    WHERE p.id = v_transmittal.project_id AND public.is_design_studio_comember(p.designer_id)
  ) THEN
    RAISE EXCEPTION 'transmittal % not found or access denied', p_transmittal_id
      USING errcode = 'insufficient_privilege';
  END IF;

  WITH killed AS (
    UPDATE public.plan_transmittal_tokens SET status = 'revoked'
    WHERE transmittal_id = p_transmittal_id AND status = 'active'
    RETURNING 1
  )
  SELECT count(*) INTO v_count FROM killed;

  RETURN jsonb_build_object('revokedCount', v_count);
END;
$$;
ALTER FUNCTION public.revoke_plan_transmittal_link(uuid) RESET ALL;
ALTER FUNCTION public.revoke_plan_transmittal_link(uuid) SET search_path = pg_catalog, public, extensions, pg_temp;
ALTER FUNCTION public.revoke_plan_transmittal_link(uuid) OWNER TO postgres;

CREATE OR REPLACE FUNCTION public.rewire_legacy_proposal_phase_delete()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, pg_temp
AS $$
DECLARE
  v_proposal public.proposals%ROWTYPE;
BEGIN
  IF pg_trigger_depth() > 0
     AND NOT EXISTS (
       SELECT 1 FROM public.proposals AS proposal
       WHERE proposal.id = OLD.proposal_id
     )
  THEN
    RETURN OLD;
  END IF;

  IF auth.uid() IS NULL THEN
    RETURN OLD;
  END IF;

  IF TG_WHEN = 'BEFORE' THEN
    SELECT * INTO v_proposal
    FROM public.proposals
    WHERE id = OLD.proposal_id
    FOR UPDATE;
    IF NOT FOUND OR NOT public._can_author_proposal(v_proposal.designer_id) THEN
      RAISE EXCEPTION 'proposal % not found or access denied', OLD.proposal_id
        USING ERRCODE = 'insufficient_privilege';
    END IF;
    IF v_proposal.status <> 'draft' THEN
      RAISE EXCEPTION 'proposal % is %, so its authored copy is immutable',
        OLD.proposal_id, v_proposal.status
        USING ERRCODE = 'check_violation';
    END IF;

    PERFORM phase.id
    FROM public.proposal_phases AS phase
    WHERE phase.proposal_id = OLD.proposal_id
    ORDER BY phase.id
    FOR UPDATE;

    UPDATE public.proposal_phases
    SET follows_phase_id = OLD.follows_phase_id,
        updated_at = now()
    WHERE proposal_id = OLD.proposal_id
      AND follows_phase_id = OLD.id;
    RETURN OLD;
  END IF;

  PERFORM public._assert_proposal_phase_topology(
    OLD.proposal_id, 'legacy proposal phase delete result'
  );
  IF to_regprocedure('public._recompute_proposal_total_locked(uuid)') IS NOT NULL
  THEN
    PERFORM public._recompute_proposal_total_locked(OLD.proposal_id);
  END IF;
  RETURN OLD;
END;
$$;
ALTER FUNCTION public.rewire_legacy_proposal_phase_delete() RESET ALL;
ALTER FUNCTION public.rewire_legacy_proposal_phase_delete() SET search_path = pg_catalog, public, pg_temp;
ALTER FUNCTION public.rewire_legacy_proposal_phase_delete() OWNER TO postgres;

CREATE OR REPLACE FUNCTION public.save_board_as_template(
  p_board_id uuid,
  p_studio_id uuid,
  p_name text,
  p_description text DEFAULT NULL
)
RETURNS public.board_templates
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, extensions, pg_temp
AS $$
DECLARE
  v_board public.proposal_boards%ROWTYPE;
  v_owner_id uuid;
  v_items jsonb;
  v_template public.board_templates%ROWTYPE;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'authentication required'
      USING ERRCODE = 'insufficient_privilege';
  END IF;

  IF length(btrim(COALESCE(p_name, ''))) = 0 THEN
    RAISE EXCEPTION 'template name is required'
      USING ERRCODE = 'check_violation';
  END IF;

  SELECT board.*
  INTO v_board
  FROM public.proposal_boards AS board
  WHERE board.id = p_board_id
    AND board.status = 'active';

  IF NOT FOUND THEN
    RAISE EXCEPTION 'board not found or not accessible'
      USING ERRCODE = 'insufficient_privilege';
  END IF;

  SELECT COALESCE(proposal.designer_id, project.designer_id)
  INTO v_owner_id
  FROM (VALUES (1)) AS singleton(dummy)
  LEFT JOIN public.proposals AS proposal ON proposal.id = v_board.proposal_id
  LEFT JOIN public.projects AS project ON project.id = v_board.project_id;

  IF v_owner_id IS NULL
     OR NOT public.is_design_studio_comember(v_owner_id)
  THEN
    RAISE EXCEPTION 'board not found or not accessible'
      USING ERRCODE = 'insufficient_privilege';
  END IF;

  -- Both the caller and the board's owning designer must be active non-guest
  -- members of the exact active design_studio receiving the template.
  IF NOT EXISTS (
    SELECT 1
    FROM public.organizations AS studio
    JOIN public.organization_members AS actor_membership
      ON actor_membership.organization_id = studio.id
     AND actor_membership.user_id = auth.uid()
     AND actor_membership.status = 'active'
     AND actor_membership.role <> 'guest'
    JOIN public.organization_members AS owner_membership
      ON owner_membership.organization_id = studio.id
     AND owner_membership.user_id = v_owner_id
     AND owner_membership.status = 'active'
     AND owner_membership.role <> 'guest'
    WHERE studio.id = p_studio_id
      AND studio.type = 'design_studio'
      AND studio.status = 'active'
  ) THEN
    RAISE EXCEPTION 'template studio is not an authorized design workspace'
      USING ERRCODE = 'insufficient_privilege';
  END IF;

  SELECT COALESCE(jsonb_agg(jsonb_strip_nulls(jsonb_build_object(
    'type', item.type,
    'x', item.x,
    'y', item.y,
    'width', item.width,
    'height', item.height,
    'z_index', item.z_index,
    'rotation', item.rotation,
    'locked', item.locked,
    'image_url', item.image_url,
    'content', item.content,
    'data', public.sanitize_board_template_json(item.data)
  )) ORDER BY item.z_index, item.created_at, item.id), '[]'::jsonb)
  INTO v_items
  FROM public.proposal_board_items AS item
  WHERE item.board_id = p_board_id;

  INSERT INTO public.board_templates (
    template_key,
    name,
    description,
    kind,
    studio_id,
    canvas_width,
    canvas_height,
    background_color,
    sections,
    items,
    cover_url,
    created_by
  )
  VALUES (
    'studio.' || extensions.gen_random_uuid()::text,
    btrim(p_name),
    NULLIF(btrim(p_description), ''),
    'studio',
    p_studio_id,
    v_board.canvas_width,
    v_board.canvas_height,
    v_board.background_color,
    public.sanitize_board_template_json(v_board.sections),
    v_items,
    v_board.cover_image_url,
    auth.uid()
  )
  RETURNING * INTO v_template;

  RETURN v_template;
END;
$$;
ALTER FUNCTION public.save_board_as_template(uuid,uuid,text,text) RESET ALL;
ALTER FUNCTION public.save_board_as_template(uuid,uuid,text,text) SET search_path = pg_catalog, public, extensions, pg_temp;
ALTER FUNCTION public.save_board_as_template(uuid,uuid,text,text) OWNER TO postgres;

CREATE OR REPLACE FUNCTION public.seed_project_schedule_from_template(
  p_project_id uuid,
  p_template_slug text
)
RETURNS SETOF uuid
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, pg_temp
AS $$
DECLARE
  v_actor uuid := auth.uid();
  v_project public.projects%ROWTYPE;
  v_template public.phase_templates%ROWTYPE;
  v_phase_data jsonb;
  v_phase_id uuid;
  v_prev_phase_id uuid := NULL;
  v_sort integer := -1;
  v_previous_metadata_token text := current_setting(
    'app.phase_workflow_metadata_token', true
  );
  v_metadata_token_set boolean := false;
BEGIN
  IF v_actor IS NULL THEN
    RAISE EXCEPTION
      'seed_project_schedule_from_template requires an authenticated user'
      USING ERRCODE = 'insufficient_privilege';
  END IF;

  SELECT * INTO v_project
  FROM public.projects
  WHERE id = p_project_id
  FOR UPDATE;

  IF NOT FOUND OR NOT public._can_author_proposal(v_project.designer_id) THEN
    RAISE EXCEPTION
      'seed_project_schedule_from_template: project not found or access denied'
      USING ERRCODE = 'insufficient_privilege';
  END IF;

  IF EXISTS (
    SELECT 1
    FROM public.project_phases
    WHERE project_id = p_project_id
  ) THEN
    RAISE EXCEPTION
      'project % already has phases; the schedule is never rebuilt (R100)',
      p_project_id
      USING ERRCODE = 'check_violation';
  END IF;

  SELECT * INTO v_template
  FROM public.phase_templates
  WHERE slug = p_template_slug
    AND (is_system OR public._can_author_proposal(designer_id))
  FOR SHARE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'template not found or access denied: %', p_template_slug
      USING ERRCODE = 'insufficient_privilege';
  END IF;

  PERFORM set_config(
    'app.phase_workflow_metadata_token',
    format(
      'phase_workflow_metadata:project_phases:%s:%s',
      p_project_id,
      pg_catalog.txid_current()
    ),
    true
  );
  v_metadata_token_set := true;

  FOR v_phase_data IN
    SELECT value
    FROM jsonb_array_elements(v_template.phases)
  LOOP
    v_sort := v_sort + 1;

    SELECT created.id
    INTO v_phase_id
    FROM public.create_project_phase(
      p_project_id => p_project_id,
      p_phase_key => v_phase_data->>'phase_key',
      p_name => v_phase_data->>'name',
      p_sort_order => v_sort,
      p_duration_days => (v_phase_data->>'duration_days')::integer,
      p_follows_phase_id => v_prev_phase_id,
      p_lane => COALESCE(v_phase_data->>'lane', 'main'),
      p_duration_weeks => (v_phase_data->>'duration_weeks')::integer,
      p_fee_cents => COALESCE((v_phase_data->>'fee_cents')::integer, 0),
      p_revision_limit => COALESCE(
        (v_phase_data->>'revision_limit')::integer,
        2
      ),
      p_deliverables => COALESCE(
        v_phase_data->'deliverables',
        '[]'::jsonb
      )
    ) AS created;

    UPDATE public.project_phases
    SET canonical_stage_key = NULLIF(
          v_phase_data->>'canonical_stage_key', ''
        ),
        workflow_track = NULLIF(v_phase_data->>'workflow_track', ''),
        source_template_slug = v_template.slug,
        source_template_version = v_template.version
    WHERE id = v_phase_id;

    RETURN NEXT v_phase_id;
    v_prev_phase_id := v_phase_id;
  END LOOP;

  PERFORM set_config(
    'app.phase_workflow_metadata_token',
    COALESCE(v_previous_metadata_token, ''),
    true
  );
  v_metadata_token_set := false;
EXCEPTION WHEN OTHERS THEN
  IF v_metadata_token_set THEN
    PERFORM set_config(
      'app.phase_workflow_metadata_token',
      COALESCE(v_previous_metadata_token, ''),
      true
    );
  END IF;
  RAISE;
END;
$$;
ALTER FUNCTION public.seed_project_schedule_from_template(uuid,text) RESET ALL;
ALTER FUNCTION public.seed_project_schedule_from_template(uuid,text) SET search_path = pg_catalog, public, pg_temp;
ALTER FUNCTION public.seed_project_schedule_from_template(uuid,text) OWNER TO postgres;

CREATE OR REPLACE FUNCTION public.select_trade_bid(p_bid_id uuid)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, pg_temp
AS $$
DECLARE
  v_bid public.trade_scope_bids%ROWTYPE;
  v_proposal public.proposals%ROWTYPE;
  v_document public.project_commercial_documents%ROWTYPE;
  v_party public.project_parties%ROWTYPE;
BEGIN
  SELECT * INTO v_bid FROM public.trade_scope_bids WHERE id = p_bid_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'trade scope bid % not found or access denied', p_bid_id
      USING ERRCODE = 'insufficient_privilege';
  END IF;
  SELECT * INTO v_proposal FROM public.proposals
  WHERE id = v_bid.proposal_id FOR UPDATE;
  IF NOT FOUND OR v_proposal.document_kind <> 'trade_scope'
     OR auth.uid() IS NULL
     OR NOT public._can_author_proposal(v_proposal.designer_id)
  THEN
    RAISE EXCEPTION 'trade scope bid % not found or access denied', p_bid_id
      USING ERRCODE = 'insufficient_privilege';
  END IF;
  IF v_proposal.status <> 'draft' THEN
    RAISE EXCEPTION 'a trade scope bid may only be selected while the scope is a draft'
      USING ERRCODE = 'check_violation';
  END IF;

  -- The party is scoped to the project the scope is bound to, exactly as
  -- set_trade_scope_party scopes it. Selecting a bid is the OTHER way a party's
  -- identity gets frozen onto the signed terms, and it read project_parties as a
  -- SECURITY DEFINER (i.e. RLS-bypassing) lookup with no such check — so a bid
  -- naming a party from another project stamped that party's name, company and
  -- trade onto this document and handed the display name back to the caller.
  -- Resolved BEFORE the demote/promote, so a refusal leaves the bid ledger as it
  -- was rather than half-restated.
  SELECT * INTO v_document FROM public.project_commercial_documents
  WHERE proposal_id = v_bid.proposal_id;
  IF v_document.id IS NULL THEN
    RAISE EXCEPTION 'trade scope has no project binding'
      USING ERRCODE = 'check_violation';
  END IF;
  SELECT * INTO v_party FROM public.project_parties WHERE id = v_bid.party_id;
  IF NOT FOUND OR v_party.project_id IS DISTINCT FROM v_document.project_id THEN
    RAISE EXCEPTION 'party % does not belong to project %',
      v_bid.party_id, v_document.project_id
      USING ERRCODE = 'check_violation';
  END IF;

  -- Demote FIRST. uniq_trade_scope_selected_bid is a partial unique index, and
  -- promoting before demoting would collide with the incumbent inside the same
  -- statement sequence.
  UPDATE public.trade_scope_bids SET status = 'quoted'
  WHERE proposal_id = v_bid.proposal_id AND status = 'selected' AND id <> p_bid_id;
  UPDATE public.trade_scope_bids SET status = 'selected'
  WHERE id = p_bid_id RETURNING * INTO v_bid;

  UPDATE public.trade_scope_terms SET
    party_id = v_bid.party_id,
    party_display_name = COALESCE(v_party.display_name, v_bid.party_display_name),
    party_company_name = v_party.company_name,
    party_trade = v_party.trade
  WHERE proposal_id = v_bid.proposal_id;

  RETURN jsonb_build_object(
    'bidId', v_bid.id,
    'proposalId', v_bid.proposal_id,
    'partyId', v_bid.party_id,
    'partyDisplayName', COALESCE(v_party.display_name, v_bid.party_display_name),
    'amountCents', v_bid.amount_cents,
    'status', v_bid.status
  );
END;
$$;
ALTER FUNCTION public.select_trade_bid(uuid) RESET ALL;
ALTER FUNCTION public.select_trade_bid(uuid) SET search_path = pg_catalog, public, pg_temp;
ALTER FUNCTION public.select_trade_bid(uuid) OWNER TO postgres;

CREATE OR REPLACE FUNCTION public.send_commercial_document(
  p_proposal_id uuid,
  p_expected_fingerprint text,
  p_personal_message text DEFAULT NULL,
  p_valid_until timestamptz DEFAULT NULL
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, pg_temp
AS $$
DECLARE
  v_proposal public.proposals%ROWTYPE;
  v_current_fingerprint text;
  v_dispatch_id uuid := extensions.gen_random_uuid();
  v_client_email text;
  v_client_name text;
  v_designer_name text;
  v_identity_name text;
  v_identity_logo text;
  v_identity_source text;
  v_sender_name text;
  v_studio_name text;
  v_studio_logo text;
  v_terms public.trade_scope_terms%ROWTYPE;
  v_draw_total bigint;
  v_allocation_total bigint;
  v_allocation_count integer;
  v_section_count integer;
  v_draw_count integer;
  v_gate_count integer;
  v_gate_sort integer;
  v_max_sort integer;
  v_first_gates boolean;
  v_percentage_count integer;
  v_percentage_total numeric;
  v_previous_send text := current_setting('app.proposal_send_id', true);
  v_previous_dispatch text := current_setting('app.proposal_send_dispatch_link', true);
BEGIN
  SELECT * INTO v_proposal FROM public.proposals
  WHERE id = p_proposal_id FOR UPDATE;
  IF NOT FOUND OR v_proposal.status <> 'draft' OR v_proposal.document_kind = 'legacy'
     OR NOT public._can_author_proposal(v_proposal.designer_id)
  THEN
    RAISE EXCEPTION 'commercial draft % not found or access denied', p_proposal_id
      USING ERRCODE = 'insufficient_privilege';
  END IF;
  v_current_fingerprint := public._commercial_document_fingerprint(p_proposal_id);
  IF v_current_fingerprint IS DISTINCT FROM p_expected_fingerprint THEN
    RAISE EXCEPTION 'commercial document changed after review; refresh before sending'
      USING ERRCODE = 'serialization_failure';
  END IF;

  IF v_proposal.client_id IS NULL OR v_proposal.designer_client_id IS NULL
     OR NOT EXISTS (
       SELECT 1 FROM public.designer_clients dc
       WHERE dc.id = v_proposal.designer_client_id
         AND dc.designer_id = v_proposal.designer_id
         AND dc.client_id = v_proposal.client_id
     )
  THEN
    RAISE EXCEPTION 'commercial document requires an exact client relationship before sending'
      USING ERRCODE = 'check_violation';
  END IF;
  IF v_proposal.document_kind IN ('design_services', 'service_addendum') AND (
    NOT EXISTS (SELECT 1 FROM public.proposal_service_terms t WHERE t.proposal_id = p_proposal_id)
    OR NOT EXISTS (SELECT 1 FROM public.proposal_service_rates r WHERE r.proposal_id = p_proposal_id)
  ) THEN
    RAISE EXCEPTION 'design-services send requires terms and role rates'
      USING ERRCODE = 'check_violation';
  END IF;
  IF v_proposal.document_kind = 'furnishings_authorization' AND NOT EXISTS (
    SELECT 1 FROM public.project_commercial_documents d
    JOIN public.furnishing_authorization_items i ON i.commercial_document_id = d.id
    WHERE d.proposal_id = p_proposal_id
      AND EXISTS (SELECT 1 FROM public.project_budget_checkpoints c
        WHERE c.id = d.budget_checkpoint_id AND c.status IN ('acknowledged', 'overridden'))
  ) THEN
    RAISE EXCEPTION 'furnishings send requires a valid checkpoint and item snapshot'
      USING ERRCODE = 'check_violation';
  END IF;

  -- 00423: the trade arm. A scope is only a document when it says WHO does the
  -- work, WHAT the work is, WHAT it costs, and WHEN the client pays — and when
  -- the last two agree to the cent.
  IF v_proposal.document_kind = 'trade_scope' THEN
    SELECT * INTO v_terms FROM public.trade_scope_terms
    WHERE proposal_id = p_proposal_id;
    IF v_terms.proposal_id IS NULL OR v_terms.party_id IS NULL
       OR COALESCE(v_terms.client_price_cents, 0) <= 0 THEN
      RAISE EXCEPTION 'trade scope send requires a named party and a client price'
        USING ERRCODE = 'check_violation';
    END IF;

    SELECT count(*) INTO v_section_count FROM public.trade_scope_sections
    WHERE proposal_id = p_proposal_id;
    IF v_section_count = 0 THEN
      RAISE EXCEPTION 'trade scope send requires at least one scope section'
        USING ERRCODE = 'check_violation';
    END IF;

    SELECT count(*), COALESCE(sum(amount_cents), 0),
           count(*) FILTER (WHERE gates_on_acceptance),
           max(sort_order),
           max(sort_order) FILTER (WHERE gates_on_acceptance)
    INTO v_draw_count, v_draw_total, v_gate_count, v_max_sort, v_gate_sort
    FROM public.trade_scope_draws WHERE proposal_id = p_proposal_id;
    IF v_draw_count = 0 THEN
      RAISE EXCEPTION 'trade scope send requires at least one draw'
        USING ERRCODE = 'check_violation';
    END IF;
    IF v_draw_total IS DISTINCT FROM v_terms.client_price_cents::bigint THEN
      RAISE EXCEPTION 'trade scope draw schedule must sum to the client price'
        USING ERRCODE = 'check_violation';
    END IF;
    IF v_gate_count <> 1 THEN
      RAISE EXCEPTION 'trade scope draw schedule must have exactly one acceptance-gated draw'
        USING ERRCODE = 'check_violation';
    END IF;
    IF v_gate_sort IS DISTINCT FROM v_max_sort THEN
      RAISE EXCEPTION 'the acceptance-gated draw must be the last draw in the schedule'
        USING ERRCODE = 'check_violation';
    END IF;

    -- The one-gate and gate-is-last rules hold TRIVIALLY on a single-draw
    -- schedule: with one row, min sort_order = max sort_order, so a lone 100%
    -- "Final · on acceptance" draw satisfies every check above. Execution then
    -- bills the lowest-sort draw at signature — which would invoice the client
    -- the whole scope price the moment they sign, on the strength of a document
    -- that says the money is due on acceptance. The first draw is the deposit by
    -- construction, so it is the one draw that cannot gate. Same selector the
    -- execute rail uses (sort_order, id), so the two can never disagree about
    -- which draw is first.
    SELECT w.gates_on_acceptance INTO v_first_gates
    FROM public.trade_scope_draws w
    WHERE w.proposal_id = p_proposal_id
    ORDER BY w.sort_order, w.id LIMIT 1;
    IF COALESCE(v_first_gates, false) THEN
      RAISE EXCEPTION 'the first draw is billed at signature, so it must not be the acceptance-gated one'
        USING ERRCODE = 'check_violation';
    END IF;

    -- Percentage is display and amount_cents is the money, but a display figure
    -- that contradicts the money beside it is a second payment plan on the same
    -- page — and the client's document renders both. So when the studio states
    -- percentages at all, they must total 100 and each must describe its own
    -- amount. The tolerances are the honest ones: half a point for the total (a
    -- 33.3/33.3/33.4 schedule is a real schedule), and a dollar per line for the
    -- rounding an exact-cents split of an odd price forces.
    SELECT count(*) FILTER (WHERE w.percentage IS NOT NULL),
           COALESCE(sum(w.percentage), 0)
    INTO v_percentage_count, v_percentage_total
    FROM public.trade_scope_draws w WHERE w.proposal_id = p_proposal_id;
    IF v_percentage_count > 0 THEN
      IF abs(v_percentage_total - 100) > 0.5 THEN
        RAISE EXCEPTION 'trade scope draw percentages must total 100'
          USING ERRCODE = 'check_violation';
      END IF;
      IF EXISTS (
        SELECT 1 FROM public.trade_scope_draws w
        WHERE w.proposal_id = p_proposal_id AND w.percentage IS NOT NULL
          AND abs(round(v_terms.client_price_cents * w.percentage / 100.0)
                  - w.amount_cents) > 100
      ) THEN
        RAISE EXCEPTION 'each trade scope draw percentage must match the amount beside it'
          USING ERRCODE = 'check_violation';
      END IF;
    END IF;

    -- Allocations are optional as a SET. Once the studio starts apportioning the
    -- price across rooms, the apportionment must be complete and exact — a
    -- half-allocated scope tells the client a room costs $X and leaves the rest
    -- of the money unaccounted for.
    SELECT count(*) FILTER (WHERE allocation_cents IS NOT NULL),
           COALESCE(sum(allocation_cents), 0)
    INTO v_allocation_count, v_allocation_total
    FROM public.trade_scope_sections WHERE proposal_id = p_proposal_id;
    IF v_allocation_count > 0
       AND (v_allocation_count <> v_section_count
            OR v_allocation_total IS DISTINCT FROM v_terms.client_price_cents::bigint) THEN
      RAISE EXCEPTION 'trade scope section allocations must sum to the client price'
        USING ERRCODE = 'check_violation';
    END IF;
  END IF;

  PERFORM 1 FROM public.proposal_service_terms
  WHERE proposal_id = p_proposal_id FOR UPDATE;
  PERFORM 1 FROM public.proposal_service_rates
  WHERE proposal_id = p_proposal_id ORDER BY id FOR UPDATE;
  PERFORM i.id FROM public.furnishing_authorization_items i
  JOIN public.project_commercial_documents d ON d.id = i.commercial_document_id
  WHERE d.proposal_id = p_proposal_id ORDER BY i.id FOR UPDATE OF i;
  PERFORM 1 FROM public.trade_scope_terms
  WHERE proposal_id = p_proposal_id FOR UPDATE;
  PERFORM 1 FROM public.trade_scope_sections
  WHERE proposal_id = p_proposal_id ORDER BY id FOR UPDATE;
  PERFORM 1 FROM public.trade_scope_draws
  WHERE proposal_id = p_proposal_id ORDER BY id FOR UPDATE;
  IF public._commercial_document_fingerprint(p_proposal_id)
     IS DISTINCT FROM p_expected_fingerprint THEN
    RAISE EXCEPTION 'commercial document changed while sending; refresh before sending'
      USING ERRCODE = 'serialization_failure';
  END IF;

  PERFORM set_config('app.proposal_send_id', p_proposal_id::text, true);
  UPDATE public.proposals SET
    status = 'sent', sent_at = now(),
    total_amount = CASE
      WHEN v_proposal.document_kind = 'trade_scope'
        THEN COALESCE(v_terms.client_price_cents, total_amount)
      ELSE total_amount END,
    personal_message = COALESCE(p_personal_message, personal_message),
    valid_until = COALESCE(p_valid_until, valid_until), updated_at = now()
  WHERE id = p_proposal_id RETURNING * INTO v_proposal;
  PERFORM set_config('app.proposal_send_id', COALESCE(v_previous_send, ''), true);

  -- The UPDATE above writes hashed fields — total_amount for a trade scope, and
  -- valid_until / personal_message on every rail — so the fingerprint verified
  -- twice before the write is no longer the hash of the document that just left.
  -- Recompute, so what the caller is handed is what
  -- _commercial_document_fingerprint answers about this document now. (Nothing
  -- after this point touches a hashed column: proposal_send_dispatch_id, status,
  -- sent_at and updated_at are all outside _proposal_review_fingerprint.)
  v_current_fingerprint := public._commercial_document_fingerprint(p_proposal_id);

  SELECT profile.email, profile.full_name INTO v_client_email, v_client_name
  FROM public.profiles profile WHERE profile.id = v_proposal.client_id;
  IF NULLIF(btrim(COALESCE(v_client_email, '')), '') IS NULL THEN
    RAISE EXCEPTION 'commercial document client must have an email before sending'
      USING ERRCODE = 'check_violation';
  END IF;
  SELECT COALESCE(profile.full_name, profile.display_name) INTO v_designer_name
  FROM public.profiles profile WHERE profile.id = v_proposal.designer_id;
  SELECT identity.name, identity.logo_url, identity.source
  INTO v_identity_name, v_identity_logo, v_identity_source
  FROM public.resolve_studio_identity(v_proposal.project_id, v_proposal.designer_id) identity;
  v_designer_name := COALESCE(NULLIF(btrim(v_designer_name), ''),
    NULLIF(btrim(v_identity_name), ''), 'Your designer');
  v_sender_name := COALESCE(NULLIF(btrim(v_identity_name), ''), v_designer_name);
  IF v_identity_source IN ('studio', 'business_name') THEN
    v_studio_name := NULLIF(btrim(v_identity_name), '');
    v_studio_logo := NULLIF(btrim(v_identity_logo), '');
  END IF;

  INSERT INTO public.proposal_send_dispatches (
    id, proposal_id, sent_at, designer_id, client_id, project_id,
    proposal_title, personal_message, valid_until, total_amount,
    recipient_email, recipient_name, designer_name, sender_name,
    studio_name, studio_logo_url, client_portal_path,
    provider_idempotency_key, email_log_id, in_app_log_id
  ) VALUES (
    v_dispatch_id, v_proposal.id, v_proposal.sent_at, v_proposal.designer_id,
    v_proposal.client_id, v_proposal.project_id, v_proposal.title,
    v_proposal.personal_message, v_proposal.valid_until, v_proposal.total_amount,
    v_client_email, v_client_name, v_designer_name, v_sender_name,
    v_studio_name, v_studio_logo, '/proposals/' || v_proposal.id::text,
    'proposal-send/' || v_dispatch_id::text,
    extensions.uuid_generate_v5('eb7b4041-796a-4c77-bd4d-817d2437917f'::uuid,
      'proposal-send/email/' || v_dispatch_id::text),
    extensions.uuid_generate_v5('eb7b4041-796a-4c77-bd4d-817d2437917f'::uuid,
      'proposal-send/in-app/' || v_dispatch_id::text)
  );
  PERFORM set_config('app.proposal_send_dispatch_link',
    v_proposal.id::text || ':' || v_dispatch_id::text, true);
  UPDATE public.proposals SET proposal_send_dispatch_id = v_dispatch_id
  WHERE id = v_proposal.id AND proposal_send_dispatch_id IS NULL
  RETURNING * INTO v_proposal;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'commercial document send dispatch link already exists'
      USING ERRCODE = 'check_violation';
  END IF;
  PERFORM set_config('app.proposal_send_dispatch_link', COALESCE(v_previous_dispatch, ''), true);

  RETURN jsonb_build_object(
    'proposalId', v_proposal.id,
    'documentKind', v_proposal.document_kind,
    'commercialState', 'sent',
    'status', v_proposal.status,
    'sentAt', v_proposal.sent_at,
    'proposalSendDispatchId', v_proposal.proposal_send_dispatch_id,
    'proposal_send_dispatch_id', v_proposal.proposal_send_dispatch_id,
    'updatedAt', v_proposal.updated_at,
    'documentFingerprint', v_current_fingerprint
  );
EXCEPTION WHEN OTHERS THEN
  PERFORM set_config('app.proposal_send_id', COALESCE(v_previous_send, ''), true);
  PERFORM set_config('app.proposal_send_dispatch_link', COALESCE(v_previous_dispatch, ''), true);
  RAISE;
END;
$$;
ALTER FUNCTION public.send_commercial_document(uuid,text,text,timestamp with time zone) RESET ALL;
ALTER FUNCTION public.send_commercial_document(uuid,text,text,timestamp with time zone) SET search_path = pg_catalog, public, pg_temp;
ALTER FUNCTION public.send_commercial_document(uuid,text,text,timestamp with time zone) OWNER TO postgres;

CREATE OR REPLACE FUNCTION public.send_proposal(
  p_proposal_id uuid,
  p_expected_updated_at timestamptz,
  p_expected_total_amount integer,
  p_expected_schedule_fingerprint text,
  p_personal_message text DEFAULT NULL,
  p_cc_email text DEFAULT NULL,
  p_valid_until timestamptz DEFAULT NULL
)
RETURNS public.proposals
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, pg_temp
AS $$
DECLARE
  v_designer_id uuid;
  v_document_kind text;
  v_project_id uuid;
  v_status text;
  v_result public.proposals;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'send_proposal requires an authenticated studio author'
      USING ERRCODE = 'insufficient_privilege';
  END IF;

  SELECT proposal.designer_id, proposal.document_kind, proposal.project_id,
         proposal.status
  INTO v_designer_id, v_document_kind, v_project_id, v_status
  FROM public.proposals AS proposal
  WHERE proposal.id = p_proposal_id
  FOR UPDATE;

  IF NOT FOUND OR NOT public._can_author_proposal(v_designer_id) THEN
    RAISE EXCEPTION 'send_proposal: proposal % not found or access denied',
      p_proposal_id
      USING ERRCODE = 'insufficient_privilege';
  END IF;

  -- 00414: two send seams, one per rail. A commercial edition carries terms,
  -- rates, checkpoint, or snapshot preconditions this body never evaluates.
  IF v_document_kind <> 'legacy' THEN
    RAISE EXCEPTION 'commercial documents send through send_commercial_document'
      USING ERRCODE = 'check_violation';
  END IF;

  -- A legacy DRAFT already bound to a project is the internal authoring
  -- vehicle create_furnishings_authorization snapshots. It is never the thing
  -- a client receives — the wave edition minted from it is. The refusal is
  -- scoped to exactly that shape: an activated legacy proposal also carries a
  -- project back-link (activate_proposal_as_project writes it), and refusing
  -- on project_id alone would answer for a population this seam never meant to
  -- name. Non-draft rows keep the base body's own answer
  -- ('proposal must be in draft status before sending', _commit_proposal_send),
  -- which is the only status send_proposal has ever processed.
  IF v_document_kind = 'legacy' AND v_project_id IS NOT NULL
     AND v_status = 'draft' THEN
    RAISE EXCEPTION 'project-bound furnishing drafts are internal authoring vehicles; send their wave'
      USING ERRCODE = 'check_violation';
  END IF;

  PERFORM deliverable.id
  FROM public.proposal_phase_deliverables AS deliverable
  JOIN public.proposal_phases AS phase ON phase.id = deliverable.phase_id
  WHERE phase.proposal_id = p_proposal_id
  ORDER BY deliverable.id
  FOR UPDATE OF deliverable;

  PERFORM gate.id
  FROM public.proposal_phase_gates AS gate
  JOIN public.proposal_phases AS phase ON phase.id = gate.phase_id
  WHERE phase.proposal_id = p_proposal_id
  ORDER BY gate.id
  FOR UPDATE OF gate;

  PERFORM milestone.id
  FROM public.proposal_schedule_milestones AS milestone
  JOIN public.proposal_phases AS phase ON phase.id = milestone.phase_id
  WHERE phase.proposal_id = p_proposal_id
  ORDER BY milestone.id
  FOR UPDATE OF milestone;

  SELECT sent.* INTO v_result
  FROM public._send_proposal_with_dispatch(
    p_proposal_id,
    p_expected_updated_at,
    p_expected_total_amount,
    p_expected_schedule_fingerprint,
    p_personal_message,
    p_cc_email,
    p_valid_until
  ) AS sent;

  RETURN v_result;
END;
$$;
ALTER FUNCTION public.send_proposal(uuid,timestamp with time zone,integer,text,text,text,timestamp with time zone) RESET ALL;
ALTER FUNCTION public.send_proposal(uuid,timestamp with time zone,integer,text,text,text,timestamp with time zone) SET search_path = pg_catalog, public, pg_temp;
ALTER FUNCTION public.send_proposal(uuid,timestamp with time zone,integer,text,text,text,timestamp with time zone) OWNER TO postgres;

CREATE OR REPLACE FUNCTION public.set_plan_sheet_state(
  p_sheet_id uuid,
  p_state text
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, extensions, pg_temp
AS $$
DECLARE
  v_sheet public.plan_sheets%ROWTYPE;
  v_doc   record;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'sharing a plan sheet requires an authenticated designer'
      USING errcode = 'insufficient_privilege';
  END IF;
  IF p_state IS NULL OR p_state NOT IN ('draft', 'shared') THEN
    RAISE EXCEPTION 'a plan sheet is either draft or shared'
      USING errcode = 'check_violation';
  END IF;

  -- Authority BEFORE the lock, and one answer for both misses. Locking first
  -- would let an unauthorized caller hold a foreign row for the length of the
  -- refusal, and answering 'not found' separately from 'access denied' would
  -- turn this RPC into an existence oracle for other studios' sheets (00424's
  -- non-enumeration posture).
  IF NOT EXISTS (
    SELECT 1 FROM public.plan_sheets s
    JOIN public.projects p ON p.id = s.project_id
    WHERE s.id = p_sheet_id AND public.is_design_studio_comember(p.designer_id)
  ) THEN
    RAISE EXCEPTION 'plan sheet % not found or access denied', p_sheet_id
      USING errcode = 'insufficient_privilege';
  END IF;

  SELECT * INTO v_sheet FROM public.plan_sheets WHERE id = p_sheet_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'plan sheet % not found or access denied', p_sheet_id
      USING errcode = 'insufficient_privilege';
  END IF;
  IF p_state = 'shared' AND v_sheet.current_print_id IS NULL THEN
    RAISE EXCEPTION 'a sheet with no filed print cannot be shared'
      USING errcode = 'check_violation';
  END IF;

  PERFORM set_config('app.plan_room_sheet_maintenance', v_sheet.id::text, true);
  UPDATE public.plan_sheets SET state = p_state WHERE id = v_sheet.id
  RETURNING * INTO v_sheet;
  PERFORM set_config('app.plan_room_sheet_maintenance', '', true);

  FOR v_doc IN
    SELECT pp.project_document_id AS doc_id,
           (pp.id = v_sheet.current_print_id) AS is_current
    FROM public.plan_prints pp
    WHERE pp.sheet_id = v_sheet.id
  LOOP
    PERFORM public._plan_room_set_doc_visibility(
      v_doc.doc_id, p_state = 'shared' AND v_doc.is_current);
  END LOOP;

  RETURN jsonb_build_object(
    'id', v_sheet.id,
    'projectId', v_sheet.project_id,
    'sheetNumber', v_sheet.sheet_number,
    'title', v_sheet.title,
    'discipline', v_sheet.discipline,
    'state', v_sheet.state,
    'currentPrintNumber', v_sheet.current_print_number,
    'currentPrintId', v_sheet.current_print_id,
    'sortOrder', v_sheet.sort_order,
    'updatedAt', v_sheet.updated_at
  );
END;
$$;
ALTER FUNCTION public.set_plan_sheet_state(uuid,text) RESET ALL;
ALTER FUNCTION public.set_plan_sheet_state(uuid,text) SET search_path = pg_catalog, public, extensions, pg_temp;
ALTER FUNCTION public.set_plan_sheet_state(uuid,text) OWNER TO postgres;

CREATE OR REPLACE FUNCTION public.set_project_decision_authority(
  p_project_id uuid,
  p_decision_lead_id uuid,
  p_required_coapprover_id uuid,
  p_expected_revision integer
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, pg_temp
AS $$
DECLARE
  v_actor uuid := auth.uid();
  v_project public.projects%ROWTYPE;
  v_authority public.project_decision_authorities%ROWTYPE;
  v_authority_exists boolean;
  v_previous_capability text := current_setting(
    'app.project_decision_authority_project_id', true
  );
BEGIN
  IF v_actor IS NULL THEN
    RAISE EXCEPTION 'authority assignment requires an authenticated studio actor'
      USING ERRCODE = 'insufficient_privilege';
  END IF;
  IF p_expected_revision IS NULL OR p_expected_revision < 0 THEN
    RAISE EXCEPTION 'expected authority revision must be zero or greater'
      USING ERRCODE = 'invalid_parameter_value';
  END IF;

  SELECT * INTO v_project
  FROM public.projects AS project
  WHERE project.id = p_project_id
  FOR UPDATE;
  IF NOT FOUND OR NOT public.is_design_studio_comember(v_project.designer_id) THEN
    RAISE EXCEPTION 'project not found or authority assignment denied'
      USING ERRCODE = 'insufficient_privilege';
  END IF;
  IF v_project.client_id IS NULL
     OR p_decision_lead_id IS DISTINCT FROM v_project.client_id
  THEN
    RAISE EXCEPTION 'decision lead must be the exact project client'
      USING ERRCODE = 'check_violation';
  END IF;
  IF p_required_coapprover_id IS NOT NULL THEN
    RAISE EXCEPTION 'coapprover requires a durable household-membership source'
      USING ERRCODE = 'check_violation';
  END IF;
  IF NOT EXISTS (
    SELECT 1 FROM public.profiles AS profile
    WHERE profile.id = p_decision_lead_id
  ) THEN
    RAISE EXCEPTION 'decision lead profile does not exist'
      USING ERRCODE = 'check_violation';
  END IF;

  SELECT * INTO v_authority
  FROM public.project_decision_authorities AS authority
  WHERE authority.project_id = p_project_id
  FOR UPDATE;
  v_authority_exists := FOUND;

  PERFORM set_config(
    'app.project_decision_authority_project_id', p_project_id::text, true
  );
  IF NOT v_authority_exists THEN
    IF p_expected_revision <> 0 THEN
      RAISE EXCEPTION 'authority revision conflict: expected 0 for first assignment'
        USING ERRCODE = 'serialization_failure';
    END IF;
    INSERT INTO public.project_decision_authorities (
      project_id, decision_lead_id, required_coapprover_id,
      revision, assigned_by
    ) VALUES (
      p_project_id, p_decision_lead_id, NULL, 1, v_actor
    ) RETURNING * INTO v_authority;
  ELSE
    IF v_authority.revision IS DISTINCT FROM p_expected_revision THEN
      RAISE EXCEPTION 'authority revision conflict: expected %, actual %',
        p_expected_revision, v_authority.revision
        USING ERRCODE = 'serialization_failure';
    END IF;
    UPDATE public.project_decision_authorities
    SET decision_lead_id = p_decision_lead_id,
        required_coapprover_id = NULL,
        revision = v_authority.revision + 1,
        assigned_by = v_actor
    WHERE project_id = p_project_id
    RETURNING * INTO v_authority;
  END IF;
  PERFORM set_config(
    'app.project_decision_authority_project_id',
    COALESCE(v_previous_capability, ''), true
  );

  RETURN jsonb_build_object(
    'projectId', v_authority.project_id,
    'decisionLeadId', v_authority.decision_lead_id,
    'requiredCoapproverId', v_authority.required_coapprover_id,
    'revision', v_authority.revision,
    'assignedBy', v_authority.assigned_by,
    'assignedAt', v_authority.assigned_at,
    'updatedAt', v_authority.updated_at
  );
EXCEPTION WHEN OTHERS THEN
  PERFORM set_config(
    'app.project_decision_authority_project_id',
    COALESCE(v_previous_capability, ''), true
  );
  RAISE;
END;
$$;
ALTER FUNCTION public.set_project_decision_authority(uuid,uuid,uuid,integer) RESET ALL;
ALTER FUNCTION public.set_project_decision_authority(uuid,uuid,uuid,integer) SET search_path = pg_catalog, public, pg_temp;
ALTER FUNCTION public.set_project_decision_authority(uuid,uuid,uuid,integer) OWNER TO postgres;

CREATE OR REPLACE FUNCTION public.set_project_operational_status(
  p_project_id uuid,
  p_expected_status public.project_status,
  p_status public.project_status
)
RETURNS public.projects
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, pg_temp
AS $$
DECLARE
  v_project public.projects%ROWTYPE;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'set_project_operational_status requires an authenticated user'
      USING ERRCODE = 'insufficient_privilege';
  END IF;
  IF p_status NOT IN ('active', 'on_hold') THEN
    RAISE EXCEPTION 'operational status must be active or on_hold'
      USING ERRCODE = 'invalid_parameter_value';
  END IF;

  SELECT * INTO v_project
  FROM public.projects
  WHERE id = p_project_id
  FOR UPDATE;

  IF NOT FOUND OR NOT public._can_author_proposal(v_project.designer_id) THEN
    RAISE EXCEPTION 'project % not found or access denied', p_project_id
      USING ERRCODE = 'insufficient_privilege';
  END IF;
  IF v_project.status IS DISTINCT FROM p_expected_status THEN
    RAISE EXCEPTION 'project % changed since it was loaded', p_project_id
      USING ERRCODE = 'serialization_failure';
  END IF;
  IF v_project.status = p_status THEN
    RETURN v_project;
  END IF;
  IF (v_project.status, p_status) NOT IN (
    ('active'::public.project_status, 'on_hold'::public.project_status),
    ('on_hold'::public.project_status, 'active'::public.project_status)
  ) THEN
    RAISE EXCEPTION 'project % cannot move from % to %',
      p_project_id, v_project.status, p_status
      USING ERRCODE = 'check_violation';
  END IF;

  PERFORM set_config('app.project_operational_status_id', p_project_id::text, true);
  UPDATE public.projects
  SET status = p_status, updated_at = now()
  WHERE id = p_project_id
  RETURNING * INTO v_project;
  PERFORM set_config('app.project_operational_status_id', '', true);
  RETURN v_project;
END;
$$;
ALTER FUNCTION public.set_project_operational_status(uuid,public.project_status,public.project_status) RESET ALL;
ALTER FUNCTION public.set_project_operational_status(uuid,public.project_status,public.project_status) SET search_path = pg_catalog, public, pg_temp;
ALTER FUNCTION public.set_project_operational_status(uuid,public.project_status,public.project_status) OWNER TO postgres;

CREATE OR REPLACE FUNCTION public.set_trade_scope_party(
  p_proposal_id uuid,
  p_party_id uuid
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, pg_temp
AS $$
DECLARE
  v_proposal public.proposals%ROWTYPE;
  v_document public.project_commercial_documents%ROWTYPE;
  v_party public.project_parties%ROWTYPE;
BEGIN
  SELECT * INTO v_proposal FROM public.proposals
  WHERE id = p_proposal_id FOR UPDATE;
  IF NOT FOUND OR v_proposal.document_kind <> 'trade_scope'
     OR auth.uid() IS NULL
     OR NOT public._can_author_proposal(v_proposal.designer_id)
  THEN
    RAISE EXCEPTION 'trade scope % not found or access denied', p_proposal_id
      USING ERRCODE = 'insufficient_privilege';
  END IF;
  IF v_proposal.status <> 'draft' THEN
    RAISE EXCEPTION 'a trade scope party may only be set while the scope is a draft'
      USING ERRCODE = 'check_violation';
  END IF;

  SELECT * INTO v_document FROM public.project_commercial_documents
  WHERE proposal_id = p_proposal_id;
  IF v_document.id IS NULL THEN
    RAISE EXCEPTION 'trade scope has no project binding'
      USING ERRCODE = 'check_violation';
  END IF;

  SELECT * INTO v_party FROM public.project_parties WHERE id = p_party_id;
  IF NOT FOUND OR v_party.project_id IS DISTINCT FROM v_document.project_id THEN
    RAISE EXCEPTION 'party % does not belong to project %',
      p_party_id, v_document.project_id
      USING ERRCODE = 'check_violation';
  END IF;

  UPDATE public.trade_scope_terms SET
    party_id = v_party.id,
    party_display_name = v_party.display_name,
    party_company_name = v_party.company_name,
    party_trade = v_party.trade
  WHERE proposal_id = p_proposal_id;

  RETURN jsonb_build_object(
    'proposalId', p_proposal_id,
    'partyId', v_party.id,
    'partyDisplayName', v_party.display_name,
    'partyCompanyName', v_party.company_name,
    'partyTrade', v_party.trade
  );
END;
$$;
ALTER FUNCTION public.set_trade_scope_party(uuid,uuid) RESET ALL;
ALTER FUNCTION public.set_trade_scope_party(uuid,uuid) SET search_path = pg_catalog, public, pg_temp;
ALTER FUNCTION public.set_trade_scope_party(uuid,uuid) OWNER TO postgres;

CREATE OR REPLACE FUNCTION public.stamp_client_decision_reminder(
  p_decision_id uuid
)
RETURNS public.client_decisions
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, pg_temp
AS $$
DECLARE
  v_decision public.client_decisions%ROWTYPE;
  v_client_id uuid;
  v_artifact public.project_approval_artifacts%ROWTYPE;
  v_metadata jsonb;
  v_previous_parent_write text := current_setting(
    'app.project_approval_decision_write_id', true
  );
  v_previous_legacy_write text := current_setting(
    'app.client_decision_write_id', true
  );
BEGIN
  SELECT * INTO v_decision
  FROM public.client_decisions
  WHERE id = p_decision_id
  FOR UPDATE;
  IF NOT FOUND OR NOT public._can_author_proposal(v_decision.designer_id) THEN
    RAISE EXCEPTION 'decision % not found or access denied', p_decision_id
      USING ERRCODE = 'insufficient_privilege';
  END IF;
  IF v_decision.status <> 'pending' THEN
    RAISE EXCEPTION 'only pending decisions may be reminded'
      USING ERRCODE = 'check_violation';
  END IF;
  IF v_decision.reminder_sent_at IS NOT NULL
     AND v_decision.reminder_sent_at > now() - interval '1 hour'
  THEN
    RAISE EXCEPTION 'a reminder was sent less than one hour ago'
      USING ERRCODE = 'check_violation';
  END IF;

  IF v_decision.approval_contract = 'project_artifact_v1' THEN
    SELECT snapshot.decision_lead_id INTO v_client_id
    FROM public.project_decision_authority_snapshots AS snapshot
    WHERE snapshot.decision_id = v_decision.id
      AND snapshot.project_id = v_decision.project_id;
    SELECT artifact.* INTO v_artifact
    FROM public.project_approval_artifacts AS artifact
    WHERE artifact.decision_id = v_decision.id
      AND artifact.project_id = v_decision.project_id;
    IF v_client_id IS NULL OR v_artifact.id IS NULL THEN
      RAISE EXCEPTION
        'Stage-2 reminder requires coherent frozen authority and artifact'
        USING ERRCODE = 'check_violation';
    END IF;
  ELSE
    SELECT relationship.client_id INTO v_client_id
    FROM public.designer_clients AS relationship
    WHERE relationship.id = v_decision.designer_client_id;
  END IF;
  IF v_client_id IS NULL THEN
    RAISE EXCEPTION 'decision has no registered client reminder recipient'
      USING ERRCODE = 'check_violation';
  END IF;

  v_metadata := jsonb_build_object(
    'decision_id', p_decision_id,
    'subject', 'Decision reminder',
    'preview', v_decision.title,
    'deep_link', '/decisions/' || p_decision_id::text
  );
  IF v_decision.approval_contract = 'project_artifact_v1' THEN
    v_metadata := v_metadata || jsonb_build_object(
      'artifactKind', v_artifact.source_kind,
      'artifactVersion', v_artifact.source_version,
      'artifactChecksum', v_artifact.artifact_hash,
      'artifactTitle', v_artifact.artifact_title
    );
  END IF;

  INSERT INTO public.notification_log (
    user_id, type, channel, status, template_id, metadata, sent_at
  ) VALUES (
    v_client_id,
    'decision_reminder',
    'in_app',
    'delivered',
    CASE WHEN v_decision.approval_contract = 'project_artifact_v1'
      THEN 'decision_reminder_v2' ELSE 'decision_reminder_v1' END,
    v_metadata,
    now()
  );

  PERFORM set_config(
    'app.client_decision_write_id', p_decision_id::text, true
  );
  IF v_decision.approval_contract = 'project_artifact_v1' THEN
    PERFORM set_config(
      'app.project_approval_decision_write_id', p_decision_id::text, true
    );
  END IF;
  UPDATE public.client_decisions
  SET reminder_sent_at = now(), updated_at = now()
  WHERE id = p_decision_id
  RETURNING * INTO v_decision;
  PERFORM set_config(
    'app.project_approval_decision_write_id',
    COALESCE(v_previous_parent_write, ''), true
  );
  PERFORM set_config(
    'app.client_decision_write_id',
    COALESCE(v_previous_legacy_write, ''), true
  );
  RETURN v_decision;
EXCEPTION WHEN OTHERS THEN
  PERFORM set_config(
    'app.project_approval_decision_write_id',
    COALESCE(v_previous_parent_write, ''), true
  );
  PERFORM set_config(
    'app.client_decision_write_id',
    COALESCE(v_previous_legacy_write, ''), true
  );
  RAISE;
END;
$$;
ALTER FUNCTION public.stamp_client_decision_reminder(uuid) RESET ALL;
ALTER FUNCTION public.stamp_client_decision_reminder(uuid) SET search_path = pg_catalog, public, pg_temp;
ALTER FUNCTION public.stamp_client_decision_reminder(uuid) OWNER TO postgres;

CREATE OR REPLACE FUNCTION public.supersede_project_approval_decision(
  p_decision_id uuid,
  p_payload jsonb,
  p_expected_updated_at timestamptz,
  p_idempotency_key text
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, pg_temp
AS $$
DECLARE
  v_actor uuid := auth.uid();
  v_project_id uuid;
  v_project public.projects%ROWTYPE;
  v_decision public.client_decisions%ROWTYPE;
  v_old_artifact public.project_approval_artifacts%ROWTYPE;
  v_new_source record;
  v_successor public.client_decisions%ROWTYPE;
  v_receipt public.project_approval_action_receipts%ROWTYPE;
  v_unknown jsonb;
  v_key text := btrim(COALESCE(p_idempotency_key, ''));
  v_source_kind text;
  v_source_id uuid;
  v_core_payload jsonb;
  v_create_result jsonb;
  v_successor_id uuid;
  v_request_hash text;
  v_result jsonb;
  v_receipt_id uuid := extensions.gen_random_uuid();
  v_previous_parent_write text := current_setting(
    'app.project_approval_decision_write_id', true
  );
  v_previous_legacy_write text := current_setting(
    'app.client_decision_write_id', true
  );
  v_previous_evidence_write text := current_setting(
    'app.project_approval_evidence_decision_id', true
  );
BEGIN
  IF v_actor IS NULL THEN
    RAISE EXCEPTION 'project approval supersession requires an authenticated studio actor'
      USING ERRCODE = 'insufficient_privilege';
  END IF;
  IF p_payload IS NULL OR jsonb_typeof(p_payload) <> 'object' THEN
    RAISE EXCEPTION 'p_payload must be a JSON object'
      USING ERRCODE = 'invalid_parameter_value';
  END IF;
  IF p_expected_updated_at IS NULL THEN
    RAISE EXCEPTION 'p_expected_updated_at is required'
      USING ERRCODE = 'invalid_parameter_value';
  END IF;
  IF v_key = '' OR char_length(v_key) > 160 THEN
    RAISE EXCEPTION 'idempotency key must contain 1 to 160 characters'
      USING ERRCODE = 'invalid_parameter_value';
  END IF;
  v_unknown := p_payload - ARRAY[
    'title', 'question', 'context', 'dueAt', 'artifactKind', 'artifactId',
    'costCentsDelta', 'scheduleDaysDelta', 'leadTimeDaysDelta'
  ];
  IF v_unknown <> '{}'::jsonb THEN
    RAISE EXCEPTION 'unsupported project supersede payload keys: %', v_unknown
      USING ERRCODE = 'invalid_parameter_value';
  END IF;

  SELECT decision.project_id INTO v_project_id
  FROM public.client_decisions AS decision
  WHERE decision.id = p_decision_id
    AND decision.approval_contract = 'project_artifact_v1';
  IF v_project_id IS NULL THEN
    RAISE EXCEPTION 'project approval not found or supersession denied'
      USING ERRCODE = 'insufficient_privilege';
  END IF;

  -- Project → predecessor matches advance_project_phase lock order. The exact
  -- predecessor lock serializes competing successor creation.
  SELECT * INTO v_project
  FROM public.projects AS project
  WHERE project.id = v_project_id
  FOR UPDATE;
  SELECT * INTO v_decision
  FROM public.client_decisions AS decision
  WHERE decision.id = p_decision_id
    AND decision.project_id = v_project_id
    AND decision.approval_contract = 'project_artifact_v1'
  FOR UPDATE;
  IF NOT FOUND OR NOT public._can_author_proposal(v_decision.designer_id) THEN
    RAISE EXCEPTION 'project approval not found or supersession denied'
      USING ERRCODE = 'insufficient_privilege';
  END IF;

  v_request_hash := public._project_approval_hash(jsonb_build_object(
    'decisionId', p_decision_id,
    'payload', p_payload,
    'expectedUpdatedAt', p_expected_updated_at
  ));
  SELECT * INTO v_receipt
  FROM public.project_approval_action_receipts AS receipt
  WHERE receipt.decision_id = p_decision_id
    AND receipt.action_kind = 'superseded'
    AND receipt.idempotency_key = v_key
  FOR UPDATE;
  IF FOUND THEN
    IF v_receipt.request_hash IS DISTINCT FROM v_request_hash
       OR v_receipt.actor_id IS DISTINCT FROM v_actor
    THEN
      RAISE EXCEPTION 'idempotency key was reused with a different supersession'
        USING ERRCODE = 'unique_violation';
    END IF;
    RETURN v_receipt.result || jsonb_build_object('idempotent', true);
  END IF;

  IF v_decision.updated_at IS DISTINCT FROM p_expected_updated_at THEN
    RAISE EXCEPTION 'project approval decision changed since it was loaded'
      USING ERRCODE = 'serialization_failure';
  END IF;
  IF v_decision.status NOT IN ('pending', 'responded') THEN
    RAISE EXCEPTION 'only pending or responded Stage-2 decisions may be superseded'
      USING ERRCODE = 'check_violation';
  END IF;
  IF EXISTS (
       SELECT 1 FROM public.client_decisions AS successor
       WHERE successor.predecessor_decision_id = p_decision_id
     )
     OR EXISTS (
       SELECT 1 FROM public.project_approval_action_receipts AS prior
       WHERE prior.decision_id = p_decision_id
         AND prior.action_kind IN ('withdrawn', 'superseded')
     )
  THEN
    RAISE EXCEPTION 'only the exact current Stage-2 leaf may be superseded'
      USING ERRCODE = 'check_violation';
  END IF;

  SELECT * INTO v_old_artifact
  FROM public.project_approval_artifacts AS artifact
  WHERE artifact.decision_id = p_decision_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'predecessor artifact evidence is missing'
      USING ERRCODE = 'check_violation';
  END IF;

  v_source_kind := NULLIF(p_payload->>'artifactKind', '');
  v_source_id := NULLIF(p_payload->>'artifactId', '')::uuid;
  SELECT * INTO v_new_source
  FROM public._resolve_project_approval_artifact(
    v_project_id, v_source_kind, v_source_id
  );
  IF v_source_kind IS NOT DISTINCT FROM v_old_artifact.source_kind
     AND v_source_id IS NOT DISTINCT FROM v_old_artifact.source_id
     OR v_new_source.artifact_hash IS NOT DISTINCT FROM v_old_artifact.artifact_hash
  THEN
    RAISE EXCEPTION 'supersession requires a genuinely new immutable artifact'
      USING ERRCODE = 'check_violation';
  END IF;

  v_core_payload := p_payload || jsonb_build_object(
    'phaseId', v_decision.phase_id,
    'sectionKey', v_decision.section_key
  );
  v_create_result := public._create_project_approval_decision_checked(
    v_project_id,
    v_core_payload,
    'supersede-create:' || v_key,
    p_decision_id
  );
  v_successor_id := (v_create_result->>'decisionId')::uuid;

  SELECT * INTO v_successor
  FROM public.client_decisions AS successor
  WHERE successor.id = v_successor_id
  FOR UPDATE;
  IF NOT FOUND
     OR v_successor.predecessor_decision_id IS DISTINCT FROM p_decision_id
     OR v_successor.project_id IS DISTINCT FROM v_decision.project_id
     OR v_successor.phase_id IS DISTINCT FROM v_decision.phase_id
     OR v_successor.section_key IS DISTINCT FROM v_decision.section_key
     OR v_successor.blocks_kind IS DISTINCT FROM v_decision.blocks_kind
     OR v_successor.blocking_status IS DISTINCT FROM v_decision.blocking_status
     OR v_successor.blocks_kind IS DISTINCT FROM 'phase'
     OR v_successor.blocking_status IS DISTINCT FROM 'blocks_phase'
  THEN
    RAISE EXCEPTION 'successor project, phase, section, or gate lineage drifted'
      USING ERRCODE = 'check_violation';
  END IF;

  IF v_decision.status = 'pending' THEN
    PERFORM set_config(
      'app.project_approval_decision_write_id', p_decision_id::text, true
    );
    PERFORM set_config(
      'app.client_decision_write_id', p_decision_id::text, true
    );
    UPDATE public.client_decisions
    SET status = 'expired', updated_at = now()
    WHERE id = p_decision_id
    RETURNING * INTO v_decision;
  END IF;

  v_result := jsonb_build_object(
    'receiptId', v_receipt_id,
    'projectId', v_decision.project_id,
    'decisionId', v_decision.id,
    'successorDecisionId', v_successor.id,
    'status', v_decision.status,
    'disposition', 'superseded',
    'successorStatus', v_successor.status,
    'updatedAt', v_decision.updated_at
  );
  PERFORM set_config(
    'app.project_approval_evidence_decision_id', p_decision_id::text, true
  );
  INSERT INTO public.project_approval_action_receipts (
    id, project_id, decision_id, action_kind, idempotency_key,
    request_hash, actor_id, result, successor_decision_id
  ) VALUES (
    v_receipt_id, v_decision.project_id, p_decision_id, 'superseded', v_key,
    v_request_hash, v_actor, v_result, v_successor.id
  );

  PERFORM set_config(
    'app.project_approval_decision_write_id',
    COALESCE(v_previous_parent_write, ''), true
  );
  PERFORM set_config(
    'app.client_decision_write_id', COALESCE(v_previous_legacy_write, ''), true
  );
  PERFORM set_config(
    'app.project_approval_evidence_decision_id',
    COALESCE(v_previous_evidence_write, ''), true
  );
  RETURN v_result || jsonb_build_object('idempotent', false);
EXCEPTION WHEN OTHERS THEN
  PERFORM set_config(
    'app.project_approval_decision_write_id',
    COALESCE(v_previous_parent_write, ''), true
  );
  PERFORM set_config(
    'app.client_decision_write_id', COALESCE(v_previous_legacy_write, ''), true
  );
  PERFORM set_config(
    'app.project_approval_evidence_decision_id',
    COALESCE(v_previous_evidence_write, ''), true
  );
  RAISE;
END;
$$;
ALTER FUNCTION public.supersede_project_approval_decision(uuid,jsonb,timestamp with time zone,text) RESET ALL;
ALTER FUNCTION public.supersede_project_approval_decision(uuid,jsonb,timestamp with time zone,text) SET search_path = pg_catalog, public, pg_temp;
ALTER FUNCTION public.supersede_project_approval_decision(uuid,jsonb,timestamp with time zone,text) OWNER TO postgres;

CREATE OR REPLACE FUNCTION public.update_client_decision(
  p_decision_id uuid,
  p_patch jsonb DEFAULT '{}'::jsonb,
  p_options jsonb DEFAULT NULL,
  p_expected_updated_at timestamptz DEFAULT NULL
)
RETURNS public.client_decisions
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, pg_temp
AS $$
DECLARE
  v_decision public.client_decisions%ROWTYPE;
  v_result public.client_decisions%ROWTYPE;
  v_target_project_id uuid;
  v_target_party_id uuid;
  v_relationship_client_id uuid;
  v_unknown jsonb;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'update_client_decision requires an authenticated user'
      USING ERRCODE = 'insufficient_privilege';
  END IF;
  IF p_patch IS NULL OR jsonb_typeof(p_patch) <> 'object' THEN
    RAISE EXCEPTION 'p_patch must be a JSON object'
      USING ERRCODE = 'invalid_parameter_value';
  END IF;

  v_unknown := p_patch - ARRAY[
    'title', 'context', 'due_date', 'linked_phase', 'phase_id', 'room_id',
    'section_key', 'project_id', 'decision_type', 'decision_kind',
    'coordination_kind', 'blocking_status', 'blocks_kind',
    'blocks_milestone_id', 'court', 'court_party_id'
  ];
  IF v_unknown <> '{}'::jsonb THEN
    RAISE EXCEPTION 'unsupported decision patch keys: %', v_unknown
      USING ERRCODE = 'invalid_parameter_value';
  END IF;

  SELECT * INTO v_decision
  FROM public.client_decisions
  WHERE id = p_decision_id
  FOR UPDATE;

  IF NOT FOUND OR NOT public._can_author_proposal(v_decision.designer_id) THEN
    RAISE EXCEPTION 'decision % not found or access denied', p_decision_id
      USING ERRCODE = 'insufficient_privilege';
  END IF;
  IF v_decision.status NOT IN ('draft', 'pending') THEN
    RAISE EXCEPTION 'decision % cannot be edited from status %',
      p_decision_id, v_decision.status
      USING ERRCODE = 'check_violation';
  END IF;
  IF v_decision.linked_proposal_id IS NOT NULL THEN
    RAISE EXCEPTION 'proposal approval decisions are signature-workflow only'
      USING ERRCODE = 'check_violation';
  END IF;
  IF p_expected_updated_at IS NULL THEN
    RAISE EXCEPTION 'p_expected_updated_at is required'
      USING ERRCODE = 'invalid_parameter_value';
  END IF;
  IF v_decision.updated_at IS DISTINCT FROM p_expected_updated_at
  THEN
    RAISE EXCEPTION 'decision % changed since it was loaded', p_decision_id
      USING ERRCODE = 'serialization_failure';
  END IF;

  IF p_patch ? 'title'
     AND btrim(COALESCE(p_patch->>'title', '')) = ''
  THEN
    RAISE EXCEPTION 'decision title is required'
      USING ERRCODE = 'check_violation';
  END IF;

  SELECT client_id INTO v_relationship_client_id
  FROM public.designer_clients
  WHERE id = v_decision.designer_client_id;

  v_target_project_id := CASE
    WHEN p_patch ? 'project_id' THEN NULLIF(p_patch->>'project_id', '')::uuid
    ELSE v_decision.project_id
  END;

  -- A decision's dependency web, room/phase references, and notification
  -- history are project-scoped. Moving the parent without atomically moving
  -- every one of those children creates cross-project blockers. Accept an
  -- echoed project_id from edit forms, but make actual project identity
  -- immutable after creation.
  IF v_target_project_id IS DISTINCT FROM v_decision.project_id THEN
    RAISE EXCEPTION 'decision project is immutable after creation'
      USING ERRCODE = 'check_violation';
  END IF;

  IF p_patch ? 'project_id'
     AND v_target_project_id IS NOT NULL
     AND NOT EXISTS (
       SELECT 1 FROM public.projects AS project
       WHERE project.id = v_target_project_id
         AND project.designer_id IS NOT DISTINCT FROM v_decision.designer_id
         AND project.client_id IS NOT DISTINCT FROM v_relationship_client_id
     )
  THEN
    RAISE EXCEPTION
      'decision project must match its exact designer/client relationship'
      USING ERRCODE = 'check_violation';
  END IF;

  v_target_party_id := CASE
    WHEN p_patch ? 'court_party_id'
      THEN NULLIF(p_patch->>'court_party_id', '')::uuid
    ELSE v_decision.court_party_id
  END;
  IF v_target_party_id IS NOT NULL
     AND (
       v_target_project_id IS NULL
       OR NOT EXISTS (
         SELECT 1 FROM public.project_parties AS party
         WHERE party.id = v_target_party_id
           AND party.project_id = v_target_project_id
       )
     )
  THEN
    RAISE EXCEPTION 'court party must belong to the decision project'
      USING ERRCODE = 'check_violation';
  END IF;

  IF p_options IS NOT NULL THEN
    IF jsonb_typeof(p_options) <> 'array' THEN
      RAISE EXCEPTION 'p_options must be a JSON array'
        USING ERRCODE = 'invalid_parameter_value';
    END IF;
    IF EXISTS (
      SELECT 1
      FROM jsonb_array_elements(p_options) AS option(value)
      WHERE jsonb_typeof(option.value) <> 'object'
         OR btrim(COALESCE(option.value->>'name', '')) = ''
    ) THEN
      RAISE EXCEPTION 'every decision option requires a name'
        USING ERRCODE = 'check_violation';
    END IF;
  END IF;

  PERFORM set_config('app.client_decision_write_id', p_decision_id::text, true);

  UPDATE public.client_decisions
  SET title = CASE WHEN p_patch ? 'title' THEN btrim(p_patch->>'title') ELSE title END,
      context = CASE WHEN p_patch ? 'context' THEN p_patch->>'context' ELSE context END,
      due_date = CASE WHEN p_patch ? 'due_date'
        THEN NULLIF(p_patch->>'due_date', '')::timestamptz ELSE due_date END,
      linked_phase = CASE WHEN p_patch ? 'linked_phase'
        THEN p_patch->>'linked_phase' ELSE linked_phase END,
      phase_id = CASE WHEN p_patch ? 'phase_id'
        THEN NULLIF(p_patch->>'phase_id', '')::uuid ELSE phase_id END,
      room_id = CASE WHEN p_patch ? 'room_id'
        THEN NULLIF(p_patch->>'room_id', '')::uuid ELSE room_id END,
      section_key = CASE WHEN p_patch ? 'section_key'
        THEN p_patch->>'section_key' ELSE section_key END,
      project_id = v_target_project_id,
      decision_type = CASE WHEN p_patch ? 'decision_type'
        THEN p_patch->>'decision_type' ELSE decision_type END,
      decision_kind = CASE WHEN p_patch ? 'decision_kind'
        THEN p_patch->>'decision_kind' ELSE decision_kind END,
      coordination_kind = CASE WHEN p_patch ? 'coordination_kind'
        THEN p_patch->>'coordination_kind' ELSE coordination_kind END,
      blocking_status = CASE WHEN p_patch ? 'blocking_status'
        THEN p_patch->>'blocking_status' ELSE blocking_status END,
      blocks_kind = CASE WHEN p_patch ? 'blocks_kind'
        THEN p_patch->>'blocks_kind' ELSE blocks_kind END,
      blocks_milestone_id = CASE WHEN p_patch ? 'blocks_milestone_id'
        THEN NULLIF(p_patch->>'blocks_milestone_id', '')::uuid
        ELSE blocks_milestone_id END,
      court = CASE WHEN p_patch ? 'court' THEN p_patch->>'court' ELSE court END,
      court_party_id = v_target_party_id,
      updated_at = now()
  WHERE id = p_decision_id;

  IF p_options IS NOT NULL THEN
    DELETE FROM public.client_decision_options
    WHERE decision_id = p_decision_id;

    INSERT INTO public.client_decision_options (
      decision_id, name, image_url, designer_note, is_recommended,
      price, quantity, cost_delta_cents, lead_time_days_delta,
      product_id, approves, configuration_id, selection_snapshot,
      selected, client_note, sort_order
    )
    SELECT
      p_decision_id,
      btrim(option.value->>'name'),
      option.value->>'image_url',
      option.value->>'designer_note',
      COALESCE((option.value->>'is_recommended')::boolean, false),
      NULLIF(option.value->>'price', '')::integer,
      COALESCE(NULLIF(option.value->>'quantity', '')::integer, 1),
      NULLIF(option.value->>'cost_delta_cents', '')::integer,
      NULLIF(option.value->>'lead_time_days_delta', '')::integer,
      NULLIF(option.value->>'product_id', '')::uuid,
      COALESCE((option.value->>'approves')::boolean, false),
      NULLIF(option.value->>'configuration_id', '')::uuid,
      -- Never the caller's array verbatim: the client reads this row.
      public._decision_selection_snapshot_safe(option.value->'selection_snapshot'),
      false,
      NULL,
      COALESCE(NULLIF(option.value->>'sort_order', '')::integer,
               option.ordinality::integer - 1)
    FROM jsonb_array_elements(p_options) WITH ORDINALITY AS option(value, ordinality);
  END IF;

  PERFORM set_config('app.client_decision_write_id', '', true);
  SELECT * INTO v_result FROM public.client_decisions WHERE id = p_decision_id;

  PERFORM public.assert_client_decision_reference_integrity(
    v_result.id,
    v_result.designer_client_id,
    v_result.designer_id,
    v_result.project_id,
    v_result.status,
    v_result.phase_id,
    v_result.room_id,
    v_result.blocks_milestone_id,
    v_result.court_party_id,
    v_result.linked_proposal_id,
    v_result.recommended_option_id
  );

  IF v_result.status = 'pending'
     AND (p_patch <> '{}'::jsonb OR p_options IS NOT NULL)
  THEN
    PERFORM public._enqueue_decision_notification(
      p_decision_id, 'decision_updated'
    );
  END IF;
  RETURN v_result;
END;
$$;
ALTER FUNCTION public.update_client_decision(uuid,jsonb,jsonb,timestamp with time zone) RESET ALL;
ALTER FUNCTION public.update_client_decision(uuid,jsonb,jsonb,timestamp with time zone) SET search_path = pg_catalog, public, pg_temp;
ALTER FUNCTION public.update_client_decision(uuid,jsonb,jsonb,timestamp with time zone) OWNER TO postgres;

CREATE OR REPLACE FUNCTION public.update_coordination_item(
  p_item_id uuid,
  p_patch jsonb,
  p_options jsonb,
  p_blocked_ffe_item_ids uuid[],
  p_blocked_task_ids uuid[],
  p_expected_updated_at timestamptz
)
RETURNS public.client_decisions
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, pg_temp
AS $$
DECLARE
  v_item public.client_decisions%ROWTYPE;
  v_expected_count integer;
  v_matched_count integer;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'update_coordination_item requires an authenticated user'
      USING ERRCODE = 'insufficient_privilege';
  END IF;
  IF p_expected_updated_at IS NULL THEN
    RAISE EXCEPTION 'p_expected_updated_at is required'
      USING ERRCODE = 'invalid_parameter_value';
  END IF;

  SELECT * INTO v_item
  FROM public.client_decisions
  WHERE id = p_item_id
  FOR UPDATE;
  IF NOT FOUND OR NOT public._can_author_proposal(v_item.designer_id) THEN
    RAISE EXCEPTION 'coordination item % not found or access denied', p_item_id
      USING ERRCODE = 'insufficient_privilege';
  END IF;
  IF v_item.status NOT IN ('draft', 'pending') THEN
    RAISE EXCEPTION 'coordination item % is immutable from status %',
      p_item_id, v_item.status
      USING ERRCODE = 'check_violation';
  END IF;

  IF p_blocked_ffe_item_ids IS NOT NULL
     AND cardinality(p_blocked_ffe_item_ids) > 0
  THEN
    PERFORM 1
    FROM public.project_ffe_items AS item
    WHERE item.id = ANY(p_blocked_ffe_item_ids)
    ORDER BY item.id
    FOR UPDATE;
    SELECT count(DISTINCT item.id) INTO v_matched_count
    FROM public.project_ffe_items AS item
    WHERE item.id = ANY(p_blocked_ffe_item_ids)
      AND item.project_id IS NOT DISTINCT FROM v_item.project_id
      AND (item.blocked_by_decision_id IS NULL
           OR item.blocked_by_decision_id = p_item_id);
    SELECT count(DISTINCT id) INTO v_expected_count
    FROM unnest(p_blocked_ffe_item_ids) AS id;
    IF v_item.project_id IS NULL OR v_matched_count <> v_expected_count THEN
      RAISE EXCEPTION 'blocked FF&E items must be available in the item project'
        USING ERRCODE = 'check_violation';
    END IF;
  END IF;

  IF p_blocked_task_ids IS NOT NULL
     AND cardinality(p_blocked_task_ids) > 0
  THEN
    PERFORM 1
    FROM public.project_tasks AS task
    WHERE task.id = ANY(p_blocked_task_ids)
    ORDER BY task.id
    FOR UPDATE;
    SELECT count(DISTINCT task.id) INTO v_matched_count
    FROM public.project_tasks AS task
    WHERE task.id = ANY(p_blocked_task_ids)
      AND task.project_id IS NOT DISTINCT FROM v_item.project_id
      AND task.status <> 'done'
      AND (task.blocked_by_item_id IS NULL
           OR task.blocked_by_item_id = p_item_id);
    SELECT count(DISTINCT id) INTO v_expected_count
    FROM unnest(p_blocked_task_ids) AS id;
    IF v_item.project_id IS NULL OR v_matched_count <> v_expected_count THEN
      RAISE EXCEPTION 'blocked tasks must be open and available in the item project'
        USING ERRCODE = 'check_violation';
    END IF;
  END IF;

  v_item := public.update_client_decision(
    p_item_id,
    COALESCE(p_patch, '{}'::jsonb),
    p_options,
    p_expected_updated_at
  );

  IF p_blocked_ffe_item_ids IS NOT NULL THEN
    UPDATE public.project_ffe_items
    SET blocked = false,
        blocked_reason = NULL,
        blocked_by_decision_id = NULL,
        updated_at = now()
    WHERE blocked_by_decision_id = p_item_id
      AND NOT (id = ANY(p_blocked_ffe_item_ids));

    UPDATE public.project_ffe_items
    SET blocked = true,
        blocked_by_decision_id = p_item_id,
        updated_at = now()
    WHERE id = ANY(p_blocked_ffe_item_ids);
  END IF;

  IF p_blocked_task_ids IS NOT NULL THEN
    UPDATE public.project_tasks
    SET status = 'todo', blocked_by_item_id = NULL, updated_at = now()
    WHERE blocked_by_item_id = p_item_id
      AND NOT (id = ANY(p_blocked_task_ids));

    UPDATE public.project_tasks
    SET status = 'blocked', blocked_by_item_id = p_item_id, updated_at = now()
    WHERE id = ANY(p_blocked_task_ids);
  END IF;

  SELECT * INTO v_item
  FROM public.client_decisions
  WHERE id = p_item_id;
  RETURN v_item;
END;
$$;
ALTER FUNCTION public.update_coordination_item(uuid,jsonb,jsonb,uuid[],uuid[],timestamp with time zone) RESET ALL;
ALTER FUNCTION public.update_coordination_item(uuid,jsonb,jsonb,uuid[],uuid[],timestamp with time zone) SET search_path = pg_catalog, public, pg_temp;
ALTER FUNCTION public.update_coordination_item(uuid,jsonb,jsonb,uuid[],uuid[],timestamp with time zone) OWNER TO postgres;

CREATE OR REPLACE FUNCTION public.update_project_phase(
  p_project_id uuid,
  p_phase_id uuid,
  p_expected_updated_at timestamptz,
  p_patch jsonb
)
RETURNS public.project_phases
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, pg_temp
AS $$
DECLARE
  v_actor uuid := auth.uid();
  v_project public.projects%ROWTYPE;
  v_target public.project_phases%ROWTYPE;
  v_updated public.project_phases%ROWTYPE;
  v_follows_phase_id uuid;
  v_guard_prior text;
  v_guard_set boolean := false;
  v_live_main_count integer;
  v_live_main_label text;
BEGIN
  IF v_actor IS NULL THEN
    RAISE EXCEPTION 'update_project_phase requires an authenticated user'
      USING ERRCODE = 'insufficient_privilege';
  END IF;

  IF p_expected_updated_at IS NULL THEN
    RAISE EXCEPTION 'update_project_phase: expected_updated_at is required'
      USING ERRCODE = 'invalid_parameter_value';
  END IF;

  IF p_patch IS NULL
     OR jsonb_typeof(p_patch) <> 'object'
     OR p_patch = '{}'::jsonb THEN
    RAISE EXCEPTION 'update_project_phase: patch must be a non-empty JSON object'
      USING ERRCODE = 'invalid_parameter_value';
  END IF;

  IF EXISTS (
    SELECT 1
    FROM jsonb_object_keys(p_patch) AS patch_key(key)
    WHERE patch_key.key NOT IN (
      'name',
      'phase_key',
      'sort_order',
      'duration_days',
      'anchor_date',
      'follows_phase_id',
      'lane'
    )
  ) THEN
    RAISE EXCEPTION 'update_project_phase: patch contains an unsupported field'
      USING ERRCODE = 'invalid_parameter_value';
  END IF;

  IF p_patch ? 'name'
     AND btrim(COALESCE(p_patch->>'name', '')) = '' THEN
    RAISE EXCEPTION 'update_project_phase: name cannot be blank'
      USING ERRCODE = 'invalid_parameter_value';
  END IF;

  IF p_patch ? 'phase_key'
     AND jsonb_typeof(p_patch->'phase_key') <> 'null'
     AND btrim(COALESCE(p_patch->>'phase_key', '')) = '' THEN
    RAISE EXCEPTION 'update_project_phase: phase_key cannot be blank'
      USING ERRCODE = 'invalid_parameter_value';
  END IF;

  IF p_patch ? 'lane'
     AND COALESCE(p_patch->>'lane', '') NOT IN ('main', 'thread') THEN
    RAISE EXCEPTION 'update_project_phase: lane must be main or thread'
      USING ERRCODE = 'invalid_parameter_value';
  END IF;

  IF p_patch ? 'duration_days'
     AND jsonb_typeof(p_patch->'duration_days') <> 'null'
     AND (p_patch->>'duration_days')::integer <= 0 THEN
    RAISE EXCEPTION 'update_project_phase: duration_days must be positive'
      USING ERRCODE = 'invalid_parameter_value';
  END IF;

  SELECT * INTO v_project
  FROM public.projects
  WHERE id = p_project_id
  FOR UPDATE;

  IF NOT FOUND OR NOT public._can_author_proposal(v_project.designer_id) THEN
    RAISE EXCEPTION 'update_project_phase: project not found or access denied'
      USING ERRCODE = 'insufficient_privilege';
  END IF;

  PERFORM phase.id
  FROM public.project_phases AS phase
  WHERE phase.project_id = p_project_id
  ORDER BY phase.id
  FOR UPDATE;

  SELECT * INTO v_target
  FROM public.project_phases AS phase
  WHERE phase.id = p_phase_id
    AND phase.project_id = p_project_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'update_project_phase: phase does not belong to project'
      USING ERRCODE = 'check_violation';
  END IF;

  -- The caller-observed row timestamp is the compare-and-swap token. Project
  -- locking serializes writers; the loser that wakes after a committed edit
  -- sees a new timestamp and fails instead of silently applying stale intent.
  IF v_target.updated_at IS DISTINCT FROM p_expected_updated_at THEN
    RAISE EXCEPTION
      'update_project_phase: phase changed since it was read'
      USING ERRCODE = 'serialization_failure';
  END IF;

  IF v_target.status <> 'pending'
     AND (
       p_patch ? 'phase_key'
       OR p_patch ? 'lane'
       OR p_patch ? 'follows_phase_id'
     ) THEN
    RAISE EXCEPTION
      'update_project_phase: phase_key, lane, and follows_phase_id are immutable after pending'
      USING ERRCODE = 'check_violation';
  END IF;

  PERFORM public._assert_project_phase_topology(
    p_project_id,
    'update_project_phase'
  );

  v_follows_phase_id := CASE
    WHEN NOT (p_patch ? 'follows_phase_id') THEN v_target.follows_phase_id
    WHEN jsonb_typeof(p_patch->'follows_phase_id') = 'null' THEN NULL
    ELSE (p_patch->>'follows_phase_id')::uuid
  END;

  IF v_follows_phase_id = p_phase_id THEN
    RAISE EXCEPTION 'update_project_phase: a phase cannot follow itself'
      USING ERRCODE = 'check_violation';
  END IF;

  IF v_follows_phase_id IS NOT NULL AND NOT EXISTS (
    SELECT 1
    FROM public.project_phases AS predecessor
    WHERE predecessor.id = v_follows_phase_id
      AND predecessor.project_id = p_project_id
  ) THEN
    RAISE EXCEPTION
      'update_project_phase: predecessor does not belong to project'
      USING ERRCODE = 'check_violation';
  END IF;

  v_guard_prior := current_setting('app.project_phase_topology_token', true);
  PERFORM set_config(
    'app.project_phase_topology_token',
    format('update_project_phase:%s:%s', p_project_id, pg_catalog.txid_current()),
    true
  );
  v_guard_set := true;

  UPDATE public.project_phases AS phase
  SET name = CASE
        WHEN p_patch ? 'name' THEN btrim(p_patch->>'name')
        ELSE phase.name
      END,
      phase_key = CASE
        WHEN NOT (p_patch ? 'phase_key') THEN phase.phase_key
        WHEN jsonb_typeof(p_patch->'phase_key') = 'null' THEN NULL
        ELSE btrim(p_patch->>'phase_key')
      END,
      sort_order = CASE
        WHEN p_patch ? 'sort_order' THEN (p_patch->>'sort_order')::integer
        ELSE phase.sort_order
      END,
      duration_days = CASE
        WHEN NOT (p_patch ? 'duration_days') THEN phase.duration_days
        WHEN jsonb_typeof(p_patch->'duration_days') = 'null' THEN NULL
        ELSE (p_patch->>'duration_days')::integer
      END,
      anchor_date = CASE
        WHEN NOT (p_patch ? 'anchor_date') THEN phase.anchor_date
        WHEN jsonb_typeof(p_patch->'anchor_date') = 'null' THEN NULL
        ELSE (p_patch->>'anchor_date')::date
      END,
      follows_phase_id = v_follows_phase_id,
      lane = CASE
        WHEN p_patch ? 'lane' THEN p_patch->>'lane'
        ELSE phase.lane
      END,
      updated_at = clock_timestamp()
  WHERE phase.id = p_phase_id
    AND phase.project_id = p_project_id
  RETURNING * INTO v_updated;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'update_project_phase: phase changed during update'
      USING ERRCODE = 'serialization_failure';
  END IF;

  PERFORM public._assert_project_phase_topology(
    p_project_id,
    'update_project_phase'
  );

  -- phase_key and lane participate in the live-main projection. Keep the
  -- project pointer transactionally consistent when either one changes.
  IF p_patch ? 'phase_key' OR p_patch ? 'lane' THEN
    SELECT count(*),
           (array_agg(
             COALESCE(NULLIF(phase.phase_key, ''), phase.name)
             ORDER BY phase.id
           ))[1]
    INTO v_live_main_count, v_live_main_label
    FROM public.project_phases AS phase
    WHERE phase.project_id = p_project_id
      AND phase.lane = 'main'
      AND phase.status IN ('in_progress', 'delayed');

    UPDATE public.projects
    SET current_phase = CASE
          WHEN v_live_main_count = 0 THEN NULL
          ELSE v_live_main_label
        END,
        updated_at = now()
    WHERE id = p_project_id;
  END IF;

  PERFORM set_config(
    'app.project_phase_topology_token', COALESCE(v_guard_prior, ''), true
  );
  v_guard_set := false;
  RETURN v_updated;
EXCEPTION WHEN OTHERS THEN
  IF v_guard_set THEN
    PERFORM set_config(
      'app.project_phase_topology_token', COALESCE(v_guard_prior, ''), true
    );
  END IF;
  RAISE;
END;
$$;
ALTER FUNCTION public.update_project_phase(uuid,uuid,timestamp with time zone,jsonb) RESET ALL;
ALTER FUNCTION public.update_project_phase(uuid,uuid,timestamp with time zone,jsonb) SET search_path = pg_catalog, public, pg_temp;
ALTER FUNCTION public.update_project_phase(uuid,uuid,timestamp with time zone,jsonb) OWNER TO postgres;

CREATE OR REPLACE FUNCTION public.update_proposal_phase(
  p_phase_id uuid,
  p_proposal_id uuid,
  p_patch jsonb,
  p_expected_updated_at timestamptz
)
RETURNS public.proposal_phases
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, pg_temp
AS $$
DECLARE
  v_proposal public.proposals%ROWTYPE;
  v_phase public.proposal_phases%ROWTYPE;
  v_unknown jsonb;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'update_proposal_phase requires an authenticated user'
      USING ERRCODE = 'insufficient_privilege';
  END IF;
  IF p_patch IS NULL OR jsonb_typeof(p_patch) <> 'object' THEN
    RAISE EXCEPTION 'p_patch must be a JSON object'
      USING ERRCODE = 'invalid_parameter_value';
  END IF;
  IF p_expected_updated_at IS NULL THEN
    RAISE EXCEPTION 'p_expected_updated_at is required'
      USING ERRCODE = 'invalid_parameter_value';
  END IF;
  v_unknown := p_patch - ARRAY[
    'name', 'phase_key', 'duration_weeks', 'fee_cents', 'revision_limit',
    'gate_condition', 'deliverables', 'duration_days', 'anchor_date'
  ];
  IF v_unknown <> '{}'::jsonb THEN
    RAISE EXCEPTION 'unsupported proposal phase patch keys: %', v_unknown
      USING ERRCODE = 'invalid_parameter_value';
  END IF;
  IF p_patch ? 'name'
     AND btrim(COALESCE(p_patch->>'name', '')) = ''
  THEN
    RAISE EXCEPTION 'phase name is required'
      USING ERRCODE = 'check_violation';
  END IF;
  IF p_patch ? 'fee_cents' AND p_patch->>'fee_cents' IS NULL THEN
    RAISE EXCEPTION 'phase fee_cents cannot be null'
      USING ERRCODE = 'check_violation';
  END IF;
  IF p_patch ? 'deliverables'
     AND (
       p_patch->'deliverables' IS NULL
       OR jsonb_typeof(p_patch->'deliverables') <> 'array'
     )
  THEN
    RAISE EXCEPTION 'phase deliverables must be a JSON array'
      USING ERRCODE = 'invalid_parameter_value';
  END IF;

  SELECT * INTO v_proposal
  FROM public.proposals
  WHERE id = p_proposal_id
  FOR UPDATE;
  IF NOT FOUND OR NOT public._can_author_proposal(v_proposal.designer_id) THEN
    RAISE EXCEPTION 'proposal % not found or access denied', p_proposal_id
      USING ERRCODE = 'insufficient_privilege';
  END IF;
  IF v_proposal.status <> 'draft' THEN
    RAISE EXCEPTION 'proposal % is %, so its authored copy is immutable',
      p_proposal_id, v_proposal.status
      USING ERRCODE = 'check_violation';
  END IF;

  SELECT * INTO v_phase
  FROM public.proposal_phases
  WHERE id = p_phase_id
    AND proposal_id = p_proposal_id
  FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'proposal phase % not found in proposal %',
      p_phase_id, p_proposal_id
      USING ERRCODE = 'insufficient_privilege';
  END IF;
  IF v_phase.updated_at IS DISTINCT FROM p_expected_updated_at THEN
    RAISE EXCEPTION 'proposal phase % changed since it was loaded', p_phase_id
      USING ERRCODE = 'serialization_failure';
  END IF;

  UPDATE public.proposal_phases
  SET name = CASE WHEN p_patch ? 'name'
        THEN btrim(p_patch->>'name') ELSE name END,
      phase_key = CASE WHEN p_patch ? 'phase_key'
        THEN NULLIF(btrim(COALESCE(p_patch->>'phase_key', '')), '')
        ELSE phase_key END,
      duration_weeks = CASE WHEN p_patch ? 'duration_weeks'
        THEN NULLIF(p_patch->>'duration_weeks', '')::integer
        ELSE duration_weeks END,
      fee_cents = CASE WHEN p_patch ? 'fee_cents'
        THEN (p_patch->>'fee_cents')::integer ELSE fee_cents END,
      revision_limit = CASE WHEN p_patch ? 'revision_limit'
        THEN NULLIF(p_patch->>'revision_limit', '')::integer
        ELSE revision_limit END,
      gate_condition = CASE WHEN p_patch ? 'gate_condition'
        THEN NULLIF(btrim(COALESCE(p_patch->>'gate_condition', '')), '')
        ELSE gate_condition END,
      deliverables = CASE WHEN p_patch ? 'deliverables'
        THEN p_patch->'deliverables' ELSE deliverables END,
      duration_days = CASE WHEN p_patch ? 'duration_days'
        THEN NULLIF(p_patch->>'duration_days', '')::integer
        ELSE duration_days END,
      anchor_date = CASE WHEN p_patch ? 'anchor_date'
        THEN NULLIF(p_patch->>'anchor_date', '')::date ELSE anchor_date END,
      updated_at = now()
  WHERE id = p_phase_id
    AND proposal_id = p_proposal_id
  RETURNING * INTO v_phase;

  PERFORM public._assert_proposal_phase_topology(
    p_proposal_id, 'update_proposal_phase result'
  );
  PERFORM public._recompute_proposal_total_locked(p_proposal_id);
  RETURN v_phase;
END;
$$;
ALTER FUNCTION public.update_proposal_phase(uuid,uuid,jsonb,timestamp with time zone) RESET ALL;
ALTER FUNCTION public.update_proposal_phase(uuid,uuid,jsonb,timestamp with time zone) SET search_path = pg_catalog, public, pg_temp;
ALTER FUNCTION public.update_proposal_phase(uuid,uuid,jsonb,timestamp with time zone) OWNER TO postgres;

CREATE OR REPLACE FUNCTION public.upsert_design_services_draft(
  p_proposal_id uuid,
  p_terms jsonb,
  p_rates jsonb
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, pg_temp
AS $$
DECLARE
  v_proposal public.proposals%ROWTYPE;
  v_rate jsonb;
  v_current_version integer := COALESCE((p_terms->>'currentRateVersion')::integer, 1);
  v_previous_commercial text := current_setting('app.commercial_document_id', true);
BEGIN
  IF auth.uid() IS NULL OR jsonb_typeof(COALESCE(p_terms, '{}'::jsonb)) <> 'object'
     OR jsonb_typeof(COALESCE(p_rates, 'null'::jsonb)) <> 'array'
     OR jsonb_array_length(p_rates) = 0
  THEN
    RAISE EXCEPTION 'design-services draft requires an authenticated author, terms, and rates'
      USING ERRCODE = 'check_violation';
  END IF;
  SELECT * INTO v_proposal FROM public.proposals
  WHERE id = p_proposal_id FOR UPDATE;
  IF NOT FOUND OR v_proposal.status <> 'draft'
     OR NOT public._can_author_proposal(v_proposal.designer_id)
  THEN
    RAISE EXCEPTION 'draft proposal % not found or access denied', p_proposal_id
      USING ERRCODE = 'insufficient_privilege';
  END IF;
  IF v_proposal.document_kind NOT IN ('legacy', 'design_services', 'service_addendum') THEN
    RAISE EXCEPTION 'proposal % is not a design-services draft', p_proposal_id
      USING ERRCODE = 'check_violation';
  END IF;

  PERFORM set_config('app.commercial_document_id', p_proposal_id::text, true);
  UPDATE public.proposals
  SET document_kind = CASE WHEN document_kind = 'legacy' THEN 'design_services' ELSE document_kind END,
      commercial_state = 'draft', updated_at = now()
  WHERE id = p_proposal_id;

  INSERT INTO public.proposal_service_terms (
    proposal_id, scope, deliverables, exclusions, billing_ceiling_cents,
    retainer_amount_cents, retainer_activation_policy, billing_cadence,
    currency, terms, current_rate_version, furnishings_deposit_percent
  ) VALUES (
    p_proposal_id,
    COALESCE(p_terms->>'scope', ''),
    COALESCE(p_terms->'deliverables', '[]'::jsonb),
    COALESCE(p_terms->'exclusions', '[]'::jsonb),
    COALESCE((p_terms->>'billingCeilingCents')::integer, 0),
    COALESCE((p_terms->>'retainerAmountCents')::integer, 0),
    COALESCE(NULLIF(p_terms->>'retainerActivationPolicy', ''), 'immediate'),
    COALESCE(NULLIF(p_terms->>'billingCadence', ''), 'monthly'),
    upper(COALESCE(NULLIF(p_terms->>'currency', ''), 'USD')),
    NULLIF(p_terms->>'terms', ''),
    v_current_version,
    NULLIF(p_terms->>'furnishingsDepositPercent', '')::numeric
  ) ON CONFLICT (proposal_id) DO UPDATE SET
    scope = EXCLUDED.scope,
    deliverables = EXCLUDED.deliverables,
    exclusions = EXCLUDED.exclusions,
    billing_ceiling_cents = EXCLUDED.billing_ceiling_cents,
    retainer_amount_cents = EXCLUDED.retainer_amount_cents,
    retainer_activation_policy = EXCLUDED.retainer_activation_policy,
    billing_cadence = EXCLUDED.billing_cadence,
    currency = EXCLUDED.currency,
    terms = EXCLUDED.terms,
    current_rate_version = EXCLUDED.current_rate_version,
    furnishings_deposit_percent = EXCLUDED.furnishings_deposit_percent,
    updated_at = now();

  DELETE FROM public.proposal_service_rates WHERE proposal_id = p_proposal_id;
  FOR v_rate IN SELECT value FROM jsonb_array_elements(p_rates)
  LOOP
    INSERT INTO public.proposal_service_rates (
      proposal_id, version, role_name, hourly_rate_cents, sort_order, effective_at
    ) VALUES (
      p_proposal_id,
      COALESCE((v_rate->>'version')::integer, v_current_version),
      btrim(v_rate->>'roleName'),
      (v_rate->>'hourlyRateCents')::integer,
      COALESCE((v_rate->>'sortOrder')::integer, 0),
      COALESCE((v_rate->>'effectiveAt')::timestamptz, now())
    );
  END LOOP;

  PERFORM set_config('app.commercial_document_id', COALESCE(v_previous_commercial, ''), true);
  RETURN jsonb_build_object(
    'proposalId', p_proposal_id,
    'documentKind', CASE WHEN v_proposal.document_kind = 'legacy' THEN 'design_services' ELSE v_proposal.document_kind END,
    'commercialState', 'draft',
    'currentRateVersion', v_current_version,
    'rateCount', jsonb_array_length(p_rates),
    'documentFingerprint', public._commercial_document_fingerprint(p_proposal_id)
  );
EXCEPTION WHEN OTHERS THEN
  PERFORM set_config('app.commercial_document_id', COALESCE(v_previous_commercial, ''), true);
  RAISE;
END;
$$;
ALTER FUNCTION public.upsert_design_services_draft(uuid,jsonb,jsonb) RESET ALL;
ALTER FUNCTION public.upsert_design_services_draft(uuid,jsonb,jsonb) SET search_path = pg_catalog, public, pg_temp;
ALTER FUNCTION public.upsert_design_services_draft(uuid,jsonb,jsonb) OWNER TO postgres;

CREATE OR REPLACE FUNCTION public.void_furnishings_authorization(
  p_proposal_id uuid,
  p_reason text
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, pg_temp
AS $$
DECLARE
  v_actor uuid := auth.uid();
  v_proposal public.proposals%ROWTYPE;
  v_reason text := btrim(COALESCE(p_reason, ''));
  v_freed uuid[];
  v_previous_commercial text := current_setting('app.commercial_document_id', true);
BEGIN
  IF v_actor IS NULL THEN
    RAISE EXCEPTION 'voiding an authorization requires an authenticated author'
      USING ERRCODE = 'insufficient_privilege';
  END IF;
  IF char_length(v_reason) < 5 THEN
    RAISE EXCEPTION 'voiding an authorization requires a reason of at least 5 characters'
      USING ERRCODE = 'check_violation';
  END IF;

  SELECT * INTO v_proposal FROM public.proposals
  WHERE id = p_proposal_id FOR UPDATE;
  IF NOT FOUND OR v_proposal.document_kind <> 'furnishings_authorization'
     OR NOT public._can_author_proposal(v_proposal.designer_id)
  THEN
    RAISE EXCEPTION 'furnishings authorization % not found or access denied', p_proposal_id
      USING ERRCODE = 'insufficient_privilege';
  END IF;
  IF COALESCE(v_proposal.commercial_state, 'draft') NOT IN ('draft', 'sent') THEN
    RAISE EXCEPTION 'furnishings authorization % is % and can no longer be voided',
      p_proposal_id, COALESCE(v_proposal.commercial_state, 'draft')
      USING ERRCODE = 'check_violation';
  END IF;

  SELECT COALESCE(array_agg(a.source_ffe_item_id ORDER BY a.sort_order, a.id), '{}'::uuid[])
  INTO v_freed
  FROM public.furnishing_authorization_items a
  JOIN public.project_commercial_documents d ON d.id = a.commercial_document_id
  WHERE d.proposal_id = p_proposal_id AND a.source_ffe_item_id IS NOT NULL;

  -- The exact-row commercial capability. Note what is NOT written: status. A
  -- voided draft keeps status 'draft' and a voided sent instrument keeps 'sent'
  -- — the legacy lifecycle column is not this rail's business, and the 00412
  -- terminal rule keys on OLD.commercial_state, so this transition is legal
  -- while every later one off 'superseded' is refused.
  PERFORM set_config('app.commercial_document_id', p_proposal_id::text, true);
  UPDATE public.proposals SET
    commercial_state = 'superseded',
    superseded_at = now(),
    superseded_reason = v_reason,
    updated_at = now()
  WHERE id = p_proposal_id;
  PERFORM set_config('app.commercial_document_id', COALESCE(v_previous_commercial, ''), true);

  RETURN jsonb_build_object(
    'proposalId', p_proposal_id,
    'commercialState', 'superseded',
    'freedLineIds', to_jsonb(v_freed)
  );
EXCEPTION WHEN OTHERS THEN
  PERFORM set_config('app.commercial_document_id', COALESCE(v_previous_commercial, ''), true);
  RAISE;
END;
$$;
ALTER FUNCTION public.void_furnishings_authorization(uuid,text) RESET ALL;
ALTER FUNCTION public.void_furnishings_authorization(uuid,text) SET search_path = pg_catalog, public, pg_temp;
ALTER FUNCTION public.void_furnishings_authorization(uuid,text) OWNER TO postgres;

CREATE OR REPLACE FUNCTION public.void_invoice(
  p_invoice_id uuid,
  p_reason text
)
RETURNS public.invoices
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, pg_temp
AS $$
DECLARE
  v_invoice public.invoices%ROWTYPE;
BEGIN
  SELECT * INTO v_invoice
  FROM public.invoices
  WHERE id = p_invoice_id
  FOR UPDATE;

  IF NOT FOUND OR NOT public._can_manage_invoice_owner(v_invoice.designer_id) THEN
    RAISE EXCEPTION 'void_invoice: invoice % not found or access denied', p_invoice_id;
  END IF;

  RETURN public._void_invoice_authorized_legacy_00397(p_invoice_id, p_reason);
END;
$$;
