CREATE OR REPLACE FUNCTION public.void_trade_scope(
  p_proposal_id uuid,
  p_reason text
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, pg_temp
AS $$
DECLARE
  v_actor uuid := auth.uid();
  v_proposal public.proposals%ROWTYPE;
  v_reason text := btrim(COALESCE(p_reason, ''));
  v_previous_commercial text := current_setting('app.commercial_document_id', true);
BEGIN
  IF v_actor IS NULL THEN
    RAISE EXCEPTION 'voiding a trade scope requires an authenticated author'
      USING ERRCODE = 'insufficient_privilege';
  END IF;
  IF char_length(v_reason) < 5 THEN
    RAISE EXCEPTION 'voiding a trade scope requires a reason of at least 5 characters'
      USING ERRCODE = 'check_violation';
  END IF;

  SELECT * INTO v_proposal FROM public.proposals
  WHERE id = p_proposal_id FOR UPDATE;
  IF NOT FOUND OR v_proposal.document_kind <> 'trade_scope'
     OR NOT public._can_author_proposal(v_proposal.designer_id)
  THEN
    RAISE EXCEPTION 'trade scope % not found or access denied', p_proposal_id
      USING ERRCODE = 'insufficient_privilege';
  END IF;
  IF COALESCE(v_proposal.commercial_state, 'draft') NOT IN ('draft', 'sent') THEN
    RAISE EXCEPTION 'trade scope % is % and can no longer be voided',
      p_proposal_id, COALESCE(v_proposal.commercial_state, 'draft')
      USING ERRCODE = 'check_violation';
  END IF;

  PERFORM set_config('app.commercial_document_id', p_proposal_id::text, true);
  UPDATE public.proposals SET
    commercial_state = 'superseded',
    superseded_at = now(),
    superseded_reason = v_reason,
    updated_at = now()
  WHERE id = p_proposal_id;
  PERFORM set_config('app.commercial_document_id', COALESCE(v_previous_commercial, ''), true);

  -- 00424 DELTA — the document is retired, so the asking is over. A sub holding
  -- a link to a voided scope must not be able to spend an evening pricing it,
  -- and must not be able to answer into it.
  PERFORM public._close_trade_rfqs_for_scope(p_proposal_id);

  RETURN jsonb_build_object(
    'proposalId', p_proposal_id,
    'commercialState', 'superseded'
  );
EXCEPTION WHEN OTHERS THEN
  PERFORM set_config('app.commercial_document_id', COALESCE(v_previous_commercial, ''), true);
  RAISE;
END;
$$;
ALTER FUNCTION public.void_trade_scope(uuid,text) RESET ALL;
ALTER FUNCTION public.void_trade_scope(uuid,text) SET search_path = pg_catalog, public, pg_temp;
ALTER FUNCTION public.void_trade_scope(uuid,text) OWNER TO postgres;

CREATE OR REPLACE FUNCTION public.withdraw_project_approval_decision(
  p_decision_id uuid,
  p_expected_updated_at timestamptz,
  p_reason text,
  p_idempotency_key text
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, pg_temp
AS $$
DECLARE
  v_actor uuid := auth.uid();
  v_decision public.client_decisions%ROWTYPE;
  v_receipt public.project_approval_action_receipts%ROWTYPE;
  v_reason text := btrim(COALESCE(p_reason, ''));
  v_key text := btrim(COALESCE(p_idempotency_key, ''));
  v_request_hash text;
  v_result jsonb;
  v_receipt_id uuid := extensions.gen_random_uuid();
  v_previous_parent_write text := current_setting(
    'app.project_approval_decision_write_id', true
  );
  v_previous_legacy_write text := current_setting(
    'app.client_decision_write_id', true
  );
  v_previous_evidence_write text := current_setting(
    'app.project_approval_evidence_decision_id', true
  );
  v_previous_withdraw_write text := current_setting(
    'app.project_approval_withdraw_decision_id', true
  );
BEGIN
  IF v_actor IS NULL THEN
    RAISE EXCEPTION 'project approval withdrawal requires an authenticated studio actor'
      USING ERRCODE = 'insufficient_privilege';
  END IF;
  IF p_expected_updated_at IS NULL THEN
    RAISE EXCEPTION 'p_expected_updated_at is required'
      USING ERRCODE = 'invalid_parameter_value';
  END IF;
  IF char_length(v_reason) NOT BETWEEN 1 AND 500 THEN
    RAISE EXCEPTION 'withdrawal reason must contain 1 to 500 characters'
      USING ERRCODE = 'invalid_parameter_value';
  END IF;
  IF v_key = '' OR char_length(v_key) > 200 THEN
    RAISE EXCEPTION 'idempotency key must contain 1 to 200 characters'
      USING ERRCODE = 'invalid_parameter_value';
  END IF;

  SELECT * INTO v_decision
  FROM public.client_decisions AS decision
  WHERE decision.id = p_decision_id
    AND decision.approval_contract = 'project_artifact_v1'
  FOR UPDATE;
  IF NOT FOUND OR NOT public._can_author_proposal(v_decision.designer_id) THEN
    RAISE EXCEPTION 'project approval not found or withdrawal denied'
      USING ERRCODE = 'insufficient_privilege';
  END IF;

  v_request_hash := public._project_approval_hash(jsonb_build_object(
    'decisionId', p_decision_id,
    'expectedUpdatedAt', p_expected_updated_at,
    'reason', v_reason
  ));
  SELECT * INTO v_receipt
  FROM public.project_approval_action_receipts AS receipt
  WHERE receipt.decision_id = p_decision_id
    AND receipt.action_kind = 'withdrawn'
    AND receipt.idempotency_key = v_key
  FOR UPDATE;
  IF FOUND THEN
    IF v_receipt.request_hash IS DISTINCT FROM v_request_hash
       OR v_receipt.actor_id IS DISTINCT FROM v_actor
    THEN
      RAISE EXCEPTION 'idempotency key was reused with a different withdrawal'
        USING ERRCODE = 'unique_violation';
    END IF;
    RETURN v_receipt.result || jsonb_build_object('idempotent', true);
  END IF;

  IF v_decision.updated_at IS DISTINCT FROM p_expected_updated_at THEN
    RAISE EXCEPTION 'project approval decision changed since it was loaded'
      USING ERRCODE = 'serialization_failure';
  END IF;
  IF v_decision.status NOT IN ('draft', 'pending') THEN
    RAISE EXCEPTION 'only draft or pending Stage-2 decisions may be withdrawn'
      USING ERRCODE = 'check_violation';
  END IF;
  IF EXISTS (
    SELECT 1 FROM public.client_decisions AS successor
    WHERE successor.predecessor_decision_id = p_decision_id
  ) THEN
    RAISE EXCEPTION 'only a current Stage-2 leaf may be withdrawn'
      USING ERRCODE = 'check_violation';
  END IF;

  PERFORM set_config(
    'app.project_approval_decision_write_id', p_decision_id::text, true
  );
  PERFORM set_config(
    'app.client_decision_write_id', p_decision_id::text, true
  );
  PERFORM set_config(
    'app.project_approval_withdraw_decision_id', p_decision_id::text, true
  );
  UPDATE public.client_decisions
  SET status = 'expired', updated_at = now()
  WHERE id = p_decision_id
  RETURNING * INTO v_decision;

  v_result := jsonb_build_object(
    'receiptId', v_receipt_id,
    'projectId', v_decision.project_id,
    'decisionId', v_decision.id,
    'status', v_decision.status,
    'disposition', 'withdrawn',
    'reason', v_reason,
    'updatedAt', v_decision.updated_at
  );
  PERFORM set_config(
    'app.project_approval_evidence_decision_id', p_decision_id::text, true
  );
  INSERT INTO public.project_approval_action_receipts (
    id, project_id, decision_id, action_kind, idempotency_key,
    request_hash, actor_id, result
  ) VALUES (
    v_receipt_id, v_decision.project_id, p_decision_id, 'withdrawn', v_key,
    v_request_hash, v_actor, v_result
  );

  PERFORM set_config(
    'app.project_approval_decision_write_id',
    COALESCE(v_previous_parent_write, ''), true
  );
  PERFORM set_config(
    'app.client_decision_write_id', COALESCE(v_previous_legacy_write, ''), true
  );
  PERFORM set_config(
    'app.project_approval_evidence_decision_id',
    COALESCE(v_previous_evidence_write, ''), true
  );
  PERFORM set_config(
    'app.project_approval_withdraw_decision_id',
    COALESCE(v_previous_withdraw_write, ''), true
  );
  RETURN v_result || jsonb_build_object('idempotent', false);
EXCEPTION WHEN OTHERS THEN
  PERFORM set_config(
    'app.project_approval_decision_write_id',
    COALESCE(v_previous_parent_write, ''), true
  );
  PERFORM set_config(
    'app.client_decision_write_id', COALESCE(v_previous_legacy_write, ''), true
  );
  PERFORM set_config(
    'app.project_approval_evidence_decision_id',
    COALESCE(v_previous_evidence_write, ''), true
  );
  PERFORM set_config(
    'app.project_approval_withdraw_decision_id',
    COALESCE(v_previous_withdraw_write, ''), true
  );
  RAISE;
END;
$$;
ALTER FUNCTION public.withdraw_project_approval_decision(uuid,timestamp with time zone,text,text) RESET ALL;
ALTER FUNCTION public.withdraw_project_approval_decision(uuid,timestamp with time zone,text,text) SET search_path = pg_catalog, public, pg_temp;
ALTER FUNCTION public.withdraw_project_approval_decision(uuid,timestamp with time zone,text,text) OWNER TO postgres;

CREATE OR REPLACE FUNCTION public.begin_direction_from_discovery(p_designer_client_id uuid)
returns uuid
language plpgsql
security invoker
set search_path = public, pg_temp
as $$
declare
  v_disc client_discovery%rowtype;
  v_dc   designer_clients%rowtype;
  v_prop uuid;
  v_room jsonb;
  v_sort int := 0;
  v_seeded_state text;
  v_seeded_found boolean := false;
begin
  -- RLS-filtered read: a designer can only touch their own engagement.
  select * into v_disc from client_discovery where designer_client_id = p_designer_client_id;
  if not found then
    raise exception 'discovery not found or access denied for %', p_designer_client_id;
  end if;

  -- Idempotency: already seeded → return the existing draft. 00414: unless the
  -- commercial cutover retired it. A superseded edition is terminal — nothing
  -- can send, sign, or activate it — so returning it would strand the
  -- engagement on a dead document. Fall through and mint a fresh one instead.
  -- (The read is RLS-filtered like every other read here; an invisible seed
  --  keeps the pre-00414 answer.)
  if v_disc.seeded_proposal_id is not null then
    select seed.commercial_state into v_seeded_state
    from proposals as seed where seed.id = v_disc.seeded_proposal_id;
    v_seeded_found := found;
    if not v_seeded_found or v_seeded_state is distinct from 'superseded' then
      return v_disc.seeded_proposal_id;
    end if;
  end if;

  -- The soft gate, server-enforced for the seed: the five essentials must be filled.
  if v_disc.project_type is null
     or jsonb_array_length(coalesce(v_disc.rooms, '[]'::jsonb)) = 0
     or v_disc.budget_max_cents is null
     or (v_disc.target_date is null and v_disc.hard_date is null)
     or (coalesce(array_length(v_disc.style_tag_ids, 1), 0) = 0
         and coalesce(array_length(v_disc.style_keywords, 1), 0) = 0)
     or jsonb_array_length(coalesce(v_disc.lifestyle, '[]'::jsonb)) = 0
  then
    raise exception 'discovery not ready: the five essentials must be captured';
  end if;

  select * into v_dc from designer_clients where id = p_designer_client_id;

  -- 1) The DRAFT proposal (the Shape D→B flip). Mirrors useCreateProposal's
  --    minimal insert (use-proposals.ts). version/total_amount take defaults.
  --    Arrival Arc (I62): also stamp the household link so Shape B can rescue a
  --    no-login household's name post-flip. 00414: the seed is a design-services
  --    edition from birth, so the whole engagement rides the commercial rail
  --    (send_commercial_document, the two-act signature, billing authority)
  --    instead of the legacy accept-then-activate path.
  insert into proposals (
    designer_id, client_id, designer_client_id, title, status, description,
    document_kind, commercial_state
  )
  values (
    v_dc.designer_id,
    v_dc.client_id,
    p_designer_client_id,
    coalesce(nullif(v_dc.client_name, ''), 'New proposal'),
    'draft',
    'Seeded from Discovery · budget '
      || coalesce(to_char(v_disc.budget_min_cents / 100, 'FM999,999,999'), '?')
      || '–'
      || coalesce(to_char(v_disc.budget_max_cents / 100, 'FM999,999,999'), '?'),
    'design_services',
    'draft'
  )
  returning id into v_prop;

  -- 2) Scope rooms, field→field from the discovery rooms[].
  for v_room in select * from jsonb_array_elements(v_disc.rooms) loop
    insert into proposal_scope_rooms
      (proposal_id, name, room_type, floor_area_sqft, budget_cents, notes, sort_order)
    values (
      v_prop,
      coalesce(nullif(v_room->>'name', ''), 'Room'),
      nullif(v_room->>'room_type', ''),
      nullif(v_room->>'floor_area_sqft', '')::numeric,
      0,  -- per-room budget is allocated in the Drafting Room
      nullif(
        concat_ws(' · ',
          case when coalesce((v_room->>'keep_as_is')::boolean, false) then 'Keep as-is' end,
          nullif(v_room->>'notes', '')),
        ''),
      v_sort
    );
    v_sort := v_sort + 1;
  end loop;

  -- 3) Style read → a 'vision' narrative section (the Drafting Room Vision facet
  --    reads this; the designer fleshes it into palette/boards). metadata carries
  --    the structured tag ids for a future palette auto-build.
  insert into proposal_sections (proposal_id, type, title, body, metadata, sort_order)
  values (
    v_prop,
    'vision',
    'Style direction',
    nullif(array_to_string(v_disc.style_keywords, ' · '), ''),
    jsonb_build_object('style_tag_ids', to_jsonb(v_disc.style_tag_ids)),
    0
  );

  -- 4) Stamp the discovery row seeded (idempotency + provenance).
  update client_discovery
     set seeded_proposal_id = v_prop,
         seeded_at = now(),
         ready_at = coalesce(ready_at, now()),
         updated_at = now()
   where id = v_disc.id;

  return v_prop;
end;
$$;
ALTER FUNCTION public.begin_direction_from_discovery(uuid) RESET ALL;
ALTER FUNCTION public.begin_direction_from_discovery(uuid) SET search_path = public, pg_temp;
ALTER FUNCTION public.begin_direction_from_discovery(uuid) OWNER TO postgres;

CREATE OR REPLACE FUNCTION public.ceremony_complete(
  p_lead_id         uuid,
  p_intro           text,
  p_slots           jsonb,
  p_timezone        text,
  p_credential_line text DEFAULT NULL,
  p_portfolio_url   text DEFAULT NULL
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, pg_temp
AS $$
DECLARE
  v_uid          uuid := auth.uid();
  v_lead         leads%ROWTYPE;
  v_ceremony     match_ceremonies%ROWTYPE;
  v_slot         jsonb;
  v_slots        jsonb := '[]'::jsonb;
  v_slot_count   int;
  v_starts       timestamptz;
  v_dc           designer_clients%ROWTYPE;
  v_client_name  text;
  v_scan         room_scans%ROWTYPE;
  v_scan_found   boolean := false;
  v_rooms        jsonb := '[]'::jsonb;
  v_styles       text[] := '{}';
  v_scan_id      uuid;
  v_budget_min   integer;
  v_budget_max   integer;
  v_band         text[];
  v_thread_id    uuid;
  v_msg_id       uuid;
  v_studio_name  text;
  v_log_id       uuid;
  v_title        text;
  v_message      text;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'not_authenticated' USING DETAIL = 'auth.uid() is null';
  END IF;

  -- ── Validate: caller owns the lead, and the ceremony stub exists ──
  SELECT * INTO v_lead FROM leads WHERE id = p_lead_id;
  IF NOT FOUND OR v_lead.designer_id IS DISTINCT FROM v_uid THEN
    RAISE EXCEPTION 'not_authorized' USING DETAIL = p_lead_id::text;
  END IF;

  -- Lock the ceremony row: serializes a double-send race on one transaction.
  SELECT * INTO v_ceremony FROM match_ceremonies
   WHERE lead_id = p_lead_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'ceremony_not_found'
      USING DETAIL = 'accept_design_request has not run for lead ' || p_lead_id::text;
  END IF;

  -- ── IDEMPOTENT: already sent/picked → return the existing stamps ──
  IF v_ceremony.state IN ('sent', 'picked') THEN
    RETURN jsonb_build_object(
      'ceremony_id',        v_ceremony.id,
      'lead_id',            p_lead_id,
      'designer_client_id', v_ceremony.designer_client_id,
      'thread_id',          v_ceremony.thread_id,
      'intro_message_id',   v_ceremony.intro_message_id,
      'already_sent',       true
    );
  END IF;

  -- ── Gate re-check (2.2: non-empty words AND 2–3 future slots) ──
  IF p_intro IS NULL OR btrim(p_intro) = '' THEN
    RAISE EXCEPTION 'intro_required' USING DETAIL = 'the introduction must be written';
  END IF;

  IF p_slots IS NULL OR jsonb_typeof(p_slots) <> 'array' THEN
    RAISE EXCEPTION 'slots_invalid' USING DETAIL = 'offered slots must be a json array';
  END IF;
  v_slot_count := jsonb_array_length(p_slots);
  IF v_slot_count < 2 OR v_slot_count > 3 THEN
    RAISE EXCEPTION 'slots_count' USING DETAIL = '2-3 offered slots required, got ' || v_slot_count;
  END IF;

  -- Normalize: every slot gets a server-side uuid id if absent, a 45-minute
  -- default duration, and must start in the future.
  FOR v_slot IN SELECT * FROM jsonb_array_elements(p_slots) LOOP
    v_starts := (v_slot->>'starts_at')::timestamptz;
    IF v_starts IS NULL THEN
      RAISE EXCEPTION 'slot_starts_at_required' USING DETAIL = v_slot::text;
    END IF;
    IF v_starts <= now() THEN
      RAISE EXCEPTION 'slot_in_past' USING DETAIL = v_starts::text;
    END IF;
    v_slots := v_slots || jsonb_build_array(jsonb_build_object(
      'id',               COALESCE(NULLIF(v_slot->>'id', '')::uuid, gen_random_uuid()),
      'starts_at',        to_jsonb(v_starts),
      'duration_minutes', COALESCE(NULLIF(v_slot->>'duration_minutes', '')::int, 45)
    ));
  END LOOP;

  -- ── Freeze the ceremony FIRST: the 00332 trigger guard reads state='sent'
  --    when the leads UPDATE below fires it, suppressing the generic 00289
  --    homeowner notification in favor of the named introduction moment. ──
  UPDATE match_ceremonies
     SET state           = 'sent',
         intro_text      = p_intro,
         credential_line = NULLIF(btrim(COALESCE(p_credential_line, '')), ''),
         portfolio_url   = NULLIF(btrim(COALESCE(p_portfolio_url, '')), ''),
         offered_slots   = v_slots,
         offered_at      = now(),
         timezone        = NULLIF(btrim(COALESCE(p_timezone, '')), ''),
         updated_at      = now()
   WHERE id = v_ceremony.id;

  UPDATE leads
     SET status      = 'accepted',
         accepted_at = COALESCE(accepted_at, now()),
         updated_at  = now()
   WHERE id = p_lead_id;

  -- ── designer_clients: the engagement row (I65 bug 2 — NEVER downgrade an
  --    active/proposal relationship; the index re-scope above makes a second,
  --    engagement-scoped 'lead' row legal). Resolution order:
  --      1. a lead-status row already linked to THIS lead (idempotency/root)
  --      2. a virgin lead-status row for the pair (no lead linked) → adopt it
  --      3. otherwise INSERT a fresh engagement row — existing active/proposal
  --         rows are never read, touched, or downgraded. ──
  SELECT COALESCE(NULLIF(btrim(p.display_name), ''), p.full_name)
    INTO v_client_name
  FROM profiles p WHERE p.id = v_lead.homeowner_id;

  SELECT * INTO v_dc FROM designer_clients
   WHERE designer_id = v_uid AND lead_id = p_lead_id AND status = 'lead'
   ORDER BY created_at LIMIT 1;

  IF NOT FOUND THEN
    SELECT * INTO v_dc FROM designer_clients
     WHERE designer_id = v_uid AND client_id = v_lead.homeowner_id
       AND status = 'lead' AND lead_id IS NULL
     ORDER BY created_at LIMIT 1;

    IF FOUND THEN
      UPDATE designer_clients
         SET lead_id     = p_lead_id,
             client_name = COALESCE(client_name, v_client_name),
             source      = COALESCE(source, 'design_request'),
             updated_at  = now()
       WHERE id = v_dc.id
       RETURNING * INTO v_dc;
    ELSE
      INSERT INTO designer_clients (designer_id, client_id, client_name, source, lead_id, status)
      VALUES (v_uid, v_lead.homeowner_id, v_client_name, 'design_request', p_lead_id, 'lead')
      RETURNING * INTO v_dc;
    END IF;
  END IF;

  -- ── client_discovery, seeded atomically from the request (I65 find 1: this
  --    replaces the lazy first-render seed for arc-born engagements). ──
  SELECT rs.* INTO v_scan
  FROM lead_room_scans lrs
  JOIN room_scans rs ON rs.id = lrs.scan_id
  WHERE lrs.lead_id = p_lead_id
  ORDER BY lrs.is_primary DESC, lrs.position ASC
  LIMIT 1;
  v_scan_found := FOUND;

  IF v_scan_found THEN
    v_rooms := jsonb_build_array(jsonb_build_object(
      'name',            initcap(replace(COALESCE(NULLIF(v_scan.room_type, ''), 'room'), '_', ' ')),
      'floor_area_sqft', v_scan.floor_area
    ));
    v_styles  := COALESCE(v_scan.suggested_styles, '{}');
    v_scan_id := v_scan.id;
  END IF;

  -- Budget mapping, DEFENSIVE (I62: prod budget_range has drifted to free
  -- text). The 5 documented slugs, then a $Nk–$Mk / $Nk-$Mk parse (en/em dash
  -- or hyphen, optional $ and decimals), else both stay null.
  CASE v_lead.budget_range
    WHEN 'under_5k'  THEN v_budget_min := 0;          v_budget_max := 500000;
    WHEN '5k_15k'    THEN v_budget_min := 500000;     v_budget_max := 1500000;
    WHEN '15k_50k'   THEN v_budget_min := 1500000;    v_budget_max := 5000000;
    WHEN '50k_100k'  THEN v_budget_min := 5000000;    v_budget_max := 10000000;
    WHEN 'over_100k' THEN v_budget_min := 10000000;   v_budget_max := NULL;
    ELSE
      v_band := regexp_match(
        COALESCE(v_lead.budget_range, ''),
        '^\$?\s*(\d+(?:\.\d+)?)\s*[kK]\s*[–—-]\s*\$?\s*(\d+(?:\.\d+)?)\s*[kK]$'
      );
      IF v_band IS NOT NULL THEN
        v_budget_min := round(v_band[1]::numeric * 100000);
        v_budget_max := round(v_band[2]::numeric * 100000);
      END IF;
  END CASE;

  INSERT INTO client_discovery (
    designer_client_id, designer_id, project_type, rooms, style_keywords,
    budget_min_cents, budget_max_cents, room_scan_id
  )
  VALUES (
    v_dc.id, v_uid, v_lead.project_type, v_rooms, v_styles,
    v_budget_min, v_budget_max, v_scan_id
  )
  ON CONFLICT (designer_client_id) DO NOTHING;
  -- ready_at stays null: the seed pre-fills, it does not declare readiness.

  -- ── The thread + the introduction as its head message (R106 §6: "this
  --    message becomes the head of the client–designer thread"). ──
  -- rpc_start_direct_thread (00103) reads auth.uid() from the JWT claim, which
  -- survives the definer context (I65-verified); idempotent by design (finds
  -- an existing direct thread for the pair first).
  v_thread_id := public.rpc_start_direct_thread(v_lead.homeowner_id);

  INSERT INTO comms_messages (thread_id, sender_id, body)
  VALUES (v_thread_id, v_uid, p_intro)
  RETURNING id INTO v_msg_id;

  -- ── Client notification: the named introduction moment. Best-effort — a
  --    notification failure must never unwind the send. ──
  BEGIN
    SELECT rsi.name INTO v_studio_name
    FROM public.resolve_studio_identity(NULL, v_uid) rsi;
    v_studio_name := COALESCE(NULLIF(btrim(v_studio_name), ''), 'Your designer');

    v_title   := v_studio_name || ' introduced themselves';
    v_message := v_studio_name || ' introduced themselves — pick a time.';

    INSERT INTO notification_log (user_id, type, channel, status, template_id, metadata)
    VALUES (
      v_lead.homeowner_id,
      'match_introduction',
      'in_app',
      'delivered',
      'design-request-intro-delivered',
      jsonb_build_object(
        'lead_id',            p_lead_id,
        'designer_id',        v_uid,
        'ceremony_id',        v_ceremony.id,
        'designer_client_id', v_dc.id,
        'thread_id',          v_thread_id,
        'entity_type',        'design_request',
        'entity_id',          p_lead_id::text,
        'title',              v_title,
        'message',            v_message,
        'deep_link',          '/doc/' || p_lead_id::text,
        'url',                '/doc/' || p_lead_id::text
      )
    )
    RETURNING id INTO v_log_id;

    PERFORM public.invoke_edge_function(
      'notification-dispatch',
      jsonb_build_object(
        'user_id',     v_lead.homeowner_id,
        'type',        'match_introduction',
        'channel',     'email',
        'template_id', 'design-request-intro-delivered',
        'data', jsonb_build_object(
          'studio_name', v_studio_name,
          'projectType', v_lead.project_type,
          'slot_count',  v_slot_count,
          'leadId',      p_lead_id,
          'thread_id',   v_thread_id
        ),
        'priority', 'high'
      )
    );

    PERFORM public.invoke_edge_function(
      'apns-send',
      jsonb_build_object(
        'user_id',             v_lead.homeowner_id,
        'title',               v_title,
        'body',                v_message,
        'entity_type',         'design_request',
        'entity_id',           p_lead_id::text,
        'notification_log_id', v_log_id
      )
    );
  EXCEPTION WHEN OTHERS THEN
    RAISE WARNING 'ceremony_complete: notification step failed for lead %: %',
      p_lead_id, sqlerrm;
  END;

  -- ── Stamp the ceremony with what the send created. ──
  UPDATE match_ceremonies
     SET designer_client_id = v_dc.id,
         thread_id          = v_thread_id,
         intro_message_id   = v_msg_id,
         updated_at         = now()
   WHERE id = v_ceremony.id;

  RETURN jsonb_build_object(
    'ceremony_id',        v_ceremony.id,
    'lead_id',            p_lead_id,
    'designer_client_id', v_dc.id,
    'thread_id',          v_thread_id,
    'intro_message_id',   v_msg_id,
    'already_sent',       false
  );
END;
$$;
ALTER FUNCTION public.ceremony_complete(uuid,text,jsonb,text,text,text) RESET ALL;
ALTER FUNCTION public.ceremony_complete(uuid,text,jsonb,text,text,text) SET search_path = pg_catalog, public, pg_temp;
ALTER FUNCTION public.ceremony_complete(uuid,text,jsonb,text,text,text) OWNER TO postgres;

CREATE OR REPLACE FUNCTION public.reassign_project_lead(
  p_project_id uuid,
  p_expected_designer_id uuid,
  p_new_designer_id uuid
)
RETURNS public.projects
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, pg_temp
AS $$
DECLARE
  v_actor uuid := auth.uid();
  v_project public.projects%ROWTYPE;
  v_old_relationship public.designer_clients%ROWTYPE;
  v_new_relationship_id uuid;
  v_studio_id uuid;
  v_actor_name text;
  v_decision record;
BEGIN
  IF v_actor IS NULL THEN
    RAISE EXCEPTION 'reassign_project_lead requires an authenticated user'
      USING ERRCODE = 'insufficient_privilege';
  END IF;
  IF p_new_designer_id IS NULL THEN
    RAISE EXCEPTION 'a new lead designer is required'
      USING ERRCODE = 'invalid_parameter_value';
  END IF;

  SELECT * INTO v_project
  FROM public.projects
  WHERE id = p_project_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'project % not found or access denied', p_project_id
      USING ERRCODE = 'insufficient_privilege';
  END IF;
  IF v_project.designer_id IS DISTINCT FROM p_expected_designer_id THEN
    RAISE EXCEPTION 'project % lead changed since it was loaded', p_project_id
      USING ERRCODE = 'serialization_failure';
  END IF;
  IF v_project.status IN ('completed', 'archived') THEN
    RAISE EXCEPTION 'terminal project lead is immutable'
      USING ERRCODE = 'check_violation';
  END IF;
  SELECT organization.id INTO v_studio_id
    FROM public.organizations AS organization
    JOIN public.organization_members AS old_membership
      ON old_membership.organization_id = organization.id
    JOIN public.organization_members AS new_membership
      ON new_membership.organization_id = organization.id
    WHERE organization.id = v_project.studio_id
      AND old_membership.user_id = v_project.designer_id
      AND old_membership.status = 'active'
      AND old_membership.role <> 'guest'
      AND new_membership.user_id = p_new_designer_id
      AND new_membership.status = 'active'
      AND new_membership.role <> 'guest'
      AND organization.type = 'design_studio'
      AND organization.status = 'active'
      AND (
        v_actor = v_project.designer_id
        OR EXISTS (
          SELECT 1
          FROM public.organization_members AS actor_membership
          WHERE actor_membership.organization_id = organization.id
            AND actor_membership.user_id = v_actor
            AND actor_membership.status = 'active'
            AND actor_membership.role IN ('owner', 'admin')
        )
      )
    ORDER BY organization.id
    LIMIT 1;

  IF v_studio_id IS NULL
     OR NOT EXISTS (
       SELECT 1 FROM public.profiles
       WHERE id = p_new_designer_id AND is_designer IS TRUE
     )
  THEN
    RAISE EXCEPTION
      'lead reassignment requires the current lead or an exact-studio owner/admin and an active designer target'
      USING ERRCODE = 'insufficient_privilege';
  END IF;
  IF p_new_designer_id = v_project.designer_id THEN
    RETURN v_project;
  END IF;

  SELECT * INTO v_old_relationship
  FROM public.designer_clients
  WHERE (
      v_project.proposal_id IS NOT NULL
      AND id = (
        SELECT proposal.designer_client_id
        FROM public.proposals AS proposal
        WHERE proposal.id = v_project.proposal_id
      )
    ) OR (
      v_project.proposal_id IS NULL
      AND designer_id = v_project.designer_id
      AND client_id = v_project.client_id
    )
  ORDER BY (status <> 'lead') DESC, created_at, id
  LIMIT 1
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'project has no canonical designer-client relationship'
      USING ERRCODE = 'check_violation';
  END IF;

  INSERT INTO public.designer_clients (
    designer_id, client_id, client_name, client_email, nickname,
    status, source, first_project_at, last_project_at
  ) VALUES (
    p_new_designer_id, v_project.client_id,
    v_old_relationship.client_name, v_old_relationship.client_email,
    v_old_relationship.nickname, 'active',
    COALESCE(v_old_relationship.source, 'direct'),
    COALESCE(v_old_relationship.first_project_at, now()), now()
  )
  ON CONFLICT (designer_id, client_id)
    WHERE client_id IS NOT NULL AND status <> 'lead'
  DO UPDATE SET last_project_at = now(), updated_at = now()
  RETURNING id INTO v_new_relationship_id;

  INSERT INTO public.project_team_members (
    project_id, user_id, role, assigned_by, removed_at
  ) VALUES (
    p_project_id, v_project.designer_id, 'previous_lead', v_actor, NULL
  )
  ON CONFLICT (project_id, user_id, role)
  DO UPDATE SET removed_at = NULL, assigned_by = EXCLUDED.assigned_by,
                updated_at = now();

  UPDATE public.project_team_members
  SET removed_at = now(), updated_at = now()
  WHERE project_id = p_project_id
    AND user_id = v_project.designer_id
    AND role = 'lead_designer'
    AND removed_at IS NULL;

  INSERT INTO public.project_team_members (
    project_id, user_id, role, assigned_by, removed_at
  ) VALUES (
    p_project_id, p_new_designer_id, 'lead_designer', v_actor, NULL
  )
  ON CONFLICT (project_id, user_id, role)
  DO UPDATE SET removed_at = NULL, assigned_by = EXCLUDED.assigned_by,
                updated_at = now();

  SELECT full_name INTO v_actor_name
  FROM public.profiles
  WHERE id = v_actor;

  INSERT INTO public.client_activity_log (
    designer_client_id, activity_type, title, metadata, actor_name
  ) VALUES (
    v_old_relationship.id, 'lead_reassigned', 'Lead designer reassigned',
    jsonb_build_object(
      'project_id', p_project_id,
      'old_designer_id', v_project.designer_id,
      'new_designer_id', p_new_designer_id
    ),
    COALESCE(v_actor_name, 'Unknown')
  );

  INSERT INTO public.audit_logs (
    user_id, organization_id, action, resource_type, resource_id,
    old_values, new_values, metadata
  ) VALUES (
    v_actor, v_studio_id, 'project.lead_reassigned', 'project', p_project_id,
    jsonb_build_object('designer_id', v_project.designer_id),
    jsonb_build_object('designer_id', p_new_designer_id),
    jsonb_build_object('via', 'reassign_project_lead')
  );

  PERFORM set_config('app.project_reassignment_id', p_project_id::text, true);
  UPDATE public.projects
  SET designer_id = p_new_designer_id, updated_at = now()
  WHERE id = p_project_id
  RETURNING * INTO v_project;
  PERFORM set_config('app.project_reassignment_id', '', true);

  -- Proposal approvals retain the source proposal relationship as historical
  -- evidence. Other project decisions follow the current lead atomically.
  FOR v_decision IN
    SELECT id
    FROM public.client_decisions
    WHERE project_id = p_project_id
      AND linked_proposal_id IS NULL
    ORDER BY id
    FOR UPDATE
  LOOP
    PERFORM set_config('app.client_decision_write_id', v_decision.id::text, true);
    UPDATE public.client_decisions
    SET designer_id = p_new_designer_id,
        designer_client_id = v_new_relationship_id,
        updated_at = now()
    WHERE id = v_decision.id;
  END LOOP;
  PERFORM set_config('app.client_decision_write_id', '', true);

  RETURN v_project;
END;
$$;
ALTER FUNCTION public.reassign_project_lead(uuid,uuid,uuid) RESET ALL;
ALTER FUNCTION public.reassign_project_lead(uuid,uuid,uuid) SET search_path = pg_catalog, public, pg_temp;
ALTER FUNCTION public.reassign_project_lead(uuid,uuid,uuid) OWNER TO postgres;

CREATE OR REPLACE FUNCTION public.submit_design_request(
  p_scan_ids         uuid[],
  p_project_type     text,
  p_primary_scan_id  uuid DEFAULT NULL,
  p_budget_range     text DEFAULT NULL,
  p_timeline         text DEFAULT NULL,
  p_description      text DEFAULT NULL,
  p_designer_id      uuid DEFAULT NULL,
  p_source           text DEFAULT 'Patina app',
  p_client_request_id uuid DEFAULT NULL
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, pg_temp
AS $$
DECLARE
  v_uid         uuid := auth.uid();
  v_primary     uuid;
  v_scan_id     uuid;
  v_scan_status text;
  v_designer_id uuid := p_designer_id;
  v_dc_designers uuid[];
  v_city        text;
  v_state       text;
  v_zip         text;
  v_lead_id     uuid;
  v_pos         integer := 0;
  v_scan_count  integer := COALESCE(array_length(p_scan_ids, 1), 0);
  -- A roomless request carries no scans: skip scan validation, leave
  -- leads.room_scan_id NULL, write no junction/association rows.
  v_is_roomless boolean := (p_scan_ids IS NULL OR COALESCE(array_length(p_scan_ids, 1), 0) = 0);
  -- idempotent-replay probes (kept separate so a miss cannot clobber v_designer_id)
  v_replay_id       uuid;
  v_replay_designer uuid;
  v_replay_status   text;
BEGIN
  -- ── validation (stable machine-readable slugs; iOS maps on message) ────────
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'not_authenticated' USING DETAIL = 'auth.uid() is null';
  END IF;

  -- Scans are optional now. Validate them only when provided.
  IF NOT v_is_roomless THEN
    v_primary := COALESCE(p_primary_scan_id, p_scan_ids[1]);
    IF NOT (v_primary = ANY (p_scan_ids)) THEN
      RAISE EXCEPTION 'primary_not_in_set' USING DETAIL = v_primary::text;
    END IF;
  END IF;

  IF p_project_type IS NULL
     OR p_project_type NOT IN ('full_room', 'consultation', 'single_piece', 'staging') THEN
    RAISE EXCEPTION 'invalid_project_type' USING DETAIL = COALESCE(p_project_type, 'null');
  END IF;

  IF v_designer_id IS NOT NULL
     AND NOT EXISTS (SELECT 1 FROM profiles p WHERE p.id = v_designer_id AND p.is_designer) THEN
    RAISE EXCEPTION 'designer_not_found' USING DETAIL = v_designer_id::text;
  END IF;

  IF NOT v_is_roomless THEN
    FOREACH v_scan_id IN ARRAY p_scan_ids LOOP
      SELECT rs.status INTO v_scan_status
      FROM room_scans rs
      WHERE rs.id = v_scan_id AND rs.user_id = v_uid;

      IF NOT FOUND THEN
        RAISE EXCEPTION 'scan_not_found_or_not_owned' USING DETAIL = v_scan_id::text;
      END IF;
      IF v_scan_status IS DISTINCT FROM 'ready' THEN
        RAISE EXCEPTION 'scan_not_ready' USING DETAIL = v_scan_id::text;
      END IF;
    END LOOP;
  END IF;

  -- ── idempotent replay ─────────────────────────────────────────────────────
  IF p_client_request_id IS NOT NULL THEN
    SELECT l.id, l.designer_id, l.status
      INTO v_replay_id, v_replay_designer, v_replay_status
    FROM leads l
    WHERE l.homeowner_id = v_uid
      AND l.client_request_id = p_client_request_id
    LIMIT 1;

    IF v_replay_id IS NOT NULL THEN
      RETURN jsonb_build_object(
        'lead_id',           v_replay_id,
        'designer_id',       v_replay_designer,
        'status',            v_replay_status,
        'pooled',            (v_replay_designer IS NULL),
        'idempotent_replay', true
      );
    END IF;
  END IF;

  -- ── auto-resolve designer (conductor ruling #2) ──────────────────────────
  -- Assign iff the caller has EXACTLY ONE active designer_clients relationship.
  IF v_designer_id IS NULL THEN
    SELECT array_agg(DISTINCT dc.designer_id) INTO v_dc_designers
    FROM designer_clients dc
    WHERE dc.client_id = v_uid AND dc.status = 'active';

    IF array_length(v_dc_designers, 1) = 1 THEN
      v_designer_id := v_dc_designers[1];
    END IF;
  END IF;

  -- Copy the homeowner''s location onto the lead so the pool card / Brief can
  -- show a city/state without exposing the profile.
  SELECT p.city, p.state, p.zip INTO v_city, v_state, v_zip
  FROM profiles p WHERE p.id = v_uid;

  -- ── insert lead ───────────────────────────────────────────────────────────
  -- room_scan_id = v_primary, which is NULL for a roomless request.
  BEGIN
    INSERT INTO leads (
      homeowner_id, designer_id, project_type, project_description,
      budget_range, timeline, status, source, room_scan_id, client_request_id,
      location_city, location_state, location_zip
    ) VALUES (
      v_uid, v_designer_id, p_project_type, p_description,
      p_budget_range, p_timeline, 'new', COALESCE(p_source, 'Patina app'),
      v_primary, p_client_request_id,
      v_city, v_state, v_zip
    )
    RETURNING id INTO v_lead_id;
  EXCEPTION WHEN unique_violation THEN
    IF p_client_request_id IS NULL THEN
      RAISE;  -- no idempotency key in play — not our race, rethrow
    END IF;

    -- concurrent duplicate with the same idempotency key: replay the winner
    SELECT l.id, l.designer_id, l.status
      INTO v_replay_id, v_replay_designer, v_replay_status
    FROM leads l
    WHERE l.homeowner_id = v_uid
      AND l.client_request_id = p_client_request_id
    LIMIT 1;

    IF v_replay_id IS NULL THEN
      RAISE;  -- some other unique constraint fired — rethrow
    END IF;

    RETURN jsonb_build_object(
      'lead_id',           v_replay_id,
      'designer_id',       v_replay_designer,
      'status',            v_replay_status,
      'pooled',            (v_replay_designer IS NULL),
      'idempotent_replay', true
    );
  END;

  -- ── junction rows (ordered; exactly one primary) — none when roomless ─────
  v_pos := 0;
  FOREACH v_scan_id IN ARRAY p_scan_ids LOOP
    INSERT INTO lead_room_scans (lead_id, scan_id, is_primary, position)
    VALUES (v_lead_id, v_scan_id, (v_scan_id = v_primary), v_pos)
    ON CONFLICT (lead_id, scan_id) DO NOTHING;
    v_pos := v_pos + 1;
  END LOOP;

  -- ── resolved designer: mint associations + in-app notification ───────────
  IF v_designer_id IS NOT NULL THEN
    -- No-op FOREACH over an empty array for a roomless request.
    FOREACH v_scan_id IN ARRAY p_scan_ids LOOP
      INSERT INTO room_scan_associations (
        scan_id, consumer_id, designer_id, association_type, status, access_level,
        shared_at, requested_at, lead_id
      ) VALUES (
        v_scan_id, v_uid, v_designer_id, 'explicit', 'active', 'full',
        now(), now(), v_lead_id
      )
      ON CONFLICT (scan_id, designer_id) DO UPDATE SET
        status         = 'active',
        access_level   = 'full',
        shared_at      = now(),
        revoked_at     = NULL,
        revoked_reason = NULL,
        lead_id        = EXCLUDED.lead_id,
        updated_at     = now();
    END LOOP;

    -- In-app inbox row (bell polls). Best-effort — a notification failure must
    -- never fail the submit. Emails are the 00042 triggers' job, not ours.
    BEGIN
      INSERT INTO notification_log (user_id, type, channel, status, template_id, metadata)
      VALUES (
        v_designer_id,
        'design_request_received',
        'in_app',
        'delivered',
        'design-request-received',
        jsonb_build_object(
          'lead_id',    v_lead_id,
          'scan_count', v_scan_count,
          'title',      'New design request',
          'message',    CASE
                          WHEN v_is_roomless THEN
                            'A homeowner sent you a design request (no room scan attached).'
                          ELSE
                            'A homeowner sent you a design request with '
                              || v_scan_count::text || ' room scan'
                              || CASE WHEN v_scan_count = 1 THEN '' ELSE 's' END || '.'
                        END,
          'deep_link',  '/doc/' || v_lead_id::text,
          'url',        '/doc/' || v_lead_id::text
        )
      );
    EXCEPTION WHEN OTHERS THEN
      RAISE WARNING 'submit_design_request: notification insert failed for lead %: %',
        v_lead_id, sqlerrm;
    END;
  END IF;

  RETURN jsonb_build_object(
    'lead_id',           v_lead_id,
    'designer_id',       v_designer_id,
    'status',            'new',
    'pooled',            (v_designer_id IS NULL),
    'idempotent_replay', false
  );
END;
$$;
ALTER FUNCTION public.submit_design_request(uuid[],text,uuid,text,text,text,uuid,text,uuid) RESET ALL;
ALTER FUNCTION public.submit_design_request(uuid[],text,uuid,text,text,text,uuid,text,uuid) SET search_path = pg_catalog, public, pg_temp;
ALTER FUNCTION public.submit_design_request(uuid[],text,uuid,text,text,text,uuid,text,uuid) OWNER TO postgres;

CREATE OR REPLACE FUNCTION public._void_invoice_authorized_legacy_00397(
  p_invoice_id uuid,
  p_reason text
)
RETURNS public.invoices
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, pg_temp
AS $$
DECLARE
  v_invoice invoices%ROWTYPE;
BEGIN
  SELECT * INTO v_invoice FROM invoices WHERE id = p_invoice_id FOR UPDATE;
  IF NOT FOUND OR NOT public.is_studio_comember(v_invoice.designer_id) THEN
    RAISE EXCEPTION 'void_invoice: invoice % not found or access denied', p_invoice_id;
  END IF;
  IF v_invoice.status NOT IN ('draft','sent','partially_paid') THEN
    RAISE EXCEPTION 'void_invoice: invoice % is %, expected draft/sent/partially_paid',
      p_invoice_id, v_invoice.status;
  END IF;
  IF v_invoice.amount_paid_cents <> 0 THEN
    RAISE EXCEPTION 'void_invoice: invoice % has collected payments and cannot be voided', p_invoice_id;
  END IF;

  -- Canonical billing lock order is invoice -> lines -> milestones. The latch
  -- synchronization trigger also takes line -> milestone, so lock every line
  -- deterministically before changing either lifecycle.
  PERFORM 1
  FROM invoice_line_items
  WHERE invoice_id = p_invoice_id
  ORDER BY id
  FOR UPDATE;

  UPDATE invoices
  SET status = 'void', voided_at = now(), void_reason = p_reason,
      stripe_checkout_session_id = NULL, updated_at = now()
  WHERE id = p_invoice_id
  RETURNING * INTO v_invoice;

  -- Reset the milestone while both the header latch and live line pointer are
  -- still available. Covers old header-only drafts as well as current lines.
  UPDATE project_payment_milestones m
  SET invoice_id = NULL, status = 'pending', due_date = NULL, paid_at = NULL,
      updated_at = now()
  WHERE m.invoice_id = p_invoice_id
     OR EXISTS (
       SELECT 1 FROM invoice_line_items li
       WHERE li.invoice_id = p_invoice_id AND li.milestone_id = m.id
     );

  UPDATE invoice_line_items
  SET metadata = metadata || jsonb_build_object('released_milestone_id', milestone_id::text),
      milestone_id = NULL,
      kind = 'adhoc'
  WHERE invoice_id = p_invoice_id
    AND milestone_id IS NOT NULL;

  UPDATE invoice_line_items
  SET metadata = metadata || jsonb_build_object('released_ffe_item_id', ffe_item_id::text),
      ffe_item_id = NULL,
      kind = 'adhoc'
  WHERE invoice_id = p_invoice_id
    AND ffe_item_id IS NOT NULL;

  IF to_regclass('public.project_time_entries') IS NOT NULL THEN
    EXECUTE 'UPDATE public.project_time_entries SET invoice_id = NULL WHERE invoice_id = $1'
    USING p_invoice_id;
  END IF;

  -- A hosted session cannot be expired from SQL. Close the local attempt and
  -- row now; if Stripe reports a late charge, settle_invoice_checkout_payment
  -- converts it to requires_refund because the invoice is void.
  UPDATE invoice_payments
  SET status = 'failed',
      note = concat_ws(' ', note, 'Invoice voided before Checkout settled.')
  WHERE invoice_id = p_invoice_id
    AND status = 'pending'
    AND method = 'stripe';

  UPDATE invoice_checkout_attempts
  SET state = 'failed', failure_reason = 'invoice_voided', finalized_at = now()
  WHERE invoice_id = p_invoice_id
    AND state IN ('claimed','session_created','processing');

  RETURN v_invoice;
END;
$$;
ALTER FUNCTION public._void_invoice_authorized_legacy_00397(uuid,text) RESET ALL;
ALTER FUNCTION public._void_invoice_authorized_legacy_00397(uuid,text) SET search_path = pg_catalog, public, pg_temp;
ALTER FUNCTION public._void_invoice_authorized_legacy_00397(uuid,text) OWNER TO postgres;

CREATE OR REPLACE FUNCTION public.claim_design_request(p_lead_id uuid)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, pg_temp
AS $$
DECLARE
  v_uid              uuid := auth.uid();
  v_lead             leads%ROWTYPE;
  v_scan_id          uuid;
  v_existing_designer uuid;
  v_existing_homeowner uuid;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'not_authenticated' USING DETAIL = 'auth.uid() is null';
  END IF;

  IF NOT EXISTS (SELECT 1 FROM profiles p WHERE p.id = v_uid AND p.is_designer) THEN
    RAISE EXCEPTION 'not_designer' USING DETAIL = v_uid::text;
  END IF;

  -- Atomic first-wins: only an unassigned, homeowner-originated, 'new' lead is
  -- claimable, and only the row that matches here is updated. A concurrent
  -- second caller finds designer_id already set and drops to the diagnosis below.
  UPDATE leads
     SET designer_id = v_uid, updated_at = now()
   WHERE id = p_lead_id
     AND designer_id IS NULL
     AND homeowner_id IS NOT NULL
     AND status = 'new'
  RETURNING * INTO v_lead;

  -- FOUND here reflects the UPDATE (true iff a claimable row matched).
  IF NOT FOUND THEN
    SELECT l.designer_id, l.homeowner_id
      INTO v_existing_designer, v_existing_homeowner
    FROM leads l WHERE l.id = p_lead_id;

    -- FOUND here reflects the SELECT above.
    IF NOT FOUND THEN
      RAISE EXCEPTION 'request_not_found' USING DETAIL = p_lead_id::text;
    ELSIF v_existing_designer = v_uid THEN
      RETURN jsonb_build_object('lead_id', p_lead_id, 'already_yours', true);
    ELSE
      RAISE EXCEPTION 'already_claimed' USING DETAIL = p_lead_id::text;
    END IF;
  END IF;

  -- Mint winner's active/full associations for the whole junction set.
  FOR v_scan_id IN
    SELECT lrs.scan_id FROM lead_room_scans lrs WHERE lrs.lead_id = v_lead.id
  LOOP
    INSERT INTO room_scan_associations (
      scan_id, consumer_id, designer_id, association_type, status, access_level,
      shared_at, requested_at, lead_id
    ) VALUES (
      v_scan_id, v_lead.homeowner_id, v_uid, 'explicit', 'active', 'full',
      now(), now(), v_lead.id
    )
    ON CONFLICT (scan_id, designer_id) DO UPDATE SET
      status         = 'active',
      access_level   = 'full',
      shared_at      = now(),
      revoked_at     = NULL,
      revoked_reason = NULL,
      lead_id        = EXCLUDED.lead_id,
      updated_at     = now();
  END LOOP;

  -- Notifications (both parties in-app + homeowner email). Best-effort — a
  -- notification failure must never unwind a successful claim.
  BEGIN
    INSERT INTO notification_log (user_id, type, channel, status, template_id, metadata)
    VALUES (
      v_lead.homeowner_id,
      'design_request_claimed',
      'in_app',
      'delivered',
      'design-request-claimed',
      jsonb_build_object(
        'lead_id',     v_lead.id,
        'designer_id', v_uid,
        'entity_type', 'design_request',
        'entity_id',   v_lead.id::text,
        'title',       'Your design request was accepted',
        'message',     'A designer accepted your design request and will be in touch.',
        'deep_link',   '/doc/' || v_lead.id::text,
        'url',         '/doc/' || v_lead.id::text
      )
    );

    INSERT INTO notification_log (user_id, type, channel, status, template_id, metadata)
    VALUES (
      v_uid,
      'design_request_claim_confirmed',
      'in_app',
      'delivered',
      'design-request-claim-confirmed',
      jsonb_build_object(
        'lead_id',     v_lead.id,
        'entity_type', 'design_request',
        'entity_id',   v_lead.id::text,
        'title',       'You accepted a design request',
        'message',     'The request is now on your Desk.',
        'deep_link',   '/doc/' || v_lead.id::text,
        'url',         '/doc/' || v_lead.id::text
      )
    );

    PERFORM public.invoke_edge_function(
      'notification-dispatch',
      jsonb_build_object(
        'user_id',     v_lead.homeowner_id,
        'type',        'design_request_claimed',
        'channel',     'email',
        'template_id', 'design-request-claimed',
        'data', jsonb_build_object(
          'projectType', v_lead.project_type,
          'leadId',      v_lead.id
        ),
        'priority', 'high'
      )
    );
  EXCEPTION WHEN OTHERS THEN
    RAISE WARNING 'claim_design_request: notification step failed for lead %: %',
      v_lead.id, sqlerrm;
  END;

  RETURN jsonb_build_object(
    'lead_id',      v_lead.id,
    'designer_id',  v_uid,
    'status',       v_lead.status,
    'already_yours', false
  );
END;
$$;
ALTER FUNCTION public.claim_design_request(uuid) RESET ALL;
ALTER FUNCTION public.claim_design_request(uuid) SET search_path = pg_catalog, public, pg_temp;
ALTER FUNCTION public.claim_design_request(uuid) OWNER TO postgres;

CREATE OR REPLACE FUNCTION public.accept_design_request(p_lead_id uuid)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, pg_temp
AS $$
DECLARE
  v_actor uuid := auth.uid();
  v_homeowner_id uuid;
BEGIN
  IF v_actor IS NULL THEN
    RAISE EXCEPTION 'not_authenticated' USING DETAIL = 'auth.uid() is null';
  END IF;
  IF NOT EXISTS (
    SELECT 1 FROM public.profiles
    WHERE id = v_actor AND is_designer IS TRUE
  ) THEN
    RAISE EXCEPTION 'not_designer' USING DETAIL = v_actor::text;
  END IF;

  SELECT homeowner_id INTO v_homeowner_id
  FROM public.leads
  WHERE id = p_lead_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'request_not_found' USING DETAIL = p_lead_id::text;
  END IF;
  IF v_homeowner_id IS NULL THEN
    RAISE EXCEPTION 'arrival_requires_client_profile'
      USING DETAIL = 'captured profileless leads must begin Discovery directly';
  END IF;

  RETURN public._accept_design_request_profile_bound_core(p_lead_id);
END;
$$;
ALTER FUNCTION public.accept_design_request(uuid) RESET ALL;
ALTER FUNCTION public.accept_design_request(uuid) SET search_path = pg_catalog, public, pg_temp;
ALTER FUNCTION public.accept_design_request(uuid) OWNER TO postgres;

CREATE OR REPLACE FUNCTION public.open_project_direct(
  p_title text,
  p_client_id uuid DEFAULT NULL,
  p_budget_min_cents integer DEFAULT NULL,
  p_budget_max_cents integer DEFAULT NULL,
  p_start_date date DEFAULT CURRENT_DATE,
  p_id uuid DEFAULT NULL
)
RETURNS uuid
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pg_catalog, public, pg_temp
AS $open_project_direct$
DECLARE
  v_designer uuid := auth.uid();
  v_id uuid := coalesce(p_id, gen_random_uuid());
  v_title text := pg_catalog.btrim(coalesce(p_title, ''));
  v_existing public.projects;
  v_membership_id uuid;
  v_studio_id uuid;
  v_client_relationship_id uuid;
  v_client_relationship_status text;
BEGIN
  IF v_designer IS NULL THEN
    RAISE EXCEPTION 'open_project_not_authorized'
      USING ERRCODE = 'insufficient_privilege';
  END IF;

  IF v_title = '' THEN
    RAISE EXCEPTION 'a project title is required'
      USING ERRCODE = 'check_violation';
  END IF;

  IF p_budget_min_cents IS NOT NULL
     AND p_budget_max_cents IS NOT NULL
     AND p_budget_min_cents > p_budget_max_cents
  THEN
    RAISE EXCEPTION 'budget band minimum exceeds its maximum'
      USING ERRCODE = 'check_violation';
  END IF;

  PERFORM 1
  FROM public.user_roles AS user_role
  JOIN public.roles AS role_row ON role_row.id = user_role.role_id
  WHERE user_role.user_id = v_designer
    AND role_row.domain = 'designer'
  ORDER BY user_role.role_id, user_role.id
  LIMIT 1
  FOR SHARE OF user_role, role_row;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'open_project_not_authorized'
      USING ERRCODE = 'insufficient_privilege';
  END IF;

  SELECT membership.id, membership.organization_id
  INTO v_membership_id, v_studio_id
  FROM public.organization_members AS membership
  JOIN public.organizations AS organization
    ON organization.id = membership.organization_id
  WHERE membership.user_id = v_designer
    AND membership.status = 'active'
    AND membership.role <> 'guest'
    AND organization.type = 'design_studio'
    AND organization.status = 'active'
  ORDER BY membership.created_at, membership.id
  LIMIT 1
  FOR SHARE OF membership;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'open_project_not_authorized'
      USING ERRCODE = 'insufficient_privilege';
  END IF;

  PERFORM 1
  FROM public.organizations AS organization
  WHERE organization.id = v_studio_id
    AND organization.type = 'design_studio'
    AND organization.status = 'active'
  FOR SHARE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'open_project_not_authorized'
      USING ERRCODE = 'insufficient_privilege';
  END IF;

  IF p_client_id IS NOT NULL THEN
    SELECT relationship.id, relationship.status
    INTO v_client_relationship_id, v_client_relationship_status
    FROM public.designer_clients AS relationship
    WHERE relationship.designer_id = v_designer
      AND relationship.client_id = p_client_id
      AND relationship.status IN ('lead', 'proposal', 'prospect', 'active')
    ORDER BY CASE relationship.status
               WHEN 'active' THEN 0
               WHEN 'proposal' THEN 1
               WHEN 'prospect' THEN 2
               ELSE 3
             END,
             relationship.created_at,
             relationship.id
    LIMIT 1
    FOR UPDATE;

    IF NOT FOUND THEN
      RAISE EXCEPTION 'open_project_not_authorized'
        USING ERRCODE = 'insufficient_privilege';
    END IF;
  END IF;

  IF p_id IS NOT NULL THEN
    SELECT *
    INTO v_existing
    FROM public.projects AS project
    WHERE project.id = p_id
    FOR SHARE;

    IF FOUND THEN
      IF v_existing.designer_id IS DISTINCT FROM v_designer
         OR v_existing.studio_id IS DISTINCT FROM v_studio_id
         OR v_existing.client_id IS DISTINCT FROM p_client_id
      THEN
        RAISE EXCEPTION 'open_project_not_authorized'
          USING ERRCODE = 'insufficient_privilege';
      END IF;
      RETURN v_existing.id;
    END IF;
  END IF;

  INSERT INTO public.projects (
    id, name, status, designer_id, client_id, created_by, studio_id,
    proposal_id, start_date, budget_min, budget_max
  )
  VALUES (
    v_id, v_title, 'active', v_designer, p_client_id, v_designer, v_studio_id,
    NULL, p_start_date, p_budget_min_cents, p_budget_max_cents
  )
  ON CONFLICT (id) DO NOTHING;

  IF NOT FOUND THEN
    SELECT *
    INTO v_existing
    FROM public.projects AS project
    WHERE project.id = v_id
    FOR SHARE;

    IF NOT FOUND
       OR v_existing.designer_id IS DISTINCT FROM v_designer
       OR v_existing.studio_id IS DISTINCT FROM v_studio_id
       OR v_existing.client_id IS DISTINCT FROM p_client_id
    THEN
      RAISE EXCEPTION 'open_project_not_authorized'
        USING ERRCODE = 'insufficient_privilege';
    END IF;
  END IF;

  IF v_client_relationship_status = 'lead' THEN
    UPDATE public.designer_clients AS relationship
    SET status = 'active',
        updated_at = now()
    WHERE relationship.id = v_client_relationship_id
      AND NOT EXISTS (
        SELECT 1
        FROM public.designer_clients AS engaged
        WHERE engaged.designer_id = v_designer
          AND engaged.client_id = p_client_id
          AND engaged.id <> relationship.id
          AND engaged.status <> 'lead'
      );
  ELSIF v_client_relationship_status IN ('proposal', 'prospect') THEN
    UPDATE public.designer_clients AS relationship
    SET status = 'active',
        updated_at = now()
    WHERE relationship.id = v_client_relationship_id;
  END IF;

  RETURN v_id;
END;
$open_project_direct$;
ALTER FUNCTION public.open_project_direct(text,uuid,integer,integer,date,uuid) RESET ALL;
ALTER FUNCTION public.open_project_direct(text,uuid,integer,integer,date,uuid) SET search_path = pg_catalog, public, pg_temp;
ALTER FUNCTION public.open_project_direct(text,uuid,integer,integer,date,uuid) OWNER TO postgres;

CREATE OR REPLACE FUNCTION public.set_document_client(
  p_engagement_kind text,
  p_target_id uuid,
  p_client_id uuid
)
RETURNS void
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, pg_temp
AS $$
DECLARE
  v_designer uuid := auth.uid();
  v_target_designer uuid;
  v_current_designer_client_id uuid;
  v_proposal_status text;
  v_relationship public.designer_clients%ROWTYPE;
BEGIN
  IF v_designer IS NULL THEN
    RAISE EXCEPTION 'set_document_client requires an authenticated user'
      USING ERRCODE = 'insufficient_privilege';
  END IF;

  IF p_engagement_kind NOT IN ('project', 'proposal') THEN
    RAISE EXCEPTION 'unknown engagement kind %', p_engagement_kind
      USING ERRCODE = 'check_violation';
  END IF;

  IF p_engagement_kind = 'project' THEN
    SELECT designer_id
    INTO v_target_designer
    FROM public.projects
    WHERE id = p_target_id
    FOR UPDATE;
  ELSE
    -- Status and both identity legs share this one row lock. No sent/accepted
    -- proposal can be reassigned between the validation and protected update.
    SELECT designer_id, designer_client_id, status
    INTO v_target_designer, v_current_designer_client_id, v_proposal_status
    FROM public.proposals
    WHERE id = p_target_id
    FOR UPDATE;
  END IF;

  IF NOT FOUND OR v_target_designer IS DISTINCT FROM v_designer THEN
    RAISE EXCEPTION 'no % owned by you with id %', p_engagement_kind, p_target_id
      USING ERRCODE = 'insufficient_privilege';
  END IF;

  IF p_engagement_kind = 'proposal' AND v_proposal_status <> 'draft' THEN
    RAISE EXCEPTION 'proposal client identity may only change while draft'
      USING ERRCODE = 'check_violation';
  END IF;

  IF p_client_id IS NOT NULL THEN
    SELECT relationship.*
    INTO v_relationship
    FROM public.designer_clients AS relationship
    WHERE relationship.designer_id = v_designer
      AND relationship.client_id = p_client_id
    ORDER BY
      COALESCE(relationship.id = v_current_designer_client_id, false) DESC,
      (relationship.status <> 'lead') DESC,
      relationship.updated_at DESC,
      relationship.created_at DESC,
      relationship.id
    LIMIT 1
    FOR UPDATE;

    IF NOT FOUND THEN
      RAISE EXCEPTION 'client % is not one of your clients', p_client_id
        USING ERRCODE = 'insufficient_privilege';
    END IF;
  ELSE
    v_relationship := NULL;
  END IF;

  IF p_engagement_kind = 'project' THEN
    PERFORM set_config('app.project_identity_id', p_target_id::text, true);
    UPDATE public.projects
    SET client_id = p_client_id, updated_at = now()
    WHERE id = p_target_id;
    PERFORM set_config('app.project_identity_id', '', true);
  ELSE
    PERFORM set_config('app.proposal_identity_id', p_target_id::text, true);
    UPDATE public.proposals
    SET client_id = p_client_id,
        designer_client_id = CASE
          WHEN p_client_id IS NULL THEN NULL
          ELSE v_relationship.id
        END,
        updated_at = now()
    WHERE id = p_target_id;
    PERFORM set_config('app.proposal_identity_id', '', true);
  END IF;

  IF p_client_id IS NOT NULL THEN
    IF p_engagement_kind = 'project'
       AND v_relationship.status IN ('lead', 'proposal')
    THEN
      UPDATE public.designer_clients
      SET status = 'active', updated_at = now()
      WHERE id = v_relationship.id;
    ELSIF p_engagement_kind = 'proposal'
          AND v_relationship.status = 'lead'
          AND NOT EXISTS (
            SELECT 1
            FROM public.designer_clients AS canonical
            WHERE canonical.designer_id = v_designer
              AND canonical.client_id = p_client_id
              AND canonical.id <> v_relationship.id
              AND canonical.status <> 'lead'
          )
    THEN
      UPDATE public.designer_clients
      SET status = 'proposal', updated_at = now()
      WHERE id = v_relationship.id;
    END IF;
  END IF;
END;
$$;
ALTER FUNCTION public.set_document_client(text,uuid,uuid) RESET ALL;
ALTER FUNCTION public.set_document_client(text,uuid,uuid) SET search_path = pg_catalog, public, pg_temp;
ALTER FUNCTION public.set_document_client(text,uuid,uuid) OWNER TO postgres;

-- Restore the exact source security-invoker view before removing columns it
-- no longer references.
CREATE OR REPLACE VIEW public.people_directory
WITH (security_invoker = true) AS
-- ── CLIENTS ───────────────────────────────────────────────────────────────
-- v4: meta gains has_sent_proposal + issued_on_paper (this migration).
-- Everything else in this branch is unchanged from 00420.
SELECT
  dc.id                                                          AS person_id,
  'client'::text                                                 AS role,
  COALESCE(dc.client_name, pr.full_name, pr.display_name, dc.client_email, 'Unnamed client') AS display_name,
  COALESCE(dc.client_email, pr.email)                            AS email,
  pr.phone                                                       AS phone,
  dc.client_id                                                   AS profile_id,
  NULL::uuid                                                     AS project_id,
  dc.designer_id                                                 AS designer_id,
  dc.status                                                      AS status_raw,
  COALESCE(dc.last_contacted_at, dc.last_project_at, dc.updated_at) AS last_touch_at,
  jsonb_build_object(
    'total_projects',     dc.total_projects,
    'total_revenue',      dc.total_revenue,
    'last_project_at',    dc.last_project_at,
    'last_contacted_at',  dc.last_contacted_at,
    'first_project_at',   dc.first_project_at,
    'style_tags',         dc.style_tags,
    'source',             dc.source,
    'satisfaction_score', dc.satisfaction_score,
    'nickname',           dc.nickname,
    'location',           dc.location,
    'lead_id',            dc.lead_id
  ) || public.designer_client_send_evidence(dc.id, dc.designer_id, dc.client_id)
                                                                 AS meta,
  (CASE WHEN dc.designer_id = (select auth.uid()) THEN 'mine' ELSE 'studio' END)::text AS scope
FROM public.designer_clients dc
LEFT JOIN public.profiles pr ON pr.id = dc.client_id
WHERE public.is_studio_comember(dc.designer_id)

UNION ALL

-- ── LEADS (open only) ─────────────────────────────────────────────────────
-- Unchanged from 00420.
SELECT
  l.id,
  'lead',
  COALESCE(l.contact_name, hp.full_name, hp.display_name, l.contact_email, 'New lead'),
  COALESCE(l.contact_email, hp.email),
  hp.phone,
  l.homeowner_id,
  NULL::uuid,
  l.designer_id,
  l.status,
  COALESCE(l.contacted_at, l.created_at),
  jsonb_build_object(
    'project_type',      l.project_type,
    'project_description', l.project_description,
    'budget_range',      l.budget_range,
    'timeline',          l.timeline,
    'match_score',       l.match_score,
    'location_city',     l.location_city,
    'location_state',    l.location_state,
    'response_deadline', l.response_deadline,
    'created_at',        l.created_at
  ),
  (CASE WHEN l.designer_id = (select auth.uid()) THEN 'mine' ELSE 'studio' END)::text
FROM public.leads l
LEFT JOIN public.profiles hp ON hp.id = l.homeowner_id
WHERE public.is_studio_comember(l.designer_id)
  AND l.status NOT IN ('accepted', 'declined', 'expired')

UNION ALL

-- ── MAKERS / VENDORS (saved or engaged, studio-wide) ──────────────────────
-- Unchanged from 00420.
SELECT
  v.id,
  'maker',
  v.name,
  COALESCE(v.orders_email, v.trade_account_email),
  NULL::text,
  v.contact_profile_id,
  NULL::uuid,
  auth.uid(),
  v.nomination_status,
  v.updated_at,
  jsonb_build_object(
    'primary_category',      v.primary_category,
    'lead_times',            v.lead_times,
    'default_payment_terms', v.default_payment_terms,
    'founding_circle',       v.founding_circle,
    'made_in',               v.made_in,
    'trade_terms',           v.trade_terms,
    'is_patina_catalog',     v.is_patina_catalog,
    'review_count',          v.review_count,
    'designer_rating_avg',   v.designer_rating_avg
  ),
  (CASE
     WHEN EXISTS (
       SELECT 1 FROM public.saved_vendors mine
       WHERE mine.vendor_id = v.id
         AND mine.designer_id = (select auth.uid())
     ) THEN 'mine'
     ELSE 'studio'
   END)::text
FROM public.vendors v
WHERE v.id IN (
  SELECT sv.vendor_id
  FROM public.saved_vendors sv
  WHERE public.is_studio_comember(sv.designer_id)
  UNION
  SELECT pp.vendor_id
  FROM public.project_parties pp
  JOIN public.projects pj ON pj.id = pp.project_id
  WHERE pp.vendor_id IS NOT NULL
    AND ( public.is_studio_comember(pj.designer_id)
       OR public.is_studio_comember(pj.lead_designer_id)
       OR public.is_studio_comember(pj.created_by) )
)

UNION ALL

-- ── FIELD / ROSTER PARTIES on studio projects ─────────────────────────────
-- Unchanged from 00420.
SELECT
  pp.id,
  pp.party_kind,
  pp.display_name,
  pp.email,
  pp.phone,
  pp.profile_id,
  pp.project_id,
  auth.uid(),
  pp.sms_consent_status,
  pp.updated_at,
  jsonb_build_object(
    'company_name',       pp.company_name,
    'vendor_id',          pp.vendor_id,
    'project_name',       pj.name,
    'party_kind',         pp.party_kind,
    'trade',              pp.trade,
    'phone_e164',         pp.phone_e164,
    'sms_consent_status', pp.sms_consent_status,
    'sms_consented_at',   pp.sms_consented_at,
    'sms_opt_out_at',     pp.sms_opt_out_at,
    'show_to_client',     pp.show_to_client,
    'studio_contact_id',  pp.studio_contact_id
  ),
  (CASE
     WHEN pj.designer_id      = (select auth.uid())
       OR pj.lead_designer_id = (select auth.uid())
       OR pj.created_by       = (select auth.uid())
     THEN 'mine' ELSE 'studio'
   END)::text
FROM public.project_parties pp
JOIN public.projects pj ON pj.id = pp.project_id
WHERE pp.party_kind IN ('gc', 'sub', 'installer', 'receiver',
                        'architect', 'photographer', 'stager')
  AND ( public.is_studio_comember(pj.designer_id)
     OR public.is_studio_comember(pj.lead_designer_id)
     OR public.is_studio_comember(pj.created_by) )

UNION ALL

-- ── TEAM (studio collaborators on studio projects, one row per teammate) ───
-- Unchanged from 00420.
SELECT
  t.id,
  'team',
  COALESCE(tp.full_name, tp.display_name, tp.email, 'Teammate'),
  tp.email,
  tp.phone,
  t.user_id,
  t.project_id,
  auth.uid(),
  t.role,
  t.assigned_at,
  jsonb_build_object(
    'role',         t.role,
    'project_name', t.project_name,
    'job_title',    t.job_title,
    'staff_role',   t.staff_role
  ),
  (CASE WHEN t.is_mine THEN 'mine' ELSE 'studio' END)::text
FROM (
  SELECT DISTINCT ON (tm.user_id)
    tm.id, tm.user_id, tm.role, tm.project_id, tm.assigned_at, pj.name AS project_name,
    om.job_title  AS job_title,
    om.staff_role AS staff_role,
    ( pj.designer_id      = (select auth.uid())
   OR pj.lead_designer_id = (select auth.uid())
   OR pj.created_by       = (select auth.uid()) ) AS is_mine
  FROM public.project_team_members tm
  JOIN public.projects pj ON pj.id = tm.project_id
  LEFT JOIN public.organization_members om
    ON om.user_id = tm.user_id
   AND om.organization_id = pj.studio_id
   AND om.status = 'active'
  WHERE tm.removed_at IS NULL
    AND tm.user_id <> auth.uid()
    AND tm.role IN ('lead_designer', 'support_designer', 'bookkeeper', 'previous_lead')
    AND ( public.is_studio_comember(pj.designer_id)
       OR public.is_studio_comember(pj.lead_designer_id)
       OR public.is_studio_comember(pj.created_by) )
  ORDER BY tm.user_id, tm.assigned_at DESC
) t
LEFT JOIN public.profiles tp ON tp.id = t.user_id

UNION ALL

-- ── CONTACTS (the shared rolodex, 00417) ──────────────────────────────────
-- Unchanged from 00420.
SELECT
  sc.id,
  'contact',
  COALESCE(sc.full_name, sc.company_name),
  sc.email,
  sc.phone,
  sc.profile_id,
  NULL::uuid,
  sc.created_by,
  (CASE WHEN sc.archived_at IS NULL THEN 'active' ELSE 'archived' END)::text,
  sc.updated_at,
  jsonb_build_object(
    'contact_kind',    sc.contact_kind,
    'entity_kind',     sc.entity_kind,
    'company_name',    sc.company_name,
    'company_id',      sc.company_id,
    'specialties',     sc.specialties,
    'vendor_id',       sc.vendor_id,
    'organization_id', sc.organization_id,
    'archived_at',     sc.archived_at
  ),
  (CASE WHEN sc.created_by = (select auth.uid()) THEN 'mine' ELSE 'studio' END)::text
FROM public.studio_contacts sc
WHERE public.is_active_studio_member(sc.organization_id);

