          JOIN pg_catalog.pg_attribute AS attribute
            ON attribute.attrelid = index_meta.indrelid AND attribute.attnum = key.attnum
        ) = ARRAY['designer_id','client_email']::name[]
        AND pg_catalog.regexp_replace(
